const REVIEW_REMEDIATION_EVIDENCE_TEST_GROUP =
  process.env.DEVPRO_REVIEW_REMEDIATION_EVIDENCE_TEST_GROUP ?? "core";
const REVIEW_REMEDIATION_EVIDENCE_TEST_GROUP_RANGES = Object.freeze({
  core: [1, 25],
  runner_a: [26, 35],
  runner_b: [36, 54],
  runner_c: [55, 76],
  runner_d1: [77, 116],
  runner_d2: [117, 132],
  runner_d3: [133, 194],
  runner_d4: [195, 281], // #3085: large-input cases 275–277; #2975: coverage-only case 279.
});
const REVIEW_REMEDIATION_EVIDENCE_TEST_GROUP_RANGE_END = Math.max(
  ...Object.values(REVIEW_REMEDIATION_EVIDENCE_TEST_GROUP_RANGES).map(([, end]) => end),
);
let reviewRemediationEvidenceTestIndex = 0;

if (!Object.hasOwn(REVIEW_REMEDIATION_EVIDENCE_TEST_GROUP_RANGES, REVIEW_REMEDIATION_EVIDENCE_TEST_GROUP)) {
  throw new Error(`unknown review-remediation-evidence test group: ${REVIEW_REMEDIATION_EVIDENCE_TEST_GROUP}`);
}

{
  const orderedRanges = Object.values(REVIEW_REMEDIATION_EVIDENCE_TEST_GROUP_RANGES);
  for (let i = 0; i < orderedRanges.length - 1; i++) {
    const [, end] = orderedRanges[i];
    const [nextStart] = orderedRanges[i + 1];
    if (end + 1 !== nextStart) {
      throw new Error(
        `review-remediation-evidence test group ranges are not contiguous at seam index ${end}: ` +
          `expected next group to start at ${end + 1}, got ${nextStart}`,
      );
    }
  }
}

function reviewRemediationEvidenceTestGroupForIndex(index) {
  for (const [group, [start, end]] of Object.entries(REVIEW_REMEDIATION_EVIDENCE_TEST_GROUP_RANGES)) {
    if (index >= start && index <= end) return group;
  }
  throw new Error(`review-remediation-evidence test index ${index} has no group`);
}

function test(name, optionsOrFn, maybeFn) {
  reviewRemediationEvidenceTestIndex += 1;
  if (
    reviewRemediationEvidenceTestGroupForIndex(reviewRemediationEvidenceTestIndex) !==
    REVIEW_REMEDIATION_EVIDENCE_TEST_GROUP
  ) {
    return;
  }
  if (typeof optionsOrFn === "function") {
    return nodeTest(name, optionsOrFn);
  }
  return nodeTest(name, optionsOrFn, maybeFn);
}

