function api() {
  assert.equal(
    helperLoadError ?? null,
    null,
    `${HELPER_RELATIVE_PATH} helper contract is unavailable: ${helperLoadError?.code ?? helperLoadError?.message}`,
  );
  assert.deepEqual(
    Object.keys(helperModule).sort(),
    [...REQUIRED_EXPORTS].sort(),
    "production helper exports must remain the exact v1 API and must not expose test capabilities",
  );
  assert.equal(helperModule.REVIEW_RECEIPT_SCHEMA, REVIEW_RECEIPT_SCHEMA);
  assert.equal(helperModule.REVIEW_MANIFEST_SCHEMA, REVIEW_MANIFEST_SCHEMA);
  assert.equal(helperModule.FINAL_EVIDENCE_SCHEMA, FINAL_EVIDENCE_SCHEMA);
  return helperModule;
}

function coreApi() {
  assert.equal(
    coreLoadError ?? null,
    null,
    `${CORE_RELATIVE_PATH} internal injectable core factory is unavailable: ${coreLoadError?.code ?? coreLoadError?.message}`,
  );
  assert.deepEqual(
    Object.keys(coreModule).sort(),
    [...REQUIRED_CORE_EXPORTS].sort(),
    "internal core module exposes only its factory and the closed D30 failure contract, never production façade commands",
  );
  return coreModule;
}

function coreFailureIs(code) {
  return (error) => error instanceof CoreFailure && error.code === code;
}

function nativeErrorIs(code) {
  return (error) => !(error instanceof CoreFailure) && error?.code === code;
}

function sha256(value) {
  return createHash("sha256").update(value).digest("hex");
}

function clone(value) {
  return structuredClone(value);
}

function listMjsFiles(root) {
  const files = [];
  for (const entry of readdirSync(root, { withFileTypes: true })) {
    const absolute = path.join(root, entry.name);
    if (entry.isDirectory()) files.push(...listMjsFiles(absolute));
    else if (entry.isFile() && entry.name.endsWith(".mjs")) files.push(absolute);
  }
  return files;
}

function sourceFunctionSlice(source, functionName, nextFunctionName) {
  const start = source.indexOf(`function ${functionName}`);
  const end = source.indexOf(`function ${nextFunctionName}`, start + 1);
  assert.notEqual(start, -1, `missing source function ${functionName}`);
  assert.notEqual(end, -1, `missing source boundary ${nextFunctionName}`);
  return source.slice(start, end);
}

function gitExec(args, options = {}) {
  return retryOnTransientGitIo(() => execFileSync("git", args, options));
}

// `git clone` is not idempotent: a transient EINTR retry MUST reset the
// destination first, or the second attempt aborts with "destination path
// already exists and is not an empty directory"
// (strengthen-hook-runtime-robustness).
function cloneSharedFresh(repoRoot) {
  const cloned = retryOnTransientGitIo(() => {
    rmSync(repoRoot, { recursive: true, force: true });
    return execFileSync("git", ["clone", "--shared", "--quiet", repoPath("."), repoRoot]);
  });
  // Historical fixtures also commit authority mutations; a fresh clone does
  // not inherit its source repository's local author configuration.
  git(repoRoot, ["config", "user.name", "Review Evidence Test"]);
  git(repoRoot, ["config", "user.email", "review-evidence@example.invalid"]);
  return cloned;
}

function git(repoRoot, args, options = {}) {
  return gitExec(args, { cwd: repoRoot, encoding: "utf8", ...options }).trim();
}

function write(repoRoot, relativePath, bytes) {
  const target = path.join(repoRoot, relativePath);
  mkdirSync(path.dirname(target), { recursive: true });
  writeFileSync(target, bytes);
  return target;
}

function commitAll(repoRoot, message, { executablePaths = [] } = {}) {
  git(repoRoot, ["add", "-A"]);
  for (const relativePath of executablePaths) git(repoRoot, ["update-index", "--chmod=+x", "--", relativePath]);
  git(repoRoot, ["commit", "--quiet", "-m", message]);
  return git(repoRoot, ["rev-parse", "HEAD"]);
}

function suiteTerminalOutput({ result = "pass", tests = 2, passed = 2, failed = 0, skipped = 0 } = {}) {
  return [
    "[test-suite] --changed main: 4 changed file(s) → tiers: generated",
    formatLogSummary({
      scope: "tier",
      label: "generated",
      logPath: "notes/tmp/fixture-suite.log",
      summary: { lines: 8, bytes: 256, digestSha256: "a".repeat(64), tests, pass: passed, fail: failed, skipped, failedNames: [] },
    }),
    `[test-suite] tier=generated real=0.1s status=${result}`,
    "",
  ].join("\n");
}

function multiTierSuiteTerminalOutput() {
  return [
    "[test-suite] --changed main: 4 changed file(s) → tiers: unit, integration",
    formatLogSummary({
      scope: "tier",
      label: "unit",
      logPath: "notes/tmp/unit.log",
      summary: { lines: 8, bytes: 256, digestSha256: "b".repeat(64), tests: 2, pass: 2, fail: 0, skipped: 0, failedNames: [] },
    }),
    "[test-suite] tier=unit real=0.1s status=pass",
    formatLogSummary({
      scope: "tier",
      label: "integration",
      logPath: "notes/tmp/integration.log",
      summary: { lines: 12, bytes: 512, digestSha256: "c".repeat(64), tests: 3, pass: 3, fail: 0, skipped: 0, failedNames: [] },
    }),
    "[test-suite] tier=integration real=0.2s status=pass",
    "",
  ].join("\n");
}

function bufferedSpawnResult({ stdout = "", stderr = "", ...result }) {
  return { ...result, stdout: Buffer.from(stdout), stderr: Buffer.from(stderr) };
}

function assertInlineLog(log, expectedBytes = null) {
  assert.deepEqual(Object.keys(log).sort(), ["byte_length", "bytes_base64", "digest_sha256", "encoding"]);
  assert.equal(log.encoding, "base64");
  assert.equal(typeof log.bytes_base64, "string");
  const bytes = Buffer.from(log.bytes_base64, "base64");
  assert.equal(bytes.toString("base64"), log.bytes_base64, "inline log base64 must be canonical");
  assert.equal(log.byte_length, bytes.length);
  assert.equal(log.digest_sha256, sha256(bytes));
  if (expectedBytes !== null) assert.deepEqual(bytes, Buffer.from(expectedBytes));
  return bytes;
}

function canonicalRunnerSource({ modeBranches = [] } = {}) {
  return [
    'import fs from "node:fs";',
    'import crypto from "node:crypto";',
    'if (process.argv.slice(2).join(" ") !== "--changed main --stdio log") process.exit(9);',
    'const control = ".suite-control.json";',
    'const state = fs.existsSync(control) ? JSON.parse(fs.readFileSync(control, "utf8")) : {};',
    ...modeBranches,
    'if (state.result === "malformed-success") { process.stdout.write("success\\n"); process.exit(0); }',
    'const result = state.result === "failed" ? "fail" : "pass";',
    'const passed = result === "fail" ? 1 : 2;',
    'const failed = result === "fail" ? 1 : 0;',
    'const raw = Buffer.alloc(state.rawBytes ?? 256, 0x78);',
    'fs.mkdirSync("notes/tmp", {recursive: true});',
    'fs.writeFileSync("notes/tmp/fixture-suite.log", raw);',
    'const digest = crypto.createHash("sha256").update(raw).digest("hex");',
    'process.stdout.write(`[test-suite] --changed main: 4 changed file(s) → tiers: generated\\n`);',
    'process.stdout.write(`[test-suite] tier=generated log=notes/tmp/fixture-suite.log lines=8 bytes=${raw.length} digest_sha256=${digest} tests=2 pass=${passed} fail=${failed} skipped=0\\n`);',
    'process.stdout.write(`[test-suite] tier=generated real=0.1s status=${result}\\n`);',
    'process.stderr.write(state.stderr ?? "canonical fixture stderr\\n");',
    'process.exit(result === "fail" ? 1 : 0);',
    "",
  ].join("\n");
}

function oracleSource({ mode = "pass" } = {}) {
  if (mode === "nonzero") return "export async function verify() { throw new Error('oracle nonzero equivalent'); }\n";
  if (mode === "malformed") return "export async function verify() { return 'not-structured-evidence'; }\n";
  return [
    'import crypto from "node:crypto";',
    'const sort = (v) => Array.isArray(v) ? v.map(sort) : v && typeof v === "object" ? Object.fromEntries(Object.keys(v).sort().map((k) => [k, sort(v[k])])) : v;',
    'const canonical = (v) => JSON.stringify(sort(v));',
    'export async function verify(request) {',
    'const assertion = request.manifest_assertion;',
    'if (!assertion || assertion.manifest_digest_sha256 || assertion.validator?.independent_evidence) throw new Error("invalid assertion");',
    'const manifestDigest = crypto.createHash("sha256").update(canonical(assertion)).digest("hex");',
    'const evidence = {schema: "devpro.review-remediation.validator-evidence/v1", oracle: request.oracle, subject: {validator_source_path: assertion.validator.source_path, validator_source_digest_sha256: assertion.validator.source_digest_sha256, manifest_assertion_digest_sha256: manifestDigest}, lineage: {change_base_sha: assertion.lineage.change_base_sha, candidate_head_sha: assertion.lineage.candidate_head_sha}, result: "verified"};',
    'const digest = crypto.createHash("sha256").update(JSON.stringify(sort(evidence))).digest("hex");',
    'return {...evidence, evidence_digest_sha256: digest};',
    '}',
    "",
  ].join("\n");
}

function withNodeEnvironment(value, run) {
  const previous = process.env.NODE_ENV;
  if (value === undefined) delete process.env.NODE_ENV;
  else process.env.NODE_ENV = value;
  try {
    return run();
  } finally {
    if (previous === undefined) delete process.env.NODE_ENV;
    else process.env.NODE_ENV = previous;
  }
}

function initializeReviewRepo(repoRoot, { runnerSource = canonicalRunnerSource(), extraFiles = {}, originUrl = null } = {}) {
  mkdirSync(repoRoot, { recursive: true });
  git(repoRoot, ["init", "--quiet", "--initial-branch=main"]);
  git(repoRoot, ["config", "user.name", "Review Evidence Test"]);
  git(repoRoot, ["config", "user.email", "review-evidence@example.invalid"]);
  git(repoRoot, ["config", "commit.gpgsign", "false"]);
  git(repoRoot, ["config", "core.autocrlf", "false"]);
  // Every fixture commit otherwise forks a detached `git maintenance run
  // --auto` that has nothing to do in a repository this small.
  git(repoRoot, ["config", "maintenance.auto", "false"]);
  git(repoRoot, ["config", "gc.auto", "0"]);
  // Git for Windows cannot reflect the index execute bit in the working tree.
  // Keep executable modes in the index via update-index below, while asking
  // status to ignore that host limitation in these temporary repositories.
  git(repoRoot, ["config", "core.filemode", process.platform === "win32" ? "false" : "true"]);
  // Fixture faithfulness: production `.gitignore` (managed block, SSOT
  // `gitignore-alignment.md`) ignores both hook-carrier prefixes, so a real
  // repo can never track them. Without these two lines `commitAll`'s
  // `git add -A` tracked them as a side effect and the archive-transition
  // fixtures exercised a tree shape that cannot occur in production.
  write(
    repoRoot,
    ".gitignore",
    "notes/\n.suite-control.json\nopenspec/changes/**/override-ledger/\nopenspec/changes/**/admission-records/\n",
  );
  write(repoRoot, "src/review-target.mjs", "export const reviewTarget = true;\n");
  write(repoRoot, "src/second-target.mjs", "export const secondTarget = true;\n");
  write(repoRoot, "src/modified.txt", "before\n");
  write(repoRoot, "src/deleted.txt", "delete me\n");
  write(repoRoot, "src/type-change", "regular file\n");
  write(repoRoot, "tools/validator.mjs", "export const validate = true;\n");
  write(repoRoot, "tools/validator-oracle.mjs", oracleSource());
  write(repoRoot, "tools/oracle-nonzero.mjs", oracleSource({ mode: "nonzero" }));
  write(repoRoot, "tools/oracle-malformed.mjs", oracleSource({ mode: "malformed" }));
  write(repoRoot, "tests/validator.test.mjs", oracleSource());
  write(repoRoot, "docs/oracle.md", "validator is valid\n");
  write(repoRoot, ".devpro/scripts/run-test-suite.mjs", runnerSource);
  for (const [relativePath, bytes] of Object.entries(extraFiles)) write(repoRoot, relativePath, bytes);
  if (originUrl !== null) git(repoRoot, ["remote", "add", "origin", originUrl]);
  for (const executable of [
    "tools/validator-oracle.mjs",
    "tools/oracle-nonzero.mjs",
    "tools/oracle-malformed.mjs",
    ".devpro/scripts/run-test-suite.mjs",
  ]) chmodSync(path.join(repoRoot, executable), 0o755);
  const mainSha = commitAll(repoRoot, "baseline", { executablePaths: [
    "tools/validator-oracle.mjs",
    "tools/oracle-nonzero.mjs",
    "tools/oracle-malformed.mjs",
    ".devpro/scripts/run-test-suite.mjs",
  ] });
  // Receipt tip SSOT is refs/remotes/origin/main (exact-ref). Keep the template
  // remote-tracking tip homologous with local main so existing fixtures that
  // never diverge the two keep their prior merge-base semantics.
  git(repoRoot, ["update-ref", "refs/remotes/origin/main", mainSha]);
  git(repoRoot, ["checkout", "--quiet", "-b", "feature/evidence"]);
  return mainSha;
}

function syncOriginMain(repoRoot, sha = git(repoRoot, ["rev-parse", "main"])) {
  git(repoRoot, ["update-ref", "refs/remotes/origin/main", sha]);
  return sha;
}

/** Historical post-hoc clones pin local main to a closed allowlisted tip; keep
 * receipt tip SSOT (`refs/remotes/origin/main`) homologous with that tip. */
const HISTORICAL_POST_HOC_MAIN_TIP = "f1e879d1079bdf4029967df4d84823f7815c225c";

function pinHistoricalReceiptMainTip(repoRoot, sha = HISTORICAL_POST_HOC_MAIN_TIP) {
  // update-ref (not `branch -f`): a fresh clone's initial branch mirrors the
  // source checkout's active branch, so `branch -f main` aborts when main is
  // the checked-out branch (F-hrr-f2-02); update-ref is branch-state agnostic.
  // Detach first: if that branch IS main, moving the ref under a checked-out
  // HEAD would behave like `reset --soft` and leave the index/worktree stale
  // (cross-model F1), which makes the follow-up fixture checkout abort.
  gitExec(["checkout", "--quiet", "--detach"], { cwd: repoRoot });
  gitExec(["update-ref", "refs/heads/main", sha], { cwd: repoRoot });
  gitExec(["update-ref", "refs/remotes/origin/main", sha], { cwd: repoRoot });
  return sha;
}

// Historical post-hoc fixtures need this checkout's object store (the closed
// allowlisted commits) and nothing else from it. `git clone --shared` also
// paid, per fixture, for copying every ref and for a full default-branch
// checkout that the next step immediately replaced with the reviewed commit.
// Borrowing the objects through alternates reaches the same end state
// (detached reviewed HEAD, pinned main and remote-tracking main) without it.
let historicalSourceObjectStore;

function historicalSourceObjects() {
  if (historicalSourceObjectStore === undefined) {
    // --git-path, not <root>/.git: a linked worktree's .git is a file, and a
    // shallow source checkout keeps its graft list beside the object store.
    const [objects, shallow] = gitExec(
      ["rev-parse", "--path-format=absolute", "--git-path", "objects", "--git-path", "shallow"],
      { cwd: repoPath("."), encoding: "utf8" },
    ).trim().split(/\r?\n/u);
    historicalSourceObjectStore = Object.freeze({ objects, shallow });
  }
  return historicalSourceObjectStore;
}

// The post-hoc readers touch the change directory and the scripts tree, and
// commitRound() writes under src/; materialising the other ~4k historical
// files is pure filesystem load. A path a fixture writes MUST be in the cone:
// `git add -A` refuses paths outside the sparse definition.
const HISTORICAL_POST_HOC_SPARSE_CONE = Object.freeze([
  "openspec/changes/fix-zero-value-review-rounds",
  ".devpro/scripts",
  "src",
]);

function initializeHistoricalPostHocRepo(repoRoot, reviewedHeadSha) {
  const source = historicalSourceObjects();
  const gitDir = path.join(repoRoot, ".git");
  // Like `git clone`, a partially materialised checkout is not idempotent: a
  // transient EINTR retry MUST start from an empty destination.
  retryOnTransientGitIo(() => {
    rmSync(repoRoot, { recursive: true, force: true });
    mkdirSync(repoRoot, { recursive: true });
    execFileSync("git", ["init", "--quiet", "--initial-branch=main"], { cwd: repoRoot });
    mkdirSync(path.join(gitDir, "objects", "info"), { recursive: true });
    writeFileSync(path.join(gitDir, "objects", "info", "alternates"), `${source.objects}\n`);
    if (existsSync(source.shallow)) cpSync(source.shallow, path.join(gitDir, "shallow"));
    execFileSync("git", ["sparse-checkout", "set", "--cone", ...HISTORICAL_POST_HOC_SPARSE_CONE], { cwd: repoRoot });
    return execFileSync("git", ["checkout", "--quiet", "--detach", reviewedHeadSha], { cwd: repoRoot });
  });
  // Historical fixtures also commit authority mutations; a fresh repository
  // does not inherit its source repository's local author configuration.
  git(repoRoot, ["config", "user.name", "Review Evidence Test"]);
  git(repoRoot, ["config", "user.email", "review-evidence@example.invalid"]);
  pinHistoricalReceiptMainTip(repoRoot);
}

let reviewRepoTemplate;
const semanticGitObjectFormats = new Map();

function getReviewRepoTemplate() {
  if (reviewRepoTemplate !== undefined) return reviewRepoTemplate;
  const tempRoot = mkdtempSync(path.join(os.tmpdir(), "review-evidence-template-v1-"));
  const repoRoot = path.join(tempRoot, "main-checkout");
  const mainSha = initializeReviewRepo(repoRoot);
  reviewRepoTemplate = Object.freeze({ tempRoot, repoRoot, mainSha });
  process.once("exit", () => rmSync(tempRoot, { recursive: true, force: true }));
  return reviewRepoTemplate;
}

// fix-seal-final-consumer-na-suite-evidence T1 (design D12): consumer-profile
// fixtures. These use their OWN template caches so the shared template (and
// every existing source-path test) keeps its profile. The consumer N/A line and
// the forged-source stub path come from the production exports (T2). The smoke
// N/A wording is not exported by the runner, so it stays a local literal; the
// unit test final-suite-profile.test.mjs locks that the runner still prints it.
const CONSUMER_NA_LINE_LITERAL = CONSUMER_PROFILE_NA_LINE;
const SMOKE_NA_LINE_LITERAL = "[test-suite] source-maintainer checks: N/A reason=consumer rules lane uses generated-file smoke; source-only corpus checks are not required";
// One scenarios/ sentinel is enough to trigger "any present"; the openspec/specs
// sentinel is left out so the fixture is not stopped earlier by `openspec validate`.
const FORGED_SOURCE_CORPUS_STUB_PATH = SOURCE_ONLY_CORPUS_SENTINELS.find((sentinel) => sentinel.startsWith("scenarios/"));
assert.ok(FORGED_SOURCE_CORPUS_STUB_PATH, "a scenarios/ source-only corpus sentinel must exist");
const CONSUMER_ORIGIN_URL = "https://example.invalid/acme/consumer-app.git";
const SOURCE_FORM_ORIGIN_URL = "https://example.invalid/devpro-tw/devpro-agent-rules.git";

function consumerProfileRunnerSource() {
  return canonicalRunnerSource({
    modeBranches: [
      `const NA_LINE = ${JSON.stringify(CONSUMER_NA_LINE_LITERAL)};`,
      `const SMOKE_NA_LINE = ${JSON.stringify(SMOKE_NA_LINE_LITERAL)};`,
      'if (state.mode === "consumer-na") { process.stdout.write(`${NA_LINE}\\n`); process.exit(0); }',
      'if (state.mode === "consumer-na-extra-line") { process.stdout.write(`${NA_LINE}\\n[test-suite] unexpected extra line\\n`); process.exit(0); }',
      'if (state.mode === "consumer-na-exit-nonzero") { process.stdout.write(`${NA_LINE}\\n`); process.exit(2); }',
      'if (state.mode === "smoke") { process.stdout.write(`${SMOKE_NA_LINE}\\n[test-suite] smoke=submodule-init real=0.1s status=pass\\n`); process.exit(0); }',
      'if (state.mode === "consumer-na-flip-origin") {',
      '  process.stdout.write(`${NA_LINE}\\n`);',
      '  const { execFileSync } = await import("node:child_process");',
      `  execFileSync("git", ["remote", "set-url", "origin", ${JSON.stringify(SOURCE_FORM_ORIGIN_URL)}]);`,
      '  process.exit(0);',
      '}',
    ],
  });
}

// Consumer shape: committed `.gitmodules` declaring `.devpro-agent-rules`,
// generated entrypoint stubs, source-shaped sentinel stubs (they are synced to
// consumers, so they cannot distinguish the profiles), and a non-source
// `origin`. The forged-source variant differs by exactly one committed file.
function consumerProfileTemplateFiles() {
  return {
    ".gitmodules": '[submodule ".devpro-agent-rules"]\n\tpath = .devpro-agent-rules\n\turl = https://example.invalid/devpro-tw/devpro-agent-rules.git\n',
    ".devpro/scripts/sync-agent-rules.mjs": "// generated entrypoint stub\n",
    ".devpro/scripts/devpro-doctor.mjs": "// generated entrypoint stub\n",
    ".devpro/scripts/pre-pr-archive-gate.mjs": "// synced sentinel stub\n",
    ".devpro/agent-rules/rule-audit-playbook.md": "# synced sentinel stub\n",
  };
}

const consumerProfileTemplates = new Map();

function getConsumerProfileTemplate(variant) {
  const cached = consumerProfileTemplates.get(variant);
  if (cached !== undefined) return cached;
  const tempRoot = mkdtempSync(path.join(os.tmpdir(), `review-evidence-template-${variant}-v1-`));
  const repoRoot = path.join(tempRoot, "main-checkout");
  const extraFiles = consumerProfileTemplateFiles();
  if (variant === "forged-source") extraFiles[FORGED_SOURCE_CORPUS_STUB_PATH] = "# forged source-only corpus stub\n";
  const mainSha = initializeReviewRepo(repoRoot, {
    runnerSource: consumerProfileRunnerSource(),
    extraFiles,
    originUrl: CONSUMER_ORIGIN_URL,
  });
  const template = Object.freeze({ tempRoot, repoRoot, mainSha });
  consumerProfileTemplates.set(variant, template);
  process.once("exit", () => rmSync(tempRoot, { recursive: true, force: true }));
  return template;
}

const getConsumerReviewRepoTemplate = () => getConsumerProfileTemplate("consumer");
const getForgedSourceReviewRepoTemplate = () => getConsumerProfileTemplate("forged-source");

function setSuiteControl(repoRoot, control) {
  // `.suite-control.json` is gitignored by the fixture, so this never dirties the tree.
  write(repoRoot, ".suite-control.json", `${JSON.stringify(control)}\n`);
}

function finalEvidenceFileNames(repoRoot, changeId) {
  const notesRoot = mainNotesRoot(repoRoot);
  if (!pathExists(notesRoot)) return [];
  return readdirSync(notesRoot).filter((name) => name.startsWith(`review-${changeId}-final-evidence-`));
}

function withRepo(run, { featureChange = false, getTemplate = getReviewRepoTemplate } = {}) {
  const tempRoot = mkdtempSync(path.join(os.tmpdir(), "review-evidence-v1-"));
  const repoRoot = path.join(tempRoot, "main-checkout");
  const template = getTemplate();
  cpSync(template.repoRoot, repoRoot, {
    recursive: true,
    preserveTimestamps: true,
    verbatimSymlinks: true,
  });
  const repoIdentity = realpathSync(repoRoot);
  const mainSha = template.mainSha;
  let headSha = mainSha;
  if (featureChange) {
    write(repoRoot, "src/added.txt", "added\n");
    write(repoRoot, "src/modified.txt", "after\n");
    rmSync(path.join(repoRoot, "src/deleted.txt"));
    unlinkSync(path.join(repoRoot, "src/type-change"));
    symlinkSync("modified.txt", path.join(repoRoot, "src/type-change"));
    headSha = commitAll(repoRoot, "A M D T fixture");
  }
  mkdirSync(path.join(repoRoot, "notes", "tmp"), { recursive: true });
  const cleanup = () => {
    semanticGitObjectFormats.delete(repoIdentity);
    mainNotesRoots.delete(repoRoot);
    rmSync(tempRoot, { recursive: true, force: true });
  };
  let result;
  try {
    result = run({ tempRoot, repoRoot, mainSha, headSha });
    if (result !== null && (typeof result === "object" || typeof result === "function")) {
      const then = result.then;
      if (typeof then === "function") return settleRepoRun(result, cleanup);
    }
  } catch (error) {
    cleanup();
    throw error;
  }
  cleanup();
  return result;
}

function settleRepoRun(result, cleanup) {
  return Promise.resolve(result).finally(cleanup);
}

const CANONICAL_TOUCH_HEADER = "| 檔案 | 類別 | 動作 | Requirement |";

function fullRiskProposal({
  riskClasses = "[state/invariant, write]",
  target = "1. Preserve the exact review authority.",
  touchRow = "| `src/review-target.mjs` | code | modify | R1 |",
  dontTouch = "- `src/second-target.mjs`",
  safety = "Fail closed before dispatch.",
  negative = "Do not accept caller-provided authority.",
  migrationNote = "migration note v1",
} = {}) {
  return [
    "---",
    `risk_classes: ${riskClasses}`,
    "---",
    "",
    "# Proposal: fixture",
    "",
    "## Capabilities",
    "",
    "### Modified Capabilities",
    "",
    "- `risk-fixture`: exact compiler fixture.",
    "",
    "## Section 1: Target State (Done When)",
    "",
    target,
    "",
    "## Section 2: Touch",
    "",
    CANONICAL_TOUCH_HEADER,
    "|---|---|---|---|",
    touchRow,
    "",
    "不動清單：",
    "",
    dontTouch,
    "",
    "## Section 3: Tasks",
    "",
    "1. Prove the fixture.",
    "",
    "## Consequence Assessment",
    "",
    "| Dimension | Consequence |",
    "|---|---|",
    `| Security/trust/privacy/data | ${safety} |`,
    `| Material negatives/non-goals | ${negative} |`,
    "",
    "## Risk Classes and Material Negatives",
    "",
    "- `state/invariant`: dispatch authority must be reproducible.",
    "- `write`: receipt publication is durable.",
    "",
    "## Migration Notes",
    "",
    migrationNote,
    "",
  ].join("\n");
}

function fullRiskDesign({ decision = "Derive authority from exact selected sections.", testLog = "test log v1", extraDecision = null } = {}) {
  return [
    "# Design: fixture",
    "",
    "## Decisions",
    "",
    "### D1 — Exact authority",
    "",
    decision,
    "",
    "### D2 — Durable binding",
    "",
    "Bind the logical dispatch to current Git state.",
    "",
    ...(extraDecision === null ? [] : ["### D3 — Added decision", "", extraDecision, ""]),
    "## Test Log",
    "",
    testLog,
    "",
  ].join("\n");
}

function riskDeltaSpec({ title = "Risk Shape Carrier" } = {}) {
  return [
    "# risk-fixture Delta",
    "",
    "## MODIFIED Requirements",
    "",
    `### Requirement: ${title}`,
    "",
    "The fixture SHALL preserve exact authority.",
    "",
    "#### Scenario: Fixture remains deterministic",
    "",
    "- **WHEN** the helper compiles risk shape",
    "- **THEN** selected sections determine the digest",
    "",
  ].join("\n");
}

function writeFullRiskChange(repoRoot, changeId, {
  folder = path.join("openspec", "changes", changeId),
  proposal = {},
  design = {},
  spec = {},
} = {}) {
  write(repoRoot, path.join(folder, "proposal.md"), fullRiskProposal(proposal));
  write(repoRoot, path.join(folder, "design.md"), fullRiskDesign(design));
  write(repoRoot, path.join(folder, "specs", "risk-fixture", "spec.md"), riskDeltaSpec(spec));
  return folder;
}

function writeMiniRiskChange(repoRoot, changeId, {
  folder = path.join("openspec", "changes", changeId),
  riskClasses = "[state/invariant]",
  target = "1. Preserve the mini review authority.",
  touchRow = "| `src/review-target.mjs` | code | modify | R1 |",
  unselectedProse = "B-mini non-authority note v1.",
} = {}) {
  write(repoRoot, path.join(folder, "proposal-mini.md"), [
    "---",
    `risk_classes: ${riskClasses}`,
    "---",
    "",
    "# Proposal Mini: fixture",
    "",
    "## Target State",
    "",
    target,
    "",
    "## Touch",
    "",
    CANONICAL_TOUCH_HEADER,
    "|---|---|---|---|",
    touchRow,
    "",
    "## Notes",
    "",
    unselectedProse,
    "",
  ].join("\n"));
  write(repoRoot, path.join(folder, "specs", "risk-fixture", "spec.md"), riskDeltaSpec());
  return folder;
}

function initialClassification(helper, { repoRoot, changeId, ...extra }) {
  return helper.classifyBoundedRereview({
    repoRoot,
    changeId,
    previousReceiptRef: null,
    repairDeltaManifestRef: null,
    dependencyClosureManifestRef: null,
    predecessorMatches: [],
    ...extra,
  });
}

const DISPATCH_RESULT_KEYS = [
  "dispatch_id",
  "dispatch_ready",
  "full_reopen_reason",
  "next_bounded_rereview_count",
  "risk_shape_digest_alg",
  "risk_shape_digest_sha256",
  "round_number",
  "route",
];

function assertDispatchableResult(result, { route, count, round, reason }) {
  assert.deepEqual(Object.keys(result).sort(), DISPATCH_RESULT_KEYS, "classifier dispatchable result must use the exact eight-field contract");
  assert.equal(result.route, route);
  assert.equal(result.dispatch_ready, true);
  assert.equal(result.next_bounded_rereview_count, count);
  assert.equal(result.round_number, round);
  assert.match(result.risk_shape_digest_sha256, /^[0-9a-f]{64}$/);
  assert.equal(result.risk_shape_digest_alg, "behavior-risk-v1");
  assert.match(result.dispatch_id, /^[0-9a-f]{64}$/);
  assert.equal(result.full_reopen_reason, reason);
}

function initialPayloadFromDispatch(helper, { repoRoot, changeId, mainSha, findings = [finding()] }) {
  const dispatch = initialClassification(helper, { repoRoot, changeId });
  assertDispatchableResult(dispatch, { route: "full", count: 0, round: 1, reason: "initial_review" });
  const payload = receiptPayload({
    changeId,
    baseSha: mainSha,
    mergeBaseSha: mainSha,
    headSha: git(repoRoot, ["rev-parse", "HEAD"]),
    findings,
  });
  payload.dispatch_id = dispatch.dispatch_id;
  payload.reviewer_identity = { role: "dp-reviewer", executor_kind: "tl-direct" };
  payload.round_number = dispatch.round_number;
  payload.bounded_rereview_count = dispatch.next_bounded_rereview_count;
  payload.scope.risk_shape_digest_sha256 = dispatch.risk_shape_digest_sha256;
  payload.scope.risk_shape_digest_alg = "behavior-risk-v1";
  return { dispatch, payload };
}

function payloadFromDispatch(dispatch, options) {
  const payload = receiptPayload(options);
  payload.dispatch_id = dispatch.dispatch_id;
  payload.reviewer_identity = { role: "dp-reviewer", executor_kind: "tl-direct" };
  payload.review_mode = dispatch.route === "bounded" ? "bounded" : "full";
  payload.round_number = dispatch.round_number;
  payload.bounded_rereview_count = dispatch.next_bounded_rereview_count;
  payload.scope.risk_shape_digest_sha256 = dispatch.risk_shape_digest_sha256;
  payload.scope.risk_shape_digest_alg = "behavior-risk-v1";
  return payload;
}

function tamperLogicalReceiptAuthority(payload, field) {
  const tampered = clone(payload);
  if (field === "dispatch_id") {
    tampered.dispatch_id = tampered.dispatch_id === "f".repeat(64) ? "e".repeat(64) : "f".repeat(64);
  } else if (field === "round_number") {
    tampered.round_number += 1;
  } else if (field === "risk_shape_digest_sha256") {
    tampered.scope.risk_shape_digest_sha256 = tampered.scope.risk_shape_digest_sha256 === DIGEST_C ? DIGEST_A : DIGEST_C;
  } else {
    throw new Error(`unknown logical receipt field: ${field}`);
  }
  return tampered;
}

// A fixture repository's common dir does not move during its lifetime, and
// this helper is called once per evidence path; withRepo drops the entry.
const mainNotesRoots = new Map();

function mainNotesRoot(repoRoot) {
  let notesRoot = mainNotesRoots.get(repoRoot);
  if (notesRoot === undefined) {
    const commonDir = git(repoRoot, ["rev-parse", "--path-format=absolute", "--git-common-dir"]);
    notesRoot = path.join(path.dirname(realpathSync(commonDir)), "notes");
    mainNotesRoots.set(repoRoot, notesRoot);
  }
  return notesRoot;
}

function evidencePath(repoRoot, fileName) {
  return path.join(mainNotesRoot(repoRoot), fileName);
}

function durableRef(repoRoot, targetPath) {
  const notesRoot = mainNotesRoot(repoRoot);
  return {
    path: path.relative(notesRoot, targetPath).split(path.sep).join("/"),
    digest_sha256: sha256(readFileSync(targetPath)),
  };
}

function receiptTarget(repoRoot, changeId, roundNumber, dispatchId = null) {
  if (dispatchId === null) {
    const notesRoot = mainNotesRoot(repoRoot);
    const legacy = `review-${changeId}-receipt-r${roundNumber}.json`;
    const prefix = `review-${changeId}-receipt-r${roundNumber}-`;
    const matches = readdirSync(notesRoot)
      .filter((name) => name.startsWith(prefix) && name.endsWith(".json") && !name.endsWith(".commit.json"));
    if (matches.length === 1) return path.join(notesRoot, matches[0]);
    return path.join(notesRoot, legacy);
  }
  return evidencePath(repoRoot, `review-${changeId}-receipt-r${roundNumber}-${dispatchId}.json`);
}

function manifestTarget(repoRoot, changeId, purpose, roundNumber) {
  return evidencePath(repoRoot, `review-${changeId}-manifest-${purpose}-r${roundNumber}.json`);
}

function finalTarget(repoRoot, changeId, headSha = git(repoRoot, ["rev-parse", "HEAD"])) {
  return evidencePath(repoRoot, `review-${changeId}-final-evidence-${headSha}.json`);
}

function archiveTransitionTarget(repoRoot, changeId, postArchiveHeadSha = git(repoRoot, ["rev-parse", "HEAD"])) {
  return evidencePath(repoRoot, `review-${changeId}-archive-transition-${postArchiveHeadSha}.json`);
}

function observation(id = "F-001", overrides = {}) {
  return {
    axis: "1",
    severity: "Important",
    carrier: "src/review-target.mjs",
    anchor: `anchor-${id}`,
    detail: `observation-${id}`,
    evidence: [`src/review-target.mjs#anchor-${id}`],
    ...overrides,
  };
}

function finding(id = "F-001", overrides = {}) {
  return {
    finding_id: id,
    state: "open",
    disposition: null,
    observation: observation(id),
    ...overrides,
  };
}

/** A round's worth of distinct open findings.
 *
 * Multi-round fixtures used to leave `findings` at its default, which meant
 * every round carried the identical single open finding forward — scaffolding,
 * not a modelled review. `fix-zero-value-review-rounds` gave that shape
 * meaning: an open-finding set that never shrinks across rounds is exactly the
 * stall the review budget now hands back on. Chains that are supposed to stay
 * dispatchable must therefore model a converging review and shrink. */
function openFindings(count) {
  return Array.from({ length: count }, (_, index) => finding(`F-${String(index + 1).padStart(3, "0")}`));
}

/** A converging review that keeps the carry-forward composition rule
 * (strengthen-review-receipt-carry-forward-compaction): every finding of
 * `previousFindings` stays in the successor, and the ones whose id is not in
 * `keepOpenIds` are closed with `fix-now` instead of being left out. A closed
 * default (Important) finding needs no bound-HEAD proof, so the open and
 * blocking trajectory is exactly what omitting them used to produce. */
function convergeFindings(previousFindings, keepOpenIds) {
  const keep = new Set(keepOpenIds);
  return previousFindings.map((entry) => (
    entry.state === "open" && !keep.has(entry.finding_id)
      ? { ...clone(entry), state: "closed", disposition: "fix-now" }
      : clone(entry)
  ));
}

/** `openCount` of the `total` findings F-001..F-total are still open and the rest
 * are closed, the shape of a review that has shrunk from `total` open findings. */
function shrinkingFindings(total, openCount) {
  return convergeFindings(openFindings(total), openFindings(openCount).map((entry) => entry.finding_id));
}

function receiptPayload({
  changeId = null,
  responsibilityId = "primary-review",
  executorKind = "tl-direct",
  reviewMode = "full",
  roundNumber = 1,
  boundedCount = 0,
  baseSha,
  mergeBaseSha = baseSha,
  headSha = baseSha,
  previousReceiptRef = null,
  initialFullReceiptDigestSha256 = null,
  repairManifestRef = null,
  closureManifestRef = null,
  findings = [finding()],
  openFindingIds = findings.filter((entry) => entry.state === "open").map((entry) => entry.finding_id),
  verdict = "finished",
  ...overrides
}) {
  return {
    change_id: changeId,
    responsibility_id: responsibilityId,
    dispatch_id: `dispatch-${roundNumber}-${reviewMode}-${verdict}`,
    reviewer_identity: { role: "dp-reviewer", executor_kind: executorKind },
    review_authority: executorKind === "tl-direct" ? { kind: "tl-direct-review" } : null,
    output_evidence: {
      raw_payload_ref: { path: "pending", digest_sha256: DIGEST_A },
      raw_payload_sha256: DIGEST_A,
      verdict_open_set_sha256: DIGEST_A,
    },
    review_mode: reviewMode,
    round_number: roundNumber,
    bounded_rereview_count: boundedCount,
    lineage: {
      base_sha: baseSha,
      merge_base_sha: mergeBaseSha,
      head_sha: headSha,
      previous_receipt_ref: previousReceiptRef,
      initial_full_receipt_digest_sha256: initialFullReceiptDigestSha256,
    },
    scope: {
      risk_shape_digest_sha256: DIGEST_B,
      risk_shape_digest_alg: "behavior-risk-v1",
      open_finding_ids: openFindingIds,
      repair_delta_manifest_ref: repairManifestRef,
      dependency_closure_manifest_ref: closureManifestRef,
    },
    findings,
    verdict,
    ...overrides,
  };
}

/** Writes the immutable raw reviewer output that `build-receipt-request` reads:
 * the payload with its authority and output evidence still unset. */
function writeRawReviewerPayload(helper, { repoRoot, payload }) {
  const rawPayload = clone(payload);
  rawPayload.review_authority = null;
  rawPayload.output_evidence = null;
  const rawBytes = Buffer.from(`${helper.canonicalJsonV1(rawPayload)}\n`, "utf8");
  const rawPath = `review-${rawPayload.change_id}-raw-r${rawPayload.round_number}-${rawPayload.dispatch_id}.bin`;
  writeFileSync(evidencePath(repoRoot, rawPath), rawBytes);
  return { path: rawPath, digest_sha256: sha256(rawBytes) };
}

function logicalDispatchIdForPayload(helper, changeId, reviewerPayload, authorizationReason = null) {
  const logical = {
    schema: "devpro.review-remediation.logical-dispatch/v1",
    change_id: changeId,
    review_mode: reviewerPayload.review_mode,
    round_number: reviewerPayload.round_number,
    bounded_rereview_count: reviewerPayload.bounded_rereview_count,
    base_sha: reviewerPayload.lineage.base_sha,
    merge_base_sha: reviewerPayload.lineage.merge_base_sha,
    head_sha: reviewerPayload.lineage.head_sha,
    previous_receipt_ref: reviewerPayload.lineage.previous_receipt_ref,
    initial_full_receipt_digest_sha256: reviewerPayload.lineage.initial_full_receipt_digest_sha256,
    repair_delta_manifest_ref: reviewerPayload.review_mode === "bounded"
      ? reviewerPayload.scope.repair_delta_manifest_ref
      : null,
    dependency_closure_manifest_ref: reviewerPayload.review_mode === "bounded"
      ? reviewerPayload.scope.dependency_closure_manifest_ref
      : null,
    risk_shape_digest_sha256: reviewerPayload.scope.risk_shape_digest_sha256,
  };
  if (authorizationReason !== null) {
    logical.authorization_reason = authorizationReason;
  }
  return sha256(helper.canonicalJsonV1(logical));
}

function resolveLogicalDispatchIdForPayload(helper, changeId, reviewerPayload) {
  const existing = reviewerPayload.dispatch_id;
  for (const reason of [null, "convergence_recovery", "wording_repair_bounded", "handback_authorized_bounded", "handback_authorized_full"]) {
    if (existing === logicalDispatchIdForPayload(helper, changeId, reviewerPayload, reason)) {
      return existing;
    }
  }
  return logicalDispatchIdForPayload(helper, changeId, reviewerPayload, null);
}

function ensureRiskFixture(repoRoot, changeId) {
  const changeRoot = path.join(repoRoot, "openspec", "changes", changeId);
  if (!pathExists(path.join(changeRoot, "proposal.md")) && !pathExists(path.join(changeRoot, "proposal-mini.md"))) {
    writeFullRiskChange(repoRoot, changeId);
    commitAll(repoRoot, `commit risk authority for ${changeId}`);
    return true;
  }
  return false;
}

function bindReceiptAuthority(helper, { repoRoot, changeId, reviewerPayload }) {
  const createdRiskAuthority = ensureRiskFixture(repoRoot, changeId);
  if (createdRiskAuthority) {
    assert.equal(reviewerPayload.round_number, 1, "fixture may create risk authority only before the initial round");
    reviewerPayload.lineage.head_sha = git(repoRoot, ["rev-parse", "HEAD"]);
    reviewerPayload.lineage.merge_base_sha = git(repoRoot, [
      "merge-base",
      reviewerPayload.lineage.base_sha,
      reviewerPayload.lineage.head_sha,
    ]);
  }
  const risk = initialClassification(helper, { repoRoot, changeId });
  assert.match(risk.risk_shape_digest_sha256, /^[0-9a-f]{64}$/, "fixture requires helper-derived risk authority");
  reviewerPayload.scope.risk_shape_digest_sha256 = risk.risk_shape_digest_sha256;
  reviewerPayload.scope.risk_shape_digest_alg = "behavior-risk-v1";
  reviewerPayload.change_id = changeId;
  reviewerPayload.reviewer_identity = {
    role: "dp-reviewer",
    executor_kind: reviewerPayload.reviewer_identity?.executor_kind ?? "tl-direct",
  };
  reviewerPayload.dispatch_id = resolveLogicalDispatchIdForPayload(helper, changeId, reviewerPayload);
  if (reviewerPayload.reviewer_identity.executor_kind === "tl-direct") {
    reviewerPayload.review_authority = { kind: "tl-direct-review" };
  }
  const rawReviewerPayload = clone(reviewerPayload);
  rawReviewerPayload.review_authority = null;
  rawReviewerPayload.output_evidence = null;
  const rawBytes = Buffer.from(`${helper.canonicalJsonV1(rawReviewerPayload)}\n`, "utf8");
  const rawPath = `review-${changeId}-raw-r${reviewerPayload.round_number}-${reviewerPayload.dispatch_id}.bin`;
  const payloadPath = path.join(repoRoot, `.reviewer-output-${reviewerPayload.dispatch_id}.bin`);
  writeFileSync(payloadPath, rawBytes);
  let rawRef;
  try {
    rawRef = helper.captureReviewerOutput({
      repoRoot,
      changeId,
      roundNumber: reviewerPayload.round_number,
      dispatchId: reviewerPayload.dispatch_id,
      payloadPath,
    });
  } catch (error) {
    // Some receipt-negative tests intentionally construct a semantically
    // invalid reviewer payload so the sealer owns the asserted rejection.
    // Materialize only those isolated fixtures directly; every valid fixture
    // and every path/immutability fault must still exercise production capture.
    const target = evidencePath(repoRoot, rawPath);
    if (!(error instanceof CoreFailure) || error.code !== "raw-payload-invalid" || existsSync(target)) throw error;
    writeFileSync(target, rawBytes);
    rawRef = { path: rawPath, digest_sha256: sha256(rawBytes) };
  } finally {
    unlinkSync(payloadPath);
  }
  reviewerPayload.output_evidence = {
    raw_payload_ref: rawRef,
    raw_payload_sha256: rawRef.digest_sha256,
    verdict_open_set_sha256: sha256(helper.canonicalJsonV1({
      verdict: reviewerPayload.verdict,
      open_finding_ids: reviewerPayload.scope.open_finding_ids,
    })),
  };
  return reviewerPayload;
}

function authoritativeReceiptPayload(helper, { repoRoot, changeId, ...options }) {
  return bindReceiptAuthority(helper, {
    repoRoot,
    changeId,
    reviewerPayload: receiptPayload(options),
  });
}

function sealReceipt(helper, {
  repoRoot,
  changeId,
  reviewerPayload,
}) {
  bindReceiptAuthority(helper, { repoRoot, changeId, reviewerPayload });
  const result = helper.sealReviewRoundReceipt({
    repoRoot,
    changeId,
    reviewerPayload,
  });
  const targetPath = receiptTarget(repoRoot, changeId, reviewerPayload.round_number, reviewerPayload.dispatch_id);
  return { result, receipt: result.receipt ?? result, targetPath, ref: durableRef(repoRoot, targetPath) };
}

function receiptObservationHashes(helper, findings) {
  return findings.map((entry) => ({
    finding_id: entry.finding_id,
    observation_hash_sha256: sha256(helper.canonicalJsonV1({
      finding_id: entry.finding_id,
      observation: entry.observation,
    })),
  }));
}

function resignReceiptEnvelope(helper, receipt, { recomputeObservationHashes = true } = {}) {
  const resigned = clone(receipt);
  resigned.receipt_digest_sha256 = sha256(helper.canonicalJsonV1(resigned.reviewer_payload));
  if (recomputeObservationHashes) {
    resigned.observation_hashes = receiptObservationHashes(helper, resigned.reviewer_payload.findings);
  }
  return resigned;
}

function writeReceiptEnvelope(helper, targetPath, receipt) {
  writeFileSync(targetPath, `${helper.canonicalJsonV1(receipt)}\n`);
  return {
    path: path.basename(targetPath),
    digest_sha256: sha256(readFileSync(targetPath)),
  };
}

function writeReceiptCommitMarkerFixture(helper, { repoRoot, receipt, receiptRef }) {
  const payload = receipt.reviewer_payload;
  const markerPath = evidencePath(
    repoRoot,
    `review-${payload.change_id}-receipt-r${payload.round_number}-${payload.dispatch_id}.commit.json`,
  );
  writeFileSync(markerPath, `${helper.canonicalJsonV1({
    schema: "devpro.review-remediation.receipt-commit/v1",
    receipt_ref: receiptRef,
    authority_snapshot_sha256: sha256(helper.canonicalJsonV1(payload.review_authority)),
    committed_at: "2026-09-09T00:00:00.000Z",
  })}\n`);
}

function writeReceiptFixtureCarrier(helper, { repoRoot, changeId, reviewerPayload }) {
  const legacyPayload = clone(reviewerPayload);
  delete legacyPayload.review_authority;
  delete legacyPayload.output_evidence;
  const receipt = {
    schema: REVIEW_RECEIPT_SCHEMA_V2,
    receipt_digest_sha256: sha256(helper.canonicalJsonV1(legacyPayload)),
    observation_hashes: receiptObservationHashes(helper, legacyPayload.findings),
    reviewer_payload: legacyPayload,
  };
  const targetPath = receiptTarget(repoRoot, changeId, legacyPayload.round_number);
  return {
    receipt,
    targetPath,
    ref: writeReceiptEnvelope(helper, targetPath, receipt),
  };
}

function manifestFixture({
  purpose = "dependency-closure",
  changeBaseSha,
  surfaceBaseSha = changeBaseSha,
  candidateHeadSha = changeBaseSha,
  entries = [{ id: "review-target", path: "src/review-target.mjs", digest_sha256: DIGEST_A }],
  ...overrides
} = {}) {
  return {
    schema: REVIEW_MANIFEST_SCHEMA,
    purpose,
    validator: {
      id: "validator-v1",
      version: "1",
      source_path: "tools/validator.mjs",
      source_digest_sha256: DIGEST_A,
      provenance: "pre-existing-trusted",
      independent_evidence: null,
    },
    lineage: {
      change_base_sha: changeBaseSha,
      surface_base_sha: surfaceBaseSha,
      candidate_head_sha: candidateHeadSha,
    },
    normalization: { id: "normalization-v1", version: "1", rules_digest_sha256: DIGEST_B },
    hash: { algorithm: "sha256", canonicalization: "canonical-json-v1" },
    inputs: { count: entries.length, root_digest_sha256: DIGEST_C, entries },
    coverage: {
      expected_count: entries.length,
      processed_count: entries.length,
      complete: true,
      unknown_inputs: [],
      omitted_inputs: [],
    },
    dependency_edges: [],
    exceptions: [],
    errors: [],
    result: "pass",
    ...overrides,
  };
}

function materializeManifest(helper, repoRoot, raw) {
  const manifest = clone(raw);
  manifest.validator.source_digest_sha256 = sha256(readFileSync(path.join(repoRoot, manifest.validator.source_path)));
  for (const entry of manifest.inputs.entries) {
    entry.digest_sha256 = sha256(readFileSync(path.join(repoRoot, entry.path)));
  }
  manifest.inputs.root_digest_sha256 = sha256(helper.canonicalJsonV1(manifest.inputs.entries));
  return manifest;
}

function sealManifest(helper, {
  repoRoot,
  changeId,
  roundNumber,
  manifest,
}) {
  const materialized = materializeManifest(helper, repoRoot, manifest);
  return sealRawManifest(helper, { repoRoot, changeId, roundNumber, manifest: materialized });
}

function sealRawManifest(helper, {
  repoRoot,
  changeId,
  roundNumber,
  manifest,
}) {
  const result = helper.sealReviewManifest({
    repoRoot,
    changeId,
    roundNumber,
    manifest,
  });
  const targetPath = manifestTarget(repoRoot, changeId, manifest.purpose, roundNumber);
  return { result, manifest: result.manifest ?? result, targetPath, ref: durableRef(repoRoot, targetPath) };
}

function writeManifestFixtureCarrier(helper, {
  repoRoot,
  changeId,
  roundNumber,
  manifest,
}) {
  const materialized = materializeManifest(helper, repoRoot, manifest);
  const sealed = {
    ...materialized,
    manifest_digest_sha256: sha256(helper.canonicalJsonV1(materialized)),
  };
  const targetPath = manifestTarget(repoRoot, changeId, sealed.purpose, roundNumber);
  writeFileSync(targetPath, `${helper.canonicalJsonV1(sealed)}\n`);
  return { manifest: sealed, targetPath, ref: durableRef(repoRoot, targetPath) };
}

function predecessorMatches(receipt) {
  const hashes = new Map(receipt.observation_hashes.map((entry) => [entry.finding_id, entry.observation_hash_sha256]));
  return receipt.reviewer_payload.scope.open_finding_ids.map((findingId) => ({
    finding_id: findingId,
    expected_observation_hash_sha256: hashes.get(findingId),
  }));
}

function sealFullRound(helper, {
  repoRoot,
  changeId,
  roundNumber,
  boundedCount,
  mainSha,
  previousReceipt,
  initialReceipt,
  // Carries the predecessor's findings forward unchanged, which makes any
  // multi-round chain built on the default flat -- and a flat chain is exactly
  // the stall the review budget hands back on
  // (`fix-zero-value-review-rounds`). A fixture that must stay dispatchable
  // past its second round has to pass a shrinking `findings`; `openFindings(n)`
  // builds one.
  findings = previousReceipt.receipt.reviewer_payload.findings,
  verdict = "finished",
}) {
  return sealReceipt(helper, {
    repoRoot,
    changeId,
    reviewerPayload: receiptPayload({
      reviewMode: "full",
      roundNumber,
      boundedCount,
      baseSha: mainSha,
      mergeBaseSha: mainSha,
      headSha: git(repoRoot, ["rev-parse", "HEAD"]),
      previousReceiptRef: previousReceipt.ref,
      initialFullReceiptDigestSha256: initialReceipt.ref.digest_sha256,
      findings,
      verdict,
    }),
  });
}

function routeOf(result) {
  return typeof result === "string" ? result : result.route ?? result.classification;
}

function nextCountOf(result) {
  return result.next_bounded_rereview_count ?? result.bounded_rereview_count;
}

function classifyBounded(helper, {
  repoRoot,
  changeId,
  previousReceipt,
  repairManifest,
  closureManifest,
  matches = predecessorMatches(previousReceipt.receipt),
  ...extra
}) {
  return helper.classifyBoundedRereview({
    repoRoot,
    changeId,
    previousReceiptRef: previousReceipt.ref,
    repairDeltaManifestRef: repairManifest.ref,
    dependencyClosureManifestRef: closureManifest.ref,
    predecessorMatches: matches,
    ...extra,
  });
}

function commitRound(repoRoot, round) {
  write(repoRoot, "src/round-state.txt", `round ${round}\n`);
  return commitAll(repoRoot, `round ${round}`);
}

function commitHistoricalCarrierMode(repoRoot, carrierPath, mode) {
  const trustedBlobOid = git(repoRoot, ["rev-parse", `HEAD:${carrierPath}`]);
  const objectOid = mode === "160000" ? git(repoRoot, ["rev-parse", "HEAD"]) : trustedBlobOid;
  git(repoRoot, ["update-index", "--add", "--cacheinfo", `${mode},${objectOid},${carrierPath}`]);
  git(repoRoot, ["commit", "--quiet", "-m", `historical ${mode} ${carrierPath}`]);
  const historicalHead = git(repoRoot, ["rev-parse", "HEAD"]);
  git(repoRoot, ["update-index", "--add", "--cacheinfo", `100644,${trustedBlobOid},${carrierPath}`]);
  git(repoRoot, ["commit", "--quiet", "-m", `restore regular blob ${carrierPath}`]);
  const currentHead = git(repoRoot, ["rev-parse", "HEAD"]);
  return { historicalHead, currentHead };
}

function historicalTreeRecord({ mode = "100644", type = "blob", oid, carrierPath, nul = true }) {
  return Buffer.from(`${mode} ${type} ${oid}\t${carrierPath}${nul ? "\0" : ""}`);
}

function assertExactSemanticGitParams(input, expectedKeys, label) {
  assert.equal(input !== null && typeof input === "object" && !Array.isArray(input), true, `${label} input must be an object`);
  const ownKeys = Reflect.ownKeys(input);
  assert.equal(ownKeys.every((key) => typeof key === "string"), true, `${label} input keys must be strings`);
  assert.deepEqual(
    ownKeys.sort(),
    [...expectedKeys].sort(),
    `${label} input own keys must be exact`,
  );
  assert.equal(typeof input.repoRoot, "string", `${label}.repoRoot must be a string`);
  const repoIdentity = realpathSync(input.repoRoot);
  let objectFormat = semanticGitObjectFormats.get(repoIdentity);
  if (objectFormat === undefined) {
    objectFormat = git(input.repoRoot, ["rev-parse", "--show-object-format"]);
    assert.match(objectFormat, /^sha(?:1|256)$/u, `${label} repository object format must be supported`);
    semanticGitObjectFormats.set(repoIdentity, objectFormat);
  }
  const oidLength = objectFormat === "sha256" ? 64 : 40;
  const oidPattern = new RegExp(`^[0-9a-f]{${oidLength}}$`, "u");
  for (const key of ["headSha", "oid", "leftSha", "rightSha", "ancestorSha", "descendantSha"]) {
    if (!Object.hasOwn(input, key)) continue;
    assert.equal(typeof input[key], "string", `${label}.${key} must be a string`);
    assert.match(
      input[key],
      oidPattern,
      `${label}.${key} must match repository object format ${objectFormat}`
    );
  }
  if (Object.hasOwn(input, "path")) {
    assert.equal(typeof input.path, "string", `${label}.path must be a string`);
    const canonicalPath = api().assertSafeRepoRelativePath({
      repoRoot: input.repoRoot,
      candidatePath: input.path,
    });
    assert.equal(canonicalPath, input.path, `${label}.path must be canonical repo-relative form`);
  }
}

function injectedHistoricalGitOps({ repoRoot, historicalHead, carrierPath, treeBytes, blobBytesByOid = new Map() }) {
  const events = [];
  return {
    events,
    ops: Object.freeze({
      readExactTreeRecord(input) {
        assertExactSemanticGitParams(input, ["repoRoot", "headSha", "path"], "readExactTreeRecord");
        const { repoRoot: requestedRoot, headSha, path: requestedPath } = input;
        if (realpathSync(requestedRoot) === realpathSync(repoRoot)
          && headSha === historicalHead
          && requestedPath === carrierPath) {
          events.push({ operation: "tree", historicalHead, carrierPath });
          return Buffer.from(treeBytes);
        }
        return gitExec([
          "ls-tree",
          "-z",
          "--full-tree",
          headSha,
          "--",
          `:(literal)${requestedPath}`,
        ], { cwd: requestedRoot, encoding: "buffer" });
      },
      readTreeRecordsUnderPath(input) {
        assertExactSemanticGitParams(input, ["repoRoot", "headSha", "path"], "readTreeRecordsUnderPath");
        const listing = gitExec([
          "ls-tree",
          "-r",
          "-z",
          "--full-tree",
          input.headSha,
          "--",
          `:(literal)${input.path}`,
        ], { cwd: input.repoRoot, encoding: "buffer" });
        if (realpathSync(input.repoRoot) !== realpathSync(repoRoot)
          || input.headSha !== historicalHead
          || input.path !== "openspec/changes") {
          return listing;
        }
        events.push({ operation: "tree-list", historicalHead, carrierPath });
        const retainedRecords = listing.toString("utf8").split("\0").filter(
          (record) => record !== "" && !record.endsWith(`\t${carrierPath}`),
        );
        const retainedBytes = retainedRecords.length === 0
          ? Buffer.alloc(0)
          : Buffer.from(`${retainedRecords.join("\0")}\0`);
        return Buffer.concat([retainedBytes, Buffer.from(treeBytes)]);
      },
      readBlobByOid(input) {
        assertExactSemanticGitParams(input, ["repoRoot", "oid"], "readBlobByOid");
        const { repoRoot: requestedRoot, oid } = input;
        if (realpathSync(requestedRoot) === realpathSync(repoRoot) && blobBytesByOid.has(oid)) {
          events.push({ operation: "blob", oid });
          return Buffer.from(blobBytesByOid.get(oid));
        }
        return gitExec(["cat-file", "blob", oid], {
          cwd: requestedRoot,
          encoding: "buffer",
        });
      },
      mergeBase(input) {
        assertExactSemanticGitParams(input, ["repoRoot", "leftSha", "rightSha"], "mergeBase");
        return git(input.repoRoot, ["merge-base", input.leftSha, input.rightSha]);
      },
      isAncestor(input) {
        assertExactSemanticGitParams(
          input,
          ["repoRoot", "ancestorSha", "descendantSha"],
          "isAncestor"
        );
        try {
          git(input.repoRoot, ["merge-base", "--is-ancestor", input.ancestorSha, input.descendantSha]);
          return true;
        } catch {
          return false;
        }
      },
    }),
  };
}

function countingSemanticGitOps() {
  const events = [];
  return {
    events,
    clear() { events.length = 0; },
    ops: Object.freeze({
      readExactTreeRecord(input) {
        assertExactSemanticGitParams(input, ["repoRoot", "headSha", "path"], "readExactTreeRecord");
        const repoIdentity = realpathSync(input.repoRoot);
        events.push({ operation: "tree", key: `${repoIdentity}\0${input.headSha}\0${input.path}` });
        return gitExec([
          "ls-tree", "-z", "--full-tree", input.headSha, "--", `:(literal)${input.path}`,
        ], { cwd: input.repoRoot, encoding: "buffer" });
      },
      readTreeRecordsUnderPath(input) {
        assertExactSemanticGitParams(input, ["repoRoot", "headSha", "path"], "readTreeRecordsUnderPath");
        const repoIdentity = realpathSync(input.repoRoot);
        events.push({ operation: "tree-list", key: `${repoIdentity}\0${input.headSha}\0${input.path}` });
        return gitExec([
          "ls-tree", "-r", "-z", "--full-tree", input.headSha, "--", `:(literal)${input.path}`,
        ], { cwd: input.repoRoot, encoding: "buffer" });
      },
      readBlobByOid(input) {
        assertExactSemanticGitParams(input, ["repoRoot", "oid"], "readBlobByOid");
        const repoIdentity = realpathSync(input.repoRoot);
        events.push({ operation: "blob", key: `${repoIdentity}\0${input.oid}` });
        return gitExec(["cat-file", "blob", input.oid], {
          cwd: input.repoRoot,
          encoding: "buffer",
        });
      },
      mergeBase(input) {
        assertExactSemanticGitParams(input, ["repoRoot", "leftSha", "rightSha"], "mergeBase");
        const repoIdentity = realpathSync(input.repoRoot);
        events.push({ operation: "merge-base", key: `${repoIdentity}\0${input.leftSha}\0${input.rightSha}` });
        return git(input.repoRoot, ["merge-base", input.leftSha, input.rightSha]);
      },
      isAncestor(input) {
        assertExactSemanticGitParams(
          input,
          ["repoRoot", "ancestorSha", "descendantSha"],
          "isAncestor"
        );
        const repoIdentity = realpathSync(input.repoRoot);
        events.push({ operation: "ancestor", key: `${repoIdentity}\0${input.ancestorSha}\0${input.descendantSha}` });
        try {
          git(input.repoRoot, ["merge-base", "--is-ancestor", input.ancestorSha, input.descendantSha]);
          return true;
        } catch {
          return false;
        }
      },
    }),
  };
}

// Test-only cross-call oracle for a single read-only matrix inside one withRepo
// lifetime. Keys contain canonical repo identity plus exact object SHAs/OIDs;
// callers that mutate refs, object storage, or injected failure behavior must
// create a fresh oracle or use countingSemanticGitOps directly.
function memoizedImmutableSemanticGitOps() {
  const source = countingSemanticGitOps();
  const caches = {
    exactTree: new Map(),
    treeListing: new Map(),
    blob: new Map(),
    mergeBase: new Map(),
    ancestor: new Map(),
  };
  let hits = 0;
  const key = (repoRoot, ...parts) => `${realpathSync(repoRoot)}\0${parts.join("\0")}`;
  const cachedBuffer = (cache, cacheKey, load) => {
    if (cache.has(cacheKey)) {
      hits += 1;
      return Buffer.from(cache.get(cacheKey));
    }
    const bytes = load();
    cache.set(cacheKey, Buffer.from(bytes));
    return Buffer.from(bytes);
  };
  const cachedValue = (cache, cacheKey, load) => {
    if (cache.has(cacheKey)) {
      hits += 1;
      return cache.get(cacheKey);
    }
    const value = load();
    cache.set(cacheKey, value);
    return value;
  };
  return {
    cacheHits: () => hits,
    events: source.events,
    ops: Object.freeze({
      readExactTreeRecord(input) {
        assertExactSemanticGitParams(input, ["repoRoot", "headSha", "path"], "readExactTreeRecord");
        return cachedBuffer(
          caches.exactTree,
          key(input.repoRoot, input.headSha, input.path),
          () => source.ops.readExactTreeRecord(input),
        );
      },
      readTreeRecordsUnderPath(input) {
        assertExactSemanticGitParams(input, ["repoRoot", "headSha", "path"], "readTreeRecordsUnderPath");
        return cachedBuffer(
          caches.treeListing,
          key(input.repoRoot, input.headSha, input.path),
          () => source.ops.readTreeRecordsUnderPath(input),
        );
      },
      readBlobByOid(input) {
        assertExactSemanticGitParams(input, ["repoRoot", "oid"], "readBlobByOid");
        return cachedBuffer(
          caches.blob,
          key(input.repoRoot, input.oid),
          () => source.ops.readBlobByOid(input),
        );
      },
      mergeBase(input) {
        assertExactSemanticGitParams(input, ["repoRoot", "leftSha", "rightSha"], "mergeBase");
        return cachedValue(
          caches.mergeBase,
          key(input.repoRoot, input.leftSha, input.rightSha),
          () => source.ops.mergeBase(input),
        );
      },
      isAncestor(input) {
        assertExactSemanticGitParams(input, ["repoRoot", "ancestorSha", "descendantSha"], "isAncestor");
        const cacheKey = key(input.repoRoot, input.ancestorSha, input.descendantSha);
        if (caches.ancestor.get(cacheKey) === true) {
          hits += 1;
          return true;
        }
        const result = source.ops.isAncestor(input);
        if (result === true) caches.ancestor.set(cacheKey, true);
        return result;
      },
    }),
  };
}

function assertOperationGitFactsDeduplicated(events, label) {
  assert.ok(events.length > 0, `${label}: semantic Git boundary must be exercised`);
  const counts = new Map();
  for (const event of events) counts.set(`${event.operation}\0${event.key}`, (counts.get(`${event.operation}\0${event.key}`) ?? 0) + 1);
  const duplicates = [...counts].filter(([, count]) => count > 1).map(([key, count]) => ({ key, count }));
  assert.deepEqual(duplicates, [], `${label}: each immutable Git fact is derived at most once per top-level operation`);
}

function sealRoundManifests(helper, { repoRoot, changeId, roundNumber, mainSha, surfaceBaseSha, candidateHeadSha }) {
  const common = { changeBaseSha: mainSha, surfaceBaseSha, candidateHeadSha };
  const repair = sealManifest(helper, {
    repoRoot,
    changeId,
    roundNumber,
    manifest: manifestFixture({ purpose: "repair-delta", ...common }),
  });
  const closure = sealManifest(helper, {
    repoRoot,
    changeId,
    roundNumber,
    manifest: manifestFixture({ purpose: "dependency-closure", ...common }),
  });
  return { repair, closure };
}

function writeRoundManifestFixtureCarriers(helper, {
  repoRoot,
  changeId,
  roundNumber,
  mainSha,
  surfaceBaseSha,
  candidateHeadSha,
}) {
  const common = { changeBaseSha: mainSha, surfaceBaseSha, candidateHeadSha };
  return {
    repair: writeManifestFixtureCarrier(helper, {
      repoRoot,
      changeId,
      roundNumber,
      manifest: manifestFixture({ purpose: "repair-delta", ...common }),
    }),
    closure: writeManifestFixtureCarrier(helper, {
      repoRoot,
      changeId,
      roundNumber,
      manifest: manifestFixture({ purpose: "dependency-closure", ...common }),
    }),
  };
}

function sealInitial(helper, { repoRoot, changeId, mainSha, findings = [finding()], verdict = "finished" }) {
  return sealReceipt(helper, {
    repoRoot,
    changeId,
    reviewerPayload: receiptPayload({
      baseSha: mainSha,
      mergeBaseSha: mainSha,
      headSha: git(repoRoot, ["rev-parse", "HEAD"]),
      findings,
      verdict,
    }),
  });
}

function sealBoundedRound(helper, {
  repoRoot,
  changeId,
  roundNumber,
  boundedCount,
  mainSha,
  previousReceipt,
  manifests,
  // Carries the predecessor's findings forward unchanged, which makes any
  // multi-round chain built on the default flat -- and a flat chain is exactly
  // the stall the review budget hands back on
  // (`fix-zero-value-review-rounds`). A fixture that must stay dispatchable
  // past its second round has to pass a shrinking `findings`; `openFindings(n)`
  // builds one.
  findings = previousReceipt.receipt.reviewer_payload.findings,
  verdict = "finished",
}) {
  const initialDigest = roundNumber === 2
    ? previousReceipt.ref.digest_sha256
    : previousReceipt.receipt.reviewer_payload.lineage.initial_full_receipt_digest_sha256;
  return sealReceipt(helper, {
    repoRoot,
    changeId,
    reviewerPayload: receiptPayload({
      reviewMode: "bounded",
      roundNumber,
      boundedCount,
      baseSha: mainSha,
      mergeBaseSha: mainSha,
      headSha: git(repoRoot, ["rev-parse", "HEAD"]),
      previousReceiptRef: previousReceipt.ref,
      initialFullReceiptDigestSha256: initialDigest,
      repairManifestRef: manifests.repair.ref,
      closureManifestRef: manifests.closure.ref,
      findings,
      verdict,
    }),
  });
}

function recordingFsOps({
  failAt = null,
  failAtOccurrence = 1,
  shortWrite = false,
  readbackMismatch = false,
  readbackMismatchAtOccurrence = 1,
  onReadback = null,
  parentFsyncNoop = false,
  publishErrorCode = null,
  closeFault = false,
  unlinkFault = false,
} = {}) {
  const events = [];
  let tempBytes;
  let finalBytes;
  const stageCounts = new Map();
  const maybeFail = (stage) => {
    const occurrence = (stageCounts.get(stage) ?? 0) + 1;
    stageCounts.set(stage, occurrence);
    if (failAt === stage && occurrence === failAtOccurrence) throw new Error(`injected ${stage} fault`);
  };
  return {
    events,
    state: () => ({ tempBytes, finalBytes }),
    ops: {
      createExclusiveTemp({ mode, targetPath }) {
        events.push(["createExclusiveTemp", mode]);
        maybeFail("createExclusiveTemp");
        return { handle: "h", tempPath: `${targetPath}.tmp-test` };
      },
      writeAll(_handle, value) {
        events.push(["writeAll"]);
        maybeFail("writeAll");
        tempBytes = Buffer.from(value);
        return { bytesWritten: shortWrite ? tempBytes.length - 1 : tempBytes.length };
      },
      fsyncFile() { events.push(["fsyncFile"]); maybeFail("fsyncFile"); },
      publishExclusive() {
        events.push(["publishExclusive"]);
        if (publishErrorCode) {
          const error = new Error(`link ${publishErrorCode}`);
          error.code = publishErrorCode;
          throw error;
        }
        maybeFail("publishExclusive");
        finalBytes = tempBytes;
      },
      fsyncParent() {
        events.push(["fsyncParent", parentFsyncNoop ? "win32-noop" : "synced"]);
        maybeFail("fsyncParent");
        return parentFsyncNoop ? { documentedNoop: true, platform: "win32" } : { synced: true };
      },
      readWholeFile() {
        events.push(["readWholeFile"]);
        maybeFail("readWholeFile");
        const occurrence = stageCounts.get("readWholeFile");
        onReadback?.({ occurrence, finalBytes });
        return readbackMismatch && occurrence === readbackMismatchAtOccurrence && finalBytes
          ? Buffer.concat([finalBytes, Buffer.from("tampered")])
          : finalBytes;
      },
      revalidateWholeFile() { events.push(["revalidateWholeFile"]); maybeFail("revalidateWholeFile"); },
      closeTemp() {
        events.push(["closeTemp"]);
        if (closeFault) throw new Error("injected closeTemp cleanup fault");
      },
      unlinkTemp() {
        events.push(["unlinkTemp"]);
        if (unlinkFault) throw new Error("injected unlinkTemp cleanup fault");
        tempBytes = null;
      },
      rename() { events.push(["renameFallback"]); throw new Error("rename fallback forbidden"); },
      copy() { events.push(["copyFallback"]); throw new Error("copy fallback forbidden"); },
      truncate() { events.push(["truncateFallback"]); throw new Error("truncate fallback forbidden"); },
    },
  };
}

test("helper exposes the exact v1 named contract", () => {
  api();
  const { CoreFailure, D30_CODES } = coreApi();
  assert.equal(D30_CODES.size, 84, "D30 catalog contains the reviewed 79 existing codes, 4 added domain codes, and the explicit predecessor-finding-omitted code (strengthen-review-receipt-carry-forward-compaction)");
  assert.equal(new CoreFailure("receipt-evidence-invalid").code, "receipt-evidence-invalid");
  assert.throws(() => new CoreFailure("message-derived-code"), TypeError,
    "CoreFailure rejects values outside the closed D30 catalog");

  const changeDir = resolveAdmissionChangeDir(repoPath("."), "fix-review-remediation-error-codes");
  assert.ok(changeDir, "the source OpenSpec change must resolve while active or archived");
  const design = readFileSync(path.join(changeDir, "design.md"), "utf8");
  const baselineStart = design.indexOf("#### Existing code→detail test baseline");
  const baselineEnd = design.indexOf("### D2 —", baselineStart);
  assert.ok(baselineStart >= 0 && baselineEnd > baselineStart, "design must retain the reviewed closed D30 code/detail baseline");
  const baselinePairs = new Map();
  for (const line of design.slice(baselineStart, baselineEnd).split("\n")) {
    if (!line.startsWith("| `")) continue;
    const cells = line.split("|").map((cell) => cell.trim());
    const detailKey = /^`([^`]+)`$/u.exec(cells[1])?.[1];
    if (detailKey === undefined) continue;
    for (const cellIndex of [2, 3]) {
      for (const code of cells[cellIndex].matchAll(/`([^`]+)`/gu)) baselinePairs.set(code[1], detailKey);
    }
  }
  const helperSource = readFileSync(HELPER_PATH, "utf8");
  const handlerBlock = /const D30_FILE_COMMAND_KEYS = new Map\(\[([\s\S]*?)\n\]\);/u.exec(helperSource)?.[1] ?? "";
  const runtimeHandlers = [...handlerBlock.matchAll(/^  \["([^"]+)",/gmu)].map(([, command]) => command).sort();
  const inventoryStart = design.indexOf("### Current-to-target catch and remap table");
  const helperInventoryStart = design.indexOf("### Shared helper-family inventory", inventoryStart);
  const inventory = design.slice(inventoryStart, helperInventoryStart);
  const inventoryHandlers = [...inventory.matchAll(/^\| `(capture-reviewer-output|build-receipt-request|prepare-post-hoc-attestation|record-post-hoc-authorization|seal-post-hoc-attestation|verify-post-hoc-attestation|seal-receipt|verify-receipt)` \|/gmu)]
    .map(([, command]) => command).sort();
  assert.equal(runtimeHandlers.length, 8, "the production D30 file handler set remains closed at eight commands");
  assert.deepEqual(runtimeHandlers, inventoryHandlers,
    "the design escaping-throw inventory covers every production D30 request-file handler");
  const runtimePairs = new Map();
  for (const match of helperSource.matchAll(/assignCodes\("([^"]+)", `([^`]+)`\);/gu)) {
    for (const code of match[2].trim().split(/\s+/u)) runtimePairs.set(code, match[1]);
  }
  // The baseline above is a historical snapshot of the archived fix-review-remediation-error-codes
  // design and is never edited. Codes added by later changes are listed here explicitly, each with
  // its reviewed detail key: strengthen-review-receipt-carry-forward-compaction adds
  // predecessor-finding-omitted under reviewer-payload-check (design D6).
  const codesAddedAfterBaseline = new Map([["predecessor-finding-omitted", "reviewer-payload-check"]]);
  assert.deepEqual([...runtimePairs].sort(), [...baselinePairs, ...codesAddedAfterBaseline].sort(),
    "runtime code-to-detail-key map equals every reviewed design baseline pair plus the explicitly listed later additions");
  const expectedDetails = new Map([
    ["reviewer-payload-check", "Validate the captured reviewer payload and its dispatch tuple."],
    ["post-hoc-record-check", "Verify the prepared, authorized, and witnessed post-hoc evidence."],
    ["receipt-evidence-check", "Check receipt bytes, schema, chain, and cross-carrier evidence."],
    ["receipt-authority-check", "Check the receipt's repository, dispatch, and reviewer authority."],
    ["stored-artifact-check", "Check that the referenced evidence artifact is canonical and safe."],
    ["request-input-check", "Check the request file's command-specific shape and required fields."],
    ["repository-io-check", "A repository or filesystem operation failed. Check availability and retry."],
  ]);
  const detailsBlock = /const D30_DETAILS = Object\.freeze\(\{([\s\S]*?)\n\}\);/u.exec(helperSource)?.[1] ?? "";
  const runtimeDetails = [...detailsBlock.matchAll(/^\s*"([^"]+)": "([^"]+)",$/gmu)]
    .map(([, key, value]) => [key, value]);
  assert.deepEqual([...expectedDetails].sort(), runtimeDetails.sort(),
    "runtime fixed detail text equals the seven reviewed operator hints");
});

test("immutable receipt identity is a closed executor_kind-conditional key set and rejects legacy invocation transport fields", async (t) => {
  const helper = api();
  for (const identity of [
    { role: "dp-reviewer", invocation_id: "legacy-runtime-id" },
    { role: "dp-reviewer", transport_invocation_id: "raw-ledger-only-id" },
    { role: "dp-reviewer", invocation_id: "legacy", transport_invocation_id: "transport" },
  ]) {
    await t.test(Object.keys(identity).filter((key) => key !== "role").join("+"), () => {
      withRepo(({ repoRoot, mainSha }) => {
        const changeId = `identity-${Object.keys(identity).length}`;
        writeFullRiskChange(repoRoot, changeId);
        commitAll(repoRoot, `identity fixture ${changeId}`);
        const { payload } = initialPayloadFromDispatch(helper, { repoRoot, changeId, mainSha });
        payload.reviewer_identity = identity;
        assert.throws(
          () => helper.sealReviewRoundReceipt({ repoRoot, changeId, reviewerPayload: payload }),
          /reviewer_identity|identity|unknown|invocation|transport/i,
          "immutable reviewer_identity is a closed {role} schema",
        );
      });
    });
  }
});

