test("canonical-json-v1 preserves code-point order, array order, exact LF, and original UTF-8 bytes", () => {
  const helper = api();
  const value = { "\u{10000}": 3, array: [3, 1, 2], "\ue000": 2 };
  const canonical = helper.canonicalJsonV1(value);
  assert.equal(canonical, '{"array":[3,1,2],"":2,"𐀀":3}');
  assert.deepEqual(helper.parseCanonicalJsonV1(`${canonical}\n`), value);
  for (const invalid of [
    canonical,
    `${canonical}\n\n`,
    '{"a":1,"a":2}\n',
    '{"outer":{"x":1,"x":2}}\n',
    '{"a":1,"\\u0061":2}\n',
    '{"n":-0}\n',
    '{"n":1.0}\n',
    '{"n":1e0}\n',
    '{"n":9007199254740992}\n',
    '{"array": [3,1,2],"":2,"𐀀":3}\n',
    Buffer.concat([Buffer.from('{"x":"'), Buffer.from([0xff]), Buffer.from('"}\n')]),
  ]) assert.throws(() => helper.parseCanonicalJsonV1(invalid));
  for (const invalid of [1.5, Number.NaN, Number.POSITIVE_INFINITY, Number.MAX_SAFE_INTEGER + 1]) {
    assert.throws(() => helper.canonicalJsonV1({ invalid }));
  }
});

