test("risk-shape compiler normalizes full/B-mini selected sections and accepts one exact archive authority", async (t) => {
  const helper = api();
  await t.test("full normalization ignores CRLF and non-header trailing whitespace, migration, test-log, and timestamp prose", () => {
    withRepo(({ repoRoot }) => {
      const changeId = "risk-full-stable";
      writeFullRiskChange(repoRoot, changeId);
      commitAll(repoRoot, "full risk fixture");
      const first = initialClassification(helper, { repoRoot, changeId });
      assertDispatchableResult(first, { route: "full", count: 0, round: 1, reason: "initial_review" });

      const proposalPath = path.join(repoRoot, "openspec", "changes", changeId, "proposal.md");
      const designPath = path.join(repoRoot, "openspec", "changes", changeId, "design.md");
      const normalizedEquivalent = fullRiskProposal({ migrationNote: "timestamp: 2099-01-01" })
        .split("\n").map((line) => line === "" || line === CANONICAL_TOUCH_HEADER ? line : `${line}  `).join("\r\n");
      writeFileSync(proposalPath, normalizedEquivalent);
      writeFileSync(designPath, fullRiskDesign({ testLog: "new non-authority test log and line 999" }).replaceAll("\n", "\r\n"));
      commitAll(repoRoot, "nonmaterial formatting and log edits");
      const retry = initialClassification(helper, { repoRoot, changeId });
      assert.equal(retry.risk_shape_digest_sha256, first.risk_shape_digest_sha256, "stable normalization must not hash whole files");
    });
  });

  await t.test("B-mini normalization ignores unselected prose and an extra design/full-only surface", () => {
    withRepo(({ repoRoot }) => {
      const changeId = "risk-mini-stable";
      writeMiniRiskChange(repoRoot, changeId);
      commitAll(repoRoot, "mini risk fixture");
      const first = initialClassification(helper, { repoRoot, changeId });
      assertDispatchableResult(first, { route: "full", count: 0, round: 1, reason: "initial_review" });

      writeMiniRiskChange(repoRoot, changeId, {
        unselectedProse: [
          "Changed non-authority note and timestamp 2099-01-01.",
          "",
          "## Consequence Assessment",
          "",
          "Full-only consequence prose MUST NOT be selected for B-mini.",
          "",
          "## Risk Classes and Material Negatives",
          "",
          "Full-only safety prose MUST NOT be selected for B-mini.",
        ].join("\n"),
      });
      write(repoRoot, path.join("openspec", "changes", changeId, "design.md"), fullRiskDesign({
        decision: "An extra B-mini design file is explicitly outside its risk selector.",
      }));
      const miniPath = path.join(repoRoot, "openspec", "changes", changeId, "proposal-mini.md");
      writeFileSync(miniPath, readFileSync(miniPath, "utf8")
        .split("\n").map((line) => line === "" || line === CANONICAL_TOUCH_HEADER ? line : `${line}\t`).join("\r\n"));
      commitAll(repoRoot, "mini nonmaterial formatting design and full-only prose");
      const retry = initialClassification(helper, { repoRoot, changeId });
      assert.equal(retry.risk_shape_digest_sha256, first.risk_shape_digest_sha256, "B-mini must not read design or full-only selectors");
    });
  });

  await t.test("unique latest exact-name archive is accepted when active is absent", () => {
    withRepo(({ repoRoot }) => {
      const changeId = "risk-archive-only";
      writeFullRiskChange(repoRoot, changeId, {
        folder: path.join("openspec", "changes", "archive", `2026-08-20-${changeId}`),
      });
      commitAll(repoRoot, "archived risk fixture");
      const result = initialClassification(helper, { repoRoot, changeId });
      assertDispatchableResult(result, { route: "full", count: 0, round: 1, reason: "initial_review" });
    });
  });
});

