test("classifier reconstructs chain-valid previous dispatch and risk authority before routing", async (t) => {
  const helper = api();
  for (const field of ["dispatch_id", "risk_shape_digest_sha256"]) {
    await t.test(field, () => {
      withRepo(({ repoRoot, mainSha }) => {
        const changeId = `classifier-previous-tamper-${field.replaceAll("_sha256", "")}`;
        writeFullRiskChange(repoRoot, changeId);
        commitAll(repoRoot, `previous authority baseline ${field}`);
        const initialDispatch = initialClassification(helper, { repoRoot, changeId });
        const initial = writeReceiptFixtureCarrier(helper, {
          repoRoot,
          changeId,
          reviewerPayload: payloadFromDispatch(initialDispatch, {
        changeId,
            baseSha: mainSha,
            mergeBaseSha: mainSha,
            headSha: git(repoRoot, ["rev-parse", "HEAD"]),
          }),
        });
        const trustedPreviousRef = clone(initial.ref);

        let candidateHead;
        let currentRiskDigest = initialDispatch.risk_shape_digest_sha256;
        if (field === "risk_shape_digest_sha256") {
          writeFullRiskChange(repoRoot, changeId, {
            proposal: { touchRow: "| `src/second-target.mjs` | code | modify | R2 |" },
          });
          candidateHead = commitAll(repoRoot, "legitimate selected-risk change");
          currentRiskDigest = initialClassification(helper, { repoRoot, changeId }).risk_shape_digest_sha256;
          assert.notEqual(currentRiskDigest, initialDispatch.risk_shape_digest_sha256);
        } else {
          candidateHead = commitRound(repoRoot, 201);
        }

        const manifests = writeRoundManifestFixtureCarriers(helper, {
          repoRoot,
          changeId,
          roundNumber: 2,
          mainSha,
          surfaceBaseSha: initial.receipt.reviewer_payload.lineage.head_sha,
          candidateHeadSha: candidateHead,
        });
        assert.doesNotThrow(() => helper.verifyReviewManifest({
          repoRoot,
          manifestRef: manifests.repair.ref,
          verificationMode: "current",
        }));
        assert.doesNotThrow(() => helper.verifyReviewManifest({
          repoRoot,
          manifestRef: manifests.closure.ref,
          verificationMode: "current",
        }));

        if (field === "risk_shape_digest_sha256") {
          const legitimate = helper.classifyBoundedRereview({
            repoRoot,
            changeId,
            previousReceiptRef: trustedPreviousRef,
            repairDeltaManifestRef: manifests.repair.ref,
            dependencyClosureManifestRef: manifests.closure.ref,
            predecessorMatches: predecessorMatches(initial.receipt),
          });
          assertDispatchableResult(legitimate, {
            route: "full",
            count: 0,
            round: 2,
            reason: "risk_shape_changed",
          });
          assert.equal(legitimate.risk_shape_digest_sha256, currentRiskDigest);
        }

        const tampered = clone(initial.receipt);
        if (field === "risk_shape_digest_sha256") {
          tampered.reviewer_payload.scope.risk_shape_digest_sha256 = currentRiskDigest;
        } else {
          tampered.reviewer_payload = tamperLogicalReceiptAuthority(tampered.reviewer_payload, field);
        }
        const resigned = resignReceiptEnvelope(helper, tampered);
        writeReceiptEnvelope(helper, initial.targetPath, resigned);
        const tamperedPreviousRef = durableRef(repoRoot, initial.targetPath);
        assert.deepEqual(
          helper.parseCanonicalJsonV1(readFileSync(initial.targetPath)),
          resigned,
          `${field} fixture remains canonical JSON with a recomputed outer envelope`,
        );
        assert.equal(
          resigned.receipt_digest_sha256,
          sha256(helper.canonicalJsonV1(resigned.reviewer_payload)),
          `${field} fixture has a valid inner payload digest`,
        );
        assert.match(tamperedPreviousRef.digest_sha256, /^[0-9a-f]{64}$/);

        const classified = helper.classifyBoundedRereview({
          repoRoot,
          changeId,
          previousReceiptRef: tamperedPreviousRef,
          repairDeltaManifestRef: manifests.repair.ref,
          dependencyClosureManifestRef: manifests.closure.ref,
          predecessorMatches: predecessorMatches(resigned),
        });
        assert.equal(
          routeOf(classified),
          "full_reopen_required",
          `${field} must fail closed after reconstructing the previous round from its historical Git/ref authority`,
        );
        assert.notEqual(classified.dispatch_ready, true, `${field} cannot produce dispatch authority`);
      });
    });
  }
});

