      const initial = sealInitial(helper, { repoRoot, changeId, mainSha, verdict });
      assert.equal(initial.targetPath, receiptTarget(repoRoot, changeId, 1));
      assert.equal(Object.hasOwn(initial.receipt.reviewer_payload, "suite_result"), false);
      const candidate = commitRound(repoRoot, 2);
      const manifests = sealRoundManifests(helper, {
        repoRoot, changeId, roundNumber: 2, mainSha, surfaceBaseSha: initial.receipt.reviewer_payload.lineage.head_sha, candidateHeadSha: candidate,
      });
      const memoized = memoizedImmutableSemanticGitOps();
