test("historical risk authority accepts only exact non-executable Git blobs", async (t) => {
  const helper = api();
  const modeCases = [
    ["proposal symlink", "openspec/changes/git-mode-proposal-symlink/proposal.md", "120000"],
    ["design symlink", "openspec/changes/git-mode-design-symlink/design.md", "120000"],
    ["spec symlink", "openspec/changes/git-mode-spec-symlink/specs/risk-fixture/spec.md", "120000"],
    ["executable Markdown", "openspec/changes/git-mode-executable/proposal.md", "100755"],
    ["gitlink", "openspec/changes/git-mode-gitlink/proposal.md", "160000"],
  ];
  for (const [name, carrierPath, mode] of modeCases) {
    await t.test(name, () => {
      withRepo(({ repoRoot, mainSha }) => {
        const changeId = carrierPath.split("/")[2];
        const initial = prepareFinalReceiptCarrier(helper, {
          repoRoot,
          mainSha,
          changeId,
          findings: [finding()],
        });
        const { historicalHead, currentHead } = commitHistoricalCarrierMode(repoRoot, carrierPath, mode);
        assert.equal(git(repoRoot, ["status", "--porcelain"]), "", "current restored candidate is clean");
        assert.equal(
          git(repoRoot, ["ls-tree", historicalHead, "--", carrierPath]).split(/\s+/u)[0],
          mode,
          "historical fixture reaches the exact tree-mode branch",
        );

        const historicalReceipt = clone(initial.receipt);
        historicalReceipt.reviewer_payload.lineage.head_sha = historicalHead;
        historicalReceipt.reviewer_payload.lineage.merge_base_sha = git(repoRoot, [
          "merge-base",
          mainSha,
          historicalHead,
        ]);
        historicalReceipt.reviewer_payload.dispatch_id = logicalDispatchIdForPayload(
          helper,
          changeId,
          historicalReceipt.reviewer_payload,
        );
        const canonicalHistoricalReceipt = resignReceiptEnvelope(helper, historicalReceipt);
        const historicalReceiptRef = writeReceiptEnvelope(helper, initial.targetPath, canonicalHistoricalReceipt);
        assert.deepEqual(helper.parseCanonicalJsonV1(readFileSync(initial.targetPath)), canonicalHistoricalReceipt);

        const manifestCommon = {
          changeBaseSha: mainSha,
          surfaceBaseSha: historicalHead,
          candidateHeadSha: currentHead,
        };
        const manifests = {
          repair: writeManifestFixtureCarrier(helper, {
            repoRoot,
            changeId,
            roundNumber: 2,
            manifest: manifestFixture({ purpose: "repair-delta", ...manifestCommon }),
          }),
          closure: writeManifestFixtureCarrier(helper, {
            repoRoot,
            changeId,
            roundNumber: 2,
            manifest: manifestFixture({ purpose: "dependency-closure", ...manifestCommon }),
          }),
        };
        const classified = helper.classifyBoundedRereview({
          repoRoot,
          changeId,
          previousReceiptRef: historicalReceiptRef,
          repairDeltaManifestRef: manifests.repair.ref,
          dependencyClosureManifestRef: manifests.closure.ref,
          predecessorMatches: predecessorMatches(canonicalHistoricalReceipt),
        });
        assert.equal(routeOf(classified), "full_reopen_required", `${mode} ${carrierPath} is not historical Markdown authority`);
        assert.notEqual(classified.dispatch_ready, true, "invalid historical object mode cannot issue dispatch authority");
      });
    });
  }
});

test("historical tree-record reader is exact, NUL-safe, OID-bound, and path-independent", () => {
  const coreSource = readFileSync(CORE_PATH, "utf8");
  const transitionReader = sourceFunctionSlice(coreSource, "transitionTreeFactFromListing", "transitionTreeFacts");
  const recordReader = sourceFunctionSlice(coreSource, "gitObjectBytesFromRecord", "gitObjectBytes");
  assert.match(coreSource, /function requiredOperationGitOps\(gitOps\)/u, "blob readers must have a named operation-boundary chokepoint");
  for (const [label, reader] of [["transition", transitionReader], ["tree-record", recordReader]]) {
    assert.match(reader, /requiredOperationGitOps\(gitOps\)/u, `${label} reader must acquire operation-local GitOps`);
    assert.doesNotMatch(reader, /selectedGitOps\(gitOps\)\.readBlobByOid/u, `${label} reader must not read a raw selected blob seam`);
  }
  const operationReader = sourceFunctionSlice(coreSource, "createOperationGitOps", "gitOperationContext");
  assert.match(operationReader, /verifyGitBlobBytes\(\{ oid: input\.oid, bytes, objectFormat \}\)/u, "operation cache reads must verify source and cached bytes");
  assert.match(operationReader, /context\.blobBytes\.set\(key, Buffer\.from\(bytes\)\)/u, "operation cache must own a source Buffer copy");
  assert.match(operationReader, /return Buffer\.from\(bytes\)/u, "operation cache must return a defensive Buffer copy");
  const helper = api();
  const coreFactory = coreApi().createReviewRemediationEvidenceCore;
  withRepo(({ repoRoot, headSha }) => {
    const carrierPath = "src/review-target.mjs";
    const oid = git(repoRoot, ["rev-parse", `${headSha}:${carrierPath}`]);
    const invalidCalls = [
      ["tree missing path", "readExactTreeRecord", { repoRoot, headSha }],
      ["tree extra key", "readExactTreeRecord", { repoRoot, headSha, path: carrierPath, extra: true }],
      ["tree non-string repo root", "readExactTreeRecord", { repoRoot: 42, headSha, path: carrierPath }],
      ["tree invalid head", "readExactTreeRecord", { repoRoot, headSha: headSha.slice(1), path: carrierPath }],
      ["tree non-string path", "readExactTreeRecord", { repoRoot, headSha, path: 42 }],
      ["tree unsafe path", "readExactTreeRecord", { repoRoot, headSha, path: "../outside.md" }],
      ["tree list missing path", "readTreeRecordsUnderPath", { repoRoot, headSha }],
      ["tree list extra key", "readTreeRecordsUnderPath", { repoRoot, headSha, path: carrierPath, extra: true }],
      ["tree list invalid head", "readTreeRecordsUnderPath", { repoRoot, headSha: headSha.slice(1), path: carrierPath }],
      ["tree list unsafe path", "readTreeRecordsUnderPath", { repoRoot, headSha, path: "../outside.md" }],
      ["blob missing OID", "readBlobByOid", { repoRoot }],
      ["blob extra key", "readBlobByOid", { repoRoot, oid, extra: true }],
      ["blob non-string repo root", "readBlobByOid", { repoRoot: 42, oid }],
      ["blob invalid OID", "readBlobByOid", { repoRoot, oid: oid.slice(1) }],
      ["merge-base missing right SHA", "mergeBase", { repoRoot, leftSha: headSha }],
      ["merge-base invalid left SHA", "mergeBase", { repoRoot, leftSha: headSha.slice(1), rightSha: headSha }],
      ["ancestor missing descendant SHA", "isAncestor", { repoRoot, ancestorSha: headSha }],
      ["ancestor invalid descendant SHA", "isAncestor", { repoRoot, ancestorSha: headSha, descendantSha: headSha.slice(1) }],
    ];
    for (const [name, method, input] of invalidCalls) {
      const injected = injectedHistoricalGitOps({
        repoRoot,
        historicalHead: headSha,
        carrierPath,
        treeBytes: historicalTreeRecord({ oid, carrierPath }),
        blobBytesByOid: new Map([[oid, Buffer.from("trusted")]]),
      });
      assert.throws(() => injected.ops[method](input), undefined, name);
      assert.deepEqual(injected.events, [], `${name}: parameter rejection occurs before event or fallback`);
    }

    const memoized = memoizedImmutableSemanticGitOps();
    const firstBlob = memoized.ops.readBlobByOid({ repoRoot, oid });
    const trustedBlob = Buffer.from(firstBlob);
    firstBlob.fill(0);
    assert.deepEqual(
      memoized.ops.readBlobByOid({ repoRoot, oid }),
      trustedBlob,
      "cross-call immutable blob cache returns a defensive Buffer clone",
    );
    assert.throws(
      () => memoized.ops.readBlobByOid({ repoRoot, oid, extra: true }),
      undefined,
      "cache hit never bypasses exact semantic input validation",
    );
    assert.equal(memoized.events.filter(({ operation }) => operation === "blob").length, 1);
    assert.equal(memoized.cacheHits(), 1);
    const fresh = memoizedImmutableSemanticGitOps();
    assert.deepEqual(fresh.ops.readBlobByOid({ repoRoot, oid }), trustedBlob);
    assert.equal(fresh.events.filter(({ operation }) => operation === "blob").length, 1, "fresh oracle re-reads Git authority");
  });
  const semanticGitOps = Object.freeze({
    readExactTreeRecord() { throw new Error("semantic tree probe must not execute during core construction"); },
    readTreeRecordsUnderPath() { throw new Error("semantic tree-list probe must not execute during core construction"); },
    readBlobByOid() { throw new Error("semantic blob probe must not execute during core construction"); },
    mergeBase() { throw new Error("semantic merge-base probe must not execute during core construction"); },
    isAncestor() { throw new Error("semantic ancestor probe must not execute during core construction"); },
  });
  assert.deepEqual(
    Object.keys(semanticGitOps).sort(),
    ["isAncestor", "mergeBase", "readBlobByOid", "readExactTreeRecord", "readTreeRecordsUnderPath"],
    "internal Git seam is a closed semantic five-operation boundary",
  );
  assert.doesNotThrow(
    () => coreFactory({ gitOps: semanticGitOps }),
    "internal core must expose the test-only semantic gitOps boundary; production façade remains closed",
  );

  const recordCases = [
    ["unique exact 100644 blob", ({ oid, carrierPath }) => historicalTreeRecord({ oid, carrierPath }), "bounded"],
    ["missing", () => Buffer.alloc(0), "full_reopen_required"],
    ["duplicate exact path", ({ oid, carrierPath }) => Buffer.concat([
      historicalTreeRecord({ oid, carrierPath }),
      historicalTreeRecord({ oid, carrierPath }),
    ]), "full_reopen_required"],
    ["non-NUL", ({ oid, carrierPath }) => historicalTreeRecord({ oid, carrierPath, nul: false }), "full_reopen_required"],
    ["malformed", () => Buffer.from("not-a-tree-record\0"), "full_reopen_required"],
    ["mismatched path", ({ oid, carrierPath }) => historicalTreeRecord({
      oid,
      carrierPath: `${carrierPath}.other`,
    }), "full_reopen_required"],
    ["mode mismatch", ({ oid, carrierPath }) => historicalTreeRecord({
      mode: "100755",
      oid,
      carrierPath,
    }), "full_reopen_required"],
    ["type mismatch", ({ oid, carrierPath }) => historicalTreeRecord({
      type: "tree",
      oid,
      carrierPath,
    }), "full_reopen_required"],
    ["uppercase OID", ({ oid, carrierPath }) => historicalTreeRecord({
      oid: oid.toUpperCase(),
      carrierPath,
    }), "full_reopen_required"],
    ["OID mismatch", ({ carrierPath }) => historicalTreeRecord({
      oid: "0".repeat(40),
      carrierPath,
    }), "full_reopen_required"],
  ];
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "tree-parser-record-matrix";
    const carrierPath = `openspec/changes/${changeId}/proposal.md`;
    const initial = sealInitial(helper, { repoRoot, changeId, mainSha });
    const historicalHead = initial.receipt.reviewer_payload.lineage.head_sha;
    const oid = git(repoRoot, ["rev-parse", `${historicalHead}:${carrierPath}`]);
    const objectFormat = git(repoRoot, ["rev-parse", "--show-object-format"]);
    assert.match(oid, objectFormat === "sha256" ? /^[0-9a-f]{64}$/u : /^[0-9a-f]{40}$/u, "real Git blob OID is lowercase and full length");
    const blobBytes = gitExec(["cat-file", "blob", oid], {
      cwd: repoRoot,
      encoding: "buffer",
    });
    const candidateHead = commitRound(repoRoot, 205);
    const manifests = sealRoundManifests(helper, {
      repoRoot,
      changeId,
      roundNumber: 2,
      mainSha,
      surfaceBaseSha: historicalHead,
      candidateHeadSha: candidateHead,
    });
    const request = {
      repoRoot,
      changeId,
      previousReceiptRef: initial.ref,
      repairDeltaManifestRef: manifests.repair.ref,
      dependencyClosureManifestRef: manifests.closure.ref,
      predecessorMatches: predecessorMatches(initial.receipt),
    };

    for (const [name, treeRecord, expectedRoute] of recordCases) {
      const injected = injectedHistoricalGitOps({
        repoRoot,
        historicalHead,
        carrierPath,
        treeBytes: treeRecord({ oid, carrierPath }),
        blobBytesByOid: new Map([[oid, blobBytes]]),
      });
      const classified = coreFactory({ gitOps: injected.ops }).classifyBoundedRereview(request);
      assert.equal(injected.events.some(({ operation }) => operation === "tree-list"), true, `${name}: root listing boundary fired`);
      assert.equal(routeOf(classified), expectedRoute, name);
      if (expectedRoute === "bounded") {
        assert.equal(injected.events.some(({ operation }) => operation === "blob"), true, "positive record reads the selected OID bytes");
      } else {
        assert.notEqual(classified.dispatch_ready, true, `${name}: invalid record cannot issue authority`);
      }
    }

    const wrongFormatOid = "0".repeat(oid.length === 40 ? 64 : 40);
    const wrongFormat = injectedHistoricalGitOps({
      repoRoot,
      historicalHead,
      carrierPath,
      treeBytes: historicalTreeRecord({ oid: wrongFormatOid, carrierPath }),
      blobBytesByOid: new Map([[wrongFormatOid, blobBytes]]),
    });
    const wrongFormatResult = coreFactory({ gitOps: wrongFormat.ops }).classifyBoundedRereview(request);
    assert.equal(routeOf(wrongFormatResult), "full_reopen_required", "a full-length OID from the wrong Git object format must fail closed");

    for (const [label, bytes] of [
      ["wrong bytes", Buffer.from(blobBytes).fill(0x58)],
      ["truncated bytes", blobBytes.subarray(0, -1)],
    ]) {
      const mismatchedBlob = injectedHistoricalGitOps({
        repoRoot,
        historicalHead,
        carrierPath,
        treeBytes: historicalTreeRecord({ oid, carrierPath }),
        blobBytesByOid: new Map([[oid, bytes]]),
      });
      const mismatchedResult = coreFactory({ gitOps: mismatchedBlob.ops }).classifyBoundedRereview(request);
      assert.equal(
        routeOf(mismatchedResult),
        "risk_shape_unavailable",
        `a blob with ${label} must not be accepted for the selected Git OID`,
      );
    }
  });

  withRepo(({ repoRoot, mainSha }) => {
      const changeId = "tree-parser-oid-not-path";
      const carrierPath = `openspec/changes/${changeId}/proposal.md`;
      const initial = prepareFinalReceiptCarrier(helper, {
        repoRoot,
        mainSha,
        changeId,
        findings: [finding()],
      });
      const trustedHead = initial.receipt.reviewer_payload.lineage.head_sha;
      const trustedOid = git(repoRoot, ["rev-parse", `${trustedHead}:${carrierPath}`]);
      const trustedBytes = gitExec(["cat-file", "blob", trustedOid], {
        cwd: repoRoot,
        encoding: "buffer",
      });

      writeFullRiskChange(repoRoot, changeId, {
        proposal: { target: "1. Attacker pathname bytes must never provide historical authority." },
      });
      const historicalHead = commitAll(repoRoot, "historical path bytes differ from selected OID");
      const pathOid = git(repoRoot, ["rev-parse", `${historicalHead}:${carrierPath}`]);
      assert.notEqual(pathOid, trustedOid);
      writeFullRiskChange(repoRoot, changeId);
      const currentHead = commitAll(repoRoot, "restore trusted current risk bytes");

      const historicalReceipt = clone(initial.receipt);
      historicalReceipt.reviewer_payload.lineage.head_sha = historicalHead;
      historicalReceipt.reviewer_payload.lineage.merge_base_sha = git(repoRoot, ["merge-base", mainSha, historicalHead]);
      historicalReceipt.reviewer_payload.dispatch_id = logicalDispatchIdForPayload(
        helper,
        changeId,
        historicalReceipt.reviewer_payload,
      );
      const canonicalHistoricalReceipt = resignReceiptEnvelope(helper, historicalReceipt);
      const historicalReceiptRef = writeReceiptEnvelope(helper, initial.targetPath, canonicalHistoricalReceipt);
      const manifests = sealRoundManifests(helper, {
        repoRoot,
        changeId,
        roundNumber: 2,
        mainSha,
        surfaceBaseSha: historicalHead,
        candidateHeadSha: currentHead,
      });
      const injected = injectedHistoricalGitOps({
        repoRoot,
        historicalHead,
        carrierPath,
        treeBytes: historicalTreeRecord({ oid: trustedOid, carrierPath }),
        blobBytesByOid: new Map([[trustedOid, trustedBytes]]),
      });
      const classified = coreFactory({ gitOps: injected.ops }).classifyBoundedRereview({
        repoRoot,
        changeId,
        previousReceiptRef: historicalReceiptRef,
        repairDeltaManifestRef: manifests.repair.ref,
        dependencyClosureManifestRef: manifests.closure.ref,
        predecessorMatches: predecessorMatches(canonicalHistoricalReceipt),
      });
      assert.equal(injected.events.some(({ operation }) => operation === "tree-list"), true);
      assert.equal(injected.events.some(({ operation }) => operation === "blob"), true);
      assert.equal(routeOf(classified), "bounded", "the exact selected OID bytes retain authority even when path bytes differ");
  });
});

// Scenario: Exact Existing Raw Payload Is Idempotent After Win32 Durability Verification.
test("initial and mandatory full receipts reject every non-null manifest combination before publication", () => {
  const helper = api();
  for (const reviewRound of ["initial", "mandatory"]) {
    withRepo(({ repoRoot, mainSha }) => {
      const changeId = `full-null-${reviewRound}-matrix`;
      writeFullRiskChange(repoRoot, changeId);
      commitAll(repoRoot, `full null matrix ${reviewRound}`);
      let previous = null;
      if (reviewRound === "mandatory") previous = sealInitial(helper, { repoRoot, changeId, mainSha });
      const roundNumber = reviewRound === "initial" ? 1 : 2;
      const headSha = git(repoRoot, ["rev-parse", "HEAD"]);
      const writeRoundCarriers = ({ targetRound, surfaceBaseSha }) => {
        const common = { changeBaseSha: mainSha, surfaceBaseSha, candidateHeadSha: headSha };
        return {
          repair: writeManifestFixtureCarrier(helper, {
            repoRoot,
            changeId,
            roundNumber: targetRound,
            manifest: manifestFixture({ purpose: "repair-delta", ...common }),
          }),
          closure: writeManifestFixtureCarrier(helper, {
            repoRoot,
            changeId,
            roundNumber: targetRound,
            manifest: manifestFixture({ purpose: "dependency-closure", ...common }),
          }),
        };
      };
      const ownedManifests = writeRoundCarriers({
        targetRound: roundNumber,
        surfaceBaseSha: previous?.receipt.reviewer_payload.lineage.head_sha ?? mainSha,
      });
      const nextManifests = writeRoundCarriers({
        targetRound: roundNumber + 1,
        surfaceBaseSha: headSha,
      });
      const targetPath = receiptTarget(repoRoot, changeId, roundNumber);
      let firstRawPayload = null;

      for (const [combination, selectRefs] of [
        ["repair-only", ({ repair }) => ({ repairManifestRef: repair.ref, closureManifestRef: null })],
        ["closure-only", ({ closure }) => ({ repairManifestRef: null, closureManifestRef: closure.ref })],
        ["both", ({ repair, closure }) => ({ repairManifestRef: repair.ref, closureManifestRef: closure.ref })],
      ]) {
        rmSync(targetPath, { force: true });
        const selected = selectRefs(ownedManifests);
        let payload;
        try {
          payload = authoritativeReceiptPayload(helper, {
            repoRoot,
            changeId,
            reviewMode: "full",
            roundNumber,
            boundedCount: 0,
            baseSha: mainSha,
            mergeBaseSha: mainSha,
            headSha,
            previousReceiptRef: previous?.ref ?? null,
            initialFullReceiptDigestSha256: previous?.ref.digest_sha256 ?? null,
          });
        } catch (error) {
          if (firstRawPayload !== null) {
            assert.deepEqual(
              readFileSync(firstRawPayload.path),
              firstRawPayload.bytes,
              `${reviewRound} ${combination}: failed existing-target verification must leave exact raw payload bytes unchanged`,
            );
            assert.fail(
              `${reviewRound} ${combination}: exact-existing raw payload durability verification must succeed without mutation; got ${error?.message ?? error}`,
            );
          }
          throw error;
        }
        if (firstRawPayload === null) {
          const rawPath = payload.output_evidence.raw_payload_ref.path;
          const rawTarget = evidencePath(repoRoot, rawPath);
          firstRawPayload = { path: rawTarget, bytes: readFileSync(rawTarget) };
        } else {
          assert.deepEqual(
            readFileSync(firstRawPayload.path),
            firstRawPayload.bytes,
            `${reviewRound} ${combination}: exact-existing raw payload verification must remain byte-identical`,
          );
        }
        payload.scope.repair_delta_manifest_ref = selected.repairManifestRef;
        payload.scope.dependency_closure_manifest_ref = selected.closureManifestRef;
        payload.dispatch_id = logicalDispatchIdForPayload(helper, changeId, payload);
        assert.equal(
          payload.dispatch_id,
          logicalDispatchIdForPayload(helper, changeId, payload),
          "full logical dispatch remains bound as though both manifest inputs are exact null",
        );

        assert.equal(pathExists(targetPath), false);
        assert.throws(
          () => helper.sealReviewRoundReceipt({ repoRoot, changeId, reviewerPayload: payload }),
          /full|manifest|null|bounded/i,
          `${reviewRound} ${combination}: seal rejects before publication`,
        );
        assert.equal(pathExists(targetPath), false, `${reviewRound} ${combination}: no receipt target was published`);

        const resigned = resignReceiptEnvelope(helper, {
          schema: REVIEW_RECEIPT_SCHEMA,
          receipt_digest_sha256: DIGEST_A,
          observation_hashes: receiptObservationHashes(helper, payload.findings),
          reviewer_payload: payload,
        });
        const resignedRef = writeReceiptEnvelope(helper, targetPath, resigned);
        assert.equal(resigned.receipt_digest_sha256, sha256(helper.canonicalJsonV1(payload)));
        assert.throws(
          () => helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: resignedRef }),
          /full|manifest|null|bounded/i,
          `${reviewRound} ${combination}: verify rejects an outer-resigned full receipt`,
        );

        const classified = helper.classifyBoundedRereview({
          repoRoot,
          changeId,
          previousReceiptRef: resignedRef,
          repairDeltaManifestRef: nextManifests.repair.ref,
          dependencyClosureManifestRef: nextManifests.closure.ref,
          predecessorMatches: predecessorMatches(resigned),
        });
        assert.equal(routeOf(classified), "full_reopen_required", `${reviewRound} ${combination}: classifier fails closed`);
        assert.notEqual(classified.dispatch_ready, true);
      }
    });
  }
});

test("operation-local Git facts deduplicate a multi-round classify and never cross operation boundaries", () => {
  const helper = api();
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "operation-cache-classify";
    // 3 -> 2 -> 1 across the rounds this chain seals: it must model a converging
    // review, or the stall budget hands back before the classify under test
    // is reached (`fix-zero-value-review-rounds`).
    const initial = sealInitial(helper, { repoRoot, changeId, mainSha, findings: openFindings(3) });
    const boundedHead = commitRound(repoRoot, 206);
    const boundedManifests = sealRoundManifests(helper, {
      repoRoot,
      changeId,
      roundNumber: 2,
      mainSha,
      surfaceBaseSha: initial.receipt.reviewer_payload.lineage.head_sha,
      candidateHeadSha: boundedHead,
    });
    const bounded = sealBoundedRound(helper, {
      repoRoot,
      changeId,
      roundNumber: 2,
      boundedCount: 1,
      mainSha,
      previousReceipt: initial,
      manifests: boundedManifests,
      findings: shrinkingFindings(3, 2),
    });
    const full = sealFullRound(helper, {
      repoRoot,
      changeId,
      roundNumber: 3,
      boundedCount: 1,
      mainSha,
      previousReceipt: bounded,
      initialReceipt: initial,
      findings: shrinkingFindings(3, 1),
    });
    const candidateHead = commitRound(repoRoot, 207);
    const nextManifests = sealRoundManifests(helper, {
      repoRoot,
      changeId,
      roundNumber: 4,
      mainSha,
      surfaceBaseSha: full.receipt.reviewer_payload.lineage.head_sha,
      candidateHeadSha: candidateHead,
    });
    const request = {
      repoRoot,
      changeId,
      previousReceiptRef: full.ref,
      repairDeltaManifestRef: nextManifests.repair.ref,
      dependencyClosureManifestRef: nextManifests.closure.ref,
      predecessorMatches: predecessorMatches(full.receipt),
    };
    const counting = countingSemanticGitOps();
    const core = coreApi().createReviewRemediationEvidenceCore({ gitOps: counting.ops });
    assert.equal(routeOf(core.classifyBoundedRereview(request)), "bounded");
    const firstOperation = clone(counting.events);
    counting.clear();
    assert.equal(routeOf(core.classifyBoundedRereview(request)), "bounded");
    const secondOperation = clone(counting.events);
    assert.ok(secondOperation.length > 0, "a second top-level call creates a fresh operation-local context");

    writeFullRiskChange(repoRoot, changeId, {
      proposal: { target: "1. Mutable selected worktree drift must remain visible across operations." },
    });
    counting.clear();
    const drifted = core.classifyBoundedRereview(request);
    assert.equal(routeOf(drifted), "risk_shape_unavailable", "operation-local cache never masks current pinned worktree drift");
    writeFullRiskChange(repoRoot, changeId);
    assert.equal(git(repoRoot, ["status", "--porcelain"]), "", "mutation control restores the committed carrier bytes");

    assertOperationGitFactsDeduplicated(firstOperation, "multi-round classify first call");
    assertOperationGitFactsDeduplicated(secondOperation, "multi-round classify second call");
  });
});

test("operation-local Git facts deduplicate seal pre/post/readback and a collision starts a fresh operation", () => {
  const helper = api();
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "operation-cache-seal";
    const payload = authoritativeReceiptPayload(helper, { repoRoot, changeId, baseSha: mainSha });
    const counting = countingSemanticGitOps();
    const core = coreApi().createReviewRemediationEvidenceCore({ gitOps: counting.ops });
    assert.doesNotThrow(() => core.sealReviewRoundReceipt({ repoRoot, changeId, reviewerPayload: payload }));
    const firstOperation = clone(counting.events);
    counting.clear();
    assert.throws(
      () => core.sealReviewRoundReceipt({ repoRoot, changeId, reviewerPayload: payload }),
      /receipt-path-collision/u,
    );
    const identicalRetry = clone(counting.events);
    assert.ok(identicalRetry.length > 0, "identical retry must not reuse a prior top-level operation cache");
    assertOperationGitFactsDeduplicated(firstOperation, "seal pre/post/readback");
    assertOperationGitFactsDeduplicated(identicalRetry, "seal collision retry");
  });
});

test("raw manifest sealing rejects digest drift and unsafe validator/input carriers before publication", () => {
  const helper = api();
  withRepo(({ tempRoot, repoRoot, mainSha, headSha }) => {
    const materialized = materializeManifest(helper, repoRoot, manifestFixture({
      changeBaseSha: mainSha,
      surfaceBaseSha: mainSha,
      candidateHeadSha: headSha,
    }));
    for (const [name, mutate] of [
      ["validator source digest mismatch", (manifest) => { manifest.validator.source_digest_sha256 = DIGEST_C; }],
      ["input digest mismatch", (manifest) => { manifest.inputs.entries[0].digest_sha256 = DIGEST_C; }],
      ["input root digest mismatch", (manifest) => { manifest.inputs.root_digest_sha256 = DIGEST_C; }],
    ]) {
      const invalid = clone(materialized);
      mutate(invalid);
      assert.throws(() => sealRawManifest(helper, {
        repoRoot, changeId: `raw-digest-${name.replaceAll(" ", "-")}`, roundNumber: 1, manifest: invalid,
      }), /digest|hash|bytes|input|validator/i, name);
    }

    const drifted = clone(materialized);
    write(repoRoot, "src/review-target.mjs", "export const reviewTarget = 'post-materialization drift';\n");
    commitAll(repoRoot, "post materialization drift");
    assert.throws(() => sealRawManifest(helper, {
      repoRoot, changeId: "post-materialization-drift", roundNumber: 1, manifest: drifted,
    }), /candidate|HEAD|stale|digest|drift/i);

    const outside = path.join(tempRoot, "outside");
    mkdirSync(outside);
    writeFileSync(path.join(outside, "secret.mjs"), "export const secret = true;\n");
    symlinkSync(outside, path.join(repoRoot, "escape-link"));
    commitAll(repoRoot, "add escape symlink");
    const currentHead = git(repoRoot, ["rev-parse", "HEAD"]);
    const current = materializeManifest(helper, repoRoot, manifestFixture({
      changeBaseSha: mainSha,
      surfaceBaseSha: mainSha,
      candidateHeadSha: currentHead,
    }));
    const pathCases = [
      ["validator absolute", "validator", path.join(repoRoot, "tools/validator.mjs")],
      ["validator traversal", "validator", "../tools/validator.mjs"],
      ["validator NUL", "validator", "tools/bad\0validator.mjs"],
      ["validator symlink escape", "validator", "escape-link/secret.mjs"],
      ["validator future-ancestor escape", "validator", "escape-link/future/oracle.mjs"],
      ["input absolute", "input", path.join(repoRoot, "src/review-target.mjs")],
      ["input traversal", "input", "src/../review-target.mjs"],
      ["input NUL", "input", "src/bad\0input.mjs"],
      ["input symlink escape", "input", "escape-link/secret.mjs"],
      ["input future-ancestor escape", "input", "escape-link/future/input.mjs"],
    ];
    for (const [name, field, unsafePath] of pathCases) {
      const invalid = clone(current);
      if (field === "validator") invalid.validator.source_path = unsafePath;
      else invalid.inputs.entries[0].path = unsafePath;
      assert.throws(() => sealRawManifest(helper, {
        repoRoot, changeId: `raw-path-${name.replaceAll(" ", "-")}`, roundNumber: 1, manifest: invalid,
      }), /path|relative|contain|escape|NUL|absolute/i, name);
    }
  });
});

