test("manifest exception, incomplete-content, and dependency-cycle polarity stays fail closed", () => {
  const memoized = memoizedImmutableSemanticGitOps();
  const helper = coreApi().createReviewRemediationEvidenceCore({ gitOps: memoized.ops });
  withRepo(({ repoRoot, mainSha }) => {
    const closed = finding("F-content", { state: "closed", disposition: "fix-now" });
    const sameSlug = "manifest-ownership-same";
    const sameInitial = sealInitial(helper, { repoRoot, changeId: sameSlug, mainSha });
    const sameHead = sameInitial.receipt.reviewer_payload.lineage.head_sha;
    const sameManifests = sealRoundManifests(helper, {
      repoRoot, changeId: sameSlug, roundNumber: 2, mainSha, surfaceBaseSha: sameHead, candidateHeadSha: sameHead,
    });
    assert.equal(routeOf(classifyBounded(helper, {
      repoRoot,
      changeId: sameSlug,
      previousReceipt: sameInitial,
      repairManifest: sameManifests.repair,
      closureManifest: sameManifests.closure,
    })), "bounded", "same-slug receipt/manifests are eligible");

    const ownerSlug = "manifest-ownership-owner";
    const foreignSlug = "manifest-ownership-foreign";
    const ownerInitial = sealInitial(helper, { repoRoot, changeId: ownerSlug, mainSha });
    const ownerHead = ownerInitial.receipt.reviewer_payload.lineage.head_sha;
    const foreignManifests = sealRoundManifests(helper, {
      repoRoot, changeId: foreignSlug, roundNumber: 2, mainSha, surfaceBaseSha: ownerHead, candidateHeadSha: ownerHead,
    });
    assert.equal(routeOf(classifyBounded(helper, {
      repoRoot,
      changeId: ownerSlug,
      previousReceipt: ownerInitial,
      repairManifest: foreignManifests.repair,
      closureManifest: foreignManifests.closure,
    })), "full_reopen_required", "cross-slug durable refs cannot provide bounded authority");

    const purposeChangeId = "manifest-polarity-purpose-matrix";
    const purposeInitial = sealInitial(helper, {
      repoRoot,
      changeId: purposeChangeId,
      mainSha,
      findings: [closed],
    });
    const purposeHead = purposeInitial.receipt.reviewer_payload.lineage.head_sha;
    for (const purpose of ["repair-delta", "dependency-closure"]) {
      for (const targetPurpose of ["repair-delta", "dependency-closure"]) {
        rmSync(manifestTarget(repoRoot, purposeChangeId, targetPurpose, 2), { force: true });
      }
      const exceptional = writeManifestFixtureCarrier(helper, {
        repoRoot, changeId: purposeChangeId, roundNumber: 2,
        manifest: manifestFixture({
          changeBaseSha: mainSha,
          surfaceBaseSha: purposeHead,
          candidateHeadSha: purposeHead,
          purpose,
          exceptions: [{ id: "E-1", detail: "incomplete" }],
          result: "exceptions",
        }),
      });
      const other = writeManifestFixtureCarrier(helper, {
        repoRoot, changeId: purposeChangeId, roundNumber: 2,
        manifest: manifestFixture({
          changeBaseSha: mainSha,
          surfaceBaseSha: purposeHead,
          candidateHeadSha: purposeHead,
          purpose: purpose === "repair-delta" ? "dependency-closure" : "repair-delta",
        }),
      });
      assert.equal(routeOf(classifyBounded(helper, {
        repoRoot,
        changeId: purposeChangeId,
        previousReceipt: purposeInitial,
        repairManifest: purpose === "repair-delta" ? exceptional : other,
        closureManifest: purpose === "dependency-closure" ? exceptional : other,
      })), "full_reopen_required");
    }

    const contentCases = [
      ["incomplete", { coverage: { ...manifestFixture().coverage, complete: false } }],
      ["count mismatch", { coverage: { ...manifestFixture().coverage, processed_count: 0 } }],
      ["unknown", { coverage: { ...manifestFixture().coverage, unknown_inputs: ["src/review-target.mjs"] } }],
      ["omitted", { coverage: { ...manifestFixture().coverage, omitted_inputs: ["src/review-target.mjs"] } }],
      ["errors", { errors: ["validator failed"] }],
    ];
    const contentChangeId = "manifest-content-polarity-matrix";
    const contentInitial = sealInitial(helper, {
      repoRoot,
      changeId: contentChangeId,
      mainSha,
      findings: [closed],
    });
    const contentHead = contentInitial.receipt.reviewer_payload.lineage.head_sha;
    const validContentPair = sealRoundManifests(helper, {
      repoRoot,
      changeId: contentChangeId,
      roundNumber: 2,
      mainSha,
      surfaceBaseSha: contentHead,
      candidateHeadSha: contentHead,
    });
    for (const [name, override] of contentCases) {
      rmSync(manifestTarget(repoRoot, contentChangeId, "content-comparison", 2), { force: true });
      const content = writeManifestFixtureCarrier(helper, {
        repoRoot, changeId: contentChangeId, roundNumber: 2,
        manifest: manifestFixture({
          changeBaseSha: mainSha,
          surfaceBaseSha: contentHead,
          candidateHeadSha: contentHead,
          purpose: "content-comparison",
          result: "exceptions",
          exceptions: [{ id: "E-1", detail: "difference" }],
          ...override,
        }),
      });
      assert.equal(routeOf(classifyBounded(helper, {
        repoRoot,
        changeId: contentChangeId,
        previousReceipt: contentInitial,
        repairManifest: validContentPair.repair,
        closureManifest: validContentPair.closure,
        contentComparisonManifestRef: content.ref,
        contentExceptionDispositions: [{ exception_id: "E-1", finding_id: "F-content", disposition: "fix-now" }],
      })), "manifest_repair_required", name);
    }

    const cycleCases = [
      [{ from: "root", to: "root", kind: "reference" }],
      [{ from: "root", to: "other", kind: "reference" }, { from: "other", to: "root", kind: "reference" }],
    ];
    const cycleChangeId = "manifest-cycle-polarity-matrix";
    const cycleInitial = sealInitial(helper, {
      repoRoot,
      changeId: cycleChangeId,
      mainSha,
      findings: [closed],
    });
    const cycleHead = cycleInitial.receipt.reviewer_payload.lineage.head_sha;
    const cycleEntries = [
      { id: "root", path: "src/review-target.mjs", digest_sha256: DIGEST_A },
      { id: "other", path: "src/second-target.mjs", digest_sha256: DIGEST_B },
    ];
    const cycleRepair = sealManifest(helper, {
      repoRoot, changeId: cycleChangeId, roundNumber: 2,
      manifest: manifestFixture({
        changeBaseSha: mainSha,
        surfaceBaseSha: cycleHead,
        candidateHeadSha: cycleHead,
        purpose: "repair-delta",
      }),
    });
    for (const edges of cycleCases) {
      rmSync(manifestTarget(repoRoot, cycleChangeId, "dependency-closure", 2), { force: true });
      const closure = writeManifestFixtureCarrier(helper, {
        repoRoot, changeId: cycleChangeId, roundNumber: 2,
        manifest: manifestFixture({
          changeBaseSha: mainSha,
          surfaceBaseSha: cycleHead,
          candidateHeadSha: cycleHead,
          entries: cycleEntries,
          dependency_edges: edges,
        }),
      });
      assert.equal(routeOf(classifyBounded(helper, {
        repoRoot,
        changeId: cycleChangeId,
        previousReceipt: cycleInitial,
        repairManifest: cycleRepair,
        closureManifest: closure,
      })), "full_reopen_required", `${edges.length}-edge cycle`);
    }
    assert.ok(memoized.cacheHits() > 0, "one immutable repo state serves the complete manifest polarity matrix");
  });
});

function manifestAssertion(manifest) {
  const assertion = clone(manifest);
  delete assertion.manifest_digest_sha256;
  delete assertion.validator.independent_evidence;
  return assertion;
}

function evidenceFixture(helper, repoRoot, manifest, oraclePath = "tools/validator-oracle.mjs") {
  const oracleDigest = sha256(readFileSync(path.join(repoRoot, oraclePath)));
  const graphEntries = [{ path: oraclePath, digest_sha256: oracleDigest }];
  const assertion = manifestAssertion(manifest);
  const withoutDigest = {
    schema: VALIDATOR_EVIDENCE_SCHEMA,
    oracle: {
      id: "oracle-v1",
      version: "1",
      source_path: oraclePath,
      source_digest_sha256: oracleDigest,
      module_graph: {
        root_digest_sha256: sha256(helper.canonicalJsonV1(graphEntries)),
        entries: graphEntries,
      },
    },
    subject: {
      validator_source_path: manifest.validator.source_path,
      validator_source_digest_sha256: manifest.validator.source_digest_sha256,
      manifest_assertion_digest_sha256: sha256(helper.canonicalJsonV1(assertion)),
    },
    lineage: {
      change_base_sha: manifest.lineage.change_base_sha,
      candidate_head_sha: manifest.lineage.candidate_head_sha,
    },
    result: "verified",
  };
  return { ...withoutDigest, evidence_digest_sha256: sha256(helper.canonicalJsonV1(withoutDigest)) };
}

function resignEvidence(helper, repoRoot, evidence) {
  if (typeof evidence !== "object" || evidence === null || Array.isArray(evidence)) return evidence;
  const resigned = clone(evidence);
  const sourceDigest = sha256(readFileSync(path.join(repoRoot, resigned.oracle.source_path)));
  resigned.oracle.source_digest_sha256 = sourceDigest;
  const entries = [{ path: resigned.oracle.source_path, digest_sha256: sourceDigest }];
  resigned.oracle.module_graph = {
    root_digest_sha256: sha256(helper.canonicalJsonV1(entries)),
    entries,
  };
  delete resigned.evidence_digest_sha256;
  resigned.evidence_digest_sha256 = sha256(helper.canonicalJsonV1(resigned));
  return resigned;
}

test("same-change validator accepts only structured reproducible pre-existing oracle evidence", () => {
  const helper = api();
  withRepo(({ repoRoot, mainSha }) => {
    write(repoRoot, "tools/validator.mjs", "export const validate = 'changed';\n");
    const headSha = commitAll(repoRoot, "change validator");
    const base = materializeManifest(helper, repoRoot, manifestFixture({
      changeBaseSha: mainSha,
      surfaceBaseSha: mainSha,
      candidateHeadSha: headSha,
    }));
    base.validator.provenance = "independently-verified-same-change";
    base.validator.independent_evidence = evidenceFixture(helper, repoRoot, base);
    const assertion = manifestAssertion(base);
    assert.equal(assertion.schema, REVIEW_MANIFEST_SCHEMA);
    assert.equal(assertion.purpose, base.purpose);
    assert.equal(assertion.validator.id, base.validator.id);
    assert.equal(Object.hasOwn(assertion.validator, "independent_evidence"), false);
    for (const [field, value] of [["purpose", "repair-delta"], ["schema", "changed-schema"]]) {
      const changedAssertion = clone(assertion);
      changedAssertion[field] = value;
      assert.notEqual(
        sha256(helper.canonicalJsonV1(changedAssertion)),
        base.validator.independent_evidence.subject.manifest_assertion_digest_sha256,
        `${field} remains inside the complete manifest assertion digest`,
      );
    }
    assert.doesNotThrow(() => sealManifest(helper, {
      repoRoot, changeId: "oracle-positive", roundNumber: 1, manifest: base,
    }));

    const negatives = [
      ["arbitrary digest", DIGEST_A, /evidence|schema|structured/i],
      ["self oracle", { ...base.validator.independent_evidence, oracle: { ...base.validator.independent_evidence.oracle, source_path: "tools/validator.mjs" } }, /oracle|self|validator|independent/i],
      ["validator test", { ...base.validator.independent_evidence, oracle: { ...base.validator.independent_evidence.oracle, source_path: "tests/validator.test.mjs" } }, /oracle|test|production|executable/i],
      ["prose", { ...base.validator.independent_evidence, oracle: { ...base.validator.independent_evidence.oracle, source_path: "docs/oracle.md" } }, /oracle|prose|production|executable/i],
      ["malformed output", { ...base.validator.independent_evidence, oracle: { ...base.validator.independent_evidence.oracle, source_path: "tools/oracle-malformed.mjs" } }, /oracle|output|canonical|JSON/i],
      ["nonzero output", { ...base.validator.independent_evidence, oracle: { ...base.validator.independent_evidence.oracle, source_path: "tools/oracle-nonzero.mjs" } }, /oracle|status|exit|nonzero/i],
      ["subject mismatch", { ...base.validator.independent_evidence, subject: { ...base.validator.independent_evidence.subject, validator_source_digest_sha256: DIGEST_C } }, /subject|validator|digest|mismatch/i],
      ["lineage mismatch", { ...base.validator.independent_evidence, lineage: { ...base.validator.independent_evidence.lineage, candidate_head_sha: mainSha } }, /lineage|candidate|mismatch/i],
    ];
    for (const [name, independentEvidence, expectedError] of negatives) {
      const invalid = clone(base);
      invalid.validator.independent_evidence = resignEvidence(helper, repoRoot, independentEvidence);
      assert.throws(() => sealManifest(helper, {
        repoRoot, changeId: `oracle-${name.replaceAll(" ", "-")}`, roundNumber: 1, manifest: invalid,
      }), expectedError, name);
    }
    write(repoRoot, "tools/validator-oracle.mjs", `${oracleSource()}// changed\n`);
    commitAll(repoRoot, "change oracle too");
    const changedOracle = clone(base);
    changedOracle.lineage.candidate_head_sha = git(repoRoot, ["rev-parse", "HEAD"]);
    changedOracle.validator.independent_evidence = evidenceFixture(helper, repoRoot, changedOracle);
    assert.throws(() => sealManifest(helper, {
      repoRoot, changeId: "oracle-changed", roundNumber: 1, manifest: changedOracle,
    }), /oracle|changed|pre-existing|trust/i);
  });
});

test("linked worktree writes evidence only to derived main-checkout notes and rejects outside/symlink refs", () => {
  const helper = api();
  withRepo(({ tempRoot, repoRoot, mainSha }) => {
    const linked = path.join(tempRoot, "linked-worktree");
    git(repoRoot, ["worktree", "add", "--quiet", "-b", "linked/evidence", linked, "main"]);
    mkdirSync(path.join(repoRoot, "notes"), { recursive: true });
    const sealed = sealInitial(helper, { repoRoot: linked, changeId: "linked", mainSha });
    assert.equal(
      sealed.targetPath.startsWith(path.join(realpathSync(repoRoot), "notes")),
      true,
      `${sealed.targetPath} must use the real main-checkout notes root`,
    );
    assert.equal(sealed.targetPath.startsWith(path.join(linked, "notes")), false);
    assert.throws(() => helper.sealReviewRoundReceipt({
      repoRoot: linked,
      changeId: "outside",
      targetPath: path.join(tempRoot, "outside.json"),
      evidenceRoot: tempRoot,
      reviewerPayload: receiptPayload({ baseSha: mainSha }),
    }), /targetPath|evidenceRoot|caller|unknown/i);
    const outside = path.join(tempRoot, "outside");
    mkdirSync(outside);
    symlinkSync(outside, path.join(repoRoot, "notes", "escape"));
    assert.throws(() => helper.verifyReviewRoundReceipt({
      repoRoot: linked,
      receiptRef: { path: "escape/receipt.json", digest_sha256: DIGEST_A },
    }), /path|symlink|outside|containment/i);
  });
});

function poisonAuthority(label) {
  return new Proxy({}, {
    ownKeys() { throw new Error(`${label} was inspected before production seam rejection`); },
    get() { throw new Error(`${label} was inspected before production seam rejection`); },
  });
}

test("production façade rejects mutation seams before payload access even when caller sets NODE_ENV=test", () => {
  const helper = api();
  withRepo(({ repoRoot }) => {
    const fake = recordingFsOps();
    let spawnCalled = false;
    withNodeEnvironment("test", () => {
      assert.throws(() => helper.sealReviewRoundReceipt({
        repoRoot,
        changeId: "production-fs-reject",
        reviewerPayload: poisonAuthority("reviewer payload"),
        fsOps: fake.ops,
      }), /production.*fsOps|fsOps.*production|internal core/i);
      assert.throws(() => helper.sealReviewRoundReceipt({
        repoRoot,
        changeId: "production-test-mode-reject",
        reviewerPayload: poisonAuthority("reviewer payload"),
        testMode: true,
      }), /testMode|unknown|caller/i);
      assert.throws(() => helper.sealReviewRoundReceipt({
        repoRoot,
        changeId: "production-git-reject",
        reviewerPayload: poisonAuthority("reviewer payload"),
        gitOps: poisonAuthority("git operations"),
      }), /gitOps|unknown|caller|internal core/i);
      assert.throws(() => helper.sealFinalEvidenceRecord({
        repoRoot,
        changeId: "production-spawn-reject",
        canonicalOwnerId: "owner-1",
        payload: poisonAuthority("final payload"),
        spawnSyncImpl: () => { spawnCalled = true; },
      }), /production.*spawnSyncImpl|spawnSyncImpl.*production|internal core/i);
    });
    assert.deepEqual(fake.events, [], "production fs seam is rejected before any operation");
    assert.equal(spawnCalled, false, "production spawn seam is rejected before invocation");
  });
});

test("filesystem seam is trusted-test-only and durability faults never report success", () => {
  const helper = api();
  const core = coreApi().createReviewRemediationEvidenceCore;
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "filesystem-durability-faults";
    const reviewerPayload = authoritativeReceiptPayload(helper, { repoRoot, changeId, baseSha: mainSha });
    const fake = recordingFsOps();
    core({ fsOps: fake.ops }).sealReviewRoundReceipt({
      repoRoot,
      changeId,
      reviewerPayload: clone(reviewerPayload),
    });
    const oneDurablePublication = [
      ["createExclusiveTemp", 0o600], ["writeAll"], ["fsyncFile"], ["publishExclusive"],
      ["fsyncParent", "synced"], ["readWholeFile"], ["revalidateWholeFile"], ["closeTemp"], ["unlinkTemp"],
    ];
    assert.deepEqual(fake.events, [...oneDurablePublication, ...oneDurablePublication], "receipt and commit marker each use the durable publication primitive");

    for (const [name, options] of [
      ["create", { failAt: "createExclusiveTemp" }],
      ["write", { failAt: "writeAll" }],
      ["short write", { shortWrite: true }],
      ["file fsync", { failAt: "fsyncFile" }],
      ["link", { failAt: "publishExclusive" }],
      ["parent fsync", { failAt: "fsyncParent" }],
      ["readback", { failAt: "readWholeFile" }],
      ["readback mismatch", { readbackMismatch: true }],
      ["revalidation", { failAt: "revalidateWholeFile" }],
      ["Windows fsync no-op still readbacks", { parentFsyncNoop: true, readbackMismatch: true }],
    ]) {
      const fault = recordingFsOps(options);
      assert.throws(() => core({ fsOps: fault.ops }).sealReviewRoundReceipt({
        repoRoot,
        changeId,
        reviewerPayload: clone(reviewerPayload),
      }), undefined, name);
      const ownedTemp = options.failAt !== "createExclusiveTemp";
      assert.equal(fault.events.some(([stage]) => stage === "unlinkTemp"), ownedTemp, `${name}: cleanup ownership`);
      if (options.parentFsyncNoop) {
        assert.equal(fault.events.some(([stage]) => stage === "readWholeFile"), true, "Windows no-op cannot bypass readback");
      }
    }

    for (const [name, options] of [
      ["close", { closeFault: true }],
      ["unlink", { unlinkFault: true }],
    ]) {
      const cleanup = recordingFsOps(options);
      assert.doesNotThrow(() => core({ fsOps: cleanup.ops }).sealReviewRoundReceipt({
        repoRoot,
        changeId,
        reviewerPayload: clone(reviewerPayload),
      }), `${name}: cleanup is best effort after validated publication`);
      assert.equal(cleanup.events.some(([stage]) => stage === "unlinkTemp"), true, `${name}: unlink is attempted`);
    }
  });
});

test("real hard-link publication is idempotent only for identical bytes and never rename-falls back", () => {
  const helper = api();
  const coreFactory = coreApi().createReviewRemediationEvidenceCore;
  const coreSource = readFileSync(CORE_PATH, "utf8");
  const durablePublicationSource = [
    sourceFunctionSlice(coreSource, "defaultFsOps", "durableSeal"),
    sourceFunctionSlice(
      coreSource,
    "durableSeal",
    "readCanonicalRecord",
    ),
  ].join("\n");
  assert.match(durablePublicationSource, /\blinkSync\b/, "default publication must use a real hard link");
  assert.doesNotMatch(
    durablePublicationSource,
    /\b(?:rename|renameSync|copy|copyFile|copyFileSync|truncate|truncateSync)\b/,
    "publication source must not contain rename/copy/truncate fallback paths",
  );
  withRepo(({ repoRoot, mainSha }) => {
    const payload = authoritativeReceiptPayload(helper, { repoRoot, changeId: "hard-link", baseSha: mainSha });
    const first = sealReceipt(helper, { repoRoot, changeId: "hard-link", reviewerPayload: payload });
    const original = readFileSync(first.targetPath);
    assert.throws(
      () => sealReceipt(helper, { repoRoot, changeId: "hard-link", reviewerPayload: payload }),
      /receipt-path-collision/u,
      "v3 receipt publication is never idempotent after its irreversible claim",
    );
    assert.deepEqual(readFileSync(first.targetPath), original);
    assert.throws(() => sealReceipt(helper, {
      repoRoot,
      changeId: "hard-link",
      reviewerPayload: { ...payload, verdict: "blocked" },
    }), /raw-payload-collision/u, "a different retry is rejected by immutable raw capture before receipt overwrite");
    assert.deepEqual(readFileSync(first.targetPath), original);

    const blockedPayload = authoritativeReceiptPayload(helper, {
      repoRoot,
      changeId: "hard-link-error",
      baseSha: mainSha,
    });
    const blockedTarget = receiptTarget(repoRoot, "hard-link-error", 1, blockedPayload.dispatch_id);
    mkdirSync(blockedTarget, { recursive: true });
    assert.throws(() => sealReceipt(helper, {
      repoRoot,
      changeId: "hard-link-error",
      reviewerPayload: blockedPayload,
    }), /link|exist|directory|publish/i);
    assert.equal(statSync(blockedTarget).isDirectory(), true, "pre-existing directory must remain intact");

    for (const code of ["EXDEV", "EPERM", "ENOTSUP"]) {
      const linkError = recordingFsOps({ publishErrorCode: code });
      const changeId = `hard-link-${code.toLowerCase()}`;
      const linkPayload = authoritativeReceiptPayload(helper, { repoRoot, changeId, baseSha: mainSha });
      const targetPath = receiptTarget(repoRoot, changeId, 1, linkPayload.dispatch_id);
      const preexistingBytes = code === "EPERM" ? Buffer.from("pre-existing authority\n") : null;
      if (preexistingBytes !== null) writeFileSync(targetPath, preexistingBytes);
      assert.throws(() => coreFactory({ fsOps: linkError.ops }).sealReviewRoundReceipt({
        repoRoot,
        changeId,
        reviewerPayload: linkPayload,
      }), (error) => {
        assert.ok(!(error instanceof CoreFailure), "native link errors remain untyped: " + code);
        assert.equal(error?.code, code, "native link error provenance is preserved: " + code);
        assert.equal(error?.message, "link " + code);
        return true;
      }, "native link faults stay outside the domain catalog: " + code);
      assert.equal(
        linkError.events.some(([stage]) => stage === "publishExclusive"),
        true,
        `${code}: the fault is injected at the publication boundary`,
      );
      assert.equal(
        linkError.events.some(([stage]) => /Fallback$/.test(stage)),
        false,
        `${code}: no rename/copy/truncate fallback`,
      );
      assert.equal(linkError.events.some(([stage]) => stage === "unlinkTemp"), true, `${code}: owned temp cleaned`);
      if (preexistingBytes === null) {
        assert.equal(pathExists(targetPath), false, `${code}: failed link leaves target absent`);
      } else {
        assert.deepEqual(readFileSync(targetPath), preexistingBytes, `${code}: failed link leaves target unchanged`);
      }
    }
  });
});

function prepareFinalReceipt(helper, {
  repoRoot,
  mainSha,
  changeId,
  verdict = "finished",
  roundNumber = 1,
  findings = [finding("F-final-closed", { state: "closed", disposition: "fix-now" })],
}) {
  ensureRiskFixture(repoRoot, changeId);
  if (git(repoRoot, ["status", "--porcelain", "--", path.join("openspec", "changes", changeId)]).trim() !== "") {
    commitAll(repoRoot, `final risk fixture ${changeId}`);
  }
  return sealReceipt(helper, {
    repoRoot,
    changeId,
    reviewerPayload: receiptPayload({
      baseSha: mainSha,
      mergeBaseSha: mainSha,
      headSha: git(repoRoot, ["rev-parse", "HEAD"]),
      roundNumber,
      verdict,
      findings,
      openFindingIds: findings.filter((entry) => entry.state === "open").map((entry) => entry.finding_id),
    }),
  });
}

function prepareFinalReceiptCarrier(helper, {
  repoRoot,
  mainSha,
  changeId,
  verdict = "finished",
  roundNumber = 1,
  findings = [finding("F-final-closed", { state: "closed", disposition: "fix-now" })],
}) {
  const reviewerPayload = receiptPayload({
    baseSha: mainSha,
    mergeBaseSha: mainSha,
    headSha: git(repoRoot, ["rev-parse", "HEAD"]),
    roundNumber,
    verdict,
    findings,
    openFindingIds: findings.filter((entry) => entry.state === "open").map((entry) => entry.finding_id),
  });
  bindReceiptAuthority(helper, { repoRoot, changeId, reviewerPayload });
  delete reviewerPayload.review_authority;
  delete reviewerPayload.output_evidence;
  const receipt = {
    schema: REVIEW_RECEIPT_SCHEMA_V2,
    receipt_digest_sha256: sha256(helper.canonicalJsonV1(reviewerPayload)),
    observation_hashes: receiptObservationHashes(helper, findings),
    reviewer_payload: clone(reviewerPayload),
  };
  const targetPath = receiptTarget(repoRoot, changeId, roundNumber);
  const ref = writeReceiptEnvelope(helper, targetPath, receipt);
  return { receipt, targetPath, ref };
}

