function prepareArchiveTransitionFixture(helper, {
  repoRoot,
  mainSha,
  changeId,
  mutateReviewed,
  beforeArchive,
  mutateArchive,
  postArchiveExecutablePaths = [],
  afterArchiveCommit,
  prepareReceipt = prepareFinalReceipt,
}) {
  const activeRoot = path.join(repoRoot, "openspec", "changes", changeId);
  const archiveRelativeRoot = path.join("openspec", "changes", "archive", `2026-08-21-${changeId}`);
  const archiveRoot = path.join(repoRoot, archiveRelativeRoot);
  writeFullRiskChange(repoRoot, changeId, {
    spec: {},
  });
  write(repoRoot, path.join("openspec", "changes", changeId, "specs", "archive-fixture", "spec.md"), archiveDeltaSpec());
  write(repoRoot, path.join("openspec", "changes", changeId, "tasks.md"), "# Tasks\n\n- [x] archive fixture\n");
  write(repoRoot, "openspec/specs/archive-fixture/spec.md", archiveCanonicalBeforeSpec());
  write(repoRoot, "openspec/specs/risk-fixture/spec.md", riskDeltaSpec());
  mutateReviewed?.({ repoRoot, activeRoot, archiveRoot, archiveRelativeRoot });
  const reviewedHeadSha = commitAll(repoRoot, `reviewed active artifacts ${changeId}`);
  const terminal = prepareReceipt(helper, { repoRoot, mainSha, changeId });
  assert.equal(terminal.receipt.reviewer_payload.lineage.head_sha, reviewedHeadSha);

  beforeArchive?.({ repoRoot, activeRoot, archiveRoot, archiveRelativeRoot, reviewedHeadSha, terminal });
  mkdirSync(path.dirname(archiveRoot), { recursive: true });
  renameSync(activeRoot, archiveRoot);
  write(repoRoot, "openspec/specs/archive-fixture/spec.md", archiveCanonicalSpec());
  mutateArchive?.({
    repoRoot,
    activeRoot,
    archiveRoot,
    archiveRelativeRoot,
    reviewedHeadSha,
    terminal,
  });
  const postArchiveHeadSha = commitAll(repoRoot, `archive and promote ${changeId}`, {
    executablePaths: postArchiveExecutablePaths,
  });
  if (process.platform === "win32" && postArchiveExecutablePaths.length > 0) {
    git(repoRoot, ["config", "core.filemode", "false"]);
  }
  afterArchiveCommit?.({ repoRoot, activeRoot, archiveRoot, archiveRelativeRoot, reviewedHeadSha, postArchiveHeadSha, terminal });
  return {
    activeRoot,
    archiveRoot,
    archiveRelativeRoot,
    reviewedHeadSha,
    postArchiveHeadSha: git(repoRoot, ["rev-parse", "HEAD"]),
    transitionHeadSha: postArchiveHeadSha,
    terminal,
  };
}

const TRANSITION_GATE_IDS = [
  "pre-pr-archive-gate",
  "openspec validate --strict --specs",
  "lint-spec-shall-must",
];

const OPEN_SPEC_INTERACTIVE_ARGS = ["validate", "--strict", "--specs"];
const OPEN_SPEC_NON_INTERACTIVE_ARGS = [...OPEN_SPEC_INTERACTIVE_ARGS, "--no-interactive"];

function hasExactArgs(actual, expected) {
  return actual.length === expected.length && actual.every((value, index) => value === expected[index]);
}

function transitionRunner({
  consumerFinal = false,
  failGate = null,
  failMode = "nonzero",
  finalResult = "pass",
  gateStderr = {},
  onCall = null,
  simulateInteractiveSpinner = false,
} = {}) {
  const calls = [];
  const runner = (command, args, options) => {
    let commandId;
    if (command === process.execPath && args[0] === ".devpro/scripts/pre-pr-archive-gate.mjs") {
      commandId = "pre-pr-archive-gate";
    } else if (
      path.basename(command) === "openspec"
      && (hasExactArgs(args, OPEN_SPEC_INTERACTIVE_ARGS) || hasExactArgs(args, OPEN_SPEC_NON_INTERACTIVE_ARGS))
    ) {
      commandId = "openspec validate --strict --specs";
    } else if (command === process.execPath && args[0] === ".devpro/scripts/openspec-validate-delta.mjs") {
      commandId = "openspec-validate-delta";
    } else if (command === process.execPath && args[0] === ".devpro/scripts/lint-spec-shall-must.mjs") {
      commandId = "lint-spec-shall-must";
    } else if (command === process.execPath && args.join(" ") === ".devpro/scripts/run-test-suite.mjs --changed main --stdio log") {
      commandId = "source-change-scoped-suite";
    } else {
      throw new Error(`unexpected transition subprocess: ${command} ${args.join(" ")}`);
    }
    calls.push({ commandId, command, args: [...args], timeout: options?.timeout });
    onCall?.({ commandId, repoRoot: options?.cwd, calls });
    if (commandId === failGate) {
      if (failMode === "timeout") return bufferedSpawnResult({ status: null, error: Object.assign(new Error("timed out"), { code: "ETIMEDOUT" }), stderr: "timeout\n" });
      if (failMode === "capture-overflow") return bufferedSpawnResult({ status: null, error: Object.assign(new Error("capture overflow"), { code: "ENOBUFS" }) });
      if (failMode === "spawn-error") return bufferedSpawnResult({ status: null, error: new Error("spawn failed") });
      if (failMode === "signal") return bufferedSpawnResult({ status: null, signal: "SIGTERM" });
      if (failMode === "malformed-result") return null;
      if (failMode === "malformed-status") return bufferedSpawnResult({ stderr: "malformed status\n" });
      if (failMode === "non-buffer-stdout") return { status: 0, stdout: "not a Buffer", stderr: Buffer.alloc(0) };
      if (failMode === "non-buffer-stderr") return { status: 0, stdout: Buffer.alloc(0), stderr: "not a Buffer" };
      if (failMode === "unexpected-stderr") return bufferedSpawnResult({ status: 0, stdout: `${commandId} PASS\n`, stderr: "unknown warning\n" });
      return bufferedSpawnResult({ status: 1, stderr: `${commandId} failed\n` });
    }
    if (commandId === "source-change-scoped-suite") {
      // The consumer runner prints only its own N/A line and nothing on stderr.
      if (consumerFinal) return bufferedSpawnResult({ status: 0, stdout: `${CONSUMER_NA_LINE_LITERAL}\n` });
      return finalResult === "pass"
        ? bufferedSpawnResult({ status: 0, stdout: suiteTerminalOutput(), stderr: "canonical fixture stderr\n" })
        : bufferedSpawnResult({ status: 1, stdout: suiteTerminalOutput({ result: "fail", passed: 1, failed: 1 }), stderr: "canonical fixture failed\n" });
    }
    if (commandId === "openspec validate --strict --specs" && simulateInteractiveSpinner) {
      return bufferedSpawnResult({
        status: 0,
        stdout: `${commandId} PASS\n`,
        stderr: hasExactArgs(args, OPEN_SPEC_INTERACTIVE_ARGS) ? "- Validating...\n" : "",
      });
    }
    return bufferedSpawnResult({
      status: 0,
      stdout: `${commandId} PASS\n`,
      stderr: gateStderr[commandId] ?? "",
    });
  };
  return { calls, runner };
}

function readTransitionRecord(helper, repoRoot, changeId, postArchiveHeadSha = git(repoRoot, ["rev-parse", "HEAD"])) {
  return helper.parseCanonicalJsonV1(readFileSync(archiveTransitionTarget(repoRoot, changeId, postArchiveHeadSha), "utf8"));
}

function resignTransitionRecord(helper, record) {
  const resigned = clone(record);
  resigned.record_digest_sha256 = sha256(helper.canonicalJsonV1(resigned.payload));
  return resigned;
}

function gitTreeEntries(repoRoot, headSha, rootPath) {
  const raw = gitExec([
    "ls-tree", "-r", "-z", "--full-tree", headSha, "--", `:(literal)${rootPath}`,
  ], { cwd: repoRoot, encoding: "buffer" });
  const records = raw.toString("utf8").split("\0");
  assert.equal(records.pop(), "", "fixture Git tree oracle requires exact NUL termination");
  return records.map((record) => {
    const match = record.match(/^([0-9]{6}) ([a-z]+) ([0-9a-f]+)\t(.+)$/u);
    assert.ok(match, `malformed fixture Git tree record: ${record}`);
    return { mode: match[1], type: match[2], object_id: match[3], path: match[4] };
  });
}

function archiveSemanticProjectionOracle(helper, { repoRoot, headSha, rootPath }) {
  const normalizedRootPath = rootPath.replaceAll("\\", "/");
  const prefix = `${normalizedRootPath}/`;
  const entries = gitTreeEntries(repoRoot, headSha, normalizedRootPath).map((entry) => {
    assert.equal(entry.type, "blob");
    assert.equal(entry.path.startsWith(prefix), true);
    return {
      relative_path: entry.path.slice(prefix.length),
      mode: entry.mode,
      object_id: entry.object_id,
    };
  }).sort((left, right) => left.relative_path.localeCompare(right.relative_path));
  return sha256(helper.canonicalJsonV1(entries));
}

function expectedTransitionSemanticGitEvents({
  repoRoot,
  mainSha,
  changeId,
  reviewedHeadSha,
  postArchiveHeadSha,
  archiveRelativeRoot,
}) {
  const normalizedArchiveRoot = archiveRelativeRoot.replaceAll("\\", "/");
  const repoIdentity = realpathSync(repoRoot);
  const roots = [
    [reviewedHeadSha, `openspec/changes/${changeId}`],
    [postArchiveHeadSha, normalizedArchiveRoot],
  ];
  const carrierFacts = roots.flatMap(([headSha, rootPath]) => (
    gitTreeEntries(repoRoot, headSha, rootPath).map((entry) => ({ ...entry, headSha }))
  ));
  const canonicalFacts = [];
  for (const headSha of [reviewedHeadSha, postArchiveHeadSha]) {
    for (const capability of ["archive-fixture", "risk-fixture"]) {
      const [canonical] = gitTreeEntries(repoRoot, headSha, `openspec/specs/${capability}/spec.md`);
      assert.ok(canonical, "fixture canonical spec must exist at both transition endpoints");
      canonicalFacts.push({ ...canonical, headSha });
    }
  }
  const semanticEvents = new Set();
  semanticEvents.add(`merge-base\0${repoIdentity}\0${mainSha}\0${reviewedHeadSha}`);
  semanticEvents.add(`merge-base\0${repoIdentity}\0${mainSha}\0${postArchiveHeadSha}`);
  for (const headSha of [reviewedHeadSha, postArchiveHeadSha]) {
    semanticEvents.add(`tree-list\0${repoIdentity}\0${headSha}\0openspec/changes`);
  }
  for (const [headSha, rootPath] of roots) {
    semanticEvents.add(`tree-list\0${repoIdentity}\0${headSha}\0${rootPath}`);
  }
  for (const capability of ["archive-fixture", "risk-fixture"]) {
    semanticEvents.add(`tree-list\0${repoIdentity}\0${postArchiveHeadSha}\0${normalizedArchiveRoot}/specs/${capability}/spec.md`);
    for (const headSha of [reviewedHeadSha, postArchiveHeadSha]) {
      semanticEvents.add(`tree-list\0${repoIdentity}\0${headSha}\0openspec/specs/${capability}/spec.md`);
    }
  }
  for (const fact of [...carrierFacts, ...canonicalFacts]) {
    semanticEvents.add(`blob\0${repoIdentity}\0${fact.object_id}`);
  }
  return [...semanticEvents].sort();
}

function canonicalSemanticGitEvents(events) {
  return events.map(({ operation, key }) => `${operation}\0${key}`).sort();
}

function rebindFinalToTransition(helper, { transitionPath, finalPath, transition }) {
  const transitionBytes = Buffer.from(`${helper.canonicalJsonV1(resignTransitionRecord(helper, transition))}\n`);
  writeFileSync(transitionPath, transitionBytes);
  const finalRecord = helper.parseCanonicalJsonV1(readFileSync(finalPath, "utf8"));
  finalRecord.payload.review_coverage.archive_transition_ref.digest_sha256 = sha256(transitionBytes);
  writeFileSync(finalPath, `${helper.canonicalJsonV1(resignFinalRecord(helper, finalRecord))}\n`);
}

function restoreCanonicalCarriers(carriers) {
  for (const [carrierPath, canonicalBytes] of carriers) writeFileSync(carrierPath, canonicalBytes);
}

function sealFinal(helper, { repoRoot, changeId, canonicalOwnerId = "owner-1", ...extra }) {
  return helper.sealFinalEvidenceRecord({
    repoRoot,
    changeId,
    canonicalOwnerId,
    ...extra,
  });
}

