test("direct review coverage union rejects schema-valid outer-resigned cross-binding", () => {
  const helper = api();
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "final-direct-review-coverage-negative";
    const terminal = prepareFinalReceipt(helper, { repoRoot, mainSha, changeId });
    sealFinal(helper, { repoRoot, changeId });
    const target = finalTarget(repoRoot, changeId);
    const originalBytes = readFileSync(target);
    const cases = [
      ["direct with non-null transition ref", (record) => {
        record.payload.review_coverage.archive_transition_ref = terminal.ref;
      }],
      ["wrong reviewed HEAD", (record) => {
        record.payload.review_coverage.reviewed_head_sha = mainSha;
      }],
      ["wrong terminal receipt path", (record) => {
        record.payload.review_coverage.terminal_receipt_ref.path = "review-other-receipt-r1.json";
      }],
      ["wrong terminal receipt digest", (record) => {
        record.payload.review_coverage.terminal_receipt_ref.digest_sha256 = DIGEST_A;
      }],
    ];
    for (const [name, mutate] of cases) {
      writeFileSync(target, originalBytes);
      const record = helper.parseCanonicalJsonV1(originalBytes.toString("utf8"));
      mutate(record);
      writeFileSync(target, `${helper.canonicalJsonV1(resignFinalRecord(helper, record))}\n`);
      assert.throws(
        () => helper.verifyFinalEvidenceRecord({ repoRoot, changeId }),
        /coverage|direct|transition|reviewed|terminal|receipt|digest|mismatch|unknown/i,
        name,
      );
      assert.equal(
        helper.classifyFinalReadiness({ repoRoot, changeId }).route,
        "full_reopen_required",
        name,
      );
    }
    writeFileSync(target, originalBytes);
  }, { featureChange: true });
});

test("archive transition seals exact durable mapping and extends review coverage without a second review", () => {
  const helper = api();
  const coreFactory = coreApi().createReviewRemediationEvidenceCore;
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "archive-transition-valid";
    const fixture = prepareArchiveTransitionFixture(helper, { repoRoot, mainSha, changeId });
    const fake = transitionRunner({ simulateInteractiveSpinner: true });
    let sealed;
    try {
      sealed = coreFactory({ spawnSyncImpl: fake.runner }).sealFinalEvidenceRecord({
        repoRoot,
        changeId,
        canonicalOwnerId: "owner-1",
      });
    } catch (error) {
      assert.equal(pathExists(archiveTransitionTarget(repoRoot, changeId)), false, "spinner rejection cannot publish transition authority");
      assert.equal(fake.calls.some(({ commandId }) => commandId === "source-change-scoped-suite"), false, "spinner rejection suppresses the final suite");
      throw error;
    }
    const openSpecCall = fake.calls.find(({ commandId }) => commandId === "openspec validate --strict --specs");
    assert.deepEqual(
      openSpecCall?.args,
      OPEN_SPEC_NON_INTERACTIVE_ARGS,
      "archive transition OpenSpec validation uses the exact non-interactive argv",
    );
    assert.deepEqual(fake.calls.map(({ commandId }) => commandId), [
      ...TRANSITION_GATE_IDS,
      "source-change-scoped-suite",
    ], "transition stage runs only the three fixed mechanical gates before the one final suite");
    for (const call of fake.calls.slice(0, 3)) {
      assert.equal(call.timeout, 120000, `${call.commandId} uses the fixed transition timeout`);
    }

    const transitionPath = archiveTransitionTarget(repoRoot, changeId, fixture.postArchiveHeadSha);
    const transitionBytes = readFileSync(transitionPath);
    const transition = helper.parseCanonicalJsonV1(transitionBytes.toString("utf8"));
    assert.equal(transition.schema, "devpro.review-remediation.archive-transition-evidence/v1");
    assert.deepEqual(Object.keys(transition).sort(), ["payload", "record_digest_sha256", "schema"]);
    assert.deepEqual(Object.keys(transition.payload).sort(), [
      "active_archive_mapping",
      "base_sha",
      "canonical_promotion_mapping",
      "change_id",
      "d2_equivalence",
      "mechanical_gate_runs",
      "post_archive_head_sha",
      "post_archive_parent_sha",
      "raw_diff_manifest",
      "result",
      "reviewed_head_sha",
      "terminal_receipt_ref",
    ]);
    assert.equal(transition.payload.change_id, changeId);
    assert.deepEqual(transition.payload.terminal_receipt_ref, fixture.terminal.ref);
    assert.equal(transition.payload.reviewed_head_sha, fixture.reviewedHeadSha);
    assert.equal(transition.payload.post_archive_head_sha, fixture.postArchiveHeadSha);
    assert.equal(transition.payload.post_archive_parent_sha, fixture.reviewedHeadSha);
    assert.equal(transition.payload.result, "pass");
    assert.equal(transition.record_digest_sha256, sha256(helper.canonicalJsonV1(transition.payload)));
    assert.match(transition.payload.active_archive_mapping.digest_sha256, /^[0-9a-f]{64}$/);
    assert.match(transition.payload.canonical_promotion_mapping.digest_sha256, /^[0-9a-f]{64}$/);
    assert.match(transition.payload.raw_diff_manifest.digest_sha256, /^[0-9a-f]{64}$/);
    assert.equal(transition.payload.active_archive_mapping.entries.length, 5);
    assert.deepEqual(
      new Set(transition.payload.canonical_promotion_mapping.entries.map(({ delta_mode }) => delta_mode)),
      new Set(["ADDED", "MODIFIED", "REMOVED"]),
    );
    assert.equal(
      transition.payload.active_archive_mapping.entries.every((entry) => (
        entry.active_mode === entry.archive_mode && entry.active_object_id === entry.archive_object_id
      )),
      true,
    );
    const preSemanticProjection = archiveSemanticProjectionOracle(helper, {
      repoRoot,
      headSha: fixture.reviewedHeadSha,
      rootPath: path.join("openspec", "changes", changeId),
    });
    const postSemanticProjection = archiveSemanticProjectionOracle(helper, {
      repoRoot,
      headSha: fixture.postArchiveHeadSha,
      rootPath: fixture.archiveRelativeRoot,
    });
    assert.equal(preSemanticProjection, postSemanticProjection, "fixture oracle independently proves mapped relative path/mode/OID equivalence");
    assert.deepEqual(transition.payload.d2_equivalence, {
      pre_risk_shape_digest_sha256: fixture.terminal.receipt.reviewer_payload.scope.risk_shape_digest_sha256,
      post_risk_shape_digest_sha256: fixture.terminal.receipt.reviewer_payload.scope.risk_shape_digest_sha256,
      pre_semantic_projection_digest_sha256: preSemanticProjection,
      post_semantic_projection_digest_sha256: postSemanticProjection,
    });
    assert.deepEqual(transition.payload.mechanical_gate_runs.map(({ command_id }) => command_id), TRANSITION_GATE_IDS);
    for (const run of transition.payload.mechanical_gate_runs) {
      assert.equal(run.timeout_ms, 120000);
      assert.equal(run.exit_code, 0);
      assertInlineLog(run.log, `${run.command_id} PASS\n`);
    }

    const transitionRef = {
      path: path.basename(transitionPath),
      digest_sha256: sha256(transitionBytes),
    };
    const finalRecord = sealed.record ?? sealed;
    assert.deepEqual(finalRecord.payload.review_coverage, {
      mode: "archive_transition",
      terminal_receipt_ref: fixture.terminal.ref,
      reviewed_head_sha: fixture.reviewedHeadSha,
      archive_transition_ref: transitionRef,
    });
    assert.equal(helper.verifyFinalEvidenceRecord({ repoRoot, changeId }).record.record_digest_sha256, finalRecord.record_digest_sha256);
    assert.deepEqual(helper.classifyFinalReadiness({ repoRoot, changeId }), {
      final_ready: true,
      review_lineage_valid: true,
      review_coverage_valid: true,
      review_coverage_mode: "archive_transition",
      route: "final_ready",
    });
  });

  // #2874: on Windows the npm `openspec` is a `.cmd` shim that `spawnSync` can only start through
  // a shell. Only that gate gets one, and the sealed argv does not depend on the platform.
  for (const [platform, expectShell] of [["win32", true], ["linux", undefined]]) {
    withRepo(({ repoRoot, mainSha }) => {
      const changeId = `archive-transition-${platform}-shell`;
      const fixture = prepareArchiveTransitionFixture(helper, { repoRoot, mainSha, changeId });
      const inner = transitionRunner();
      const optionsSeen = [];
      const runner = (command, args, options) => {
        optionsSeen.push({ command, shell: options?.shell });
        return inner.runner(command, args, options);
      };
      coreFactory({ spawnSyncImpl: runner, platform }).sealFinalEvidenceRecord({ repoRoot, changeId, canonicalOwnerId: "owner-1" });
      const openSpec = optionsSeen.filter(({ command }) => command === "openspec");
      assert.equal(openSpec.length, 1, `${platform}: exactly one openspec gate`);
      assert.equal(openSpec[0].shell, expectShell, `${platform}: openspec gate shell option`);
      assert.deepEqual(
        optionsSeen.filter(({ command }) => command !== "openspec").map(({ shell }) => shell),
        [undefined, undefined, undefined],
        `${platform}: the node gates and the final suite never use a shell`,
      );
      const transition = readTransitionRecord(helper, repoRoot, changeId, fixture.postArchiveHeadSha);
      assert.deepEqual(
        transition.payload.mechanical_gate_runs[1].argv,
        ["openspec", ...OPEN_SPEC_NON_INTERACTIVE_ARGS],
        `${platform}: the sealed argv is platform independent`,
      );
    });
  }
});

