test("archive transition promotion binds ADDED MODIFIED REMOVED title body and canonical path", () => {
  const helper = api();
  const coreFactory = coreApi().createReviewRemediationEvidenceCore;
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "transition-promotion-semantic-matrix";
    const fixture = prepareArchiveTransitionFixture(helper, { repoRoot, mainSha, changeId });
    const canonicalPath = "openspec/specs/archive-fixture/spec.md";
    const preCanonicalOid = git(repoRoot, ["rev-parse", `${fixture.reviewedHeadSha}:${canonicalPath}`]);
    const postCanonicalOid = git(repoRoot, ["rev-parse", `${fixture.postArchiveHeadSha}:${canonicalPath}`]);
    const removedBlock = archiveCanonicalBeforeSpec().split("### Requirement: Existing Removed")[1];
    const semanticCases = [
      ["ADDED title mismatch", postCanonicalOid, archiveCanonicalSpec().replace("Added Requirement", "Wrong Added Title")],
      ["ADDED body drift", postCanonicalOid, archiveCanonicalSpec().replace(
        "The added requirement SHALL be present after promotion.",
        "The added requirement SHALL drift after promotion.",
      )],
      ["ADDED absence", postCanonicalOid, `${archiveCanonicalSpec().split("### Requirement: Added Requirement")[0].trimEnd()}\n`],
      ["MODIFIED body mismatch", postCanonicalOid, archiveCanonicalSpec({ modifiedBody: "The modified requirement SHALL drift after review." })],
      ["REMOVED retained", postCanonicalOid, `${archiveCanonicalSpec()}### Requirement: Existing Removed${removedBlock}`],
      ["REMOVED wrong title", preCanonicalOid, archiveCanonicalBeforeSpec().replace("Existing Removed", "Wrong Removed Title")],
      ["REMOVED wrong body", preCanonicalOid, archiveCanonicalBeforeSpec().replace(
        "The removed requirement SHALL exist before promotion.",
        "The removed requirement SHALL have different reviewed bytes.",
      )],
    ];
    for (const [name, targetOid, semanticBytes] of semanticCases) {
      const injected = injectedHistoricalGitOps({
        repoRoot,
        historicalHead: mainSha,
        carrierPath: "__semantic-blob-only__",
        treeBytes: Buffer.alloc(0),
        blobBytesByOid: new Map([[targetOid, Buffer.from(semanticBytes)]]),
      });
      const fake = transitionRunner();
      const core = coreFactory({ gitOps: injected.ops, spawnSyncImpl: fake.runner });
      assert.throws(() => core.sealFinalEvidenceRecord({
        repoRoot, changeId, canonicalOwnerId: "owner-1",
      }), /promotion|requirement|title|body|canonical|path|semantic|equivalent|reopen|integrity|OID|bytes|object/i, name);
      const sealBlobReads = injected.events.filter(({ operation, oid }) => operation === "blob" && oid === targetOid).length;
      assert.equal(sealBlobReads > 0, true, `${name}: seal reads the injected canonical blob`);
      assert.equal(pathExists(archiveTransitionTarget(repoRoot, changeId)), false, `${name}: failed promotion cannot publish transition authority`);
      assert.equal(core.classifyFinalReadiness({ repoRoot, changeId }).route, "full_reopen_required", name);
    }
  });

  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "transition-promotion-canonical-path-mismatch";
    prepareArchiveTransitionFixture(helper, {
      repoRoot,
      mainSha,
      changeId,
      mutateArchive: ({ repoRoot: fixtureRoot }) => {
        rmSync(path.join(fixtureRoot, "openspec", "specs", "archive-fixture"), { recursive: true });
        write(fixtureRoot, "openspec/specs/wrong-capability/spec.md", archiveCanonicalSpec());
      },
    });
    const fake = transitionRunner();
    assert.throws(() => coreFactory({ spawnSyncImpl: fake.runner }).sealFinalEvidenceRecord({
      repoRoot, changeId, canonicalOwnerId: "owner-1",
    }), /promotion|requirement|title|body|canonical|path|semantic|equivalent|reopen/i, "canonical path mismatch");
    assert.equal(pathExists(archiveTransitionTarget(repoRoot, changeId)), false, "canonical path mismatch cannot publish transition authority");
    assert.equal(helper.classifyFinalReadiness({ repoRoot, changeId }).route, "full_reopen_required");
  });
});

for (const fixtureCase of [
  {
    name: "ADDED-only keeps an existing canonical file modified",
    mode: "ADDED",
    pre: [{ title: "Unrelated X", body: "Unrelated X SHALL remain present." }],
    post: [
      { title: "Unrelated X", body: "Unrelated X SHALL remain present." },
      { title: "Changed Y", body: "Changed Y SHALL be added." },
    ],
    delta: { title: "Changed Y", body: "Changed Y SHALL be added." },
  },
  {
    name: "REMOVED-only keeps an existing canonical file modified",
    mode: "REMOVED",
    pre: [
      { title: "Unrelated X", body: "Unrelated X SHALL remain present." },
      { title: "Changed Y", body: "Changed Y SHALL be removed." },
    ],
    post: [{ title: "Unrelated X", body: "Unrelated X SHALL remain present." }],
    delta: { title: "Changed Y", body: "Changed Y SHALL be removed." },
  },
]) {
  test(`archive transition file-level status: ${fixtureCase.name}`, () => {
    const helper = api();
    const coreFactory = coreApi().createReviewRemediationEvidenceCore;
    withRepo(({ repoRoot, mainSha }) => {
      const changeId = `transition-file-status-${fixtureCase.mode.toLowerCase()}`;
      const fixture = prepareArchiveTransitionFixture(helper, {
        repoRoot,
        mainSha,
        changeId,
        mutateReviewed: ({ activeRoot }) => {
          write(activeRoot, path.join("specs", "archive-fixture", "spec.md"), archiveSingleDelta(fixtureCase.mode, fixtureCase.delta));
          write(repoRoot, "openspec/specs/archive-fixture/spec.md", archiveCanonicalRequirements(fixtureCase.pre));
        },
        mutateArchive: () => {
          write(repoRoot, "openspec/specs/archive-fixture/spec.md", archiveCanonicalRequirements(fixtureCase.post));
        },
      });
      const fake = transitionRunner();
      coreFactory({ spawnSyncImpl: fake.runner }).sealFinalEvidenceRecord({
        repoRoot, changeId, canonicalOwnerId: "owner-1",
      });
      const transition = readTransitionRecord(helper, repoRoot, changeId, fixture.postArchiveHeadSha);
      const canonicalEntry = transition.payload.raw_diff_manifest.entries.find(({ path: carrierPath }) => (
        carrierPath === "openspec/specs/archive-fixture/spec.md"
      ));
      assert.equal(canonicalEntry?.status[0], "M", "existing canonical file remains a file-level modification");
    });
  });
}

test("archive transition fixed gates fail closed on every validation process capture and result fault", () => {
  const helper = api();
  const coreFactory = coreApi().createReviewRemediationEvidenceCore;
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "transition-gate-reusable-fixture";
    prepareArchiveTransitionFixture(helper, { repoRoot, mainSha, changeId });
    const memoized = memoizedImmutableSemanticGitOps();
    const classifier = coreFactory({ gitOps: memoized.ops });
    for (const gateId of TRANSITION_GATE_IDS) {
      for (const failMode of ["nonzero", "timeout", "malformed-status"]) {
        const fake = transitionRunner({ failGate: gateId, failMode });
        assert.throws(() => coreFactory({ gitOps: memoized.ops, spawnSyncImpl: fake.runner }).sealFinalEvidenceRecord({
          repoRoot, changeId, canonicalOwnerId: "owner-1",
        }), /gate|status|timeout|malformed|archive|transition|failed|reopen/i, gateId + " " + failMode);
        assert.equal(pathExists(archiveTransitionTarget(repoRoot, changeId)), false, "failed gate cannot publish transition authority");
        assert.equal(fake.calls.some(({ commandId }) => commandId === "source-change-scoped-suite"), false, "final suite waits for all transition gates");
        assert.equal(classifier.classifyFinalReadiness({ repoRoot, changeId }).route, "full_reopen_required");
      }
    }
    for (const failMode of [
      "spawn-error",
      "signal",
      "capture-overflow",
      "malformed-result",
      "non-buffer-stdout",
      "non-buffer-stderr",
      "unexpected-stderr",
    ]) {
      const fake = transitionRunner({
        failGate: "openspec validate --strict --specs",
        failMode,
      });
      assert.throws(() => coreFactory({ gitOps: memoized.ops, spawnSyncImpl: fake.runner }).sealFinalEvidenceRecord({
        repoRoot, changeId, canonicalOwnerId: "owner-1",
      }), /gate|spawn|signal|capture|overflow|malformed|Buffer|stderr|archive|transition|failed|reopen/i, failMode);
      assert.equal(pathExists(archiveTransitionTarget(repoRoot, changeId)), false, `${failMode} cannot publish transition authority`);
      assert.equal(fake.calls.some(({ commandId }) => commandId === "source-change-scoped-suite"), false, `${failMode} suppresses the final suite`);
      assert.equal(classifier.classifyFinalReadiness({ repoRoot, changeId }).route, "full_reopen_required", failMode);
    }
    assert.ok(memoized.cacheHits() > 0, "all gate fault rows reuse the unchanged post-archive Git state");
  });

  const warning = [
    'soft-warn cap-pressure=over count=2 showing=2',
    'soft-warn cap-pressure=over path=".devpro/agent-rules/one.md" utilization=125.5',
    'soft-warn cap-pressure=over path=".devpro/agent-rules/two.md" utilization=101',
    '',
  ].join("\n");

  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "transition-canonical-cap-pressure-stderr";
    const fixture = prepareArchiveTransitionFixture(helper, { repoRoot, mainSha, changeId });
    const fake = transitionRunner({ gateStderr: { "pre-pr-archive-gate": warning } });
    coreFactory({ spawnSyncImpl: fake.runner }).sealFinalEvidenceRecord({
      repoRoot, changeId, canonicalOwnerId: "owner-1",
    });
    const transition = readTransitionRecord(helper, repoRoot, changeId, fixture.postArchiveHeadSha);
    assertInlineLog(
      transition.payload.mechanical_gate_runs[0].log,
      `pre-pr-archive-gate PASS\n${warning}`,
    );
    assert.doesNotThrow(() => helper.verifyFinalEvidenceRecord({ repoRoot, changeId }));
    assert.equal(helper.classifyFinalReadiness({ repoRoot, changeId }).final_ready, true);
  });

  for (const [label, gateId, stderr] of [
    ["wrong gate", "openspec validate --strict --specs", warning],
    ["mixed stderr", "pre-pr-archive-gate", `${warning}unknown warning\n`],
  ]) {
    withRepo(({ repoRoot, mainSha }) => {
      const changeId = `transition-cap-pressure-${label.replaceAll(" ", "-")}`;
      prepareArchiveTransitionFixture(helper, { repoRoot, mainSha, changeId });
      const fake = transitionRunner({ gateStderr: { [gateId]: stderr } });
      assert.throws(() => coreFactory({ spawnSyncImpl: fake.runner }).sealFinalEvidenceRecord({
        repoRoot, changeId, canonicalOwnerId: "owner-1",
      }), /gate|stderr|archive|transition|failed|reopen/i);
      assert.equal(pathExists(archiveTransitionTarget(repoRoot, changeId)), false);
      assert.equal(fake.calls.some(({ commandId }) => commandId === "source-change-scoped-suite"), false);
    });
  }
});

test("archive transition evidence and final coverage cross-binding are recomputed from Git", () => {
  const helper = api();
  const coreFactory = coreApi().createReviewRemediationEvidenceCore;
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "transition-tamper-reusable-fixture";
    const fixture = prepareArchiveTransitionFixture(helper, { repoRoot, mainSha, changeId });
    const fake = transitionRunner();
    const memoized = memoizedImmutableSemanticGitOps();
    const core = coreFactory({ gitOps: memoized.ops, spawnSyncImpl: fake.runner });
    core.sealFinalEvidenceRecord({ repoRoot, changeId, canonicalOwnerId: "owner-1" });
    const transitionPath = archiveTransitionTarget(repoRoot, changeId, fixture.postArchiveHeadSha);
    const finalPath = finalTarget(repoRoot, changeId, fixture.postArchiveHeadSha);
    const canonicalCarriers = [
      [transitionPath, readFileSync(transitionPath)],
      [finalPath, readFileSync(finalPath)],
    ];
    // Restore signed carriers before every mutation so no row can inherit state from the previous row.
    for (const mutation of [
      "raw diff",
      "gate log",
      "transition null ref",
      "wrong reviewed HEAD",
      "wrong terminal receipt path",
      "wrong terminal receipt digest",
      "transition post-head cross-bind",
      "forged equal wrong risk pair",
      "forged equal wrong semantic pair",
      "final transition ref",
    ]) {
      restoreCanonicalCarriers(canonicalCarriers);
      if (mutation === "gate log") {
        const transition = readTransitionRecord(helper, repoRoot, changeId, fixture.postArchiveHeadSha);
        transition.payload.mechanical_gate_runs[0].log.bytes_base64 = Buffer.from("tampered\n").toString("base64");
        rebindFinalToTransition(helper, { transitionPath, finalPath, transition });
      } else if (mutation === "raw diff") {
        const transition = readTransitionRecord(helper, repoRoot, changeId, fixture.postArchiveHeadSha);
        transition.payload.raw_diff_manifest.entries = [];
        const rawWithoutDigest = clone(transition.payload.raw_diff_manifest);
        delete rawWithoutDigest.digest_sha256;
        transition.payload.raw_diff_manifest.digest_sha256 = sha256(helper.canonicalJsonV1(rawWithoutDigest));
        rebindFinalToTransition(helper, { transitionPath, finalPath, transition });
      } else if (mutation === "transition post-head cross-bind") {
        const transition = readTransitionRecord(helper, repoRoot, changeId, fixture.postArchiveHeadSha);
        transition.payload.post_archive_head_sha = fixture.reviewedHeadSha;
        rebindFinalToTransition(helper, { transitionPath, finalPath, transition });
      } else if (mutation === "forged equal wrong risk pair") {
        const transition = readTransitionRecord(helper, repoRoot, changeId, fixture.postArchiveHeadSha);
        transition.payload.d2_equivalence.pre_risk_shape_digest_sha256 = DIGEST_A;
        transition.payload.d2_equivalence.post_risk_shape_digest_sha256 = DIGEST_A;
        rebindFinalToTransition(helper, { transitionPath, finalPath, transition });
      } else if (mutation === "forged equal wrong semantic pair") {
        const transition = readTransitionRecord(helper, repoRoot, changeId, fixture.postArchiveHeadSha);
        transition.payload.d2_equivalence.pre_semantic_projection_digest_sha256 = DIGEST_A;
        transition.payload.d2_equivalence.post_semantic_projection_digest_sha256 = DIGEST_A;
        rebindFinalToTransition(helper, { transitionPath, finalPath, transition });
      } else {
        const finalRecord = helper.parseCanonicalJsonV1(readFileSync(finalPath, "utf8"));
        if (mutation === "transition null ref") finalRecord.payload.review_coverage.archive_transition_ref = null;
        else if (mutation === "wrong reviewed HEAD") finalRecord.payload.review_coverage.reviewed_head_sha = mainSha;
        else if (mutation === "wrong terminal receipt path") finalRecord.payload.review_coverage.terminal_receipt_ref.path = "review-other-receipt-r1.json";
        else if (mutation === "wrong terminal receipt digest") finalRecord.payload.review_coverage.terminal_receipt_ref.digest_sha256 = DIGEST_A;
        else finalRecord.payload.review_coverage.archive_transition_ref.digest_sha256 = DIGEST_A;
        writeFileSync(finalPath, `${helper.canonicalJsonV1(resignFinalRecord(helper, finalRecord))}\n`);
      }
      assert.throws(() => core.verifyFinalEvidenceRecord({ repoRoot, changeId }), /transition|diff|Git|digest|log|coverage|mismatch|reopen/i);
      const readiness = core.classifyFinalReadiness({ repoRoot, changeId });
      assert.equal(readiness.final_ready, false);
      assert.equal(readiness.route, "full_reopen_required");
    }
    assert.ok(memoized.cacheHits() > 0, "all carrier tamper rows reuse the unchanged post-archive Git state");
  });
});

test("production final façade rejects caller transition authority before semantic payload access", () => {
  const helper = api();
  for (const injectedField of [
    "archiveTransitionRef",
    "archiveTransitionMapping",
    "archiveTransitionDigests",
    "archiveTransitionCommands",
    "archiveTransitionOps",
  ]) {
    let accessed = false;
    const poison = new Proxy({}, {
      get() { accessed = true; throw new Error("caller transition authority was accessed"); },
      ownKeys() { accessed = true; throw new Error("caller transition authority was enumerated"); },
    });
    assert.throws(() => helper.sealFinalEvidenceRecord({
      repoRoot: "/semantic/access/must/not/start",
      changeId: "caller-transition-authority",
      canonicalOwnerId: "owner-1",
      [injectedField]: poison,
    }), new RegExp(`${injectedField}|unknown|caller|authority`, "i"));
    assert.equal(accessed, false, `${injectedField} is rejected by the façade before semantic payload access`);
  }
});

