    assert.deepEqual(canonicalSemanticGitEvents(retry), expectedEvents, "verify retry freshly derives the same exact semantic operation+canonical-key multiset");
    assert.equal(first.length, expectedEvents.length, "seal semantic event count is exact and linear");
    assert.equal(retry.length, expectedEvents.length, "verify retry semantic event count is exact and fresh");
