test("oracle execution uses helper-materialized candidate bytes across swap-and-restore races", () => {
  const helper = api();
  const coreFactory = coreApi().createReviewRemediationEvidenceCore;
  const prepare = (repoRoot, mainSha) => {
    write(repoRoot, "tools/validator.mjs", "export const validate = 'changed for swap restore';\n");
    const headSha = commitAll(repoRoot, "change validator for swap restore");
    const manifest = materializeManifest(helper, repoRoot, manifestFixture({
      changeBaseSha: mainSha,
      surfaceBaseSha: mainSha,
      candidateHeadSha: headSha,
    }));
    manifest.validator.provenance = "independently-verified-same-change";
    manifest.validator.independent_evidence = evidenceFixture(helper, repoRoot, manifest);
    return manifest;
  };

  const swapRestoreRunner = ({ markerPath, trustedBytes, originalOraclePath, state }) => (
    (command, args, options) => {
      state.command = command;
      state.args = [...args];
      state.input = options.input;
      const attacker = `${trustedBytes.toString("utf8")}\nimport("node:fs").then(({writeFileSync}) => writeFileSync(${JSON.stringify(markerPath)}, "attacker bytes executed\\n"));\n`;
      writeFileSync(originalOraclePath, attacker, { mode: 0o755 });
      try {
        state.result = spawnSync(command, args, options);
        return state.result;
      } finally {
        writeFileSync(originalOraclePath, trustedBytes, { mode: 0o755 });
      }
    }
  );

  const assertCandidateObjectExecution = ({ state, manifest, trustedBytes, originalOraclePath, label }) => {
    assert.equal(state.command, process.execPath, `${label} uses the fixed Node VM runner`);
    assert.equal(state.args.includes(originalOraclePath), false, `${label} argv contains no mutable absolute oracle path`);
    assert.equal(String(state.input).includes(originalOraclePath), false, `${label} transport contains no mutable absolute oracle path`);
    const transport = JSON.parse(state.input);
    assert.equal(transport.root_path, manifest.validator.independent_evidence.oracle.source_path);
    const rootModule = transport.modules.find(({ path: modulePath }) => modulePath === transport.root_path);
    assert.deepEqual(Buffer.from(rootModule.source_base64, "base64"), trustedBytes, `${label} executes candidate Git-object bytes`);
    assert.equal(state.result.status, 0, `${label} candidate-object VM execution succeeds independently of race rejection`);
    assert.deepEqual(JSON.parse(state.result.stdout), manifest.validator.independent_evidence, `${label} trusted result comes from the embedded candidate graph`);
  };

  withRepo(({ tempRoot, repoRoot, mainSha }) => {
    const manifest = prepare(repoRoot, mainSha);
    const originalOraclePath = path.join(repoRoot, manifest.validator.independent_evidence.oracle.source_path);
    const trustedBytes = readFileSync(originalOraclePath);
    const markerPath = path.join(tempRoot, "seal-attacker-ran.txt");
    const state = { command: null, args: null, input: null, result: null };
    const core = coreFactory({ spawnSyncImpl: swapRestoreRunner({ repoRoot, markerPath, trustedBytes, originalOraclePath, state }) });
    let sealError = null;
    try {
      core.sealReviewManifest({ repoRoot, changeId: "oracle-swap-seal", roundNumber: 1, manifest });
    } catch (error) {
      sealError = error;
    }
    assertCandidateObjectExecution({ state, manifest, trustedBytes, originalOraclePath, label: "seal" });
    assert.equal(pathExists(markerPath), false, "seal grants no authority to swap-and-restored attacker bytes");
    assert.notEqual(sealError, null, "seal rejects the swap-and-restore attempt");
  });

  withRepo(({ tempRoot, repoRoot, mainSha }) => {
    const manifest = prepare(repoRoot, mainSha);
    const sealed = sealRawManifest(helper, { repoRoot, changeId: "oracle-swap-verify", roundNumber: 1, manifest });
    const originalOraclePath = path.join(repoRoot, manifest.validator.independent_evidence.oracle.source_path);
    const trustedBytes = readFileSync(originalOraclePath);
    const markerPath = path.join(tempRoot, "verify-attacker-ran.txt");
    const state = { command: null, args: null, input: null, result: null };
    const core = coreFactory({ spawnSyncImpl: swapRestoreRunner({ repoRoot, markerPath, trustedBytes, originalOraclePath, state }) });
    let verifyError = null;
    try {
      core.verifyReviewManifest({ repoRoot, manifestRef: sealed.ref, verificationMode: "current" });
    } catch (error) {
      verifyError = error;
    }
    assertCandidateObjectExecution({ state, manifest, trustedBytes, originalOraclePath, label: "current verify" });
    assert.equal(pathExists(markerPath), false, "current verify grants no authority to attacker bytes");
    assert.notEqual(verifyError, null, "current verify rejects the swap-and-restore attempt");
  });
});

test("receipt publication boundary never unlinks a final target after post-validation failure", () => {
  const helper = api();
  const coreFactory = coreApi().createReviewRemediationEvidenceCore;

  function casFsOps({ targetPath, mode, onReadback }) {
    const ownership = Object.freeze({ opaque: `publication-${mode}` });
    let publishedBytes;
    let rollbackCalls = 0;
    return {
      rollbackCalls: () => rollbackCalls,
      createExclusiveTemp() {
        const tempPath = `${targetPath}.${mode}.tmp`;
        return { handle: openSync(tempPath, "wx", 0o600), tempPath };
      },
      writeAll(handle, bytes) {
        let offset = 0;
        while (offset < bytes.length) offset += writeSync(handle, bytes, offset, bytes.length - offset);
        publishedBytes = Buffer.from(bytes);
        return { bytesWritten: bytes.length };
      },
      fsyncFile(handle) { fsyncSync(handle); },
      publishExclusive({ tempPath }) {
        try {
          linkSync(tempPath, targetPath);
          return { published: true, ownership };
        } catch (error) {
          if (error?.code !== "EEXIST") throw error;
          assert.deepEqual(readFileSync(targetPath), publishedBytes, "EEXIST fixture is byte-identical");
          return { idempotent: true };
        }
      },
      fsyncParent() { return { synced: true }; },
      readWholeFile() {
        const bytes = readFileSync(targetPath);
        onReadback?.({ targetPath, bytes });
        return bytes;
      },
      revalidateWholeFile() {},
      closeTemp({ handle }) { closeSync(handle); },
      unlinkTemp({ tempPath }) {
        try { unlinkSync(tempPath); } catch (error) { if (error?.code !== "ENOENT") throw error; }
      },
      removePublished() { rollbackCalls += 1; },
    };
  }

  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "rollback-publication-cas";
    // This fixture tests receipt CAS, not worktree execute bits. On NTFS the
    // 100755 index entries materialize without +x; leave mode checks to the
    // dedicated mode tests so branch checkout remains deterministic here.
    if (process.platform === "win32") git(repoRoot, ["config", "core.filemode", "false"]);
    const targetPath = receiptTarget(repoRoot, changeId, 1);
    const reviewerPayload = authoritativeReceiptPayload(helper, { repoRoot, changeId, baseSha: mainSha });
    const authorityHead = git(repoRoot, ["rev-parse", "HEAD"]);

    git(repoRoot, ["checkout", "-q", "-b", "test/cas-own-a", authorityHead]);
    const fsOps = casFsOps({
      targetPath,
      mode: "own-a",
      onReadback: () => { commitRound(repoRoot, 101); },
    });
    assert.throws(() => coreFactory({ fsOps }).sealReviewRoundReceipt({
      repoRoot, changeId, reviewerPayload: clone(reviewerPayload),
    }), /HEAD|changed|stale|publication/i);
    assert.equal(pathExists(targetPath), true, "published A remains at the final target boundary");
    assert.equal(fsOps.rollbackCalls(), 0, "post-validation failure never attempts to unlink published A");
    git(repoRoot, ["checkout", "-q", "main"]);
    unlinkSync(targetPath);

    git(repoRoot, ["checkout", "-q", "-b", "test/cas-replaced-b", authorityHead]);
    const replacementB = Buffer.from("replacement authority B survives CAS rollback\n");
    const replacedFsOps = casFsOps({
      targetPath,
      mode: "replaced-b",
      onReadback: () => {
        unlinkSync(targetPath);
        writeFileSync(targetPath, replacementB);
        commitRound(repoRoot, 102);
      },
    });
    assert.throws(() => coreFactory({ fsOps: replacedFsOps }).sealReviewRoundReceipt({
      repoRoot, changeId, reviewerPayload: clone(reviewerPayload),
    }), /HEAD|changed|stale|publication/i);
    assert.deepEqual(readFileSync(targetPath), replacementB, "rollback cannot unlink replacement B it does not own");
    assert.equal(replacedFsOps.rollbackCalls(), 0, "post-validation failure never attempts to unlink replacement B");
    git(repoRoot, ["checkout", "-q", "main"]);
    unlinkSync(targetPath);

    git(repoRoot, ["checkout", "-q", "-b", "test/cas-eexist", authorityHead]);
    const sealed = sealReceipt(helper, {
      repoRoot,
      changeId,
      reviewerPayload: clone(reviewerPayload),
    });
    const original = readFileSync(sealed.targetPath);
    const eexistFsOps = casFsOps({
      targetPath: sealed.targetPath,
      mode: "eexist",
      onReadback: () => { commitRound(repoRoot, 103); },
    });
    assert.throws(
      () => coreFactory({ fsOps: eexistFsOps }).sealReviewRoundReceipt({
        repoRoot,
        changeId,
        reviewerPayload: clone(reviewerPayload),
      }),
      /receipt-path-collision/u,
    );
    assert.deepEqual(readFileSync(sealed.targetPath), original, "idempotent EEXIST authority is never rollback-deleted");
    assert.equal(eexistFsOps.rollbackCalls(), 0, "EEXIST never enters published-target rollback");
  });
});

function t17ClosureFinding(id, { severity = "Critical", disposition = "fix-now", carrier = "src/review-target.mjs", anchor = "reviewTarget", evidence = ["src/review-target.mjs"] } = {}) {
  return finding(id, { state: "closed", disposition, observation: observation(id, { severity, carrier, anchor, evidence }) });
}

