test("Round 2 Critical lifecycle rejects blocked/partial outer-resigned closed follow-up dispositions", async (t) => {
  const helper = api();
  for (const verdict of ["blocked", "partial"]) {
    for (const disposition of ["tracked-follow-up", "defer-with-owner-trigger"]) {
      await t.test(`${verdict} Critical ${disposition}`, () => withRepo(({ repoRoot, mainSha }) => {
        const changeId = `critical-lifecycle-verify-${verdict}-${disposition}`;
        const trusted = sealInitial(helper, {
          repoRoot,
          changeId,
          mainSha,
          verdict,
          findings: [t17ClosureFinding("F-follow-up", { severity: "Suggestion", disposition })],
        });
        const tampered = clone(trusted.receipt);
        tampered.reviewer_payload.findings[0].observation.severity = "Critical";
        const resigned = resignReceiptEnvelope(helper, tampered);
        const tamperedRef = writeReceiptEnvelope(helper, trusted.targetPath, resigned);

        assert.equal(
          resigned.receipt_digest_sha256,
          sha256(helper.canonicalJsonV1(resigned.reviewer_payload)),
          "the forged receipt has a recomputed payload envelope digest",
        );
        assert.deepEqual(
          resigned.observation_hashes,
          receiptObservationHashes(helper, resigned.reviewer_payload.findings),
          "the forged receipt has recomputed observation hashes",
        );
        assert.deepEqual(
          tamperedRef,
          durableRef(repoRoot, trusted.targetPath),
          "the caller presents the exact recomputed whole-file ref",
        );
        assert.throws(
          () => helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: tamperedRef }),
          /Critical|disposition|blocking|converge|evidence/i,
          "outer digests cannot legitimize a closed Critical follow-up",
        );
      }));
    }
  }
});

