test("Critical allowed dispositions require current HEAD carrier anchor and evidence", async (t) => {
  const helper = api();
  await withRepo(async (standardRepo) => withRepo(async (staleRepo) => {
    write(staleRepo.repoRoot, "src/stale-critical-evidence.mjs", "export const staleEvidence = true;\n");
    commitAll(staleRepo.repoRoot, "add historical critical evidence");
    rmSync(path.join(staleRepo.repoRoot, "src/stale-critical-evidence.mjs"));
    commitAll(staleRepo.repoRoot, "remove stale critical evidence before bound HEAD");

    const makeNegativeAuthority = ({ repoRoot, mainSha }, changeId) => {
      ensureRiskFixture(repoRoot, changeId);
      return {
        repoRoot,
        mainSha,
        changeId,
        reviewerPayload: authoritativeReceiptPayload(helper, {
          repoRoot,
          changeId,
          baseSha: mainSha,
          mergeBaseSha: mainSha,
          headSha: git(repoRoot, ["rev-parse", "HEAD"]),
          verdict: "finished",
          findings: [t17ClosureFinding("F-proof-invalid", { disposition: "fix-now" })],
          openFindingIds: [],
        }),
      };
    };
    const standardAuthority = makeNegativeAuthority(standardRepo, "critical-invalid-proof-shared");
    const staleAuthority = makeNegativeAuthority(staleRepo, "critical-stale-proof-shared");

    // Scenario: D30 domain failure returns a closed code and static action detail
    await t.test("a missing bound-HEAD evidence carrier returns the closed receipt code", () => withRepo(({ tempRoot, repoRoot, mainSha }) => {
      const changeId = "critical-cli-missing-bound-evidence";
      ensureRiskFixture(repoRoot, changeId);
      const reviewerPayload = authoritativeReceiptPayload(helper, {
        repoRoot,
        changeId,
        baseSha: mainSha,
        mergeBaseSha: mainSha,
        headSha: git(repoRoot, ["rev-parse", "HEAD"]),
        verdict: "finished",
        findings: [t17ClosureFinding("F-cli-missing-carrier")],
        openFindingIds: [],
      });
      // Keep the raw reviewer capture valid; mutate only the receipt content so
      // the D30 seal handler reaches the bound-HEAD proof lookup under test.
      reviewerPayload.findings[0].observation.carrier = "src/missing-proof.mjs";
      const result = runReviewEvidenceCli(tempRoot, repoRoot, "seal-receipt", `${JSON.stringify({ changeId, repoRoot, reviewerPayload })}\n`);
      assert.equal(result.status, 1, `${result.stdout}${result.stderr}`);
      assert.deepEqual(JSON.parse(result.stdout), {
        ok: false,
        code: "receipt-evidence-invalid",
        detail: "Check receipt bytes, schema, chain, and cross-carrier evidence.",
      });
    }));

    // Scenario: Native I/O remains the generic failure
    await t.test("a native Git fault during bound-HEAD proof lookup stays untyped", () => withRepo(({ repoRoot, mainSha }) => {
      const changeId = "critical-native-bound-evidence-read";
      ensureRiskFixture(repoRoot, changeId);
      const reviewerPayload = authoritativeReceiptPayload(helper, {
        repoRoot,
        changeId,
        baseSha: mainSha,
        mergeBaseSha: mainSha,
        headSha: git(repoRoot, ["rev-parse", "HEAD"]),
        verdict: "finished",
        findings: [t17ClosureFinding("F-native-carrier")],
        openFindingIds: [],
      });
      const nativeFault = Object.assign(new Error("injected tree read EIO"), { code: "EIO" });
      const gitOps = Object.freeze({
        ...countingSemanticGitOps().ops,
        readExactTreeRecord() { throw nativeFault; },
      });
      const core = coreApi().createReviewRemediationEvidenceCore({ gitOps });
      assert.throws(
        () => core.sealReviewRoundReceipt({ repoRoot, changeId, reviewerPayload }),
        (error) => error === nativeFault,
        "a failed Git tree read must not be converted into a receipt-content code",
      );
    }));

    for (const disposition of ["fix-now", "non-issue-with-evidence"]) {
      await t.test(`${disposition} accepts current HEAD-bound proof`, () => withRepo(({ repoRoot, mainSha }) => {
        const changeId = `critical-proof-${disposition}`;
        ensureRiskFixture(repoRoot, changeId);
        const memoized = memoizedImmutableSemanticGitOps();
        const core = coreApi().createReviewRemediationEvidenceCore({ gitOps: memoized.ops });
        const sealed = sealReceipt(core, { repoRoot, changeId, reviewerPayload: authoritativeReceiptPayload(core, {
          repoRoot, changeId, baseSha: mainSha, mergeBaseSha: mainSha, headSha: git(repoRoot, ["rev-parse", "HEAD"]), verdict: "finished",
          findings: [t17ClosureFinding("F-proof", { disposition })], openFindingIds: [] }) });
        assert.doesNotThrow(() => core.verifyReviewRoundReceipt({ repoRoot, receiptRef: sealed.ref }));
        assert.ok(memoized.cacheHits() > 0, "positive proof reuses the unchanged per-row Git authority");
      }));
      await t.test(`${disposition} accepts distinct evidence path present at the bound HEAD`, () => withRepo(({ repoRoot, mainSha }) => {
        const changeId = `critical-proof-${disposition}-distinct-evidence`;
        ensureRiskFixture(repoRoot, changeId);
        const memoized = memoizedImmutableSemanticGitOps();
        const core = coreApi().createReviewRemediationEvidenceCore({ gitOps: memoized.ops });
        const sealed = sealReceipt(core, { repoRoot, changeId, reviewerPayload: authoritativeReceiptPayload(core, {
          repoRoot, changeId, baseSha: mainSha, mergeBaseSha: mainSha, headSha: git(repoRoot, ["rev-parse", "HEAD"]), verdict: "finished",
          findings: [t17ClosureFinding("F-distinct-evidence", { disposition, evidence: ["src/second-target.mjs"] })], openFindingIds: [] }) });
        assert.doesNotThrow(() => core.verifyReviewRoundReceipt({ repoRoot, receiptRef: sealed.ref }));
        assert.ok(memoized.cacheHits() > 0, "distinct evidence reuses the unchanged per-row Git authority");
      }));
      for (const [label, proof] of [
        ["missing-carrier", { carrier: "src/missing-proof.mjs", anchor: "missingProof" }],
        ["stale-carrier-anchor", { anchor: "anchor-only-in-an-older-object" }],
        ["missing-evidence", { evidence: ["src/missing-evidence.mjs"] }],
        ["stale-evidence", { evidence: ["src/stale-critical-evidence.mjs"] }],
      ]) {
        await t.test(`${disposition} rejects ${label} proof`, () => {
          const authority = label === "stale-evidence" ? staleAuthority : standardAuthority;
          const reviewerPayload = clone(authority.reviewerPayload);
          reviewerPayload.findings = [t17ClosureFinding("F-proof-invalid", { disposition, ...proof })];
          reviewerPayload.dispatch_id = logicalDispatchIdForPayload(helper, authority.changeId, reviewerPayload);
          const targetPath = receiptTarget(authority.repoRoot, authority.changeId, 1);
          assert.equal(pathExists(targetPath), false, `${label}: shared negative authority starts unpublished`);
          assert.throws(
            () => helper.sealReviewRoundReceipt({
              repoRoot: authority.repoRoot,
              changeId: authority.changeId,
              reviewerPayload,
            }),
            coreFailureIs("receipt-evidence-invalid"),
          );
          assert.equal(pathExists(targetPath), false, `${label}: fail-closed row publishes no receipt`);
        });
      }
    }
  }));
});

