test("classify-bounded risk_shape_debug_reason falls back to unclassified_fault for an unmapped exception (fix-risk-shape-unavailable-diagnostics T4)", () => {
  const coreFactory = coreApi().createReviewRemediationEvidenceCore;
  withRepo(({ repoRoot }) => {
    const changeId = "risk-shape-unclassified-fault";
    writeFullRiskChange(repoRoot, changeId);
    commitAll(repoRoot, "unclassified fault fixture baseline");
    const proposalPath = realpathSync(path.join(repoRoot, "openspec", "changes", changeId, "proposal.md"));
    // deriveRiskShapeSnapshot()'s own `exists(fullPath)` existence probe is not
    // covered by any of the risk-shape fault-scope marking points (design.md
    // D2): a non-ENOENT lstatSync failure there must fall through to the
    // fail-closed unclassified_fault default, not silently disappear.
    const fsOps = {
      lstatSync(subject, ...args) {
        if (path.resolve(subject) === proposalPath) {
          const error = new Error("EACCES: permission denied (unclassified-fault fixture)");
          error.code = "EACCES";
          throw error;
        }
        return lstatSync(subject, ...args);
      },
    };
    const classified = classifyInitialWithCore(coreFactory, fsOps, repoRoot, changeId);
    assert.equal(classified.route, "risk_shape_unavailable");
    assert.equal(classified.risk_shape_debug_reason, "unclassified_fault");
  });
});

test("classify-bounded risk_shape_debug_reason set-if-absent marks the innermost carrier fault first (fix-risk-shape-unavailable-diagnostics T4 nested priority)", () => {
  const helper = api();
  withRepo(({ tempRoot, repoRoot }) => {
    const changeId = "risk-shape-nested-priority";
    writeFullRiskChange(repoRoot, changeId);
    commitAll(repoRoot, "nested priority fixture baseline");
    // currentCapabilityDocuments() -> pinnedRiskFile() (core:940) is nested
    // inside currentCapabilityDocuments()'s own capability_delta_invalid
    // call-boundary default. A carrier-integrity fault on the capability spec
    // itself must be marked carrier_integrity_unsafe by the inner pinnedRiskFile()
    // wrap before the outer capability_delta_invalid default gets a chance --
    // this is the only test that proves "innermost mark wins" is load-bearing,
    // not coincidental (design.md D2).
    const specPath = path.join(repoRoot, "openspec", "changes", changeId, "specs", "risk-fixture", "spec.md");
    const outside = path.join(tempRoot, `${changeId}-outside-spec.md`);
    writeFileSync(outside, riskDeltaSpec());
    unlinkSync(specPath);
    symlinkSync(outside, specPath);
    const classified = initialClassification(helper, { repoRoot, changeId });
    assert.equal(classified.route, "risk_shape_unavailable");
    assert.equal(
      classified.risk_shape_debug_reason,
      "carrier_integrity_unsafe",
      "the inner pinnedRiskFile() mark for the capability spec carrier must win over the outer capability_delta_invalid default",
    );
  });
});

test("CLI help documents risk_shape_debug_reason as a human-diagnosis-only closed enum with per-value next steps (fix-risk-shape-unavailable-diagnostics T5)", () => {
  const help = execFileSync(process.execPath, [HELPER_PATH, "--help"], { encoding: "utf8" });
  // Isolate this route's own section of cliHelp()'s output before asserting on
  // it -- see the sibling full_reopen_debug_reason test above for why (round-1
  // review F-RSD-01): the two sections share the same "for human diagnosis
  // only" / "MUST NOT be read as a routing signal" / unclassified_fault
  // vocabulary, so a full-text search here could be satisfied by the wrong
  // section and miss a regression in this one.
  const fullReopenHeader = "classify-bounded route=full_reopen_required also carries full_reopen_debug_reason, for human diagnosis only.";
  const riskShapeHeader = "classify-bounded route=risk_shape_unavailable also carries risk_shape_debug_reason, for human diagnosis only.";
  const riskShapeStart = help.indexOf(riskShapeHeader);
  assert.notEqual(help.indexOf(fullReopenHeader), -1, "CLI help must document the full_reopen_required section header");
  assert.notEqual(riskShapeStart, -1, "CLI help must document the risk_shape_unavailable section header");
  const section = help.slice(riskShapeStart);
  assert.match(section, /risk_shape_debug_reason/);
  assert.match(section, /for human diagnosis only/i);
  assert.match(section, /MUST NOT be read as a routing signal/);
  const reasons = [
    "carrier_not_at_head",
    "section_shape_invalid",
    "front_matter_invalid",
    "change_folder_invalid",
    "capability_delta_invalid",
    "carrier_integrity_unsafe",
    "request_or_git_authority_invalid",
    "unclassified_fault",
  ];
  const nextStepLines = [];
  for (const reason of reasons) {
    assert.match(section, new RegExp(reason), `CLI help must document the ${reason} debug reason`);
    const line = section.split("\n").find((candidate) => candidate.trim().startsWith(`${reason}:`));
    assert.notEqual(line, undefined, `CLI help must have a dedicated next-step line for ${reason}`);
    nextStepLines.push(line);
  }
  assert.equal(
    new Set(nextStepLines).size,
    nextStepLines.length,
    "each risk_shape_debug_reason value must have a unique next-step sentence",
  );
  assert.doesNotMatch(section, /ignore|can be skipped|no action needed/i, "CLI help must not imply the risk_shape_unavailable judgment can be ignored");
});

// F-RSD-03 (six-axis review round 1 fix, added 2026-09-03) appended index 109
// at the very end of the file for the same append-only reason as F5 above;
// only runner_d's upper bound moved again (108 -> 109).
// Depth-aware call-site argument extractor for the risk-shape lock test
// below: several call sites nest another call inside an argument (e.g.
// `markRiskShapeFault(new Error(message), reason)`), so a naive
// `\(([^)]*)\)` regex (fine for the sibling fullReopen() lock test, whose
// call sites never nest) would stop at the first inner `)` and mis-split the
// arguments. Tracks paren depth to find each argument's true top-level
// boundaries instead.
function riskShapeCallSiteArgs(source, calleeName) {
  const results = [];
  const opener = new RegExp(`(?<![\\w.])${calleeName}\\(`, "g");
  let match;
  while ((match = opener.exec(source)) !== null) {
    const precedingSlice = source.slice(0, match.index);
    if (/function\s+$/.test(precedingSlice)) continue;
    let depth = 1;
    let cursor = match.index + match[0].length;
    let argStart = cursor;
    const args = [];
    while (depth > 0 && cursor < source.length) {
      const char = source[cursor];
      if (char === "(") {
        depth += 1;
      } else if (char === ")") {
        depth -= 1;
        if (depth === 0) args.push(source.slice(argStart, cursor));
      } else if (char === "," && depth === 1) {
        args.push(source.slice(argStart, cursor));
        argStart = cursor + 1;
      }
      cursor += 1;
    }
    results.push({ callText: source.slice(match.index, cursor), args: args.map((arg) => arg.trim()) });
  }
  return results;
}

test("every failRiskShape()/withRiskShapeFaultScope()/riskUnavailable()/markRiskShapeFault() call site passes a named RISK_SHAPE_DEBUG_REASONS member (not a bare string) (fix-risk-shape-unavailable-diagnostics F-RSD-03)", () => {
  const coreSource = readFileSync(CORE_PATH, "utf8");
  const namedMemberPattern = /^RISK_SHAPE_DEBUG_REASONS\.[A-Z_]+$/;
  // Strip comments before scanning for call sites: prose that merely mentions
  // one of these function names (e.g. "the group their enclosing
  // withRiskShapeFaultScope() call would otherwise assign by default") is not
  // an actual call site and must not be matched.
  const coreSourceNoComments = stripJsCommentSpans(coreSource);

  const failRiskShapeCallSites = riskShapeCallSiteArgs(coreSourceNoComments, "failRiskShape");
  assert.ok(failRiskShapeCallSites.length > 0, "expected at least one failRiskShape() call site in the core module");
  for (const { callText, args } of failRiskShapeCallSites) {
    assert.match(
      args[1] ?? "",
      namedMemberPattern,
      `failRiskShape() call site "${callText}" must pass a named RISK_SHAPE_DEBUG_REASONS member as its second argument, not a bare literal`,
    );
  }

  const withRiskShapeFaultScopeCallSites = riskShapeCallSiteArgs(coreSourceNoComments, "withRiskShapeFaultScope");
  assert.ok(withRiskShapeFaultScopeCallSites.length > 0, "expected at least one withRiskShapeFaultScope() call site in the core module");
  for (const { callText, args } of withRiskShapeFaultScopeCallSites) {
    assert.match(
      args[0] ?? "",
      namedMemberPattern,
      `withRiskShapeFaultScope() call site "${callText}" must pass a named RISK_SHAPE_DEBUG_REASONS member as its first argument, not a bare literal`,
    );
  }

  const riskUnavailableCallSites = riskShapeCallSiteArgs(coreSourceNoComments, "riskUnavailable");
  assert.ok(riskUnavailableCallSites.length > 0, "expected at least one riskUnavailable() call site in the core module");
  for (const { callText, args } of riskUnavailableCallSites) {
    const reasonArg = args[1] ?? "";
    const isNamedMember = namedMemberPattern.test(reasonArg);
    // riskShapeFaultReason(error) is the one legitimate non-literal call site:
    // it reads the out-of-band WeakMap fault mark rather than passing a
    // literal directly. Its own function body is checked below to close the
    // gap this exception would otherwise open.
    const isFaultReasonLookup = reasonArg === "riskShapeFaultReason(error)";
    assert.ok(
      isNamedMember || isFaultReasonLookup,
      `riskUnavailable() call site "${callText}" must pass a named RISK_SHAPE_DEBUG_REASONS member or riskShapeFaultReason(error) as its second argument, not a bare literal (got "${reasonArg}")`,
    );
  }

  const markRiskShapeFaultCallSites = riskShapeCallSiteArgs(coreSourceNoComments, "markRiskShapeFault");
  assert.ok(markRiskShapeFaultCallSites.length > 0, "expected at least one markRiskShapeFault() call site in the core module");
  for (const { callText, args } of markRiskShapeFaultCallSites) {
    assert.match(
      args[1] ?? "",
      /^reason$/,
      `markRiskShapeFault() call site "${callText}" must forward the enclosing function's own "reason" parameter, not a bare literal`,
    );
  }

  // Close the gap the riskShapeFaultReason(error) exception above opens: its
  // function body itself must only ever return a named RISK_SHAPE_DEBUG_REASONS
  // member (or the WeakMap lookup falling back to one), never an arbitrary
  // string, so canonicalJsonV1 can never see an unmapped literal.
  const riskShapeFaultReasonBody = sourceFunctionSlice(coreSource, "riskShapeFaultReason", "failRiskShape");
  const returnedValues = [...riskShapeFaultReasonBody.matchAll(/return\s+([^;]+);/g)].map(([, value]) => value.trim());
  assert.ok(returnedValues.length > 0, "expected at least one return statement in riskShapeFaultReason()");
  for (const value of returnedValues) {
    assert.match(
      value,
      /^(?:RISK_SHAPE_DEBUG_REASONS\.[A-Z_]+|RISK_SHAPE_FAULT_SCOPE\.get\(error\) \?\? RISK_SHAPE_DEBUG_REASONS\.[A-Z_]+)$/,
      `riskShapeFaultReason() must only return a named RISK_SHAPE_DEBUG_REASONS member (got "${value}")`,
    );
  }
});

test("classify-bounded rejects overrides outside handback while cumulative totals remain advisory", () => {
  const helper = api();
  const help = execFileSync(process.execPath, [HELPER_PATH, "--help"], { encoding: "utf8" });
  assert.match(help, /budgetState is audit\/report only and never changes routing or dispatch authorization/);
  assert.doesNotMatch(help, /exhausted never issues a dispatch id/);
  assert.doesNotMatch(help, /at-or-above-half issues a route=full dispatch id only after/);
  assert.match(help, /full_reopen_reason=convergence_recovery/);
  assert.match(help, /recovery reason, NOT a full reopen/);
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "half-state-override-classify";
    boundChange(repoRoot, changeId);
    const base = { repoRoot, changeId, previousReceiptRef: null, repairDeltaManifestRef: null, dependencyClosureManifestRef: null, predecessorMatches: [] };
    const plain = helper.classifyBoundedRereview({ ...base, budgetState: "below-half" });
    assertDispatchableResult(plain, { route: "full", count: 0, round: 1, reason: "initial_review" });
    assert.deepEqual(helper.classifyBoundedRereview(base), plain, "budgetState defaults to unavailable and changes nothing below the gate");
    // Half-state used to revoke the automatic full dispatch here and demand an
    // override. `fix-zero-value-review-rounds` R1/D19 removed that: the state
    // is derived from the three cumulative totals, and a total cannot show
    // whether a round is wasting anything.
    assert.deepEqual(
      helper.classifyBoundedRereview({ ...base, budgetState: "at-or-above-half" }),
      plain,
      "half-state no longer revokes anything",
    );
    const issued = issueHalfStateOverride({ repoRoot, changeId, responsibilityId: "primary-review", reason: "user: one handback continuation" });
    assert.equal(issued.ok, true, issued.code);
    assert.throws(
      () => helper.classifyBoundedRereview({ ...base, budgetState: "at-or-above-half", overrideId: issued.override_id, responsibilityId: "primary-review" }),
      /override scope is review-dispatch: route=full is not an authorized handback continuation/,
      "an ordinary initial full dispatch must not consume handback authority",
    );
    assert.equal(halfStateOverrideStatus({ repoRoot, changeId, overrideId: issued.override_id }), "issued");
    const foreign = issueHalfStateOverride({ repoRoot, changeId, responsibilityId: "design-review", reason: "user: design review only" });
    assert.throws(
      () => helper.classifyBoundedRereview({ ...base, budgetState: "at-or-above-half", overrideId: foreign.override_id, responsibilityId: "primary-review" }),
      /override scope is review-dispatch: route=full is not an authorized handback continuation/,
      "route eligibility fails before an unrelated override record is read",
    );
    assert.equal(halfStateOverrideStatus({ repoRoot, changeId, overrideId: foreign.override_id }), "issued");
    // `exhausted` used to be a hard stop. That routing effect is gone: a
    // request with every other input complete issues a
    // dispatch id with no override at all, however large the totals grew. This
    // fixture reaches the gate on `previousReceiptRef: null`, a first dispatch
    // with no chain behind it, so the stall budget (D6) cannot be what admits
    // it and the verdict is attributable to this deletion alone.
    const bareAtExhausted = helper.classifyBoundedRereview({ ...base, budgetState: "exhausted" });
    assert.deepEqual(bareAtExhausted, plain, "brd S3: no override is needed either");
    assert.notEqual(bareAtExhausted.dispatch_id, null, "brd S3 states the outcome as a non-null dispatch id");
    // The input validation D18 keeps is untouched, and none of it consumes.
    const unclaimed = issueHalfStateOverride({ repoRoot, changeId, responsibilityId: "primary-review", reason: "user: unclaimed" });
    assert.throws(() => helper.classifyBoundedRereview({ ...base, budgetState: "plenty" }), /budgetState must be one of/);
    assert.throws(() => helper.classifyBoundedRereview({ ...base, overrideId: "nope", responsibilityId: "primary-review" }), /overrideId must be a UUID v4/);
    assert.throws(() => helper.classifyBoundedRereview({ ...base, overrideId: unclaimed.override_id }), /overrideId requires responsibilityId/);
    assert.throws(() => helper.classifyBoundedRereview({ ...base, batchApproval: true }), /unknown or missing fields: batchApproval/);
    assert.equal(halfStateOverrideStatus({ repoRoot, changeId, overrideId: unclaimed.override_id }), "issued", "rejected inputs never consume");
  });
});

// --- continue-mode admission chain (strengthen-subagent-delegation-strategy T32/T35, decisions.md D34) ---
// A `SendMessage` / `followup_task` continuation of the same responsibility thread
// writes its own admission record at the new head with `parent_record_id` pointing
// at the record it continues. Independence therefore rests on a machine-verified
// chain back to the thread's fresh root, not on the continuation payload (which
// carries no role field on either runtime -> role_binding stays cooperative-only).
// The generic v1 receipt face walks the same chain (strengthen-continuation-receipt-chain-verification);
// its matrix lives at the end of this file.

const CYCLE_RECORD_A = "11111111-1111-4111-8111-111111111111";
const CYCLE_RECORD_B = "22222222-2222-4222-8222-222222222222";

test("archive transition refuses any tracked path under the gitignored hook-carrier prefixes", async (t) => {
  const helper = api();
  const coreFactory = coreApi().createReviewRemediationEvidenceCore;
  const forceAdd = (repoRoot, relativePath, body) => {
    write(repoRoot, relativePath, body);
    git(repoRoot, ["add", "-f", "--", relativePath]);
  };
  const sealTransition = (repoRoot, changeId) => {
    const fake = transitionRunner();
    return coreFactory({ spawnSyncImpl: fake.runner }).sealFinalEvidenceRecord({
      repoRoot, changeId, canonicalOwnerId: "owner-1",
    });
  };

  // (1) archive-side injection under admission-records/ with no matching
  //     active-side deletion: the exact shape the old pairing never inspected.
  await t.test("an archive-side admission-records addition with no matching deletion is refused", () => {
    withRepo(({ repoRoot, mainSha }) => {
      const changeId = "transition-carrier-injected-admission";
      prepareArchiveTransitionFixture(helper, {
        repoRoot,
        mainSha,
        changeId,
        mutateArchive: ({ repoRoot: root, archiveRelativeRoot }) => {
          forceAdd(root, path.join(archiveRelativeRoot, "admission-records", "injected.json"), "{\"smuggled\":true}\n");
        },
      });
      assert.throws(() => sealTransition(repoRoot, changeId), /gitignored|must not be tracked|untrack/i);
    });
  });

  // (2) same injection under override-ledger/.
  await t.test("an archive-side override-ledger addition with no matching deletion is refused", () => {
    withRepo(({ repoRoot, mainSha }) => {
      const changeId = "transition-carrier-injected-override";
      prepareArchiveTransitionFixture(helper, {
        repoRoot,
        mainSha,
        changeId,
        mutateArchive: ({ repoRoot: root, archiveRelativeRoot }) => {
          forceAdd(root, path.join(archiveRelativeRoot, "override-ledger", "injected.json"), "{\"smuggled\":true}\n");
        },
      });
      assert.throws(() => sealTransition(repoRoot, changeId), /gitignored|must not be tracked|untrack/i);
    });
  });

  // (3) tracked on BOTH sides (present at the reviewed head, moved into the
  //     archive by the archive commit): the old code paired the active-side D
  //     against the archive-side A and accepted it. The message must tell the
  //     operator to untrack.
  await t.test("a carrier tracked on both sides is refused with untrack guidance", () => {
    withRepo(({ repoRoot, mainSha }) => {
      const changeId = "transition-carrier-tracked-both-sides";
      prepareArchiveTransitionFixture(helper, {
        repoRoot,
        mainSha,
        changeId,
        mutateReviewed: ({ repoRoot: root }) => {
          forceAdd(root, path.join("openspec", "changes", changeId, "admission-records", "tracked.json"), "{\"tracked\":true}\n");
        },
      });
      assert.throws(() => sealTransition(repoRoot, changeId), /untrack/i);
    });
  });

  // (4) regression guard: with neither prefix tracked anywhere (the shape a
  //     real repo always has, because both are gitignored), a normal
  //     transition still seals.
  await t.test("a transition with no tracked hook-carrier paths still seals", () => {
    withRepo(({ repoRoot, mainSha }) => {
      const changeId = "transition-carrier-clean";
      prepareArchiveTransitionFixture(helper, { repoRoot, mainSha, changeId });
      assert.ok(sealTransition(repoRoot, changeId), "a clean transition still seals");
    });
  });

  // (5) regression guard for the ORDINARY production shape: a gitignored hook
  //     carrier already sitting in the active change folder at reviewed-head
  //     time (written, never `git add -f`-ed). It is present on disk in both
  //     trees and absent from both, so the absence assertions must stay quiet.
  await t.test("an untracked hook carrier present at the reviewed head still seals", () => {
    withRepo(({ repoRoot, mainSha }) => {
      const changeId = "transition-carrier-untracked-at-reviewed-head";
      prepareArchiveTransitionFixture(helper, {
        repoRoot,
        mainSha,
        changeId,
        mutateReviewed: ({ repoRoot: root }) => {
          write(root, path.join("openspec", "changes", changeId, "admission-records", "present.json"), "{\"present\":true}\n");
          write(root, path.join("openspec", "changes", changeId, "override-ledger", "present.json"), "{\"present\":true}\n");
        },
      });
      // `ls-files` returns "" both for an untracked file and for no file at
      // all, so prove presence on disk first — otherwise this guard passes
      // vacuously if the fixture ever stops moving the carrier.
      const archivedCarrier = path.join(
        repoRoot,
        "openspec/changes/archive",
        `2026-08-21-${changeId}`,
        "admission-records",
        "present.json",
      );
      assert.ok(existsSync(archivedCarrier), "the carrier must actually be on disk at the archive path");
      assert.equal(
        git(repoRoot, ["ls-files", "--", `openspec/changes/archive/2026-08-21-${changeId}/admission-records`]),
        "",
        "the carrier is gitignored, so it is present on disk but never tracked",
      );
      assert.ok(sealTransition(repoRoot, changeId), "the ordinary production shape still seals");
    });
  });

  // (6) r19 `F-r19-mode-mismatch-message`, re-opened at r21 after r20 silently
  //     substituted its observation subject: a hook carrier force-added with
  //     mode 100755 hit `transitionTreeFactFromListing`'s exact-100644 check
  //     before `assertHookCarriersUntracked` ever ran, so the operator was told
  //     to fix a file mode on a path that must not be tracked at all -- the
  //     less actionable of the two messages. The untracked assertion now runs
  //     first, off a `--name-only` listing that never parses modes.
  await t.test("an executable-mode tracked carrier is refused with untrack guidance, not a file-mode message", () => {
    withRepo(({ repoRoot, mainSha }) => {
      const changeId = "transition-carrier-executable-mode";
      prepareArchiveTransitionFixture(helper, {
        repoRoot,
        mainSha,
        changeId,
        mutateReviewed: ({ repoRoot: root }) => {
          const relativePath = path.join("openspec", "changes", changeId, "admission-records", "tracked.json");
          forceAdd(root, relativePath, "{\"tracked\":true}\n");
          // The fixture's commit re-stages from the working tree, so the mode
          // has to be real on disk -- `update-index --chmod` alone gets reset.
          chmodSync(path.join(root, relativePath), 0o755);
          git(root, ["add", "-f", "--", relativePath]);
        },
      });
      assert.throws(
        () => sealTransition(repoRoot, changeId),
        (error) => /untrack/i.test(error.message) && !/100644/.test(error.message),
        "a path that must not be tracked has to be reported as untrack-me, never as a file-mode problem",
      );
    });
  });
});

// PR #2473 cross-model Critical B2: `assertAdmissionRecordUnique` read every
// receipt-shaped file in notes/ with a plain `readFileSync` on a lexically
// joined path (symlink-following, unbounded) and swallowed every read/parse
// error with `catch { continue; }`. Making a conflicting receipt unreadable or
// unparseable therefore bypassed the uniqueness check entirely (fail open).
function preparedRuntimeAdmissionFixture({ repoRoot, changeId }) {
  const cwd = path.join(path.dirname(repoRoot), ".worktree", changeId);
  mkdirSync(path.dirname(cwd), { recursive: true });
  git(repoRoot, ["worktree", "add", "--quiet", "--detach", cwd, "HEAD"]);
  const request = {
    schema: CODEX_REVIEWER_REQUEST_SCHEMA,
    change_id: changeId,
    base_sha: git(repoRoot, ["rev-parse", "main"]),
    head_sha: git(repoRoot, ["rev-parse", "HEAD"]),
    objective: "independent-judgment",
    responsibility_id: "primary-review",
    instance_mode: "fresh",
    evidence_scope: "local diff",
    return_and_stop: "return findings and stop",
    role: "dp-reviewer",
    agent_type: "dp-reviewer",
    task_name: "runtime_review",
    fork_turns: "none",
    context_mode: "fresh",
    ttl_seconds: 600,
  };
  const intent = issueCodexReviewerAdmission({ cwd, request });
  assert.equal(intent.ok, true, intent.code);
  const admission = admitPreparedCodexReviewer({
    cwd,
    toolInput: { agent_type: "dp-reviewer", task_name: "runtime_review", fork_turns: "none", message: `gAAAAA${"A".repeat(48)}` },
  });
  assert.equal(admission.ok, true, admission.code);
  // Receipt tests below exercise authority sealing from the fixture's main
  // checkout. T18 separately proves the admission itself must originate from
  // a real linked-worktree root; mirror that already-verified local authority
  // into the receipt fixture so those tests do not substitute a fake cwd.
  cpSync(
    path.join(cwd, "openspec", "changes", changeId, "admission-records"),
    path.join(repoRoot, "openspec", "changes", changeId, "admission-records"),
    { recursive: true },
  );
  // strengthen-admission-binding-portability: the consumer side now resolves
  // its records, change directory, and HEAD through the SAME exact-one binding
  // root (design D7.1), so with this worktree still linked the seals below
  // would write and read the worktree copy instead of the main checkout this
  // fixture publishes. Removing the worktree models the post-merge window the
  // consumer's 0-candidate fallback deliberately keeps working; the
  // worktree-present main-cwd round trip is covered by
  // main-cwd-receipt-round-trip.test.mjs.
  git(repoRoot, ["worktree", "remove", "--force", cwd]);
  return admission;
}

// New contract cases have an explicit shard owner; existing indexed registrations
