if (REVIEW_REMEDIATION_EVIDENCE_TEST_GROUP === "runner_d4") {
  nodeTest("primary guarantee assessment survives real capture seal verify without changing observations", () => {
    const helper = api();
    withRepo(({ repoRoot, mainSha }) => {
      const changeId = "add-guarantee-assessment";
      writeFullRiskChange(repoRoot, changeId);
      commitAll(repoRoot, "guarantee assessment dispatch baseline");
      const { payload } = initialPayloadFromDispatch(helper, { repoRoot, changeId, mainSha });
      payload.guarantee_assessment = {
        schema: "devpro.review-guarantee-assessment/v1",
        reviewed_target: payload.lineage.head_sha,
        dispatch_id: payload.dispatch_id,
        assessments: payload.findings.map(entry => ({
          finding_id: entry.finding_id, guarantee_ceiling: "Cooperative code review; shape checks are mechanical.",
          classification: "above-ceiling", rationale: "TL must check the claimed scope against the requirement owner.",
        })),
      };
      const observations = receiptObservationHashes(helper, payload.findings);
      const raw = clone(payload);
      raw.review_authority = null;
      raw.output_evidence = null;
      const payloadPath = path.join(repoRoot, "reviewer-output.json");
      writeFileSync(payloadPath, `${helper.canonicalJsonV1(raw)}\n`);
      const captured = helper.captureReviewerOutput({
        repoRoot, changeId, roundNumber: payload.round_number, dispatchId: payload.dispatch_id, payloadPath,
      });
      assert.ok(captured.digest_sha256, "production capture accepts the new metadata");
      const sealed = sealReceipt(helper, { repoRoot, changeId, reviewerPayload: payload });
      const verified = helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: sealed.ref }).receipt;
      assert.deepEqual(verified.reviewer_payload.guarantee_assessment, payload.guarantee_assessment);
      assert.deepEqual(verified.observation_hashes, observations);
      assert.deepEqual(verified.reviewer_payload.findings, payload.findings);
    });
  });


  nodeTest("primary assessment rejects copied binding and unresolved blocks actual final readiness", () => {
    const helper = api();
    for (const classification of ["above-ceiling", "unresolved"]) {
      withRepo(({ repoRoot, mainSha }) => {
        const changeId = "add-primary-assessment-" + classification;
        writeFullRiskChange(repoRoot, changeId); commitAll(repoRoot, "assessment final baseline");
        const { payload } = initialPayloadFromDispatch(helper, {
          repoRoot, changeId, mainSha, findings: [finding("F1", { state: "closed", disposition: "fix-now", observation: observation("F1", { severity: "Suggestion" }) })],
        });
        payload.guarantee_assessment = {
          schema: "devpro.review-guarantee-assessment/v1", reviewed_target: payload.lineage.head_sha, dispatch_id: payload.dispatch_id,
          assessments: [{ finding_id: "F1", guarantee_ceiling: "design-core: cooperative review", classification, rationale: "TL scope disposition is needed." }],
        };
        const raw = clone(payload); raw.review_authority = null; raw.output_evidence = null;
        const payloadPath = path.join(repoRoot, "assessment-output.json");
        for (const key of ["reviewed_target", "dispatch_id"]) {
          const wrong = clone(raw); wrong.guarantee_assessment[key] = "b".repeat(40);
          writeFileSync(payloadPath, helper.canonicalJsonV1(wrong) + "\n");
          assert.throws(() => helper.captureReviewerOutput({ repoRoot, changeId, roundNumber: payload.round_number, dispatchId: payload.dispatch_id, payloadPath }), { code: "raw-payload-invalid" });
        }
        unlinkSync(payloadPath);
        const sealed = sealReceipt(helper, { repoRoot, changeId, reviewerPayload: payload });
        assert.deepEqual(helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: sealed.ref }).receipt.reviewer_payload.guarantee_assessment, payload.guarantee_assessment);
        // The verify CLI succeeds either way; only an unresolved assessment adds a stderr advisory that names the
        // finding, so the TL learns at seal/verify time what classify-final will refuse at archive time.
        const verifyPath = path.join(repoRoot, "assessment-verify-request.json");
        writeFileSync(verifyPath, `${JSON.stringify({ repoRoot, receiptRef: sealed.ref })}\n`);
        const verifyCli = spawnSync(process.execPath, [HELPER_PATH, "verify-receipt", "--request", verifyPath], { encoding: "utf8" });
        unlinkSync(verifyPath);
        assert.equal(verifyCli.status, 0, `${verifyCli.stderr}\n${verifyCli.stdout}`);
        assert.deepEqual(JSON.parse(verifyCli.stdout).receipt.reviewer_payload.guarantee_assessment, payload.guarantee_assessment);
        const readiness = helper.classifyFinalReadiness({ repoRoot, changeId });
        if (classification === "unresolved") {
          assert.match(verifyCli.stderr, /guarantee assessment is unresolved for F1/u);
          assert.equal(readiness.review_coverage_valid, false);
          assert.equal(readiness.full_reopen_debug_reason, "latest_receipt_not_converged");
          assert.deepEqual(readiness.open_finding_ids, []);
          assert.deepEqual(readiness.unresolved_assessment_ids, ["F1"]);
          assert.throws(() => sealFinal(helper, { repoRoot, changeId }), /guarantee assessment requires clarification/);
        } else {
          assert.doesNotMatch(verifyCli.stderr, /guarantee assessment is unresolved/u);
          assert.equal(readiness.review_coverage_valid, true);
          assert.equal(Object.hasOwn(readiness, "unresolved_assessment_ids"), false);
        }
      }, { featureChange: true });
    }
  });

  // add-wording-fix-now-bounded-route: a risk-shape change limited to what the predecessor round's
  // fix-now Suggestions named stays bounded below the automatic cap; classify and the chain walk agree.
  const wordingSuggestion = (id, changeId, file, anchorText) => finding(id, {
    state: "closed",
    disposition: "fix-now",
    observation: observation(id, { severity: "Suggestion", carrier: `openspec/changes/${changeId}/${file}`, anchor: anchorText }),
  });
  const reviseWordingRound = (helper, { repoRoot, mainSha, changeId, previous, roundNumber, revise, request = null }) => {
    writeFullRiskChange(repoRoot, changeId, revise);
    const candidateHead = commitAll(repoRoot, `wording repair before round ${roundNumber}`);
    if (request !== null) {
      for (const ref of [request.repairDeltaManifestRef, request.dependencyClosureManifestRef]) {
        unlinkSync(path.join(mainNotesRoot(repoRoot), ref.path));
      }
    }
    const manifests = sealRoundManifests(helper, {
      repoRoot, changeId, roundNumber, mainSha,
      surfaceBaseSha: previous.receipt.reviewer_payload.lineage.head_sha,
      candidateHeadSha: candidateHead,
    });
    return { candidateHead, manifests };
  };
  const initialWithFindings = (helper, { repoRoot, mainSha, changeId, findings }) => {
    writeFullRiskChange(repoRoot, changeId);
    commitAll(repoRoot, "wording repair baseline");
    return sealReceipt(helper, {
      repoRoot, changeId,
      reviewerPayload: payloadFromDispatch(initialClassification(helper, { repoRoot, changeId }), {
        changeId, baseSha: mainSha, mergeBaseSha: mainSha, headSha: git(repoRoot, ["rev-parse", "HEAD"]), findings,
      }),
    });
  };

  nodeTest("wording repair: a D-block change named by a fix-now design Suggestion routes bounded and seals through final readiness", () => {
    const helper = api();
    withRepo(({ tempRoot, repoRoot, mainSha }) => {
      const changeId = "wording-repair-design";
      const initial = initialWithFindings(helper, {
        repoRoot, mainSha, changeId,
        findings: [wordingSuggestion("F-w1", changeId, "design.md", "### D2 — Durable binding")],
      });
      const { candidateHead, manifests } = reviseWordingRound(helper, {
        repoRoot, mainSha, changeId, previous: initial, roundNumber: 2,
        revise: { design: { decision: "Derive authority from the exact selected sections only." } },
      });
      const dispatch = classifyBounded(helper, { repoRoot, changeId, previousReceipt: initial, repairManifest: manifests.repair, closureManifest: manifests.closure });
      assertDispatchableResult(dispatch, { route: "bounded", count: 1, round: 2, reason: "wording_repair_bounded" });
      assert.notEqual(dispatch.risk_shape_digest_sha256, initial.receipt.reviewer_payload.scope.risk_shape_digest_sha256,
        "precondition: the round carries a changed risk shape");
      const bounded = payloadFromDispatch(dispatch, {
        changeId, reviewMode: "bounded", roundNumber: 2, boundedCount: 1,
        baseSha: mainSha, mergeBaseSha: mainSha, headSha: candidateHead,
        previousReceiptRef: initial.ref, initialFullReceiptDigestSha256: initial.ref.digest_sha256,
        repairManifestRef: manifests.repair.ref, closureManifestRef: manifests.closure.ref,
        findings: convergeFindings(initial.receipt.reviewer_payload.findings, []),
      });
      // The exemption is the wording-repair authorization: the same round under a plain bounded id fails closed.
      const plain = clone(bounded);
      plain.dispatch_id = logicalDispatchIdForPayload(helper, changeId, plain, null);
      bindReceiptAuthority(helper, { repoRoot, changeId, reviewerPayload: plain });
      assert.throws(() => helper.sealReviewRoundReceipt({ repoRoot, changeId, reviewerPayload: plain }), /receipt-evidence-invalid: bounded receipt risk shape changed/u);
      const sealed = sealReceipt(helper, { repoRoot, changeId, reviewerPayload: bounded });
      assert.equal(sealed.receipt.reviewer_payload.dispatch_id, dispatch.dispatch_id);
      assert.doesNotThrow(() => helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: sealed.ref }));
      const stall = coreApi().createReviewRemediationEvidenceCore().queryReviewStallState({ repoRoot, changeId });
      assert.notEqual(stall.state, "unavailable", "the chain walk accepts the sealed wording-repair transition");
      const readiness = helper.classifyFinalReadiness({ repoRoot, changeId });
      assert.equal(readiness.review_lineage_valid, true, JSON.stringify(readiness));
      assert.equal(readiness.review_coverage_valid, true, JSON.stringify(readiness));
      // The reviewer can escalate: a recorded wording_repair_substantive discovery reopens full.
      const escalated = classifyBounded(helper, {
        repoRoot, changeId, previousReceipt: initial, repairManifest: manifests.repair, closureManifest: manifests.closure,
        postDispatchDiscovery: "wording_repair_substantive", observationRecorded: true,
      });
      assertDispatchableResult(escalated, { route: "full", count: 0, round: 2, reason: "wording_repair_substantive" });
      void tempRoot;
    });
  });

  nodeTest("wording repair: only the named proposal safety row may change, and other risk-shape edits keep full", () => {
    const helper = api();
    const cases = [
      { name: "named negative row", file: "proposal.md", anchorText: "| Material negatives/non-goals |",
        revise: { proposal: { negative: "Never accept caller-provided authority." } }, route: "bounded" },
      { name: "unnamed security row", file: "proposal.md", anchorText: "| Material negatives/non-goals |",
        revise: { proposal: { safety: "Fail closed before any dispatch." } }, route: "full" },
      { name: "touch row with a design Suggestion", file: "design.md", anchorText: "### D1 — Exact authority",
        revise: { proposal: { touchRow: "| `src/second-target.mjs` | code | modify | R2 |" } }, route: "full" },
      { name: "D-block without a design Suggestion", file: "proposal.md", anchorText: "| Material negatives/non-goals |",
        revise: { design: { decision: "Derive authority from the exact selected sections only." } }, route: "full" },
      { name: "a raised Important", file: "design.md", anchorText: "### D1 — Exact authority", important: true,
        revise: { design: { decision: "Derive authority from the exact selected sections only." } }, route: "full" },
      { name: "a raised Critical", file: "design.md", anchorText: "### D1 — Exact authority", critical: true,
        revise: { design: { decision: "Derive authority from the exact selected sections only." } }, route: "full" },
      { name: "an added D-block with a design Suggestion", file: "design.md", anchorText: "### D1 — Exact authority",
        revise: { design: { extraDecision: "Record every authorization reason in the digest." } }, route: "full" },
    ];
    for (const entry of cases) {
      withRepo(({ repoRoot, mainSha }) => {
        const changeId = `wording-repair-${entry.name.replace(/[^a-z]+/gu, "-")}`;
        const findings = [wordingSuggestion("F-w1", changeId, entry.file, entry.anchorText)];
        if (entry.important) findings.push(finding("F-w2", { state: "closed", disposition: "fix-now" }));
        if (entry.critical) findings.push(finding("F-w3", { observation: observation("F-w3", { severity: "Critical" }) }));
        const initial = initialWithFindings(helper, { repoRoot, mainSha, changeId, findings });
        const { manifests } = reviseWordingRound(helper, { repoRoot, mainSha, changeId, previous: initial, roundNumber: 2, revise: entry.revise });
        const dispatch = classifyBounded(helper, { repoRoot, changeId, previousReceipt: initial, repairManifest: manifests.repair, closureManifest: manifests.closure });
        if (entry.route === "bounded") {
          assertDispatchableResult(dispatch, { route: "bounded", count: 1, round: 2, reason: "wording_repair_bounded" });
        } else {
          assertDispatchableResult(dispatch, { route: "full", count: 0, round: 2, reason: "risk_shape_changed" });
        }
      });
    }
  });

  nodeTest("wording repair: at the automatic cap the exception does not apply and a forged id cannot seal", () => {
    const helper = api();
    // A chainThrough variant whose last sealed round also raises a closed fix-now design Suggestion.
    const chainRaising = ({ repoRoot, mainSha, changeId, trajectory }) => {
      writeFullRiskChange(repoRoot, changeId);
      commitAll(repoRoot, "wording repair cap baseline");
      const raised = wordingSuggestion("F-w9", changeId, "design.md", "### D1 — Exact authority");
      const lastSealed = trajectory.length - 1;
      let previous = sealReceipt(helper, {
        repoRoot, changeId,
        reviewerPayload: payloadFromDispatch(initialClassification(helper, { repoRoot, changeId }), {
          changeId, baseSha: mainSha, mergeBaseSha: mainSha, headSha: git(repoRoot, ["rev-parse", "HEAD"]),
          findings: lastSealed === 0 ? [...openFindings(trajectory[0]), raised] : openFindings(trajectory[0]),
        }),
      });
      for (let index = 1; index <= trajectory.length; index += 1) {
        const roundNumber = index + 1;
        const candidateHead = commitRound(repoRoot, 500 + index);
        const manifests = sealRoundManifests(helper, {
          repoRoot, changeId, roundNumber, mainSha,
          surfaceBaseSha: previous.receipt.reviewer_payload.lineage.head_sha, candidateHeadSha: candidateHead,
        });
        const request = {
          repoRoot, changeId, previousReceiptRef: previous.ref,
          repairDeltaManifestRef: manifests.repair.ref, dependencyClosureManifestRef: manifests.closure.ref,
          predecessorMatches: predecessorMatches(previous.receipt),
        };
        if (index === trajectory.length) return { previous, request };
        const dispatch = helper.classifyBoundedRereview(request);
        assertDispatchableResult(dispatch, { route: "bounded", count: index, round: roundNumber, reason: null });
        const findings = shrinkingFindings(trajectory[0], trajectory[index]);
        previous = sealReceipt(helper, {
          repoRoot, changeId,
          reviewerPayload: payloadFromDispatch(dispatch, {
            changeId, reviewMode: "bounded", roundNumber, boundedCount: index,
            baseSha: mainSha, mergeBaseSha: mainSha, headSha: candidateHead, previousReceiptRef: previous.ref,
            initialFullReceiptDigestSha256: index === 1 ? previous.ref.digest_sha256 : previous.receipt.reviewer_payload.lineage.initial_full_receipt_digest_sha256,
            repairManifestRef: manifests.repair.ref, closureManifestRef: manifests.closure.ref,
            findings: index === lastSealed ? [...findings, raised] : findings,
          }),
        });
      }
      throw new Error("chainRaising must return from its final iteration");
    };
    for (const { trajectory, count } of [{ trajectory: [2, 1], count: 1 }, { trajectory: [4, 3, 2, 1], count: 3 }]) {
      withRepo(({ repoRoot, mainSha }) => {
        const changeId = `wording-repair-cap-${count}`;
        const { previous, request } = chainRaising({ repoRoot, mainSha, changeId, trajectory });
        assert.equal(previous.receipt.reviewer_payload.bounded_rereview_count, count, "precondition: bounded count before the round");
        const roundNumber = previous.receipt.reviewer_payload.round_number + 1;
        const { candidateHead, manifests } = reviseWordingRound(helper, {
          repoRoot, mainSha, changeId, previous, roundNumber, request,
          revise: { design: { decision: "Derive authority from the exact selected sections only." } },
        });
        const dispatch = helper.classifyBoundedRereview({ ...request, repairDeltaManifestRef: manifests.repair.ref, dependencyClosureManifestRef: manifests.closure.ref });
        if (count < 3) {
          assertDispatchableResult(dispatch, { route: "bounded", count: count + 1, round: roundNumber, reason: "wording_repair_bounded" });
          return;
        }
        assertDispatchableResult(dispatch, { route: "full", count, round: roundNumber, reason: "risk_shape_changed" });
        const forged = payloadFromDispatch(dispatch, {
          changeId, reviewMode: "bounded", roundNumber, boundedCount: count + 1,
          baseSha: mainSha, mergeBaseSha: mainSha, headSha: candidateHead, previousReceiptRef: previous.ref,
          initialFullReceiptDigestSha256: previous.receipt.reviewer_payload.lineage.initial_full_receipt_digest_sha256,
          repairManifestRef: manifests.repair.ref, closureManifestRef: manifests.closure.ref,
          findings: convergeFindings(previous.receipt.reviewer_payload.findings, previous.receipt.reviewer_payload.scope.open_finding_ids),
        });
        forged.review_mode = "bounded";
        forged.bounded_rereview_count = count + 1;
        forged.dispatch_id = logicalDispatchIdForPayload(helper, changeId, forged, "wording_repair_bounded");
        bindReceiptAuthority(helper, { repoRoot, changeId, reviewerPayload: forged });
        assert.throws(() => helper.sealReviewRoundReceipt({ repoRoot, changeId, reviewerPayload: forged }),
          /bounded receipt risk shape changed|past automatic cap/u, "a forged wording-repair id does not buy a bounded seal at the cap");
      });
    }
  });
}

function runtimeAgentPayload(helper, { repoRoot, changeId, mainSha, findings = [finding()] }) {
  const { payload } = initialPayloadFromDispatch(helper, { repoRoot, changeId, mainSha, findings });
  payload.reviewer_identity = { role: "dp-reviewer", executor_kind: "runtime-agent" };
  // Design D8: every new runtime-agent seal carries the positional attestation
  // `execution_root_head` — the resolved binding root HEAD, which for these
  // fixtures equals the reviewed head the record was admitted against.
  payload.execution_root_head = payload.lineage.head_sha;
  return payload;
}

function sealPreparedRuntime(helper, {
  repoRoot,
  changeId,
  mainSha,
  admission,
  payload = runtimeAgentPayload(helper, { repoRoot, changeId, mainSha }),
}) {
  bindReceiptAuthority(helper, { repoRoot, changeId, reviewerPayload: payload });
  payload.review_authority = {
    kind: "runtime-admission",
    intent_ref: { intent_id: admission.record.intent_id, digest_sha256: admission.record.intent_sha256 },
    admission_ref: { record_id: admission.record_id, digest_sha256: admission.digest },
  };
  const result = helper.sealReviewRoundReceipt({
    repoRoot,
    changeId,
    reviewerPayload: payload,
    admissionRecordId: admission.record_id,
  });
  const targetPath = receiptTarget(repoRoot, changeId, payload.round_number, payload.dispatch_id);
  return { payload, result, receipt: result.receipt, targetPath, ref: result.ref };
}

test("the admission-record uniqueness scan reads receipts safely and fails closed on unreadable ones", async (t) => {
  const helper = api();
  const uniquenessSource = sourceFunctionSlice(
    readFileSync(CORE_PATH, "utf8"),
    "assertAdmissionRecordUnique",
    "validateAdmissionBinding",
  );
  assert.match(uniquenessSource, /candidate\.name === currentReceiptName/u, "only the exact receipt path may self-exclude");
  assert.doesNotMatch(uniquenessSource, /candidate\.round === roundNumber/u, "same-round different-dispatch receipts must remain visible");
  const notesOf = (repoRoot) => mainNotesRoot(repoRoot);
  const plant = (repoRoot, changeId, roundNumber, body) => {
    const target = path.join(notesOf(repoRoot), `review-${changeId}-receipt-r${roundNumber}.json`);
    writeFileSync(target, body);
    return target;
  };

  await t.test("a receipt-shaped symlink pointing outside the notes root is refused", () => {
    withRepo(({ repoRoot, mainSha, tempRoot }) => {
      const changeId = "unique-scan-symlink";
      boundChange(repoRoot, changeId);
      const admission = preparedRuntimeAdmissionFixture({ repoRoot, changeId });
      const outside = path.join(tempRoot, "outside-receipt.json");
      writeFileSync(outside, "{}\n");
      symlinkSync(outside, path.join(notesOf(repoRoot), `review-${changeId}-receipt-r9.json`));
      assert.throws(
        () => sealPreparedRuntime(helper, { repoRoot, changeId, mainSha, admission }),
        coreFailureIs("evidence-artifact-invalid"),
      );
    });
  });

  await t.test("a receipt-shaped file above the size bound is refused", () => {
    withRepo(({ repoRoot, mainSha }) => {
      const changeId = "unique-scan-oversize";
      boundChange(repoRoot, changeId);
      const admission = preparedRuntimeAdmissionFixture({ repoRoot, changeId });
      plant(repoRoot, changeId, 9, Buffer.alloc(300 * 1024, 0x20));
      assert.throws(
        () => sealPreparedRuntime(helper, { repoRoot, changeId, mainSha, admission }),
        coreFailureIs("receipt-size-exceeded"),
      );
    });
  });

  await t.test("a receipt-shaped file that is not parseable JSON is refused, not skipped", () => {
    withRepo(({ repoRoot, mainSha }) => {
      const changeId = "unique-scan-unparseable";
      boundChange(repoRoot, changeId);
      const admission = preparedRuntimeAdmissionFixture({ repoRoot, changeId });
      plant(repoRoot, changeId, 9, "not json at all\n");
      assert.throws(
        () => sealPreparedRuntime(helper, { repoRoot, changeId, mainSha, admission }),
        coreFailureIs("receipt-evidence-invalid"),
      );
    });
  });

  await t.test("a readable receipt for another round reusing the record is still detected as a duplicate", () => {
    withRepo(({ repoRoot, mainSha }) => {
      const changeId = "unique-scan-duplicate";
      boundChange(repoRoot, changeId);
      const admission = preparedRuntimeAdmissionFixture({ repoRoot, changeId });
      const first = sealPreparedRuntime(helper, { repoRoot, changeId, mainSha, admission });
      // Park round 1's receipt under a DIFFERENT round number so the scan does
      // not skip it (it skips only the round being sealed), then drop round 1's
      // own receipt and its atomic claim. That leaves the readdir scan — the
      // defence-in-depth second line — as the only guard still standing, and
      // re-sealing round 1 must still refuse to reuse the same record.
      writeFileSync(
        path.join(notesOf(repoRoot), `review-${changeId}-receipt-r9.json`),
        readFileSync(first.targetPath),
      );
      rmSync(path.join(repoRoot, "openspec", "changes", changeId, "admission-records", `${admission.record_id}.claim`), { recursive: true, force: true });
      rmSync(first.targetPath);
      assert.throws(
        () => sealPreparedRuntime(helper, { repoRoot, changeId, mainSha, admission }),
        /already evidences another receipt/i,
      );
    });
  });

  await t.test("a same-round different-dispatch v3 receipt reusing the record is not mistaken for exact self", () => {
    withRepo(({ repoRoot, mainSha }) => {
      const changeId = "unique-scan-same-round-dispatch";
      boundChange(repoRoot, changeId);
      const admission = preparedRuntimeAdmissionFixture({ repoRoot, changeId });
      const first = sealPreparedRuntime(helper, { repoRoot, changeId, mainSha, admission });
      const alternateDispatch = "f".repeat(64);
      const conflictingPath = path.join(notesOf(repoRoot), `review-${changeId}-receipt-r1-${alternateDispatch}.json`);
      writeFileSync(conflictingPath, readFileSync(first.targetPath));
      rmSync(path.join(repoRoot, "openspec", "changes", changeId, "admission-records", `${admission.record_id}.claim`), { recursive: true, force: true });
      rmSync(first.targetPath);
      rmSync(first.targetPath.replace(/\.json$/u, ".commit.json"));
      assert.throws(
        () => sealPreparedRuntime(helper, { repoRoot, changeId, mainSha, admission }),
        /already evidences another receipt/i,
      );
    });
  });

  await t.test("files whose names do not match the receipt pattern are still skipped", () => {
    withRepo(({ repoRoot, mainSha }) => {
      const changeId = "unique-scan-unrelated";
      boundChange(repoRoot, changeId);
      const admission = preparedRuntimeAdmissionFixture({ repoRoot, changeId });
      const notes = notesOf(repoRoot);
      // Round 0 is outside the `r[1-9][0-9]*` shape; the other two miss the
      // pattern by extension and by change id. All three are unreadable junk.
      writeFileSync(path.join(notes, `review-${changeId}-receipt-r0.json`), "junk\n");
      writeFileSync(path.join(notes, `review-${changeId}-receipt-r1.json.bak`), "junk\n");
      writeFileSync(path.join(notes, "review-some-other-change-receipt-r9.json"), "junk\n");
      const sealed = sealPreparedRuntime(helper, { repoRoot, changeId, mainSha, admission });
      assert.ok(sealed.receipt, "non-matching file names never enter the scan");
    });
  });
});

// A ref's digest covers the whole file; a record's own digest covers only its
// canonical-JSON payload. Both are 64 hex characters over the same artifact, so
// nothing about a wrong choice looks wrong — the classifier just answers
// receipt_authority_invalid, which names neither field. seal-final already
// returned a ready-made ref; receipts and manifests did not, which is why this
// harness had to compute durableRef() itself for every ref it needed. These
// lock the asymmetry closed at both ends: the sealing commands hand back the
// ref, and the mismatch says which digest was actually supplied.
test("sealing a receipt or a manifest returns the ref its consumers need", () => {
  const helper = api();
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "seal-returns-consumable-ref";
    writeFullRiskChange(repoRoot, changeId);
    commitAll(repoRoot, "seal ref baseline");
    const initialDispatch = initialClassification(helper, { repoRoot, changeId });
    const sealed = sealReceipt(helper, {
      repoRoot,
      changeId,
      reviewerPayload: payloadFromDispatch(initialDispatch, {
        changeId,
        baseSha: mainSha,
        mergeBaseSha: mainSha,
        headSha: git(repoRoot, ["rev-parse", "HEAD"]),
      }),
    });

    assert.deepEqual(
      sealed.result.ref,
      sealed.ref,
      "seal-receipt must return the same ref the caller would otherwise rebuild by hand",
    );
    assert.deepEqual(
      helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: sealed.result.ref }).receipt,
      sealed.receipt,
      "the returned ref must be directly consumable, with no further derivation",
    );
    assert.notEqual(
      sealed.result.ref.digest_sha256,
      sealed.receipt.receipt_digest_sha256,
      "the two digests must be distinct, which is exactly why the ref has to be handed back",
    );

    const candidateHead = commitRound(repoRoot, 303);
    const manifests = sealRoundManifests(helper, {
      repoRoot,
      changeId,
      roundNumber: 2,
      mainSha,
      surfaceBaseSha: sealed.receipt.reviewer_payload.lineage.head_sha,
      candidateHeadSha: candidateHead,
    });
    for (const [purpose, entry] of [["repair-delta", manifests.repair], ["dependency-closure", manifests.closure]]) {
      assert.deepEqual(entry.result.ref, entry.ref, `seal-manifest must return the ${purpose} ref`);
      assert.notEqual(
        entry.result.ref.digest_sha256,
        entry.manifest.manifest_digest_sha256,
        `the ${purpose} whole-file and payload digests must be distinct`,
      );
    }
  });
});

test("supplying a record's own payload digest as a ref digest says which field was confused", () => {
  const helper = api();
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "seal-ref-digest-confusion";
    writeFullRiskChange(repoRoot, changeId);
    commitAll(repoRoot, "digest confusion baseline");
    const initialDispatch = initialClassification(helper, { repoRoot, changeId });
    const sealed = sealReceipt(helper, {
      repoRoot,
      changeId,
      reviewerPayload: payloadFromDispatch(initialDispatch, {
        changeId,
        baseSha: mainSha,
        mergeBaseSha: mainSha,
        headSha: git(repoRoot, ["rev-parse", "HEAD"]),
      }),
    });

    assert.throws(
      () => helper.verifyReviewRoundReceipt({
        repoRoot,
        receiptRef: { path: sealed.ref.path, digest_sha256: sealed.receipt.receipt_digest_sha256 },
      }),
      (error) => {
        assert.match(error.message, /whole-file digest mismatch/);
        assert.match(error.message, /receipt_digest_sha256/, "the message must name the field that was supplied");
        assert.ok(
          error.message.includes(sealed.ref.digest_sha256),
          "the message must hand back the whole-file digest the ref actually wants",
        );
        return true;
      },
    );

    // An unrelated wrong digest is a plain mismatch: the hint fires only when it
    // can actually identify the mistake, so it never speculates.
    assert.throws(
      () => helper.verifyReviewRoundReceipt({
        repoRoot,
        receiptRef: { path: sealed.ref.path, digest_sha256: "a".repeat(64) },
      }),
      (error) => {
        assert.match(error.message, /whole-file digest mismatch/);
        assert.doesNotMatch(error.message, /receipt_digest_sha256/);
        return true;
      },
    );
  });
});

test("every sealing command derives its returned ref from the sealed record, not a filesystem read", () => {
  // The durability-fault test only exercises sealReviewRoundReceipt, so a
  // regression that reintroduced the unseamed read in the other two sealing
  // commands would keep the suite green. That is the shape earlier rounds of
  // this change kept getting caught on -- a fix with no mechanical carrier --
  // so the remaining two are locked at the source level rather than left bare.
  //
  // Why the distinction matters: durableSeal performs every filesystem step
  // through the injected fsOps seam. A raw readFileSync afterwards leaves that
  // seam, which is unobservable on a real filesystem (both routes hash the same
  // bytes) and fatal under injection (ENOENT on a file the double never wrote).
  const coreSource = readFileSync(CORE_PATH, "utf8");
  for (const [name, boundary] of [
    ["sealClaimedReviewRoundReceipt", "verifyReviewRoundReceipt"],
    ["sealReviewManifest", "verifyReviewManifest"],
    ["sealArchiveTransition", "sealFinalEvidenceRecord"],
  ]) {
    const slice = sourceFunctionSlice(coreSource, name, boundary);
    assert.match(slice, /ref: sealedEvidenceRef\(/u, `${name} must build its ref from the sealed record`);
    assert.equal(
      /\bevidenceRef\(/u.test(slice.replaceAll("sealedEvidenceRef(", "")),
      false,
      `${name} must not read the published file back through the unseamed evidenceRef`,
    );
  }

  // Positive control on the helper itself: it must reach no filesystem API, and
  // it must hash the canonical encoding of the record durableSeal published.
  const helperSlice = sourceFunctionSlice(coreSource, "sealedEvidenceRef", "receiptFileName");
  assert.equal(/readFileSync|readWholeFile|readdirSync/u.test(helperSlice), false,
    "sealedEvidenceRef must not touch the filesystem");
  assert.match(helperSlice, /canonicalJsonV1\(record\)/u,
    "sealedEvidenceRef must hash the canonical encoding of the sealed record");
});

// Seal round one plus bounded rounds two..N, whose open-finding counts follow
// `trajectory`, and return the request that would dispatch round N+1. Every
// intermediate round is asserted dispatchable, so a streak that fired too
// early fails here instead of silently shortening the chain. The bounded
// count ends at N-1, and every trajectory its callers pass keeps it under
// three -- which is what makes each verdict attributable to the stall budget
// alone rather than to the pre-existing `count >= 3` cap.
// Hoisted to file scope by fix-zero-value-review-rounds T7: the stall
// query's tests need the same sealed chain this one builds, and a second
// copy of it would be a second answer to "what does a stalled chain look
// like" -- the duplication D9 rejects, in the tests instead of the rule.
function chainThrough(helper, { repoRoot, mainSha, changeId, trajectory }) {
  writeFullRiskChange(repoRoot, changeId);
  commitAll(repoRoot, `stall trajectory baseline for ${changeId}`);
  let previous = sealReceipt(helper, {
    repoRoot,
    changeId,
    reviewerPayload: payloadFromDispatch(initialClassification(helper, { repoRoot, changeId }), {
      changeId,
      baseSha: mainSha,
      mergeBaseSha: mainSha,
      headSha: git(repoRoot, ["rev-parse", "HEAD"]),
      findings: openFindings(trajectory[0]),
    }),
  });
  for (let index = 1; index <= trajectory.length; index += 1) {
    const roundNumber = index + 1;
    const candidateHead = commitRound(repoRoot, 400 + index);
    const manifests = sealRoundManifests(helper, {
      repoRoot,
      changeId,
      roundNumber,
      mainSha,
      surfaceBaseSha: previous.receipt.reviewer_payload.lineage.head_sha,
      candidateHeadSha: candidateHead,
    });
    const request = {
      repoRoot,
      changeId,
      previousReceiptRef: previous.ref,
      repairDeltaManifestRef: manifests.repair.ref,
      dependencyClosureManifestRef: manifests.closure.ref,
      predecessorMatches: predecessorMatches(previous.receipt),
    };
    if (index === trajectory.length) return { previous, request };
    const dispatch = helper.classifyBoundedRereview(request);
    assertDispatchableResult(dispatch, { route: "bounded", count: index, round: roundNumber, reason: null });
    previous = sealReceipt(helper, {
      repoRoot,
      changeId,
      reviewerPayload: payloadFromDispatch(dispatch, {
        changeId,
        reviewMode: "bounded",
        roundNumber,
        boundedCount: index,
        baseSha: mainSha,
        mergeBaseSha: mainSha,
        headSha: candidateHead,
        previousReceiptRef: previous.ref,
        initialFullReceiptDigestSha256: index === 1
          ? previous.ref.digest_sha256
          : previous.receipt.reviewer_payload.lineage.initial_full_receipt_digest_sha256,
        repairManifestRef: manifests.repair.ref,
        closureManifestRef: manifests.closure.ref,
        // The successor carries every predecessor finding (carry-forward set), so a shrinking
        // open count closes findings instead of leaving them out.
        findings: shrinkingFindings(trajectory[0], trajectory[index]),
      }),
    });
  }
  throw new Error("chainThrough must return from its final iteration");
}

test("the stall budget enters convergence recovery below the bounded cap; explicit handbackCause still overrides", () => {
  const helper = api();

  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "classifier-stall-budget";
    // Round one opens two findings and neither of the next two closes any. The
    // bounded count reaches two, so the pre-existing `count >= 3` cap cannot be
    // what fires here; `next_bounded_rereview_count` of two is the proof that
    // the handback belongs to the stall budget.
    const { previous, request } = chainThrough(helper, { repoRoot, mainSha, changeId, trajectory: [2, 2, 2] });
    const recovery = helper.classifyBoundedRereview(request);
    assert.deepEqual(Object.keys(recovery).sort(), DISPATCH_RESULT_KEYS, "D7: the stall path adds no eighth field");
    assert.equal(recovery.route, "bounded", "three rounds whose open set never shrank enter convergence recovery");
    assert.equal(recovery.dispatch_ready, true);
    assert.match(recovery.dispatch_id, /^[0-9a-f]{64}$/, "recovery issues dispatch authority");
    assert.equal(recovery.round_number, previous.receipt.reviewer_payload.round_number + 1);
    assert.equal(recovery.next_bounded_rereview_count, 3, "below the cap of three: this recovery is the stall budget's, not the cap's");
    assert.equal(recovery.full_reopen_reason, "convergence_recovery");
    assert.match(recovery.risk_shape_digest_sha256, /^[0-9a-f]{64}$/);

    // Explicit handbackCause still opens the narrow override bridge on the same tip.
    const handback = helper.classifyBoundedRereview({ ...request, handbackCause: "irreversible_high_risk" });
    assert.equal(handback.route, "handback_required");
    assert.equal(handback.dispatch_id, null);
    const resumeRequest = { ...request, responsibilityId: "primary-review", handbackCause: "irreversible_high_risk" };
    const resume = issueHalfStateOverride({
      repoRoot,
      changeId,
      responsibilityId: "primary-review",
      reason: "user: authorized one more bounded round after a true stall handback",
    });
    const authorized = helper.classifyBoundedRereview({ ...resumeRequest, overrideId: resume.override_id });
    assert.equal(authorized.route, "bounded");
    assert.equal(authorized.full_reopen_reason, "handback_authorized_bounded");
    assert.equal(halfStateOverrideStatus({ repoRoot, changeId, overrideId: resume.override_id }), "consumed");

    // Seal the recovery round with the same open set (stall still exhausted).
    const recovered = sealReceipt(helper, {
      repoRoot,
      changeId,
      reviewerPayload: payloadFromDispatch(recovery, {
        changeId,
        reviewMode: "bounded",
        roundNumber: recovery.round_number,
        boundedCount: 3,
        baseSha: mainSha,
        mergeBaseSha: mainSha,
        headSha: git(repoRoot, ["rev-parse", "HEAD"]),
        previousReceiptRef: previous.ref,
        initialFullReceiptDigestSha256: previous.receipt.reviewer_payload.lineage.initial_full_receipt_digest_sha256,
        repairManifestRef: request.repairDeltaManifestRef,
        closureManifestRef: request.dependencyClosureManifestRef,
        findings: openFindings(2),
      }),
    });
    const nextHead = commitRound(repoRoot, 77);
    const nextManifests = sealRoundManifests(helper, {
      repoRoot,
      changeId,
      roundNumber: recovered.receipt.reviewer_payload.round_number + 1,
      mainSha,
      surfaceBaseSha: recovered.receipt.reviewer_payload.lineage.head_sha,
      candidateHeadSha: nextHead,
    });
    const blocked = helper.classifyBoundedRereview({
      repoRoot,
      changeId,
      previousReceiptRef: recovered.ref,
      repairDeltaManifestRef: nextManifests.repair.ref,
      dependencyClosureManifestRef: nextManifests.closure.ref,
      predecessorMatches: predecessorMatches(recovered.receipt),
    });
    assert.equal(blocked.route, "recovery_disposition_required");
    assert.equal(blocked.dispatch_ready, false);
    assert.equal(blocked.dispatch_id, null);

    const dispositions = openFindings(2).map((f) => ({
      finding_id: f.finding_id,
      disposition: "fix-now",
      bound_dispatch_id: recovered.receipt.reviewer_payload.dispatch_id,
    }));
    const resumed = helper.classifyBoundedRereview({
      repoRoot,
      changeId,
      previousReceiptRef: recovered.ref,
      repairDeltaManifestRef: nextManifests.repair.ref,
      dependencyClosureManifestRef: nextManifests.closure.ref,
      predecessorMatches: predecessorMatches(recovered.receipt),
      recoveryDispositions: dispositions,
    });
    assert.equal(resumed.route, "bounded");
    assert.equal(resumed.full_reopen_reason, "convergence_recovery");
    assert.match(resumed.dispatch_id, /^[0-9a-f]{64}$/);
  });

  withRepo(({ repoRoot, mainSha }) => {
    // The negative that gives the assertions above their meaning: identical
    // chain length, identical bounded count, differing only in that every round
    // closed a finding. A `stallExhausted` wired to be always true would
    // satisfy every assertion above and fail only here.
    const { request } = chainThrough(helper, {
      repoRoot,
      mainSha,
      changeId: "classifier-stall-progress",
      trajectory: [3, 2, 1],
    });
    assertDispatchableResult(
      helper.classifyBoundedRereview(request),
      { route: "bounded", count: 3, round: 4, reason: null },
    );
  });
});

test("the stall query separates no receipts from an invalid v3 orphan over a committed predecessor", () => {
  const helper = api();
  // The chain is built through the production façade; the stall query is a
  // key on the internal core factory, which is what `--budget-check`
  // constructs. Both read the same repo.
  const core = coreApi().createReviewRemediationEvidenceCore();

  withRepo(({ repoRoot, mainSha }) => {
    // D20 row 1. Zero receipts is `not-applicable`, NOT `unavailable`: nothing
    // should have been read, so nothing failed to be read. The distinction is
    // the entire reason this key returns four states instead of three --
    // T12 makes `unavailable` block, and a change that has never run a review
    // round must not be stopped by a gate about review rounds.
    assert.deepEqual(
      core.queryReviewStallState({ repoRoot, changeId: "never-reviewed" }),
      { state: "not-applicable", streak: null },
      "a change with no sealed receipts has no stall to report",
    );

    // Same repo, a change that HAS receipts. The candidate list is non-empty
    // from here on, so every verdict below is about a chain that should have
    // been readable.
    const changeId = "stall-query-unreadable";
    chainThrough(helper, { repoRoot, mainSha, changeId, trajectory: [2, 2] });
    const newest = receiptTarget(repoRoot, changeId, 2);
    const intact = readFileSync(newest, "utf8");
    assert.deepEqual(
      core.queryReviewStallState({ repoRoot, changeId }),
      { state: "ok", streak: 1 },
      "the intact chain reads, so the corrupted verdicts below are attributable to the corruption",
    );

    // Three distinct ways for the newest v3 receipt to lose its marker binding.
    // Each becomes an inert orphan, so discovery falls back to the committed
    // predecessor instead of letting an invalid higher round hide valid
    // authority. The predecessor is one round and therefore has streak zero.
    const brokenDigest = intact.replace(/"digest_sha256":"[0-9a-f]{64}"/u, `"digest_sha256":"${"0".repeat(64)}"`);
    assert.notEqual(brokenDigest, intact, "the digest rewrite must actually change the bytes, or the case below tests nothing");
    const corruptions = [
      ["truncated to nothing", ""],
      ["valid JSON of the wrong shape", "{}"],
      ["the right shape with a broken digest", brokenDigest],
    ];
    for (const [label, bytes] of corruptions) {
      writeFileSync(newest, bytes);
      const state = core.queryReviewStallState({ repoRoot, changeId });
      assert.deepEqual(state, { state: "ok", streak: 0 }, `${label}: invalid v3 orphan cannot hide the committed predecessor`);
      writeFileSync(newest, intact);
    }

    // Restoring the bytes restores the verdict: the corruption, not some
    // one-way state left behind by it, is what produced `unavailable`.
    assert.deepEqual(core.queryReviewStallState({ repoRoot, changeId }), { state: "ok", streak: 1 });
  });
});

test("the stall query reads the sealed trajectory and delegates the verdict to the module that owns the cap", () => {
  const helper = api();
  // The chain is built through the production façade; the stall query is a
  // key on the internal core factory, which is what `--budget-check`
  // constructs. Both read the same repo.
  const core = coreApi().createReviewRemediationEvidenceCore();

  // Each chain gets its own repo: `chainThrough` commits `src/round-state.txt`
  // with content keyed on the round number, so a second chain in the same repo
  // would produce an empty commit at round one.
  withRepo(({ repoRoot, mainSha }) => {
    // A single sealed round has no predecessor to compare against, so the
    // rule's third halt clause gives 0. `ok` here is a verdict that was READ,
    // which is what separates it from the `not-applicable` above.
    chainThrough(helper, { repoRoot, mainSha, changeId: "stall-query-single", trajectory: [2] });
    assert.deepEqual(
      core.queryReviewStallState({ repoRoot, changeId: "stall-query-single" }),
      { state: "ok", streak: 0 },
    );
  });

  withRepo(({ repoRoot, mainSha }) => {
    // Three rounds, none of which shrank the open set. Rounds two and three
    // each add one, reaching REVIEW_STALL_ROUND_CAP. The bounded count is only
    // two here, so the pre-existing `count >= 3` cap cannot be what produced
    // this -- the verdict belongs to the stall budget.
    chainThrough(helper, { repoRoot, mainSha, changeId: "stall-query-flat", trajectory: [2, 2, 2] });
    assert.deepEqual(
      core.queryReviewStallState({ repoRoot, changeId: "stall-query-flat" }),
      { state: "exhausted", streak: 2 },
    );
  });

  withRepo(({ repoRoot, mainSha }) => {
    // The same number of rounds, with the last one shrinking the set. Progress
    // halts the walk-back immediately. This is the pair that proves the query
    // hands over the trajectory rather than counting rounds: identical chain
    // length, opposite verdict.
    chainThrough(helper, { repoRoot, mainSha, changeId: "stall-query-converging", trajectory: [2, 2, 1] });
    assert.deepEqual(
      core.queryReviewStallState({ repoRoot, changeId: "stall-query-converging" }),
      { state: "ok", streak: 0 },
    );
  });
});

test("the stall query's own return value is what the stalled_rounds threshold reads", () => {
  const helper = api();
  // The chain is built through the production façade; the stall query is a
  // key on the internal core factory, which is what `--budget-check`
  // constructs. Both read the same repo.
  const core = coreApi().createReviewRemediationEvidenceCore();

  // The seam between T5 and T7 has hand-written fixtures on both sides: T5's
  // evaluator recognizes exactly `not-applicable` / `ok` / `exhausted` and
  // degrades everything else to `unavailable`, and until this test nothing fed
  // it a value this module actually produced. A spelling drift on either side
  // would have degraded the gate to `unavailable` in silence.
  //
  // `evaluateCostBudget` no longer has a `round` threshold or a `prNumber`
  // parameter at all (`fix-second-review-loop-friction` D1) -- the stray
  // `prNumber: "none"` key below is inert, a pre-D1 leftover that the
  // destructured `{ usage, reviewStall }` signature silently ignores.
  // `usage` is omitted so the three cumulative totals read `unavailable`.
  // Neither is `exceeded`, so `exceeded_thresholds` below is attributable to
  // `stalled_rounds` alone.
  const evaluate = (reviewStall) => evaluateCostBudget({ prNumber: "none", reviewStall });

  withRepo(({ repoRoot, mainSha }) => {
    chainThrough(helper, { repoRoot, mainSha, changeId: "stall-seam-flat", trajectory: [2, 2, 2] });

    const exhausted = core.queryReviewStallState({ repoRoot, changeId: "stall-seam-flat" });
    assert.equal(exhausted.state, "exhausted", "precondition: this chain stalls");
    const stalledBudget = evaluate(exhausted);
    assert.deepEqual(stalledBudget.thresholds.stalled_rounds, { value: 2, limit: null, state: "exceeded" },
      "the producer's `exhausted` reaches the table as `exceeded`, carrying the streak it measured");
    assert.deepEqual(stalledBudget.exceeded_thresholds, ["stalled_rounds"]);
    assert.equal(stalledBudget.exceeded, true);

    // The same call for a change with no receipts leaves every other caller's
    // result untouched -- this is D10's invariant observed end to end rather
    // than on a literal.
    const absent = core.queryReviewStallState({ repoRoot, changeId: "stall-seam-never-reviewed" });
    assert.equal(absent.state, "not-applicable", "precondition: this change has no receipts");
    const quietBudget = evaluate(absent);
    assert.deepEqual(quietBudget.thresholds.stalled_rounds, { value: null, limit: null, state: "not-applicable" });
    assert.deepEqual(quietBudget.exceeded_thresholds, []);
    assert.equal(quietBudget.exceeded, false);
    assert.deepEqual(quietBudget, evaluateCostBudget({ prNumber: "none" }),
      "a change that never ran a review round is bit-identical to a caller that has no stall concept at all");
  });
});

// A classify after risk drift on the same lineage reads this round's manifests
// as current (the stall recovery path runs the bounded eligibility loop), so a
// drift commit that moved HEAD must reseal them against the drifted head.
function resealRoundManifestsAtHead(helper, { repoRoot, mainSha, changeId, previous, request }) {
  for (const ref of [request.repairDeltaManifestRef, request.dependencyClosureManifestRef]) {
    unlinkSync(path.join(mainNotesRoot(repoRoot), ref.path));
  }
  const manifests = sealRoundManifests(helper, {
    repoRoot,
    changeId,
    roundNumber: previous.receipt.reviewer_payload.round_number + 1,
    mainSha,
    surfaceBaseSha: previous.receipt.reviewer_payload.lineage.head_sha,
    candidateHeadSha: git(repoRoot, ["rev-parse", "HEAD"]),
  });
  return {
    ...request,
    repairDeltaManifestRef: manifests.repair.ref,
    dependencyClosureManifestRef: manifests.closure.ref,
  };
}

test("R6: stall keeps recovery only for mere risk_shape_changed; lineage and the cap yield to full (F1)", () => {
  const helper = api();
  // Mere Target-State risk churn under stall stays convergent recovery.
  // Git lineage (and the bounded cap for any reopen) still yield to full.
  const reopenTriggers = [
    {
      name: "risk_shape_changed",
      // R10 (design D15): a stalled recovery still needs bounded-eligible
      // manifests for the tip it dispatches, so the round's manifests are
      // resealed at the risk-drift commit.
      apply: (repoRoot, changeId, { mainSha, previous, request }) => {
        const roundNumber = previous.receipt.reviewer_payload.round_number + 1;
        for (const purpose of ["repair-delta", "dependency-closure"]) {
          rmSync(manifestTarget(repoRoot, changeId, purpose, roundNumber));
        }
        writeFullRiskChange(repoRoot, changeId, { proposal: { touchRow: "| `src/second-target.mjs` | code | modify | R2 |" } });
        const candidateHead = commitAll(repoRoot, "risk drift on a chain that already stopped earning rounds");
        const manifests = sealRoundManifests(helper, {
          repoRoot,
          changeId,
          roundNumber,
          mainSha,
          surfaceBaseSha: previous.receipt.reviewer_payload.lineage.head_sha,
          candidateHeadSha: candidateHead,
        });
        return {
          ...request,
          repairDeltaManifestRef: manifests.repair.ref,
          dependencyClosureManifestRef: manifests.closure.ref,
        };
      },
    },
    {
      name: "git_lineage_changed",
      apply: (repoRoot) => {
        const featureBranch = git(repoRoot, ["branch", "--show-current"]);
        git(repoRoot, ["checkout", "--quiet", "main"]);
        write(repoRoot, "src/main-advance.txt", "main advanced\n");
        const advancedMain = commitAll(repoRoot, "advance main under a chain that already stopped earning rounds");
        syncOriginMain(repoRoot, advancedMain);
        git(repoRoot, ["checkout", "--quiet", featureBranch]);
        git(repoRoot, ["rebase", advancedMain]);
      },
    },
  ];

  const stopConditions = [
    { name: "stall", trajectory: [2, 2, 2], expectedCount: 2 },
    { name: "cap", trajectory: [5, 4, 3, 2], expectedCount: 3 },
  ];

  for (const stop of stopConditions) {
    for (const trigger of reopenTriggers) {
      withRepo(({ repoRoot, mainSha }) => {
        const changeId = `classifier-${stop.name}-${trigger.name.replace(/_/gu, "-")}`;
        const chain = chainThrough(helper, { repoRoot, mainSha, changeId, trajectory: stop.trajectory });
        const request = trigger.apply(repoRoot, changeId, { mainSha, ...chain }) ?? chain.request;
        const result = helper.classifyBoundedRereview(request);
        const where = `${stop.name} + ${trigger.name}`;
        assert.deepEqual(Object.keys(result).sort(), DISPATCH_RESULT_KEYS, `${where}: the result shape is unchanged`);
        const keepRecovery = stop.name === "stall" && trigger.name === "risk_shape_changed";
        if (keepRecovery) {
          assert.equal(result.next_bounded_rereview_count, stop.expectedCount + 1,
            `${where}: recovery advances the monotonic count from the stall tip`);
          assert.equal(result.route, "bounded", `${where}: mere risk_shape under stall stays recovery`);
          assert.match(result.dispatch_id, /^[0-9a-f]{64}$/u, `${where}: recovery mints a dispatch id`);
          assert.equal(result.dispatch_ready, true, where);
          assert.equal(result.full_reopen_reason, "convergence_recovery", where);
        } else {
          assert.equal(result.next_bounded_rereview_count, stop.expectedCount,
            `${where}: the count attributes this row to ${stop.name} rather than the other condition`);
          assert.equal(result.route, "full", `${where}: mandatory-full reopen takes priority`);
          assert.equal(result.dispatch_ready, true, where);
          assert.equal(result.full_reopen_reason, trigger.name,
            `${where}: the dispatch reports the reopen that produced it, not an authorization it never needed`);
          assert.match(result.dispatch_id, /^[0-9a-f]{64}$/u, where);
        }
      });
    }
  }

  withRepo(({ repoRoot, mainSha }) => {
    // Explicit handbackCause under stall+risk_shape still reaches
    // handback_authorized_full (independent reopen justifies full).
    const changeId = "classifier-stall-reopen-authorized";
    // A handback request keeps the pre-R13 path: it never becomes a bounded
    // recovery, so the round's manifests are not read (F-ehrc-r6-03).
    const { previous, request } = chainThrough(helper, { repoRoot, mainSha, changeId, trajectory: [2, 2, 2] });
    writeFullRiskChange(repoRoot, changeId, { proposal: { touchRow: "| `src/second-target.mjs` | code | modify | R2 |" } });
    commitAll(repoRoot, "risk drift before the user authorizes one more round");
    const handback = helper.classifyBoundedRereview({ ...request, handbackCause: "reviewer_unrecoverable" });
    assert.equal(handback.route, "handback_required");
    const resume = issueHalfStateOverride({
      repoRoot,
      changeId,
      responsibilityId: "primary-review",
      reason: "user: one more full round, the risk shape moved",
    });
    const authorized = helper.classifyBoundedRereview({
      ...request,
      responsibilityId: "primary-review",
      overrideId: resume.override_id, handbackCause: "reviewer_unrecoverable",
    });
    assert.equal(authorized.route, "full");
    assert.equal(authorized.dispatch_ready, true);
    assert.equal(authorized.full_reopen_reason, "handback_authorized_full",
      "the authorized round is labelled by the authorization, not by the reopen condition it overtook");
    assert.equal(authorized.round_number, previous.receipt.reviewer_payload.round_number + 1);
    assert.match(authorized.dispatch_id, /^[0-9a-f]{64}$/u);
    assert.equal(halfStateOverrideStatus({ repoRoot, changeId, overrideId: resume.override_id }), "consumed");
  });
});


function boundChange(repoRoot, changeId) {
  writeFullRiskChange(repoRoot, changeId);
  commitAll(repoRoot, `fixture ${changeId}`);
}

test("v3 normal runtime receipt binds prepared intent, admission v2, raw output, irreversible claim, and commit marker", () => {
  const helper = api();
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "receipt-v3-runtime-agent";
    boundChange(repoRoot, changeId);
    const admission = preparedRuntimeAdmissionFixture({ repoRoot, changeId });
    const { payload } = initialPayloadFromDispatch(helper, { repoRoot, changeId, mainSha });
    payload.reviewer_identity = { role: "dp-reviewer", executor_kind: "runtime-agent" };
    payload.execution_root_head = admission.record.head_sha;
    bindReceiptAuthority(helper, { repoRoot, changeId, reviewerPayload: payload });
    payload.review_authority = {
      kind: "runtime-admission",
      intent_ref: { intent_id: admission.record.intent_id, digest_sha256: admission.record.intent_sha256 },
      admission_ref: { record_id: admission.record_id, digest_sha256: admission.digest },
    };
    const sealed = helper.sealReviewRoundReceipt({
      repoRoot,
      changeId,
      reviewerPayload: payload,
      admissionRecordId: admission.record_id,
    });
    assert.equal(sealed.receipt.schema, "devpro.review-remediation.receipt/v3");
    assert.match(sealed.ref.path, new RegExp(`${payload.dispatch_id}\\.json$`, "u"));
    assert.equal(existsSync(evidencePath(repoRoot, sealed.ref.path.replace(/\.json$/u, ".commit.json"))), true);
    const verified = helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: sealed.ref, requireIndependence: true });
    assert.equal(verified.executor_attribution, "runtime-agent");
    assert.throws(
      () => helper.sealReviewRoundReceipt({ repoRoot, changeId, reviewerPayload: payload, admissionRecordId: admission.record_id }),
      /admission record already claimed|admission-record-consumed/u,
    );
    commitRound(repoRoot, 909);
    assert.throws(
      () => helper.sealReviewRoundReceipt({ repoRoot, changeId, reviewerPayload: payload, admissionRecordId: admission.record_id }),
      /admission-record-consumed/u,
      "a later Git-authority drift must not mask an already consumed runtime admission",
    );
  });
});

test("v3 receipt collision is never idempotent and response-loss recovery requires the matching commit marker", () => {
  const helper = api();
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "receipt-v3-marker-recovery";
    const sealed = sealInitial(helper, { repoRoot, changeId, mainSha });
    assert.throws(() => helper.sealReviewRoundReceipt({
      repoRoot,
      changeId,
      reviewerPayload: clone(sealed.receipt.reviewer_payload),
    }), /receipt-path-collision/u);
    const markerPath = evidencePath(repoRoot, sealed.ref.path.replace(/\.json$/u, ".commit.json"));
    const markerBytes = readFileSync(markerPath);
    unlinkSync(markerPath);
    assert.throws(
      () => helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: sealed.ref }),
      /receipt-not-committed/u,
    );
    assert.deepEqual(helper.queryReviewStallState({ repoRoot, changeId }), { state: "unavailable", streak: null });
    assert.deepEqual(helper.verifyCurrentCrossCarrierClosure({ repoRoot, changeId }), {
      ok: false,
      status: "invalid-closure",
      change: changeId,
      reason: "receipt-not-committed",
    });
    writeFileSync(markerPath, markerBytes);
    assert.equal(helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: sealed.ref }).receipt.schema, REVIEW_RECEIPT_SCHEMA);
    const newerOrphanPath = evidencePath(repoRoot, `review-${changeId}-receipt-r2-${"e".repeat(64)}.json`);
    writeFileSync(newerOrphanPath, "orphan bytes without a marker\n");
    assert.equal(helper.verifyCurrentCrossCarrierClosure({ repoRoot, changeId }).ok, true, "a newer inert orphan cannot displace the committed predecessor");
    const newerMalformedMarkerPath = newerOrphanPath.replace(/\.json$/u, ".commit.json");
    writeFileSync(newerMalformedMarkerPath, "{}\n");
    assert.equal(
      helper.verifyCurrentCrossCarrierClosure({ repoRoot, changeId }).ok,
      true,
      "a marker filename without a valid marker/ref binding cannot make a higher-round orphan selectable",
    );
    unlinkSync(newerOrphanPath);
    unlinkSync(newerMalformedMarkerPath);
    const sameRoundOrphanPath = evidencePath(repoRoot, `review-${changeId}-receipt-r1-${"c".repeat(64)}.json`);
    cpSync(evidencePath(repoRoot, sealed.ref.path), sameRoundOrphanPath);
    writeFileSync(sameRoundOrphanPath.replace(/\.json$/u, ".commit.json"), "{}\n");
    assert.equal(
      helper.verifyCurrentCrossCarrierClosure({ repoRoot, changeId }).ok,
      true,
      "an invalid-marker same-round orphan cannot manufacture receipt ambiguity",
    );
    const ambiguousDispatch = "d".repeat(64);
    const ambiguousReceiptPath = evidencePath(repoRoot, `review-${changeId}-receipt-r1-${ambiguousDispatch}.json`);
    const ambiguousMarkerPath = evidencePath(repoRoot, `review-${changeId}-receipt-r1-${ambiguousDispatch}.commit.json`);
    const ambiguousReceipt = clone(sealed.receipt);
    ambiguousReceipt.reviewer_payload.dispatch_id = ambiguousDispatch;
    ambiguousReceipt.receipt_digest_sha256 = sha256(helper.canonicalJsonV1(ambiguousReceipt.reviewer_payload));
    const ambiguousRef = writeReceiptEnvelope(helper, ambiguousReceiptPath, ambiguousReceipt);
    writeReceiptCommitMarkerFixture(helper, { repoRoot, receipt: ambiguousReceipt, receiptRef: ambiguousRef });
    assert.throws(
      () => helper.verifyCurrentCrossCarrierClosure({ repoRoot, changeId }),
      /receipt-ambiguous/u,
      "two marker-present candidates at the same round are ambiguous before either carrier is trusted",
    );
  });
});

test("legacy v1/v2 receipts remain readable lineage carriers but cannot be newly sealed or satisfy independence", () => {
  const helper = api();
  for (const schema of [REVIEW_RECEIPT_SCHEMA_V1, REVIEW_RECEIPT_SCHEMA_V2]) {
    withRepo(({ repoRoot, mainSha }) => {
      const changeId = schema.endsWith("/v1") ? "legacy-receipt-v1-read" : "legacy-receipt-v2-read";
      const current = authoritativeReceiptPayload(helper, {
        repoRoot,
        changeId,
        baseSha: mainSha,
        headSha: mainSha,
      });
      const reviewerPayload = clone(current);
      delete reviewerPayload.review_authority;
      delete reviewerPayload.output_evidence;
      if (schema === REVIEW_RECEIPT_SCHEMA_V1) {
        delete reviewerPayload.change_id;
        delete reviewerPayload.responsibility_id;
        reviewerPayload.reviewer_identity = { role: "dp-reviewer" };
      } else {
        reviewerPayload.reviewer_identity = { role: "dp-reviewer", executor_kind: "tl-direct" };
      }
      const receipt = {
        schema,
        receipt_digest_sha256: sha256(helper.canonicalJsonV1(reviewerPayload)),
        observation_hashes: receiptObservationHashes(helper, reviewerPayload.findings),
        reviewer_payload: reviewerPayload,
      };
      const targetPath = evidencePath(repoRoot, `review-${changeId}-receipt-r1.json`);
      const ref = writeReceiptEnvelope(helper, targetPath, receipt);
      const verified = helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: ref });
      assert.equal(verified.receipt.schema, schema);
      assert.equal(verified.executor_attribution, schema === REVIEW_RECEIPT_SCHEMA_V1 ? "legacy-unattributed" : "tl-direct");
      assert.throws(
        () => helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: ref, requireIndependence: true }),
        /ordinary-review-not-independent/u,
      );
      assert.throws(
        () => helper.sealReviewRoundReceipt({ repoRoot, changeId, reviewerPayload: clone(reviewerPayload) }),
        /legacy-receipt-seal-forbidden/u,
      );
    });
  }
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "legacy-receipt-v2-post-hoc-rejected";
    const reviewerPayload = authoritativeReceiptPayload(helper, {
      repoRoot,
      changeId,
      baseSha: mainSha,
      headSha: mainSha,
    });
    delete reviewerPayload.review_authority;
    delete reviewerPayload.output_evidence;
    reviewerPayload.reviewer_identity = { role: "dp-reviewer", executor_kind: "post-hoc-tl-attested-runtime-review" };
    const receipt = {
      schema: REVIEW_RECEIPT_SCHEMA_V2,
      receipt_digest_sha256: sha256(helper.canonicalJsonV1(reviewerPayload)),
      observation_hashes: receiptObservationHashes(helper, reviewerPayload.findings),
      reviewer_payload: reviewerPayload,
    };
    const targetPath = evidencePath(repoRoot, `review-${changeId}-receipt-r1.json`);
    const ref = writeReceiptEnvelope(helper, targetPath, receipt);
    assert.throws(
      () => helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: ref }),
      /executor_kind must be runtime-agent or tl-direct/u,
      "legacy v2 must not inherit v3's post-hoc executor attribution",
    );
  });
});

