test("receipt v3 retains receipt-output-evidence-mismatch for raw and open-set faults", async (t) => {
  const helper = api();
  for (const fault of ["raw-bytes", "raw-path", "open-set-digest"]) {
    await t.test(fault, () => withRepo(({ repoRoot, mainSha }) => {
      const changeId = `receipt-v3-output-${fault}`;
      const reviewerPayload = authoritativeReceiptPayload(helper, {
        repoRoot,
        changeId,
        baseSha: mainSha,
        headSha: mainSha,
      });
      if (fault === "raw-bytes") {
        writeFileSync(evidencePath(repoRoot, reviewerPayload.output_evidence.raw_payload_ref.path), "tampered raw bytes\n");
      } else if (fault === "raw-path") {
        const original = evidencePath(repoRoot, reviewerPayload.output_evidence.raw_payload_ref.path);
        const wrongPath = `review-${changeId}-raw-r1-${"f".repeat(64)}.bin`;
        cpSync(original, evidencePath(repoRoot, wrongPath));
        reviewerPayload.output_evidence.raw_payload_ref.path = wrongPath;
      } else {
        reviewerPayload.output_evidence.verdict_open_set_sha256 = "0".repeat(64);
      }
      assert.throws(
        () => helper.sealReviewRoundReceipt({ repoRoot, changeId, reviewerPayload }),
        coreFailureIs("receipt-output-evidence-mismatch"),
      );
    }));
  }
});

test("post-hoc allowlist module-load validation pins full r4 and canonical open IDs", () => {
  const source = readFileSync(repoPath(".devpro/scripts/lib/review-remediation-evidence-core.mjs"), "utf8");
  const start = source.indexOf("function validatePostHocAllowlistConstants()");
  const end = source.indexOf("validatePostHocAllowlistConstants();", start);
  assert.ok(start >= 0 && end > start, "module-load allowlist validator must remain discoverable");
  const validator = source.slice(start, end);
  assert.match(validator, /tuple\.review_mode !== "full" \|\| tuple\.round_number !== 4/);
  assert.match(validator, /new Set\(tuple\.open_finding_ids\)\.size !== tuple\.open_finding_ids\.length/);
  assert.match(validator, /compareCodePoints\(tuple\.open_finding_ids\[index - 1\], id\) >= 0/);
});

