// The frozen r3 receipt lists F-fzvrr-r8-01 as open, and post-hoc authority checks only the
// open part of the carry-forward set. The frozen r11 raw payload itself carries that id as a
// closed Important fix-now entry, so a successor that seals must list it the same way; the
// frozen raw bytes are not touched and the check is not relaxed.
const R11_POST_HOC_CARRIED_R3_OPEN_FINDING = finding("F-fzvrr-r8-01", { state: "closed", disposition: "fix-now" });

function installR11ReceiptAncestors(repoRoot, changeId) {
  for (const round of [1, 2, 3]) {
    cpSync(
      path.join(D30_POST_HOC_AUTHORITY_FIXTURES, `review-${changeId}-receipt-r${round}.json`),
      path.join(mainNotesRoot(repoRoot), `review-${changeId}-receipt-r${round}.json`),
    );
  }
  const admissionRoot = path.join(repoRoot, "openspec", "changes", changeId, "admission-records");
  mkdirSync(admissionRoot, { recursive: true });
  cpSync(path.join(D30_POST_HOC_AUTHORITY_FIXTURES, "admission-records"), admissionRoot, { recursive: true });
  return path.join(mainNotesRoot(repoRoot), `review-${changeId}-receipt-r3.json`);
}

function r11PostHocReviewerPayload({ helper, repoRoot, changeId, dispatchId, reviewedHeadSha, rawPayloadRef, prepared, preparedRequest, sealed }) {
  const previousReceiptPath = installR11ReceiptAncestors(repoRoot, changeId);
  return {
    change_id: changeId,
    responsibility_id: "primary-review",
    dispatch_id: dispatchId,
    reviewer_identity: { role: "dp-reviewer", executor_kind: "post-hoc-tl-attested-runtime-review" },
    review_authority: { kind: "post-hoc-tl-attested-runtime-review", attestation_ref: sealed.authority_ref },
    output_evidence: {
      raw_payload_ref: rawPayloadRef,
      raw_payload_sha256: rawPayloadRef.digest_sha256,
      verdict_open_set_sha256: prepared.prepared.verdict_open_set_sha256,
    },
    review_mode: "full",
    round_number: 4,
    bounded_rereview_count: 0,
    lineage: {
      base_sha: preparedRequest.baseSha,
      merge_base_sha: preparedRequest.baseSha,
      head_sha: reviewedHeadSha,
      previous_receipt_ref: { path: `review-${changeId}-receipt-r3.json`, digest_sha256: sha256(readFileSync(previousReceiptPath)) },
      initial_full_receipt_digest_sha256: JSON.parse(readFileSync(previousReceiptPath, "utf8")).reviewer_payload.lineage.initial_full_receipt_digest_sha256,
    },
    scope: {
      risk_shape_digest_sha256: preparedRequest.riskShapeDigestSha256,
      // Omit alg: historical post-hoc allowlist digests resolve as full-prose-v0.
      open_finding_ids: preparedRequest.openFindingIds,
      repair_delta_manifest_ref: null,
      dependency_closure_manifest_ref: null,
    },
    findings: preparedRequest.findings,
    verdict: preparedRequest.verdict,
  };
}

function withR11PostHocReceiptCandidate(run, { findings = [finding("F-fzvrr-r11-01"), finding("F-fzvrr-r11-02")] } = {}) {
  const helper = api();
  const temporary = mkdtempSync(path.join(os.tmpdir(), "d30-post-hoc-receipt-candidate-"));
  const repoRoot = path.join(temporary, "repo");
  try {
    const changeId = "fix-zero-value-review-rounds";
    const reviewedHeadSha = "737e8cecf81974c8dbf299ce5a8666288f6aff2d";
    const dispatchId = "a4aec7bd119d193e88359ed888fbae1a9a2a2b72caadba283a4fb46717092dbf";
    initializeHistoricalPostHocRepo(repoRoot, reviewedHeadSha);
    const rawPayloadRef = helper.captureReviewerOutput({
      repoRoot, changeId, roundNumber: 4, dispatchId,
      payloadPath: D30_POST_HOC_R11_OUTPUT_FIXTURE,
    });
    const preparedRequest = {
      repoRoot, changeId, attestationId: "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb", reviewedHeadSha,
      baseSha: "f1e879d1079bdf4029967df4d84823f7815c225c", dispatchId, responsibilityId: "primary-review",
      reviewMode: "full", roundNumber: 4, riskShapeDigestSha256: "f0f06f74f7e6a2818a515fed9fcba44e568485da568a66174b6459de6e784f28",
      rawPayloadRef, verdict: "blocked", findings,
      openFindingIds: ["F-fzvrr-r11-01", "F-fzvrr-r11-02"], preparerId: "tl-preparer",
      eligibleReason: "codex-named-dp-reviewer-opaque-message-message-only-parser-v1", preparedAt: "2026-09-09T08:00:00.000Z",
    };
    const prepared = helper.preparePostHocAttestation(preparedRequest);
    const authorizationId = "cccccccc-cccc-4ccc-8ccc-cccccccccccc";
    const authorization = helper.recordPostHocAuthorization({
      repoRoot, changeId, authorizationId, preparedRef: prepared.ref, authorizedBy: "repo-owner",
      authorizationText: `authorize post-hoc recovery: prepared_sha256=${prepared.ref.digest_sha256}; authorization_id=${authorizationId}`,
      authorizedAt: "2026-09-09T08:05:00.000Z",
    });
    const sealed = helper.sealPostHocAttestation({
      repoRoot, changeId, preparedRef: prepared.ref, authorizationRef: authorization.ref,
      witnessId: "tl-witness", witnessedAt: "2026-09-09T08:10:00.000Z",
    });
    const reviewerPayload = r11PostHocReviewerPayload({
      helper, repoRoot, changeId, dispatchId, reviewedHeadSha, rawPayloadRef, prepared, preparedRequest, sealed,
    });
    return run({ helper, repoRoot, changeId, reviewedHeadSha, dispatchId, rawPayloadRef, preparedRequest, prepared, sealed, reviewerPayload });
  } finally {
    rmSync(temporary, { recursive: true, force: true });
  }
}

test("post-hoc r11 prepare authorization attestation lifecycle is tuple-bound, exact-once, and read-only recoverable", () => {
  const helper = api();
  const temporary = mkdtempSync(path.join(os.tmpdir(), "d30-post-hoc-r11-"));
  const repoRoot = path.join(temporary, "repo");
  try {
    const changeId = "fix-zero-value-review-rounds";
    const reviewedHeadSha = "737e8cecf81974c8dbf299ce5a8666288f6aff2d";
    const dispatchId = "a4aec7bd119d193e88359ed888fbae1a9a2a2b72caadba283a4fb46717092dbf";
    initializeHistoricalPostHocRepo(repoRoot, reviewedHeadSha);
    const rawPayloadRef = helper.captureReviewerOutput({
      repoRoot,
      changeId,
      roundNumber: 4,
      dispatchId,
      payloadPath: D30_POST_HOC_R11_OUTPUT_FIXTURE,
    });
    const findings = [clone(R11_POST_HOC_CARRIED_R3_OPEN_FINDING), finding("F-fzvrr-r11-01"), finding("F-fzvrr-r11-02")];
    const preparedRequest = {
      repoRoot, changeId, attestationId: "11111111-1111-4111-8111-111111111111", reviewedHeadSha,
      baseSha: "f1e879d1079bdf4029967df4d84823f7815c225c", dispatchId, responsibilityId: "primary-review",
      reviewMode: "full", roundNumber: 4, riskShapeDigestSha256: "f0f06f74f7e6a2818a515fed9fcba44e568485da568a66174b6459de6e784f28",
      rawPayloadRef, verdict: "blocked", findings, openFindingIds: ["F-fzvrr-r11-01", "F-fzvrr-r11-02"],
      preparerId: "tl-preparer", eligibleReason: "codex-named-dp-reviewer-opaque-message-message-only-parser-v1",
      preparedAt: "2026-09-09T08:00:00.000Z",
    };
    const invoke = (command, requestValue, expectedKeys) => {
      const requestPath = path.join(temporary, `${command}.json`);
      writeFileSync(requestPath, JSON.stringify(requestValue));
      const result = spawnSync(process.execPath, [HELPER_PATH, command, "--request", requestPath], { cwd: repoRoot, encoding: "utf8" });
      assert.equal(result.status, 0, `${command}: ${result.stdout}${result.stderr}`);
      const value = JSON.parse(result.stdout);
      assert.deepEqual(Object.keys(value), expectedKeys, `${command}: exact success key order`);
      assert.equal(result.stdout, `${helper.canonicalJsonV1(value)}\n`, `${command}: canonical single-line JSON + LF`);
      return value;
    };
    const prepared = invoke("prepare-post-hoc-attestation", preparedRequest, ["eligible_tuple_digest_sha256", "prepared", "ref"]);
    assert.deepEqual(
      invoke("prepare-post-hoc-attestation", preparedRequest, ["eligible_tuple_digest_sha256", "prepared", "ref"]),
      prepared,
      "prepare response-loss retry is byte-identical",
    );
    const preparedPath = path.join(repoRoot, prepared.ref.path);
    const preparedBytes = readFileSync(preparedPath);
    const forgedCases = [
      ["99999999-9999-4999-8999-999999999991", { reviewed_head_sha: "0".repeat(40) }, "closed historical allowlist"],
      ["99999999-9999-4999-8999-999999999992", {
        raw_payload_ref: { ...prepared.prepared.raw_payload_ref, digest_sha256: "0".repeat(64) },
        raw_payload_sha256: "0".repeat(64),
      }, "raw payload bytes"],
      ["99999999-9999-4999-8999-999999999993", { verdict_open_set_sha256: "0".repeat(64) }, "verdict/open-set digest"],
    ];
    for (const [forgedAuthorizationId, mutation, authority] of forgedCases) {
      const forgedPrepared = { ...prepared.prepared, ...mutation };
      const forgedPreparedBytes = Buffer.from(`${JSON.stringify(forgedPrepared, null, 2)}\n`, "utf8");
      writeFileSync(preparedPath, forgedPreparedBytes);
      const forgedPreparedRef = { path: prepared.ref.path, digest_sha256: sha256(forgedPreparedBytes) };
      assert.throws(
        () => helper.recordPostHocAuthorization({
          repoRoot, changeId, authorizationId: forgedAuthorizationId, preparedRef: forgedPreparedRef, authorizedBy: "repo-owner",
          authorizationText: `authorize post-hoc recovery: prepared_sha256=${forgedPreparedRef.digest_sha256}; authorization_id=${forgedAuthorizationId}`,
          authorizedAt: "2026-09-09T08:05:00.000Z",
        }),
        /authorization-binding-mismatch/u,
        `a hand-written canonical prepared carrier cannot bypass ${authority} authority`,
      );
      writeFileSync(preparedPath, preparedBytes);
    }
    const authorizationId = "22222222-2222-4222-8222-222222222222";
    const authorizationRequest = {
      repoRoot, changeId, authorizationId, preparedRef: prepared.ref, authorizedBy: "repo-owner",
      authorizationText: `authorize post-hoc recovery: prepared_sha256=${prepared.ref.digest_sha256}; authorization_id=${authorizationId}`,
      authorizedAt: "2026-09-09T08:05:00.000Z",
    };
    const authorization = invoke("record-post-hoc-authorization", authorizationRequest, ["authorization", "eligible_tuple_digest_sha256", "ref"]);
    const sealed = invoke("seal-post-hoc-attestation", {
      repoRoot, changeId, preparedRef: prepared.ref, authorizationRef: authorization.ref,
      witnessId: "tl-witness", witnessedAt: "2026-09-09T08:10:00.000Z",
    }, ["attestation", "authority_ref", "eligible_tuple_digest_sha256", "ref"]);
    assert.deepEqual(
      invoke("verify-post-hoc-attestation", { repoRoot, changeId, attestationId: preparedRequest.attestationId }, ["attestation", "authority_ref", "eligible_tuple_digest_sha256", "ref"]),
      sealed,
    );
    const reviewerPayload = r11PostHocReviewerPayload({
      helper, repoRoot, changeId, dispatchId, reviewedHeadSha, rawPayloadRef, prepared, preparedRequest, sealed,
    });
    const receipt = helper.sealReviewRoundReceipt({ repoRoot, changeId, reviewerPayload, attestationRef: sealed.ref });
    assert.equal(helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: receipt.ref, requireIndependence: true }).executor_attribution, "post-hoc-tl-attested-runtime-review");
    assert.throws(() => helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: receipt.ref }), /receipt-identity-authority-mismatch/u);
    assert.throws(
      () => helper.sealPostHocAttestation({ repoRoot, changeId, preparedRef: prepared.ref, authorizationRef: authorization.ref, witnessId: "another-witness", witnessedAt: "2026-09-09T08:10:01.000Z" }),
      /authorization-consumed/u,
    );
  } finally {
    rmSync(temporary, { recursive: true, force: true });
  }
});

test("post-hoc r10 historical tuple seals a committed independent receipt", () => {
  const helper = api();
  const temporary = mkdtempSync(path.join(os.tmpdir(), "d30-post-hoc-r10-"));
  const repoRoot = path.join(temporary, "repo");
  try {
    const changeId = "fix-zero-value-review-rounds";
    const reviewedHeadSha = "401953888a5b8478bfb31c8062897f1b7fa34862";
    const dispatchId = "48aab43c3fccda343b95ae07a6f4d0e64b8defbb3792b25b2b0646d067c99b8a";
    initializeHistoricalPostHocRepo(repoRoot, reviewedHeadSha);
    const rawPayloadRef = helper.captureReviewerOutput({
      repoRoot, changeId, roundNumber: 4, dispatchId,
      payloadPath: D30_POST_HOC_R10_OUTPUT_FIXTURE,
    });
    const findings = [clone(R11_POST_HOC_CARRIED_R3_OPEN_FINDING), finding("F-fzvrr-r10-01"), finding("F-fzvrr-r10-02")];
    const preparedRequest = {
      repoRoot, changeId, attestationId: "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa", reviewedHeadSha,
      baseSha: "f1e879d1079bdf4029967df4d84823f7815c225c", dispatchId, responsibilityId: "primary-review",
      reviewMode: "full", roundNumber: 4, riskShapeDigestSha256: "adf13108ced3da29a4da871df187ea1d3de67f849e2622ab0211423e1db96e21",
      rawPayloadRef, verdict: "partial", findings, openFindingIds: ["F-fzvrr-r10-01", "F-fzvrr-r10-02"],
      preparerId: "tl-preparer", eligibleReason: "codex-named-dp-reviewer-opaque-message-message-only-parser-v1",
      preparedAt: "2026-09-09T07:00:00.000Z",
    };
    const prepared = helper.preparePostHocAttestation(preparedRequest);
    const authorizationId = "dddddddd-dddd-4ddd-8ddd-dddddddddddd";
    const authorization = helper.recordPostHocAuthorization({
      repoRoot, changeId, authorizationId, preparedRef: prepared.ref, authorizedBy: "repo-owner",
      authorizationText: `authorize post-hoc recovery: prepared_sha256=${prepared.ref.digest_sha256}; authorization_id=${authorizationId}`,
      authorizedAt: "2026-09-09T07:05:00.000Z",
    });
    const sealed = helper.sealPostHocAttestation({
      repoRoot, changeId, preparedRef: prepared.ref, authorizationRef: authorization.ref,
      witnessId: "tl-witness", witnessedAt: "2026-09-09T07:10:00.000Z",
    });
    const reviewerPayload = r11PostHocReviewerPayload({
      helper, repoRoot, changeId, dispatchId, reviewedHeadSha, rawPayloadRef, prepared, preparedRequest, sealed,
    });
    const receipt = helper.sealReviewRoundReceipt({ repoRoot, changeId, reviewerPayload, attestationRef: sealed.ref });
    assert.match(receipt.ref.path, new RegExp(`r4-${dispatchId}\\.json$`, "u"));
    assert.match(receipt.commit_ref.path, new RegExp(`r4-${dispatchId}\\.commit\\.json$`, "u"));
    assert.equal(
      helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: receipt.ref, requireIndependence: true }).executor_attribution,
      "post-hoc-tl-attested-runtime-review",
    );
  } finally {
    rmSync(temporary, { recursive: true, force: true });
  }
});

// Scenario: Unlisted Git exit status remains generic
test("post-hoc r11 rejects tuple/reason/open-set/freshness/role drift and consumes one tuple across authorization IDs", () => {
  const helper = api();
  const temporary = mkdtempSync(path.join(os.tmpdir(), "d30-post-hoc-r11-negative-"));
  const repoRoot = path.join(temporary, "repo");
  try {
    const changeId = "fix-zero-value-review-rounds";
    const reviewedHeadSha = "737e8cecf81974c8dbf299ce5a8666288f6aff2d";
    const dispatchId = "a4aec7bd119d193e88359ed888fbae1a9a2a2b72caadba283a4fb46717092dbf";
    initializeHistoricalPostHocRepo(repoRoot, reviewedHeadSha);
    const rawPayloadRef = helper.captureReviewerOutput({
      repoRoot,
      changeId,
      roundNumber: 4,
      dispatchId,
      payloadPath: D30_POST_HOC_R11_OUTPUT_FIXTURE,
    });
    const findings = [finding("F-fzvrr-r11-01"), finding("F-fzvrr-r11-02")];
    const preparedRequest = {
      repoRoot, changeId, attestationId: "33333333-3333-4333-8333-333333333333", reviewedHeadSha,
      baseSha: "f1e879d1079bdf4029967df4d84823f7815c225c", dispatchId, responsibilityId: "primary-review",
      reviewMode: "full", roundNumber: 4, riskShapeDigestSha256: "f0f06f74f7e6a2818a515fed9fcba44e568485da568a66174b6459de6e784f28",
      rawPayloadRef, verdict: "blocked", findings, openFindingIds: ["F-fzvrr-r11-01", "F-fzvrr-r11-02"],
      preparerId: "tl-preparer", eligibleReason: "codex-named-dp-reviewer-opaque-message-message-only-parser-v1",
      preparedAt: "2026-09-09T08:00:00.000Z",
    };
    const rawPayloadPath = D30_POST_HOC_R11_OUTPUT_FIXTURE;
    const rawPayloadBytes = readFileSync(rawPayloadPath);
    const materializeMismatchedRawRef = ({ targetChangeId, targetRoundNumber, targetDispatchId }) => {
      const rawPath = `review-${targetChangeId}-raw-r${targetRoundNumber}-${targetDispatchId}.bin`;
      writeFileSync(path.join(mainNotesRoot(repoRoot), rawPath), rawPayloadBytes);
      return { path: rawPath, digest_sha256: sha256(rawPayloadBytes) };
    };
    const alternateChangeId = "fix-zero-value-review-rounds-other";
    const alternateChangeRawRef = materializeMismatchedRawRef({
      targetChangeId: alternateChangeId, targetRoundNumber: 4, targetDispatchId: dispatchId,
    });
    const alternateDispatchId = "9".repeat(64);
    const alternateDispatchRawRef = materializeMismatchedRawRef({
      targetChangeId: changeId, targetRoundNumber: 4, targetDispatchId: alternateDispatchId,
    });
    const alternateRoundRawRef = materializeMismatchedRawRef({
      targetChangeId: changeId, targetRoundNumber: 5, targetDispatchId: dispatchId,
    });
    const tupleMutations = [
      ["change_id", { changeId: alternateChangeId, rawPayloadRef: alternateChangeRawRef }],
      ["base_sha", { baseSha: "ab95bc8c2f33dc45818ac80b83364228dae0487c" }],
      ["reviewed_head_sha", { reviewedHeadSha: "ab95bc8c2f33dc45818ac80b83364228dae0487c" }],
      ["dispatch_id", { dispatchId: alternateDispatchId, rawPayloadRef: alternateDispatchRawRef }],
      ["responsibility_id", { responsibilityId: "secondary-review" }],
      ["review_mode", { reviewMode: "bounded" }],
      ["round_number", { roundNumber: 5, rawPayloadRef: alternateRoundRawRef }],
      ["risk_shape_digest_sha256", { riskShapeDigestSha256: "e".repeat(64) }],
      ["verdict", { verdict: "partial" }],
      ["open_finding_ids", { findings: [finding("F-other")], openFindingIds: ["F-other"] }],
    ];
    for (const [field, mutation] of tupleMutations) {
      assert.throws(
        () => helper.preparePostHocAttestation({ ...preparedRequest, ...mutation }),
        /post-hoc-eligible-tuple-mismatch/u,
        `${field} drift must reach and fail the closed tuple allowlist`,
      );
    }
    const rawTarget = path.join(mainNotesRoot(repoRoot), rawPayloadRef.path);
    const originalRawBytes = readFileSync(rawTarget);
    const differentRawBytes = Buffer.concat([originalRawBytes, Buffer.from("\nmutated", "utf8")]);
    writeFileSync(rawTarget, differentRawBytes);
    assert.throws(
      () => helper.preparePostHocAttestation({
        ...preparedRequest,
        rawPayloadRef: { path: rawPayloadRef.path, digest_sha256: sha256(differentRawBytes) },
      }),
      /post-hoc-eligible-tuple-mismatch/u,
      "raw_payload_sha256 drift must reach and fail the closed tuple allowlist",
    );
    writeFileSync(rawTarget, originalRawBytes);
    const rawReadEio = Object.assign(new Error("private stored payload EIO sentinel"), { code: "EIO" });
    const rawReadFaultCore = coreApi().createReviewRemediationEvidenceCore({
      fsOps: { readNoFollowFileHooks: { readSync() { throw rawReadEio; } } },
    });
    assert.throws(() => rawReadFaultCore.preparePostHocAttestation(preparedRequest), (error) => error === rawReadEio,
      "stored raw-payload EIO remains untyped instead of becoming raw-payload-digest-mismatch");
    const rawReadRaceCore = coreApi().createReviewRemediationEvidenceCore({
      fsOps: { readNoFollowFileHooks: { afterLstat(target) { unlinkSync(target); } } },
    });
    assert.throws(() => rawReadRaceCore.preparePostHocAttestation(preparedRequest), (error) => error?.code === "ENOENT",
      "stored raw-payload disappearance after lstat remains an untyped ENOENT race");
    writeFileSync(rawTarget, originalRawBytes);
    unlinkSync(rawTarget);
    const missingRawPayload = runReviewEvidenceCli(
      temporary,
      repoRoot,
      "prepare-post-hoc-attestation",
      `${JSON.stringify(preparedRequest)}\n`,
    );
    assert.equal(missingRawPayload.status, 1, `${missingRawPayload.stdout}${missingRawPayload.stderr}`);
    assert.deepEqual(JSON.parse(missingRawPayload.stdout), {
      ok: false,
      code: "raw-payload-digest-mismatch",
      detail: "Validate the captured reviewer payload and its dispatch tuple.",
    }, "a proven-missing stored raw payload retains its established explicit D30 code");
    writeFileSync(rawTarget, originalRawBytes);
    assert.throws(
      () => helper.preparePostHocAttestation({ ...preparedRequest, eligibleReason: "manual-recovery" }),
      /eligible-reason-invalid/u,
    );
    assert.throws(
      () => helper.preparePostHocAttestation({ ...preparedRequest, openFindingIds: ["F-fzvrr-r11-02", "F-fzvrr-r11-01"] }),
      /open-finding-ids-noncanonical/u,
    );
    assert.throws(
      () => helper.preparePostHocAttestation({ ...preparedRequest, preparedAt: "2026-02-31T00:00:00.000Z" }),
      /timestamp-invalid/u,
      "strict UTC timestamps reject calendar dates that Date.parse normalizes",
    );
    const realGitOps = countingSemanticGitOps().ops;
    const cutoffCore = coreApi().createReviewRemediationEvidenceCore({
      gitOps: Object.freeze({
        ...realGitOps,
        isAncestor(input) {
          assert.equal(input.ancestorSha, reviewedHeadSha);
          assert.equal(input.descendantSha, "ab95bc8c2f33dc45818ac80b83364228dae0487c");
          return false;
        },
      }),
    });
    // Scenario: a completed merge-base status 1 maps to the existing cutoff code.
    assert.throws(
      () => cutoffCore.preparePostHocAttestation(preparedRequest),
      /reviewed-head-after-cutoff/u,
    );
    // False from the injected isAncestor seam above models the sole completed
    // status-1 exception. Native/unlisted process faults below stay untyped.
    for (const [name, fault] of [
      ["status 128", Object.assign(new Error("private git stderr sentinel"), { status: 128, stderr: Buffer.from("private git stderr sentinel") })],
      ["unlisted status", Object.assign(new Error("private git stderr sentinel"), { status: 37, stderr: Buffer.from("private git stderr sentinel") })],
      ["spawn ENOENT", Object.assign(new Error("private spawn path sentinel"), { code: "ENOENT" })],
    ]) {
      const faultingGitCore = coreApi().createReviewRemediationEvidenceCore({
        gitOps: Object.freeze({
          ...realGitOps,
          isAncestor() { throw fault; },
        }),
      });
      assert.throws(() => faultingGitCore.preparePostHocAttestation(preparedRequest), (error) => {
        assert.equal(error, fault, `${name} must preserve the original untyped process failure`);
        assert.equal(error.message.includes("reviewed-head-after-cutoff"), false,
          `${name} cannot mint the cutoff domain code`);
        return true;
      });
    }
    const prepared = helper.preparePostHocAttestation(preparedRequest);
    const staleAuthorizationId = "88888888-8888-4888-8888-888888888888";
    const staleAuthorization = helper.recordPostHocAuthorization({
      repoRoot, changeId, authorizationId: staleAuthorizationId, preparedRef: prepared.ref, authorizedBy: "repo-owner-stale",
      authorizationText: `authorize post-hoc recovery: prepared_sha256=${prepared.ref.digest_sha256}; authorization_id=${staleAuthorizationId}`,
      authorizedAt: "2026-09-09T08:10:01.000Z",
    });
    assert.throws(
      () => helper.sealPostHocAttestation({ repoRoot, changeId, preparedRef: prepared.ref, authorizationRef: staleAuthorization.ref, witnessId: "tl-witness", witnessedAt: "2026-09-09T08:10:01.000Z" }),
      /authorization-stale/u,
    );
    const authorizationAId = "44444444-4444-4444-8444-444444444444";
    const authorizationA = helper.recordPostHocAuthorization({
      repoRoot, changeId, authorizationId: authorizationAId, preparedRef: prepared.ref, authorizedBy: "repo-owner-a",
      authorizationText: `authorize post-hoc recovery: prepared_sha256=${prepared.ref.digest_sha256}; authorization_id=${authorizationAId}`,
      authorizedAt: "2026-09-09T08:05:00.000Z",
    });
    assert.throws(
      () => helper.sealPostHocAttestation({ repoRoot, changeId, preparedRef: prepared.ref, authorizationRef: authorizationA.ref, witnessId: "tl-witness", witnessedAt: "2026-09-09T08:15:01.000Z" }),
      /authorization-stale/u,
    );
    assert.throws(
      () => helper.sealPostHocAttestation({ repoRoot, changeId, preparedRef: prepared.ref, authorizationRef: authorizationA.ref, witnessId: "tl-preparer", witnessedAt: "2026-09-09T08:10:00.000Z" }),
      /cooperative-identity-not-distinct/u,
    );
    const authorizationBId = "55555555-5555-4555-8555-555555555555";
    const authorizationB = helper.recordPostHocAuthorization({
      repoRoot, changeId, authorizationId: authorizationBId, preparedRef: prepared.ref, authorizedBy: "repo-owner-b",
      authorizationText: `authorize post-hoc recovery: prepared_sha256=${prepared.ref.digest_sha256}; authorization_id=${authorizationBId}`,
      authorizedAt: "2026-09-09T08:06:00.000Z",
    });
    helper.sealPostHocAttestation({
      repoRoot, changeId, preparedRef: prepared.ref, authorizationRef: authorizationA.ref,
      witnessId: "tl-witness", witnessedAt: "2026-09-09T08:10:00.000Z",
    });
    assert.throws(
      () => helper.sealPostHocAttestation({ repoRoot, changeId, preparedRef: prepared.ref, authorizationRef: authorizationB.ref, witnessId: "other-witness", witnessedAt: "2026-09-09T08:10:01.000Z" }),
      /authorization-consumed/u,
    );
  } finally {
    rmSync(temporary, { recursive: true, force: true });
  }
});

test("post-hoc tuple claim remains consumed when proof publication fails after the winning mkdir", () => {
  const helper = api();
  const coreFactory = coreApi().createReviewRemediationEvidenceCore;
  const temporary = mkdtempSync(path.join(os.tmpdir(), "d30-post-hoc-claim-fault-"));
  const repoRoot = path.join(temporary, "repo");
  try {
    const changeId = "fix-zero-value-review-rounds";
    const reviewedHeadSha = "737e8cecf81974c8dbf299ce5a8666288f6aff2d";
    const dispatchId = "a4aec7bd119d193e88359ed888fbae1a9a2a2b72caadba283a4fb46717092dbf";
    initializeHistoricalPostHocRepo(repoRoot, reviewedHeadSha);
    const rawPayloadRef = helper.captureReviewerOutput({
      repoRoot,
      changeId,
      roundNumber: 4,
      dispatchId,
      payloadPath: D30_POST_HOC_R11_OUTPUT_FIXTURE,
    });
    const prepared = helper.preparePostHocAttestation({
      repoRoot, changeId, attestationId: "66666666-6666-4666-8666-666666666666", reviewedHeadSha,
      baseSha: "f1e879d1079bdf4029967df4d84823f7815c225c", dispatchId, responsibilityId: "primary-review",
      reviewMode: "full", roundNumber: 4, riskShapeDigestSha256: "f0f06f74f7e6a2818a515fed9fcba44e568485da568a66174b6459de6e784f28",
      rawPayloadRef, verdict: "blocked", findings: [finding("F-fzvrr-r11-01"), finding("F-fzvrr-r11-02")],
      openFindingIds: ["F-fzvrr-r11-01", "F-fzvrr-r11-02"], preparerId: "tl-preparer",
      eligibleReason: "codex-named-dp-reviewer-opaque-message-message-only-parser-v1", preparedAt: "2026-09-09T08:00:00.000Z",
    });
    const authorizationId = "77777777-7777-4777-8777-777777777777";
    const authorization = helper.recordPostHocAuthorization({
      repoRoot, changeId, authorizationId, preparedRef: prepared.ref, authorizedBy: "repo-owner",
      authorizationText: `authorize post-hoc recovery: prepared_sha256=${prepared.ref.digest_sha256}; authorization_id=${authorizationId}`,
      authorizedAt: "2026-09-09T08:05:00.000Z",
    });
    const claimEvents = [];
    const syncDirectory = (target) => {
      const handle = openSync(target, "r");
      try { fsyncSync(handle); } finally { closeSync(handle); }
    };
    const faulting = coreFactory({
      fsOps: {
        postHocMkdirSync(target, options) {
          claimEvents.push(`mkdir:${path.basename(target)}`);
          return mkdirSync(target, options);
        },
        postHocFsyncDirectory(target) {
          claimEvents.push(`fsync:${path.basename(target)}`);
          if (process.platform === "win32") return;
          return syncDirectory(target);
        },
        postHocCreateExclusiveDurableFile({ target }) {
          assert.match(target.replaceAll("\\", "/"), /authorization-tuples\/[0-9a-f]{64}\.claim\/consumed\.json$/u);
          claimEvents.push(`write:${path.basename(target)}`);
          throw new Error("injected tuple proof write fault");
        },
      },
    });
    const sealRequest = {
      repoRoot, changeId, preparedRef: prepared.ref, authorizationRef: authorization.ref,
      witnessId: "tl-witness", witnessedAt: "2026-09-09T08:10:00.000Z",
    };
    assert.throws(() => faulting.sealPostHocAttestation(sealRequest), /injected tuple proof write fault/u);
    assert.deepEqual(claimEvents.slice(-5), [
      "mkdir:authorization-tuples",
      "fsync:post-hoc",
      `mkdir:${prepared.eligible_tuple_digest_sha256}.claim`,
      "fsync:authorization-tuples",
      "write:consumed.json",
    ]);
    assert.equal(existsSync(path.join(
      repoRoot, "openspec", "changes", changeId, "admission-records", "post-hoc", "authorization-tuples",
      `${prepared.eligible_tuple_digest_sha256}.claim`,
    )), true, "the winning claim directory is irreversible even without its proof");
    assert.throws(() => helper.sealPostHocAttestation(sealRequest), /authorization-consumed/u);
  } finally {
    rmSync(temporary, { recursive: true, force: true });
  }
});

