test("post-hoc receipt and marker faults stay fail-closed after irreversible attestation claim", async (t) => {
  const coreFactory = coreApi().createReviewRemediationEvidenceCore;
  const cases = [
    ["receipt publish", { failAt: "publishExclusive", failAtOccurrence: 1 }, /injected publishExclusive fault/u],
    ["receipt readback", { readbackMismatch: true, readbackMismatchAtOccurrence: 1 }, /receipt-readback-mismatch/u],
    ["receipt authority mutation", { onReadback: ({ occurrence }) => { if (occurrence === 1) return "mutate"; } }, /receipt-authority-changed/u],
    ["marker publish", { failAt: "publishExclusive", failAtOccurrence: 2 }, /injected publishExclusive fault/u],
    ["marker readback", { readbackMismatch: true, readbackMismatchAtOccurrence: 2 }, /receipt-readback-mismatch/u],
  ];
  for (const [name, fsOptions, expected] of cases) {
    await t.test(name, () => withR11PostHocReceiptCandidate(({ helper, repoRoot, changeId, sealed, reviewerPayload }) => {
      const options = { ...fsOptions };
      if (name === "receipt authority mutation") {
        options.onReadback = ({ occurrence }) => {
          if (occurrence === 1) commitRound(repoRoot, 404);
        };
      }
      const fake = recordingFsOps(options);
      const request = { attestationRef: sealed.ref, changeId, repoRoot, reviewerPayload };
      assert.throws(() => coreFactory({ fsOps: fake.ops }).sealReviewRoundReceipt(request), expected);
      assert.throws(() => helper.sealReviewRoundReceipt(request), /attestation-consumed/u, `${name}: retry cannot reuse authority`);
    }, {
      findings: [clone(R11_POST_HOC_CARRIED_R3_OPEN_FINDING), finding("F-fzvrr-r11-01"), finding("F-fzvrr-r11-02")],
    }));
  }
});

