const VALIDATOR_TRUST_SURFACE_CORE = ".devpro/scripts/lib/review-remediation-evidence-core.mjs";
const VALIDATOR_TRUST_SURFACE_FACADE = ".devpro/scripts/review-remediation-evidence.mjs";
const VALIDATOR_TRUST_SURFACE_DEPENDENCIES = [
  ".devpro/scripts/hooks/lib/fresh-equivalent-compare.mjs",
  ".devpro/scripts/lib/half-state-override.mjs",
  ".devpro/scripts/hooks/lib/admission-record.mjs",
  ".devpro/scripts/lib/git-exec-retry.mjs",
];
const PRODUCTION_VALIDATOR_ORACLE = ".devpro/scripts/tools/review-remediation-validator-oracle.mjs";

function seedValidatorTrustSurface(repoRoot, { content = "export const trustSurface = 'v1';\n" } = {}) {
  mkdirSync(path.join(repoRoot, ".devpro", "scripts", "lib"), { recursive: true });
  write(repoRoot, VALIDATOR_TRUST_SURFACE_FACADE, content);
  write(repoRoot, VALIDATOR_TRUST_SURFACE_CORE, content);
  for (const dependency of VALIDATOR_TRUST_SURFACE_DEPENDENCIES) {
    mkdirSync(path.dirname(path.join(repoRoot, dependency)), { recursive: true });
    write(repoRoot, dependency, content);
  }
}

function touchValidatorTrustSurface(repoRoot, targetPath = VALIDATOR_TRUST_SURFACE_CORE) {
  write(repoRoot, targetPath, "export const trustSurface = 'v2-touched';\n");
  return commitAll(repoRoot, "touch validator trust surface");
}

function installProductionOracle(repoRoot) {
  const absolute = repoPath(PRODUCTION_VALIDATOR_ORACLE);
  mkdirSync(path.join(repoRoot, ".devpro", "scripts", "tools"), { recursive: true });
  writeFileSync(path.join(repoRoot, PRODUCTION_VALIDATOR_ORACLE), readFileSync(absolute));
  chmodSync(path.join(repoRoot, PRODUCTION_VALIDATOR_ORACLE), 0o755);
}

function advanceMainWithTrustSurface(repoRoot, { oracle = false } = {}) {
  const featureBranch = git(repoRoot, ["branch", "--show-current"]);
  git(repoRoot, ["checkout", "--quiet", "main"]);
  if (oracle) installProductionOracle(repoRoot);
  seedValidatorTrustSurface(repoRoot);
  const newMain = commitAll(repoRoot, "base: production oracle + validator trust surface", {
    executablePaths: oracle ? [PRODUCTION_VALIDATOR_ORACLE] : [],
  });
  if (process.platform === "win32") git(repoRoot, ["config", "core.filemode", "false"]);
  syncOriginMain(repoRoot, newMain);
  git(repoRoot, ["checkout", "--quiet", featureBranch]);
  git(repoRoot, ["merge", "--quiet", newMain, "-m", "merge oracle base"]);
  return newMain;
}

// F-cross WARN: seed echo-oracle on main so Prefer-A negatives exercise oracle
// execution/output disagreement, not merely "oracle graph missing at change base".
function advanceMainWithEchoOracle(repoRoot) {
  const featureBranch = git(repoRoot, ["branch", "--show-current"]);
  git(repoRoot, ["checkout", "--quiet", "main"]);
  write(repoRoot, "tools/echo-oracle.mjs", echoWithoutRecomputeOracleSource());
  chmodSync(path.join(repoRoot, "tools/echo-oracle.mjs"), 0o755);
  const newMain = commitAll(repoRoot, "base: echo-without-recompute oracle", {
    executablePaths: ["tools/echo-oracle.mjs", "tools/validator-oracle.mjs"],
  });
  if (process.platform === "win32") git(repoRoot, ["config", "core.filemode", "false"]);
  syncOriginMain(repoRoot, newMain);
  git(repoRoot, ["checkout", "--quiet", featureBranch]);
  git(repoRoot, ["merge", "--quiet", newMain, "-m", "merge echo oracle base"]);
  return newMain;
}

function echoWithoutRecomputeOracleSource() {
  return [
    "export async function verify(request) {",
    "  // Intentionally skips assertion recomputation (F1 negative).",
    "  return {",
    '    schema: "devpro.review-remediation.validator-evidence/v1",',
    "    oracle: request.oracle,",
    "    subject: {",
    "      validator_source_path: request.manifest_assertion.validator.source_path,",
    "      validator_source_digest_sha256: request.manifest_assertion.validator.source_digest_sha256,",
    '      manifest_assertion_digest_sha256: "0".repeat(64),',
    "    },",
    "    lineage: {",
    "      change_base_sha: request.manifest_assertion.lineage.change_base_sha,",
    "      candidate_head_sha: request.manifest_assertion.lineage.candidate_head_sha,",
    "    },",
    '    result: "verified",',
    '    evidence_digest_sha256: "1".repeat(64),',
    "  };",
    "}",
    "",
  ].join("\n");
}

// R14 / decisions D16 (design D19): this fixture's change base has no
// production validator oracle (`advanceMainWithTrustSurface` defaults to no
// oracle), so the oracle probe is unavailable
// here regardless of the R14 gate change — the expectation below is
// unaffected by D16 and stays the Else-B positive it always was.
test("validator-touching + stable risk with absent manifests dispatches full with validator_trust_surface_changed (fix-validator-touching-bounded-escape T1/T2 prove-it)", () => {
  // RED-before-fix: without D2 Else-B this case returned full_reopen_required
  // with no dispatch_id. After the fix it must mint a dispatchable full reopen.
  const helper = api();
  for (const touchedPath of [VALIDATOR_TRUST_SURFACE_CORE, ...VALIDATOR_TRUST_SURFACE_DEPENDENCIES]) {
    withRepo(({ repoRoot }) => {
      const changeId = "validator-touching-else-b-absent";
      const mainSha = advanceMainWithTrustSurface(repoRoot);
      writeFullRiskChange(repoRoot, changeId);
      commitAll(repoRoot, "validator-touching prove-it baseline");
      const initial = sealInitial(helper, { repoRoot, changeId, mainSha });
      commitRound(repoRoot, 1301);
      touchValidatorTrustSurface(repoRoot, touchedPath);
      const result = helper.classifyBoundedRereview({
        repoRoot,
        changeId,
        previousReceiptRef: initial.ref,
        repairDeltaManifestRef: null,
        dependencyClosureManifestRef: null,
        predecessorMatches: predecessorMatches(initial.receipt),
      });
      assertDispatchableResult(result, {
        route: "full",
        count: 0,
        round: 2,
        reason: "validator_trust_surface_changed",
      });
    });
  }
});

test("validator-touching pre-existing-trusted manifests that fail trust dispatch full with validator_trust_surface_changed (fix-validator-touching-bounded-escape T2)", () => {
  const helper = api();
  for (const sourcePath of [VALIDATOR_TRUST_SURFACE_CORE, VALIDATOR_TRUST_SURFACE_FACADE]) {
    for (const touchedPath of [sourcePath, VALIDATOR_TRUST_SURFACE_DEPENDENCIES[0]]) {
      withRepo(({ repoRoot }) => {
        const changeId = "validator-touching-else-b-trust";
        const mainSha = advanceMainWithTrustSurface(repoRoot);
        writeFullRiskChange(repoRoot, changeId);
        commitAll(repoRoot, "validator-touching trust-fail baseline");
        const initial = sealInitial(helper, { repoRoot, changeId, mainSha });
        const surfaceBaseSha = initial.receipt.reviewer_payload.lineage.head_sha;
        const candidateHeadSha = touchValidatorTrustSurface(repoRoot, touchedPath);
        const common = {
          changeBaseSha: mainSha,
          surfaceBaseSha,
          candidateHeadSha,
        };
        const repair = writeManifestFixtureCarrier(helper, {
          repoRoot,
          changeId,
          roundNumber: 2,
          manifest: (() => {
            const raw = manifestFixture({ purpose: "repair-delta", ...common });
            raw.validator.source_path = sourcePath;
            raw.validator.provenance = "pre-existing-trusted";
            raw.validator.independent_evidence = null;
            return raw;
          })(),
        });
        const closure = writeManifestFixtureCarrier(helper, {
          repoRoot,
          changeId,
          roundNumber: 2,
          manifest: (() => {
            const raw = manifestFixture({ purpose: "dependency-closure", ...common });
            raw.validator.source_path = sourcePath;
            raw.validator.provenance = "pre-existing-trusted";
            raw.validator.independent_evidence = null;
            return raw;
          })(),
        });
        const result = classifyBounded(helper, {
          repoRoot,
          changeId,
          previousReceipt: initial,
          repairManifest: repair,
          closureManifest: closure,
        });
        assertDispatchableResult(result, {
          route: "full",
          count: 0,
          round: 2,
          reason: "validator_trust_surface_changed",
        });
      });
    }
  }
});

test("validator-touching mixed trust failure + structural cycle stays full_reopen_required without id (fix-validator-touching-bounded-escape T3)", () => {
  const helper = api();
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "validator-touching-mixed-trust-structural";
    seedValidatorTrustSurface(repoRoot);
    writeFullRiskChange(repoRoot, changeId);
    commitAll(repoRoot, "validator-touching mixed baseline");
    const initial = sealInitial(helper, { repoRoot, changeId, mainSha });
    const surfaceBaseSha = initial.receipt.reviewer_payload.lineage.head_sha;
    const candidateHeadSha = touchValidatorTrustSurface(repoRoot);
    const cycleEntries = [
      { id: "a", path: "src/review-target.mjs", digest_sha256: DIGEST_A },
      { id: "b", path: "src/second-target.mjs", digest_sha256: DIGEST_B },
    ];
    const repair = writeManifestFixtureCarrier(helper, {
      repoRoot,
      changeId,
      roundNumber: 2,
      manifest: (() => {
        const raw = manifestFixture({
          purpose: "repair-delta",
          changeBaseSha: mainSha,
          surfaceBaseSha,
          candidateHeadSha,
        });
        raw.validator.source_path = VALIDATOR_TRUST_SURFACE_CORE;
        raw.validator.provenance = "pre-existing-trusted";
        return raw;
      })(),
    });
    const closure = writeManifestFixtureCarrier(helper, {
      repoRoot,
      changeId,
      roundNumber: 2,
      manifest: (() => {
        const raw = manifestFixture({
          purpose: "dependency-closure",
          changeBaseSha: mainSha,
          surfaceBaseSha,
          candidateHeadSha,
          entries: cycleEntries,
          dependency_edges: [
            { from: "a", to: "b", kind: "reference" },
            { from: "b", to: "a", kind: "reference" },
          ],
        });
        // Unchanged non-trigger validator so trust passes and the cycle remains visible.
        raw.validator.source_path = "tools/validator.mjs";
        raw.validator.provenance = "pre-existing-trusted";
        return raw;
      })(),
    });
    const result = classifyBounded(helper, {
      repoRoot,
      changeId,
      previousReceipt: initial,
      repairManifest: repair,
      closureManifest: closure,
    });
    assert.equal(result.route, "full_reopen_required");
    assert.equal(Object.hasOwn(result, "dispatch_id"), false);
    assert.equal(Object.hasOwn(result, "dispatch_ready"), false);
    assert.equal(result.full_reopen_debug_reason, "manifest_verification_failed");
  });
});

test("Prefer-A: independently-verified production oracle path yields bounded when validator trust surface changes (fix-validator-touching-bounded-escape T4/T5)", () => {
  const helper = api();
  for (const sourcePath of [VALIDATOR_TRUST_SURFACE_CORE, VALIDATOR_TRUST_SURFACE_FACADE]) {
    for (const touchedPath of [sourcePath, VALIDATOR_TRUST_SURFACE_DEPENDENCIES[0]]) {
      withRepo(({ repoRoot }) => {
        const changeId = "validator-touching-prefer-a";
        const mainSha = advanceMainWithTrustSurface(repoRoot, { oracle: true });
        writeFullRiskChange(repoRoot, changeId);
        commitAll(repoRoot, "prefer-a risk baseline");
        const initial = sealInitial(helper, { repoRoot, changeId, mainSha });
        const surfaceBaseSha = initial.receipt.reviewer_payload.lineage.head_sha;
        const candidateHeadSha = touchValidatorTrustSurface(repoRoot, touchedPath);
        const sealIndependent = (purpose) => {
          const raw = manifestFixture({
            purpose,
            changeBaseSha: mainSha,
            surfaceBaseSha,
            candidateHeadSha,
          });
          raw.validator.source_path = sourcePath;
          raw.validator.provenance = "independently-verified-same-change";
          const materialized = materializeManifest(helper, repoRoot, raw);
          materialized.validator.independent_evidence = evidenceFixture(
            helper,
            repoRoot,
            materialized,
            PRODUCTION_VALIDATOR_ORACLE,
          );
          return sealRawManifest(helper, {
            repoRoot,
            changeId,
            roundNumber: 2,
            manifest: materialized,
          });
        };
        const repair = sealIndependent("repair-delta");
        const closure = sealIndependent("dependency-closure");
        const result = classifyBounded(helper, {
          repoRoot,
          changeId,
          previousReceipt: initial,
          repairManifest: repair,
          closureManifest: closure,
        });
        assertDispatchableResult(result, {
          route: "bounded",
          count: 1,
          round: 2,
          reason: null,
        });
      });
    }
  }
});

test("validator-oracle negatives: echo-without-recompute and forged subject digest still fail (fix-validator-touching-bounded-escape T6)", () => {
  const helper = api();
  withRepo(({ repoRoot }) => {
    // Echo oracle must pre-exist unchanged at change-base so seal reaches
    // oracle execution; only the validator changes afterward (cross WARN).
    const mainSha = advanceMainWithEchoOracle(repoRoot);
    write(repoRoot, "tools/validator.mjs", "export const validate = 'changed-for-oracle-negatives';\n");
    const headSha = commitAll(repoRoot, "change validator only for oracle negatives");

    const base = materializeManifest(helper, repoRoot, manifestFixture({
      changeBaseSha: mainSha,
      surfaceBaseSha: mainSha,
      candidateHeadSha: headSha,
    }));
    base.validator.provenance = "independently-verified-same-change";
    base.validator.independent_evidence = evidenceFixture(helper, repoRoot, base, "tools/echo-oracle.mjs");
    assert.throws(
      () => sealManifest(helper, {
        repoRoot,
        changeId: "validator-oracle-echo-without-recompute",
        roundNumber: 1,
        manifest: base,
      }),
      /oracle output does not agree with sealed evidence/,
      "echo-without-recompute must fail after oracle execution on output disagreement",
    );

    const forged = materializeManifest(helper, repoRoot, manifestFixture({
      changeBaseSha: mainSha,
      surfaceBaseSha: mainSha,
      candidateHeadSha: headSha,
    }));
    forged.validator.provenance = "independently-verified-same-change";
    forged.validator.independent_evidence = evidenceFixture(helper, repoRoot, forged);
    forged.validator.independent_evidence.subject.manifest_assertion_digest_sha256 = "a".repeat(64);
    delete forged.validator.independent_evidence.evidence_digest_sha256;
    forged.validator.independent_evidence.evidence_digest_sha256 = sha256(
      helper.canonicalJsonV1((() => {
        const copy = clone(forged.validator.independent_evidence);
        delete copy.evidence_digest_sha256;
        return copy;
      })()),
    );
    assert.throws(
      () => sealManifest(helper, {
        repoRoot,
        changeId: "validator-oracle-subject-digest-forged",
        roundNumber: 1,
        manifest: forged,
      }),
      /subject|assertion|digest|mismatch/i,
      "self-consistent evidence with forged assertion digest must not seal",
    );
  });
});

