// R14 / decisions D16 (design D19): this fixture's change base has no
// production validator oracle (`seedValidatorTrustSurface` alone), so the
// oracle probe is unavailable here regardless of the R14 gate change — the
// expectation below is unaffected by D16 (index 220 is the oracle-available
// counterpart, which flips to manifest_refs_absent).
test("validator_trust_surface_changed precedence: cap and stall both yield to trust reopen (F1 / was T8)", () => {
  const helper = api();
  // F1: trust is mandatory-full, not mere risk_shape_changed — stall must yield
  // so full remains reachable (same outcome as the bounded cap).
  const stopConditions = [
    { name: "stall", trajectory: [2, 2, 2], expectedCount: 2 },
    { name: "cap", trajectory: [5, 4, 3, 2], expectedCount: 3 },
  ];
  for (const stop of stopConditions) {
    withRepo(({ repoRoot, mainSha }) => {
      const changeId = `validator-touching-${stop.name}-precedence`;
      seedValidatorTrustSurface(repoRoot);
      const { request } = chainThrough(helper, {
        repoRoot,
        mainSha,
        changeId,
        trajectory: stop.trajectory,
      });
      touchValidatorTrustSurface(repoRoot);
      const result = helper.classifyBoundedRereview({
        ...request,
        repairDeltaManifestRef: null,
        dependencyClosureManifestRef: null,
      });
      assert.deepEqual(Object.keys(result).sort(), DISPATCH_RESULT_KEYS, stop.name);
      assert.equal(result.next_bounded_rereview_count, stop.expectedCount, stop.name);
      assert.equal(result.route, "full", stop.name);
      assert.equal(result.dispatch_ready, true, stop.name);
      assert.equal(result.full_reopen_reason, "validator_trust_surface_changed", stop.name);
      assert.match(result.dispatch_id, /^[0-9a-f]{64}$/u, stop.name);
    });
  }
});

