// F-fvte-r1-06: append-only registrations (indices 149-151). Else-B trust-fail
// must not mint route:full + dispatch_id when retained manifests also fail
// bounded-eligibility (wrong purpose / non-pass result / wrong transition lineage).
test("validator-touching trust-fail + wrong-purpose stays full_reopen_required without id (F-fvte-r1-06)", () => {
  const helper = api();
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "validator-touching-else-b-wrong-purpose";
    seedValidatorTrustSurface(repoRoot);
    writeFullRiskChange(repoRoot, changeId);
    commitAll(repoRoot, "validator-touching else-b wrong-purpose baseline");
    const initial = sealInitial(helper, { repoRoot, changeId, mainSha });
    const surfaceBaseSha = initial.receipt.reviewer_payload.lineage.head_sha;
    const candidateHeadSha = touchValidatorTrustSurface(repoRoot);
    const common = {
      changeBaseSha: mainSha,
      surfaceBaseSha,
      candidateHeadSha,
    };
    const trustFailValidator = (raw) => {
      raw.validator.source_path = VALIDATOR_TRUST_SURFACE_CORE;
      raw.validator.provenance = "pre-existing-trusted";
      raw.validator.independent_evidence = null;
      return raw;
    };
    // Carrier path must match the expected purpose; body purpose is swapped so
    // ownership passes and eligibility fails after the trust-eligible throw.
    const writeMismatchedPurpose = (expectedPurpose, bodyPurpose) => {
      const materialized = materializeManifest(
        helper,
        repoRoot,
        trustFailValidator(manifestFixture({ purpose: bodyPurpose, ...common })),
      );
      const sealed = {
        ...materialized,
        manifest_digest_sha256: sha256(helper.canonicalJsonV1(materialized)),
      };
      const targetPath = manifestTarget(repoRoot, changeId, expectedPurpose, 2);
      writeFileSync(targetPath, `${helper.canonicalJsonV1(sealed)}\n`);
      return { manifest: sealed, targetPath, ref: durableRef(repoRoot, targetPath) };
    };
    const repair = writeMismatchedPurpose("repair-delta", "content-comparison");
    const closure = writeMismatchedPurpose("dependency-closure", "content-comparison");
    const result = classifyBounded(helper, {
      repoRoot,
      changeId,
      previousReceipt: initial,
      repairManifest: repair,
      closureManifest: closure,
    });
    assert.equal(result.route, "full_reopen_required");
    assert.equal(Object.hasOwn(result, "dispatch_id"), false);
    assert.equal(Object.hasOwn(result, "dispatch_ready"), false);
    assert.equal(result.full_reopen_debug_reason, "bounded_input_invalid");
  });
});

