// ---------------------------------------------------------------------------
// fix-receipt-authority-host-generic T1/T2 (appended; only runner_d's upper
// bound moves). The v3 runtime-admission authority must be host-generic: a
// v1 admission record written by the real `writeAdmissionRecord` writer for a
// non-Codex host (host=opencode, role_binding host-verified) evidences a
// runtime-agent receipt through the generic content-to-ID binding. Every test
// group below carries the `generic v1` anchor for grep.
// ---------------------------------------------------------------------------

// D6 fixture: the same linked-worktree pattern as
// `preparedRuntimeAdmissionFixture` — the record is written by the production
// `writeAdmissionRecord` writer from a real `.worktree/<changeId>` cwd (so
// `record.head_sha`/`change_id` are genuinely host-derived), then mirrored
// into the main checkout the receipt tests seal from. Negative variants are
// produced by parametrization or by rewriting the mirrored record file; they
// never open a second worktree.
function genericV1AdmissionFixture({ repoRoot, changeId }, {
  role = "dp-reviewer",
  roleBinding = "host-verified",
  responsibilityId = "primary-review",
} = {}) {
  const cwd = path.join(path.dirname(repoRoot), ".worktree", changeId);
  mkdirSync(path.dirname(cwd), { recursive: true });
  git(repoRoot, ["worktree", "add", "--quiet", "--detach", cwd, "HEAD"]);
  const written = writeAdmissionRecord({
    cwd,
    host: "opencode",
    prompt: "generic v1 admission fixture prompt",
    fields: {
      objective: "specialized-surface",
      responsibility_id: responsibilityId,
      instance_mode: "fresh",
      evidence_scope: "local diff",
      return_and_stop: "return findings and stop",
      role,
    },
    roleBinding,
  });
  assert.equal(written.ok, true, written.code);
  cpSync(
    path.join(cwd, "openspec", "changes", changeId, "admission-records"),
    path.join(repoRoot, "openspec", "changes", changeId, "admission-records"),
    { recursive: true },
  );
  // strengthen-admission-binding-portability: the same reason as
  // `preparedRuntimeAdmissionFixture` — the consumer resolves the exact-one
  // binding first, so the fixture retires the worktree and leaves the mirrored
  // main-checkout authority as the post-merge window the fallback keeps
  // readable. The negatives below mutate that mirrored copy.
  git(repoRoot, ["worktree", "remove", "--force", cwd]);
  const read = readAdmissionRecord({ repoRoot, changeId, recordId: written.record_id });
  assert.equal(read.ok, true, read.code);
  return { record_id: written.record_id, digest: written.digest, record: read.record };
}

function genericV1RecordPath(repoRoot, changeId, recordId) {
  return path.join(repoRoot, "openspec", "changes", changeId, "admission-records", `${recordId}.json`);
}

// Rewrites the mirrored v1 record file exactly the way `writeAdmissionRecord`
// serialized it (pretty JSON + LF), then returns the digest of the rewritten
// bytes — the FR5 "ref digest 同步更新" half.
function rewriteGenericV1Record(repoRoot, changeId, recordId, mutate) {
  const recordPath = genericV1RecordPath(repoRoot, changeId, recordId);
  const record = JSON.parse(readFileSync(recordPath, "utf8"));
  mutate(record);
  const bytes = Buffer.from(`${JSON.stringify(record, null, 2)}\n`, "utf8");
  writeFileSync(recordPath, bytes);
  return sha256(bytes);
}

// The builder reads the raw payload carrier the same way the devpro:pre-pr action
// point does; this writes the canonical raw bytes under the canonical name.
function writeGenericV1RawPayload(helper, { repoRoot, payload }) {
  const rawPayload = clone(payload);
  rawPayload.review_authority = null;
  rawPayload.output_evidence = null;
  const rawBytes = Buffer.from(`${helper.canonicalJsonV1(rawPayload)}\n`, "utf8");
  const rawPath = `review-${rawPayload.change_id}-raw-r${rawPayload.round_number}-${rawPayload.dispatch_id}.bin`;
  writeFileSync(evidencePath(repoRoot, rawPath), rawBytes);
  return { path: rawPath, digest_sha256: sha256(rawBytes) };
}

function genericV1OnePieceAuthority(admission) {
  return {
    kind: "runtime-admission",
    admission_ref: { record_id: admission.record_id, digest_sha256: admission.digest },
  };
}

test("generic v1 runtime receipt: builder derives a one-piece authority from a host-verified v1 record and verify-receipt --require-independence attributes runtime-agent (generic v1 positive)", () => {
  const helper = api();
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "generic-v1-positive";
    boundChange(repoRoot, changeId);
    const admission = genericV1AdmissionFixture({ repoRoot, changeId });
    const payload = runtimeAgentPayload(helper, { repoRoot, changeId, mainSha, findings: [] });
    const rawPayloadRef = writeGenericV1RawPayload(helper, { repoRoot, payload });
    const built = helper.buildReviewRoundReceiptRequest({
      repoRoot,
      changeId,
      rawPayloadRef,
      admissionRecordId: admission.record_id,
    });
    assert.deepEqual(built.reviewerPayload.review_authority, genericV1OnePieceAuthority(admission));
    const claimPath = path.join(path.dirname(genericV1RecordPath(repoRoot, changeId, admission.record_id)), `${admission.record_id}.claim`);
    assert.equal(existsSync(claimPath), false, "builder must not claim generic admission authority");
    const sealed = helper.sealReviewRoundReceipt(built);
    assert.equal(sealed.receipt.schema, REVIEW_RECEIPT_SCHEMA);
    assert.equal(existsSync(evidencePath(repoRoot, sealed.ref.path.replace(/\.json$/u, ".commit.json"))), true);
    const verified = helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: sealed.ref, requireIndependence: true });
    assert.equal(verified.executor_attribution, "runtime-agent");
  });
});

test("generic v1 authority shape matrix: one-piece and two-piece seal while mixed and missing keys keep the closed tokens (generic v1 shape matrix)", () => {
  const helper = api();
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "generic-v1-shape-one-piece";
    boundChange(repoRoot, changeId);
    const admission = genericV1AdmissionFixture({ repoRoot, changeId });
    const payload = runtimeAgentPayload(helper, { repoRoot, changeId, mainSha, findings: [] });
    bindReceiptAuthority(helper, { repoRoot, changeId, reviewerPayload: payload });
    payload.review_authority = genericV1OnePieceAuthority(admission);
    const sealed = helper.sealReviewRoundReceipt({
      repoRoot,
      changeId,
      reviewerPayload: payload,
      admissionRecordId: admission.record_id,
    });
    assert.equal(sealed.receipt.schema, REVIEW_RECEIPT_SCHEMA);
    assert.equal(
      helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: sealed.ref, requireIndependence: true }).executor_attribution,
      "runtime-agent",
    );
  });
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "generic-v1-shape-two-piece";
    boundChange(repoRoot, changeId);
    const admission = preparedRuntimeAdmissionFixture({ repoRoot, changeId });
    const sealed = sealPreparedRuntime(helper, { repoRoot, changeId, mainSha, admission });
    assert.equal(sealed.receipt.schema, REVIEW_RECEIPT_SCHEMA);
  });
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "generic-v1-shape-missing-admission";
    boundChange(repoRoot, changeId);
    const payload = runtimeAgentPayload(helper, { repoRoot, changeId, mainSha, findings: [] });
    bindReceiptAuthority(helper, { repoRoot, changeId, reviewerPayload: payload });
    payload.review_authority = {
      kind: "runtime-admission",
      intent_ref: { intent_id: "00000000-0000-4000-8000-000000000000", digest_sha256: DIGEST_A },
    };
    const receipt = {
      schema: REVIEW_RECEIPT_SCHEMA,
      receipt_digest_sha256: sha256(helper.canonicalJsonV1(payload)),
      observation_hashes: receiptObservationHashes(helper, payload.findings),
      reviewer_payload: payload,
    };
    const ref = writeReceiptEnvelope(
      helper,
      evidencePath(repoRoot, `review-${changeId}-receipt-r1-${payload.dispatch_id}.json`),
      receipt,
    );
    assert.throws(
      () => helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: ref }),
      /receipt-authority-missing/u,
      "an authority with intent_ref but no admission_ref is a candidate shape missing a key",
    );
  });
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "generic-v1-shape-unknown-key";
    boundChange(repoRoot, changeId);
    const admission = genericV1AdmissionFixture({ repoRoot, changeId });
    const payload = runtimeAgentPayload(helper, { repoRoot, changeId, mainSha, findings: [] });
    bindReceiptAuthority(helper, { repoRoot, changeId, reviewerPayload: payload });
    payload.review_authority = {
      ...genericV1OnePieceAuthority(admission),
      witness: true,
    };
    assert.throws(
      () => helper.sealReviewRoundReceipt({ repoRoot, changeId, reviewerPayload: payload, admissionRecordId: admission.record_id }),
      /receipt-authority-mixed/u,
      "an unknown key beside a one-piece authority is a mixed shape, never silently dropped",
    );
  });
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "generic-v1-shape-mixed-two-piece";
    boundChange(repoRoot, changeId);
    const admission = genericV1AdmissionFixture({ repoRoot, changeId });
    const payload = runtimeAgentPayload(helper, { repoRoot, changeId, mainSha, findings: [] });
    bindReceiptAuthority(helper, { repoRoot, changeId, reviewerPayload: payload });
    payload.review_authority = {
      kind: "runtime-admission",
      intent_ref: { intent_id: "00000000-0000-4000-8000-000000000000", digest_sha256: DIGEST_A },
      admission_ref: { record_id: admission.record_id, digest_sha256: admission.digest },
      witness: true,
    };
    assert.throws(
      () => helper.sealReviewRoundReceipt({ repoRoot, changeId, reviewerPayload: payload, admissionRecordId: admission.record_id }),
      /receipt-authority-mixed/u,
      "an unknown key beside a two-piece authority keeps its existing mixed token",
    );
  });
  // F-frgh-r1-01: the two illegal cross quadrants of the shape matrix. Each
  // pins one of the two schema-first guards in validateV3NormalAuthority:
  // a v2 record with no intent_ref (core guard: intentRef === undefined) and
  // a v1 record carrying an intent_ref (core guard: intentRef !== undefined).
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "generic-v1-shape-cross-v2-one-piece";
    boundChange(repoRoot, changeId);
    const admission = preparedRuntimeAdmissionFixture({ repoRoot, changeId });
    const payload = runtimeAgentPayload(helper, { repoRoot, changeId, mainSha, findings: [] });
    bindReceiptAuthority(helper, { repoRoot, changeId, reviewerPayload: payload });
    payload.review_authority = {
      kind: "runtime-admission",
      admission_ref: { record_id: admission.record_id, digest_sha256: admission.digest },
    };
    // Without the guard the v2 branch dereferences intentRef.intent_id on
    // undefined and throws a TypeError out of the closed-token contract; the
    // guard must return receipt-identity-authority-mismatch instead.
    assert.throws(
      () => helper.sealReviewRoundReceipt({ repoRoot, changeId, reviewerPayload: payload, admissionRecordId: admission.record_id }),
      /receipt-identity-authority-mismatch/u,
      "a v2 record with a one-piece authority must fail closed, never TypeError out of the token contract",
    );
    const receipt = {
      schema: REVIEW_RECEIPT_SCHEMA,
      receipt_digest_sha256: sha256(helper.canonicalJsonV1(payload)),
      observation_hashes: receiptObservationHashes(helper, payload.findings),
      reviewer_payload: payload,
    };
    const ref = writeReceiptEnvelope(
      helper,
      evidencePath(repoRoot, `review-${changeId}-receipt-r1-${payload.dispatch_id}.json`),
      receipt,
    );
    assert.throws(
      () => helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: ref, requireIndependence: true }),
      /receipt-identity-authority-mismatch/u,
      "the verify side reads back through the same guard and must return the same closed token",
    );
  });
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "generic-v1-shape-cross-v1-two-piece";
    boundChange(repoRoot, changeId);
    const admission = genericV1AdmissionFixture({ repoRoot, changeId });
    const payload = runtimeAgentPayload(helper, { repoRoot, changeId, mainSha, findings: [] });
    bindReceiptAuthority(helper, { repoRoot, changeId, reviewerPayload: payload });
    payload.review_authority = {
      kind: "runtime-admission",
      intent_ref: { intent_id: "00000000-0000-4000-8000-000000000000", digest_sha256: DIGEST_A },
      admission_ref: { record_id: admission.record_id, digest_sha256: admission.digest },
    };
    // Without the guard the v1 branch passes content-to-ID (digest and fields
    // all match) and the unverified intent_ref silently enters the sealed
    // receipt; the guard must refuse before any claim is taken.
    assert.throws(
      () => helper.sealReviewRoundReceipt({ repoRoot, changeId, reviewerPayload: payload, admissionRecordId: admission.record_id }),
      /receipt-identity-authority-mismatch/u,
      "an unverified intent_ref beside a v1 record must not silently enter the sealed authority",
    );
    const receipt = {
      schema: REVIEW_RECEIPT_SCHEMA,
      receipt_digest_sha256: sha256(helper.canonicalJsonV1(payload)),
      observation_hashes: receiptObservationHashes(helper, payload.findings),
      reviewer_payload: payload,
    };
    const ref = writeReceiptEnvelope(
      helper,
      evidencePath(repoRoot, `review-${changeId}-receipt-r1-${payload.dispatch_id}.json`),
      receipt,
    );
    assert.throws(
      () => helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: ref, requireIndependence: true }),
      /receipt-identity-authority-mismatch/u,
      "the verify side must not accept an intent_ref a v1 record cannot bind",
    );
  });
});

test("generic v1 content mismatch: record fields that disagree with the payload fail content-to-ID (generic v1 content mismatch)", () => {
  const helper = api();
  const mutations = [
    ["change-id", (record) => { record.change_id = "generic-v1-other-change"; }],
    ["head-sha", (record) => { record.head_sha = "0".repeat(40); }],
    ["responsibility-id", (record) => { record.responsibility_id = "secondary-review"; }],
    ["role", (record) => { record.role = "dp-analyst"; }],
  ];
  for (const [name, mutate] of mutations) {
    withRepo(({ repoRoot, mainSha }) => {
      const changeId = `generic-v1-content-${name}`;
      boundChange(repoRoot, changeId);
      const admission = genericV1AdmissionFixture({ repoRoot, changeId });
      const syncedDigest = rewriteGenericV1Record(repoRoot, changeId, admission.record_id, mutate);
      const payload = runtimeAgentPayload(helper, { repoRoot, changeId, mainSha, findings: [] });
      bindReceiptAuthority(helper, { repoRoot, changeId, reviewerPayload: payload });
      payload.review_authority = {
        kind: "runtime-admission",
        admission_ref: { record_id: admission.record_id, digest_sha256: syncedDigest },
      };
      assert.throws(
        () => helper.sealReviewRoundReceipt({ repoRoot, changeId, reviewerPayload: payload, admissionRecordId: admission.record_id }),
        /receipt-identity-authority-mismatch/u,
        `${name}: a synced ref digest must not rescue content that disagrees with the payload`,
      );
    });
  }
});

test("generic v1 role binding: a host-verified dp-reviewer v1 record seals while cooperative-only and non-dp-reviewer records cannot (generic v1 role binding)", () => {
  const helper = api();
  // Discriminator prelude: the exact same builder route over a host-verified
  // dp-reviewer record must seal. Without it this group would pass vacuously
  // against an implementation that rejects every v1 record.
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "generic-v1-role-binding-baseline";
    boundChange(repoRoot, changeId);
    const admission = genericV1AdmissionFixture({ repoRoot, changeId });
    const payload = runtimeAgentPayload(helper, { repoRoot, changeId, mainSha, findings: [] });
    const rawPayloadRef = writeGenericV1RawPayload(helper, { repoRoot, payload });
    const built = helper.buildReviewRoundReceiptRequest({
      repoRoot,
      changeId,
      rawPayloadRef,
      admissionRecordId: admission.record_id,
    });
    assert.deepEqual(built.reviewerPayload.review_authority, genericV1OnePieceAuthority(admission));
    const sealed = helper.sealReviewRoundReceipt(built);
    assert.equal(sealed.receipt.schema, REVIEW_RECEIPT_SCHEMA);
  });
  for (const [name, options] of [
    ["cooperative-only", { roleBinding: "cooperative-only" }],
    ["wrong-role", { role: "dp-analyst" }],
  ]) {
    withRepo(({ repoRoot, mainSha }) => {
      const changeId = `generic-v1-role-binding-${name}`;
      boundChange(repoRoot, changeId);
      const admission = genericV1AdmissionFixture({ repoRoot, changeId }, options);
      const payload = runtimeAgentPayload(helper, { repoRoot, changeId, mainSha, findings: [] });
      const rawPayloadRef = writeGenericV1RawPayload(helper, { repoRoot, payload });
      assert.throws(
        () => helper.buildReviewRoundReceiptRequest({
          repoRoot,
          changeId,
          rawPayloadRef,
          admissionRecordId: admission.record_id,
        }),
        /receipt-identity-authority-mismatch/u,
        `${name}: the builder must reject the record before deriving any authority`,
      );
    });
  }
});

