test("generic v1 tamper: stale and synced digest rewrites stay fail closed for seal and verify (generic v1 tamper)", () => {
  const helper = api();
  const mutations = [
    ["role", (record) => { record.role = "dp-analyst"; }],
    ["role-binding", (record) => { record.role_binding = "cooperative-only"; }],
    ["head-sha", (record) => { record.head_sha = "0".repeat(40); }],
  ];
  for (const [name, mutate] of mutations) {
    withRepo(({ repoRoot, mainSha }) => {
      const changeId = `generic-v1-tamper-${name}`;
      boundChange(repoRoot, changeId);
      const admission = genericV1AdmissionFixture({ repoRoot, changeId });
      const payload = runtimeAgentPayload(helper, { repoRoot, changeId, mainSha, findings: [] });
      bindReceiptAuthority(helper, { repoRoot, changeId, reviewerPayload: payload });
      payload.review_authority = genericV1OnePieceAuthority(admission);
      const sealed = helper.sealReviewRoundReceipt({
        repoRoot,
        changeId,
        reviewerPayload: payload,
        admissionRecordId: admission.record_id,
      });
      assert.equal(
        helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: sealed.ref, requireIndependence: true }).executor_attribution,
        "runtime-agent",
      );
      // FR5 half one: the record file is rewritten but the receipt still
      // carries the pre-rewrite digest. The digest check fails first, before
      // any field comparison.
      const staleDigest = rewriteGenericV1Record(repoRoot, changeId, admission.record_id, mutate);
      assert.notEqual(staleDigest, admission.digest, `${name}: the rewrite must actually change the record bytes`);
      assert.throws(
        () => helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: sealed.ref, requireIndependence: true }),
        /receipt-identity-authority-mismatch/u,
        `${name}: a stale ref digest must fail verification before any field check`,
      );
      // FR5 half two: the receipt's ref digest is synced to the rewritten
      // bytes, but the content no longer matches the payload — still refused.
      const tamperedPayload = clone(sealed.receipt.reviewer_payload);
      tamperedPayload.review_authority.admission_ref.digest_sha256 = staleDigest;
      const tamperedReceipt = resignReceiptEnvelope(helper, {
        ...clone(sealed.receipt),
        reviewer_payload: tamperedPayload,
      });
      const tamperedPath = receiptTarget(repoRoot, changeId, tamperedPayload.round_number, tamperedPayload.dispatch_id);
      const tamperedRef = writeReceiptEnvelope(helper, tamperedPath, tamperedReceipt);
      assert.throws(
        () => helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: tamperedRef, requireIndependence: true }),
        /receipt-identity-authority-mismatch/u,
        `${name}: a synced ref digest must not rescue content that disagrees with the payload`,
      );
    });
  }
});

test("origin/main tip homology: stale local main, shadowing, and nested tag fail-closed (fix-resolved-main-origin-authority T1)", async (t) => {
  const helper = api();
  const coreSource = readFileSync(CORE_PATH, "utf8");
  const resolvedMainSrc = sourceFunctionSlice(coreSource, "resolvedMain", "riskFsOps");
  assert.match(
    resolvedMainSrc,
    /show-ref[\s\S]*--verify[\s\S]*refs\/remotes\/origin\/main/,
    "resolvedMain tip SSOT must be show-ref --verify of refs/remotes/origin/main",
  );
  assert.doesNotMatch(resolvedMainSrc, /rev-parse",\s*"main"/, "resolvedMain must not fall back to rev-parse main");
  assert.doesNotMatch(resolvedMainSrc, /rev-parse",\s*"origin\/main"/, "resolvedMain must not use bare origin/main");
  assert.doesNotMatch(
    resolvedMainSrc,
    /rev-parse",\s*"refs\/remotes\/origin\/main"/,
    "resolvedMain must not use rev-parse of the remote-tracking path as tip SSOT",
  );

  await t.test("origin/main tip homology: local main behind remote tip still seals", () => {
    withRepo(({ repoRoot, mainSha }) => {
      const changeId = "resolved-main-stale-local";
      // This fixture tests ref-tip authority, not execute-bit drift. NTFS
      // materializes the 100755 oracle files without +x during rebase.
      if (process.platform === "win32") git(repoRoot, ["config", "core.filemode", "false"]);
      const featureBranch = git(repoRoot, ["branch", "--show-current"]);
      git(repoRoot, ["checkout", "--quiet", "main"]);
      write(repoRoot, "src/remote-ahead.txt", "remote tip\n");
      const remoteTip = commitAll(repoRoot, "advance remote tip while local main stays behind");
      syncOriginMain(repoRoot, remoteTip);
      git(repoRoot, ["checkout", "--quiet", featureBranch]);
      git(repoRoot, ["rebase", remoteTip]);
      // Force local main behind after the feature rebase so the worktree stays clean.
      git(repoRoot, ["branch", "-f", "main", mainSha]);
      assert.equal(git(repoRoot, ["rev-parse", "main"]), mainSha, "local main stays behind");
      assert.equal(git(repoRoot, ["show-ref", "--verify", "--hash", "refs/remotes/origin/main"]), remoteTip);
      assert.notEqual(mainSha, remoteTip);

      writeFullRiskChange(repoRoot, changeId);
      commitAll(repoRoot, "risk for stale-local tip homology");
      const alignedHead = git(repoRoot, ["rev-parse", "HEAD"]);
      const expectedBase = git(repoRoot, ["merge-base", remoteTip, alignedHead]);
      assert.equal(expectedBase, remoteTip, "HEAD descends from remote tip");

      const dispatch = initialClassification(helper, { repoRoot, changeId });
      assertDispatchableResult(dispatch, { route: "full", count: 0, round: 1, reason: "initial_review" });
      const sealed = sealReceipt(helper, {
        repoRoot,
        changeId,
        reviewerPayload: payloadFromDispatch(dispatch, {
          changeId,
          baseSha: expectedBase,
          mergeBaseSha: expectedBase,
          headSha: alignedHead,
          findings: [],
        }),
      });
      assert.equal(sealed.receipt.reviewer_payload.lineage.base_sha, expectedBase);
      assert.equal(sealed.receipt.reviewer_payload.lineage.merge_base_sha, expectedBase);
      assert.doesNotThrow(() => helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: sealed.ref }));
    });
  });

  await t.test("show-ref verify: shadowing tag or branch origin/main does not replace remote tip", () => {
    withRepo(({ repoRoot, mainSha }) => {
      const changeId = "resolved-main-shadow-present";
      write(repoRoot, "src/shadow-tip.txt", "shadow other commit\n");
      const shadowSha = commitAll(repoRoot, "shadow tip commit");
      // Restore feature tip to the template main lineage for authority binding.
      git(repoRoot, ["reset", "--quiet", "--hard", mainSha]);
      git(repoRoot, ["tag", "origin/main", shadowSha]);
      git(repoRoot, ["branch", "refs-origin-main-shadow", shadowSha]);
      // Also plant a local branch literally named origin/main via update-ref.
      git(repoRoot, ["update-ref", "refs/heads/origin/main", shadowSha]);
      assert.equal(git(repoRoot, ["show-ref", "--verify", "--hash", "refs/remotes/origin/main"]), mainSha);

      writeFullRiskChange(repoRoot, changeId);
      commitAll(repoRoot, "risk with shadowing origin/main present");
      const headSha = git(repoRoot, ["rev-parse", "HEAD"]);
      const expectedBase = git(repoRoot, ["merge-base", mainSha, headSha]);
      const dispatch = initialClassification(helper, { repoRoot, changeId });
      const sealed = sealReceipt(helper, {
        repoRoot,
        changeId,
        reviewerPayload: payloadFromDispatch(dispatch, {
          changeId,
          baseSha: expectedBase,
          mergeBaseSha: expectedBase,
          headSha,
          findings: [],
        }),
      });
      assert.equal(sealed.receipt.reviewer_payload.lineage.base_sha, expectedBase);
      assert.notEqual(sealed.receipt.reviewer_payload.lineage.base_sha, shadowSha);
    });

    withRepo(({ repoRoot, mainSha }) => {
      write(repoRoot, "src/shadow-only.txt", "shadow only\n");
      const shadowSha = commitAll(repoRoot, "shadow without remote-tracking");
      git(repoRoot, ["update-ref", "-d", "refs/remotes/origin/main"]);
      git(repoRoot, ["tag", "origin/main", shadowSha]);
      git(repoRoot, ["update-ref", "refs/heads/origin/main", shadowSha]);
      assert.equal(git(repoRoot, ["rev-parse", "main"]), mainSha);
      const classified = helper.classifyBoundedRereview({
        repoRoot,
        changeId: "resolved-main-shadow-absent",
        previousReceiptRef: null,
        repairDeltaManifestRef: null,
        dependencyClosureManifestRef: null,
        predecessorMatches: [],
      });
      assert.equal(classified.route, "risk_shape_unavailable");
      assert.equal(classified.risk_shape_debug_reason, "request_or_git_authority_invalid");
    });
  });

  await t.test("nested tag refs/tags/refs/remotes/origin/main does not satisfy missing remote-tracking tip", () => {
    withRepo(({ repoRoot, mainSha }) => {
      write(repoRoot, "src/nested-tag.txt", "nested\n");
      const nestedSha = commitAll(repoRoot, "nested tag commit");
      git(repoRoot, ["update-ref", "-d", "refs/remotes/origin/main"]);
      git(repoRoot, ["update-ref", "refs/tags/refs/remotes/origin/main", nestedSha]);
      // rev-parse may still resolve the nested tag path; show-ref --verify must not.
      assert.equal(git(repoRoot, ["rev-parse", "refs/remotes/origin/main"]), nestedSha);
      assert.throws(
        () => git(repoRoot, ["show-ref", "--verify", "--hash", "refs/remotes/origin/main"]),
        /refs\/remotes\/origin\/main|not a valid ref/i,
      );
      const classified = helper.classifyBoundedRereview({
        repoRoot,
        changeId: "resolved-main-nested-tag",
        previousReceiptRef: null,
        repairDeltaManifestRef: null,
        dependencyClosureManifestRef: null,
        predecessorMatches: [],
      });
      assert.equal(classified.route, "risk_shape_unavailable");
      assert.equal(classified.risk_shape_debug_reason, "request_or_git_authority_invalid");
      assert.notEqual(git(repoRoot, ["rev-parse", "main"]), nestedSha);
    });
  });
});

test("historical walkReceiptAuthorityChain and cross-tip continuation after tip SSOT switch (fix-resolved-main-origin-authority T2)", async (t) => {
  const helper = api();

  await t.test("historical sealed chain stays walkable after tip source switch", () => {
    withRepo(({ repoRoot, mainSha }) => {
      const changeId = "resolved-main-historical-walk";
      writeFullRiskChange(repoRoot, changeId);
      commitAll(repoRoot, "historical walk baseline");
      const { payload } = initialPayloadFromDispatch(helper, { repoRoot, changeId, mainSha, findings: [] });
      const initial = sealReceipt(helper, { repoRoot, changeId, reviewerPayload: payload });
      assert.deepEqual(helper.queryReviewStallState({ repoRoot, changeId }), { state: "ok", streak: 0 });

      // Switch tip SSOT forward without rewriting the sealed receipt lineage.
      const featureBranch = git(repoRoot, ["branch", "--show-current"]);
      git(repoRoot, ["checkout", "--quiet", "main"]);
      write(repoRoot, "src/tip-switch.txt", "new tip\n");
      const newTip = commitAll(repoRoot, "switch remote tip after seal");
      syncOriginMain(repoRoot, newTip);
      git(repoRoot, ["checkout", "--quiet", featureBranch]);

      assert.deepEqual(
        helper.queryReviewStallState({ repoRoot, changeId }),
        { state: "ok", streak: 0 },
        "walkReceiptAuthorityChain must use stored lineage and ignore tip SSOT switch",
      );
      assert.equal(initial.receipt.reviewer_payload.lineage.base_sha, mainSha);
    });
  });

  function withForwardReanchor(run, { upstreamPath = "openspec/changes/upstream/tasks.md", executablePaths = [], independentBase = false, beforeBase = null, advanceBase = null, advanceTwice = false, beforeReview = null } = {}) {
    withRepo(({ repoRoot, mainSha }) => {
      if (beforeBase !== null) {
        const branch = git(repoRoot, ["branch", "--show-current"]);
        git(repoRoot, ["checkout", "--quiet", "main"]);
        beforeBase(repoRoot);
        if (upstreamPath?.startsWith("notes/")) git(repoRoot, ["add", "-f", "--", upstreamPath]);
        mainSha = commitAll(repoRoot, "seed upstream bookkeeping");
        syncOriginMain(repoRoot, mainSha);
        git(repoRoot, ["checkout", "--quiet", branch]);
        git(repoRoot, ["merge", "--ff-only", "--quiet", mainSha]);
      }
      const changeId = "equivalent-reanchor";
      writeFullRiskChange(repoRoot, changeId);
      if (beforeReview !== null) beforeReview(repoRoot);
      commitAll(repoRoot, "reviewed reanchor baseline");
      const initial = sealInitial(helper, { repoRoot, changeId, mainSha, findings: openFindings(2) });
      const previousHead = initial.receipt.reviewer_payload.lineage.head_sha;
      const featureBranch = git(repoRoot, ["branch", "--show-current"]);
      git(repoRoot, ["checkout", "--quiet", "main"]);
      const preparedBase = advanceBase === null ? null : advanceBase(repoRoot);
      if (advanceBase === null && upstreamPath !== null) write(repoRoot, upstreamPath, "upstream change\n");
      let newBase;
      if (typeof preparedBase === "string") {
        newBase = preparedBase;
      } else if (independentBase) {
        git(repoRoot, ["add", "-A"]);
        const tree = git(repoRoot, ["write-tree"]);
        newBase = git(repoRoot, ["commit-tree", tree, "-m", "independent base with equal review-bearing tree"]);
        git(repoRoot, ["reset", "--hard", newBase]);
      } else if (upstreamPath === null) {
        git(repoRoot, ["commit", "--quiet", "--allow-empty", "-m", "empty forward base"]);
        newBase = git(repoRoot, ["rev-parse", "HEAD"]);
      } else {
        if (upstreamPath?.startsWith("notes/")) git(repoRoot, ["add", "-f", "-A", "--", upstreamPath]);
        for (const relativePath of executablePaths) chmodSync(path.join(repoRoot, relativePath), 0o755);
        newBase = commitAll(repoRoot, "advance reanchor base", { executablePaths });
      }
      const intermediateBase = newBase;
      if (advanceTwice) {
        git(repoRoot, ["commit", "--quiet", "--allow-empty", "-m", "second forward base"]);
        newBase = git(repoRoot, ["rev-parse", "HEAD"]);
      }
      syncOriginMain(repoRoot, newBase);
      git(repoRoot, ["checkout", "--quiet", featureBranch]);
      git(repoRoot, ["rebase", "--onto", newBase, mainSha]);
      const candidateHead = git(repoRoot, ["rev-parse", "HEAD"]);
      assert.equal(spawnSync("git", ["merge-base", "--is-ancestor", previousHead, candidateHead], { cwd: repoRoot }).status, 1);
      const rangeDiff = git(repoRoot, ["range-diff", "--no-color", `${mainSha}..${previousHead}`, `${newBase}..${candidateHead}`]);
      assert.match(rangeDiff, / = /, "same patch is only human context; the upstream tree still needs verification");
      run({ repoRoot, changeId, mainSha, initial, previousHead, newBase, intermediateBase, candidateHead });
    });
  }

  await t.test("equivalent forward reanchor seals current manifests and bounded receipt; historical verification replays the proof", () => {
    withForwardReanchor(({ repoRoot, changeId, initial, previousHead, newBase, candidateHead }) => {
      const manifests = sealRoundManifests(helper, { repoRoot, changeId, roundNumber: 2, mainSha: newBase, surfaceBaseSha: previousHead, candidateHeadSha: candidateHead });
      const classified = classifyBounded(helper, { repoRoot, changeId, previousReceipt: initial, repairManifest: manifests.repair, closureManifest: manifests.closure });
      assertDispatchableResult(classified, { route: "bounded", count: 1, round: 2, reason: null });
      const bounded = sealBoundedRound(helper, { repoRoot, changeId, roundNumber: 2, boundedCount: 1, mainSha: newBase, previousReceipt: initial, manifests });
      assert.equal(bounded.receipt.reviewer_payload.lineage.base_sha, newBase);
      assert.deepEqual(bounded.receipt.reviewer_payload.lineage.previous_receipt_ref, initial.ref);
      assert.deepEqual(helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: bounded.ref }).receipt, bounded.receipt);
      assert.throws(() => helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: bounded.ref, requireIndependence: true }), /ordinary-review-not-independent/);
      write(repoRoot, "openspec/changes/upstream/tasks.md", "bookkeeping after seal\n");
      const movedBase = commitAll(repoRoot, "bookkeeping after seal");
      syncOriginMain(repoRoot, movedBase);
      assert.equal(helper.queryReviewStallState({ repoRoot, changeId }).state, "ok", "historical chain proof binds its recorded objects, not a moving main tip");
    });
  });

  for (const status of ["A", "M", "D"]) {
    const upstreamPath = "notes/reanchor-bookkeeping.md";
    await t.test(`regular notes Markdown ${status} remains bounded`, () => {
      withForwardReanchor(({ repoRoot, changeId, initial, previousHead, newBase, candidateHead }) => {
        const manifests = sealRoundManifests(helper, { repoRoot, changeId, roundNumber: 2, mainSha: newBase, surfaceBaseSha: previousHead, candidateHeadSha: candidateHead });
        assertDispatchableResult(classifyBounded(helper, { repoRoot, changeId, previousReceipt: initial, repairManifest: manifests.repair, closureManifest: manifests.closure }), { route: "bounded", count: 1, round: 2, reason: null });
      }, { upstreamPath, beforeBase: status === "A" ? null : (repoRoot) => write(repoRoot, upstreamPath, "prior bookkeeping\n"), advanceBase: status === "D" ? (repoRoot) => unlinkSync(path.join(repoRoot, upstreamPath)) : null });
    });
  }

  for (const kind of ["symlink", "gitlink"]) {
    await t.test(`${kind} inside bookkeeping whitelist still requires full review`, () => {
      withForwardReanchor(({ repoRoot, changeId, initial }) => {
        const result = helper.classifyBoundedRereview({ repoRoot, changeId, previousReceiptRef: initial.ref, repairDeltaManifestRef: null, dependencyClosureManifestRef: null, predecessorMatches: predecessorMatches(initial.receipt) });
        assertDispatchableResult(result, { route: "full", count: 0, round: 2, reason: "git_lineage_changed" });
      }, { upstreamPath: "notes/not-regular.md", advanceBase: (repoRoot) => {
        if (kind === "symlink") symlinkSync("../README.md", path.join(repoRoot, "notes/not-regular.md"));
        else {
          git(repoRoot, ["update-index", "--add", "--cacheinfo", `160000,${git(repoRoot, ["rev-parse", "HEAD"])},notes/not-regular.md`]);
          git(repoRoot, ["commit", "--quiet", "-m", "upstream gitlink"]);
          return git(repoRoot, ["rev-parse", "HEAD"]);
        }
      } });
    });
  }

  await t.test("intermediate forward base is not current manifest authority", () => {
    withForwardReanchor(({ repoRoot, changeId, initial, previousHead, newBase, intermediateBase, candidateHead }) => {
      assert.notEqual(intermediateBase, newBase);
      const manifests = sealRoundManifests(helper, { repoRoot, changeId, roundNumber: 2, mainSha: intermediateBase, surfaceBaseSha: previousHead, candidateHeadSha: candidateHead });
      const result = classifyBounded(helper, { repoRoot, changeId, previousReceipt: initial, repairManifest: manifests.repair, closureManifest: manifests.closure });
      assert.equal(result.route, "full_reopen_required");
      assert.equal(result.full_reopen_debug_reason, "bounded_input_invalid", "current-base predicate rejects before the generic manifest verification phase");
      assert.equal(result.dispatch_id, undefined);
    }, { advanceTwice: true, beforeReview: (repoRoot) => seedValidatorTrustSurface(repoRoot) });
  });

  await t.test("pruned predecessor Git objects cannot verify an equivalent reanchor receipt", () => {
    withForwardReanchor(({ repoRoot, changeId, initial, previousHead, newBase, candidateHead }) => {
      const manifests = sealRoundManifests(helper, { repoRoot, changeId, roundNumber: 2, mainSha: newBase, surfaceBaseSha: previousHead, candidateHeadSha: candidateHead });
      const bounded = sealBoundedRound(helper, { repoRoot, changeId, roundNumber: 2, boundedCount: 1, mainSha: newBase, previousReceipt: initial, manifests });
      assert.doesNotThrow(() => helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: bounded.ref }));
      git(repoRoot, ["reflog", "expire", "--expire=now", "--all"]);
      git(repoRoot, ["prune", "--expire", "now"]);
      assert.notEqual(spawnSync("git", ["cat-file", "-t", previousHead], { cwd: repoRoot }).status, 0);
      assert.throws(() => helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: bounded.ref }));
    });
  });

  await t.test("equivalent reanchor with null manifests has no dispatch authority", () => {
    withForwardReanchor(({ repoRoot, changeId, initial }) => {
      const result = helper.classifyBoundedRereview({ repoRoot, changeId, previousReceiptRef: initial.ref, repairDeltaManifestRef: null, dependencyClosureManifestRef: null, predecessorMatches: predecessorMatches(initial.receipt) });
      assert.equal(result.route, "full_reopen_required");
      assert.equal(result.full_reopen_debug_reason, "manifest_refs_absent");
      assert.equal(result.dispatch_id, undefined, "diagnostic-only route is not dispatch authority");
    });
  });

  await t.test("equal whole trees qualify but dropped predecessor findings remain blocked", () => {
    withForwardReanchor(({ repoRoot, changeId, initial, previousHead, newBase, candidateHead }) => {
      assert.equal(git(repoRoot, ["rev-parse", `${previousHead}^{tree}`]), git(repoRoot, ["rev-parse", `${candidateHead}^{tree}`]));
      const manifests = sealRoundManifests(helper, { repoRoot, changeId, roundNumber: 2, mainSha: newBase, surfaceBaseSha: previousHead, candidateHeadSha: candidateHead });
      const result = classifyBounded(helper, { repoRoot, changeId, previousReceipt: initial, repairManifest: manifests.repair, closureManifest: manifests.closure });
      assertDispatchableResult(result, { route: "bounded", count: 1, round: 2, reason: null });
      assert.throws(() => sealBoundedRound(helper, { repoRoot, changeId, roundNumber: 2, boundedCount: 1, mainSha: newBase, previousReceipt: initial, manifests, findings: [initial.receipt.reviewer_payload.findings[0]] }), /predecessor-finding-omitted/);
    }, { upstreamPath: null });
  });

  await t.test("executable Markdown bookkeeping does not qualify", () => {
    withForwardReanchor(({ repoRoot, changeId, initial }) => {
      const result = helper.classifyBoundedRereview({ repoRoot, changeId, previousReceiptRef: initial.ref, repairDeltaManifestRef: null, dependencyClosureManifestRef: null, predecessorMatches: predecessorMatches(initial.receipt) });
      assertDispatchableResult(result, { route: "full", count: 0, round: 2, reason: "git_lineage_changed" });
    }, { executablePaths: ["openspec/changes/upstream/tasks.md"] });
  });

  await t.test("equal review-bearing content with an unrelated new base does not qualify", () => {
    withForwardReanchor(({ repoRoot, changeId, initial }) => {
      const result = helper.classifyBoundedRereview({ repoRoot, changeId, previousReceiptRef: initial.ref, repairDeltaManifestRef: null, dependencyClosureManifestRef: null, predecessorMatches: predecessorMatches(initial.receipt) });
      assertDispatchableResult(result, { route: "full", count: 0, round: 2, reason: "git_lineage_changed" });
    }, { independentBase: true });
  });

  await t.test("changed behavior risk in an otherwise equivalent reanchor stays full", () => {
    withForwardReanchor(({ repoRoot, changeId, initial }) => {
      writeFullRiskChange(repoRoot, changeId, { proposal: { touchRow: "| `src/second-target.mjs` | code | modify | R2 |" } });
      commitAll(repoRoot, "selected behavior risk change");
      const result = helper.classifyBoundedRereview({ repoRoot, changeId, previousReceiptRef: initial.ref, repairDeltaManifestRef: null, dependencyClosureManifestRef: null, predecessorMatches: predecessorMatches(initial.receipt) });
      assertDispatchableResult(result, { route: "full", count: 0, round: 2, reason: "git_lineage_changed" });
    });
  });

  await t.test("unavailable tree comparison never narrows reanchor review", () => {
    withForwardReanchor(({ repoRoot, changeId, initial }) => {
      const original = childProcess.execFileSync;
      childProcess.execFileSync = function(command, args, options) {
        if (command === "git" && args[0] === "diff" && args.includes("--raw")) throw new Error("unavailable comparison fixture");
        return original.call(this, command, args, options);
      };
      syncBuiltinESMExports();
      try {
        const result = helper.classifyBoundedRereview({ repoRoot, changeId, previousReceiptRef: initial.ref, repairDeltaManifestRef: null, dependencyClosureManifestRef: null, predecessorMatches: predecessorMatches(initial.receipt) });
        assertDispatchableResult(result, { route: "full", count: 0, round: 2, reason: "git_lineage_changed" });
      } finally {
        childProcess.execFileSync = original;
        syncBuiltinESMExports();
      }
    });
  });

  for (const upstreamPath of ["src/unlisted-runtime.mjs", "config/runtime.json", "src/runtime.test.mjs", ".devpro/agent-rules/unlisted.md", "openspec/specs/unlisted/spec.md", "openspec/changes/upstream/specs/feature/spec.md", "openspec/changes/upstream/tool.mjs", "README.md"]) {
    await t.test(`same-patch reanchor still reopens full for changed ${upstreamPath}`, () => {
      withForwardReanchor(({ repoRoot, changeId, initial }) => {
        const result = helper.classifyBoundedRereview({ repoRoot, changeId, previousReceiptRef: initial.ref, repairDeltaManifestRef: null, dependencyClosureManifestRef: null, predecessorMatches: predecessorMatches(initial.receipt) });
        assertDispatchableResult(result, { route: "full", count: 0, round: 2, reason: "git_lineage_changed" });
      }, { upstreamPath });
    });
  }

  await t.test("non-equivalent cross-tip bounded fails; full-review successor allowed", () => {
    withRepo(({ repoRoot, mainSha }) => {
      const changeId = "resolved-main-cross-tip";
      writeFullRiskChange(repoRoot, changeId);
      commitAll(repoRoot, "cross-tip baseline");
      const { payload } = initialPayloadFromDispatch(helper, { repoRoot, changeId, mainSha, findings: openFindings(2) });
      const initial = sealReceipt(helper, { repoRoot, changeId, reviewerPayload: payload });
      const previousHead = initial.receipt.reviewer_payload.lineage.head_sha;
      const featureBranch = git(repoRoot, ["branch", "--show-current"]);

      git(repoRoot, ["checkout", "--quiet", "main"]);
      write(repoRoot, "src/cross-tip.txt", "cross tip\n");
      const advancedMain = commitAll(repoRoot, "advance tip for cross-lineage");
      syncOriginMain(repoRoot, advancedMain);
      git(repoRoot, ["checkout", "--quiet", featureBranch]);
      // Merge (not rebase) so the prior reviewed HEAD remains an ancestor of the
      // candidate while the receipt base moves to the new remote tip. This
      // review-bearing upstream change is non-equivalent and still needs full.
      git(repoRoot, ["merge", "--quiet", "--no-edit", advancedMain]);
      const mergedHead = git(repoRoot, ["rev-parse", "HEAD"]);
      assert.equal(git(repoRoot, ["merge-base", previousHead, mergedHead]), previousHead);

      const manifests = sealRoundManifests(helper, {
        repoRoot,
        changeId,
        roundNumber: 2,
        mainSha: advancedMain,
        surfaceBaseSha: previousHead,
        candidateHeadSha: mergedHead,
      });

      assert.throws(
        () => sealReceipt(helper, {
          repoRoot,
          changeId,
          reviewerPayload: receiptPayload({
            changeId,
            reviewMode: "bounded",
            roundNumber: 2,
            boundedCount: 1,
            baseSha: advancedMain,
            mergeBaseSha: advancedMain,
            headSha: mergedHead,
            previousReceiptRef: initial.ref,
            initialFullReceiptDigestSha256: initial.ref.digest_sha256,
            repairManifestRef: manifests.repair.ref,
            closureManifestRef: manifests.closure.ref,
            findings: shrinkingFindings(2, 1),
          }),
        }),
        /only a full-review successor may cross a changed Git lineage/,
      );

      const reopened = helper.classifyBoundedRereview({
        repoRoot,
        changeId,
        previousReceiptRef: initial.ref,
        repairDeltaManifestRef: null,
        dependencyClosureManifestRef: null,
        predecessorMatches: [],
      });
      assertDispatchableResult(reopened, {
        route: "full",
        count: 0,
        round: 2,
        reason: "git_lineage_changed",
      });
      const successor = sealReceipt(helper, {
        repoRoot,
        changeId,
        reviewerPayload: payloadFromDispatch(reopened, {
          changeId,
          reviewMode: "full",
          roundNumber: 2,
          boundedCount: 0,
          baseSha: advancedMain,
          mergeBaseSha: advancedMain,
          headSha: mergedHead,
          previousReceiptRef: initial.ref,
          initialFullReceiptDigestSha256: initial.ref.digest_sha256,
          findings: convergeFindings(initial.receipt.reviewer_payload.findings, []),
        }),
      });
      assert.equal(successor.receipt.reviewer_payload.review_mode, "full");
      assert.doesNotThrow(() => helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: successor.ref }));
    });
  });
});

// fix-codex-spawn-admission-bypass T1 prove-it (index 160): no real admission +
// requireIndependence must fail closed with the named ordinary signal, and
// ordinary/advisory findings must remain readable (not discarded).
test("ordinary tl-direct receipt without admission: requireIndependence fails closed as ordinary-review-not-independent while findings remain readable (no-ticket-ordinary-all-hosts-v3)", () => {
  const helper = api();
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "ordinary-no-admission-independence";
    const findingId = "F-ordinary-usable-001";
    const sealed = sealInitial(helper, {
      repoRoot,
      changeId,
      mainSha,
      findings: [finding(findingId)],
    });
    assert.equal(
      sealed.receipt.reviewer_payload.reviewer_identity.executor_kind,
      "tl-direct",
      "fixture is ordinary (tl-direct) with no admissionRecordId",
    );
    assert.equal(sealed.receipt.reviewer_payload.review_authority?.kind, "tl-direct-review");
    assert.equal(
      Object.hasOwn(sealed.receipt.reviewer_payload.review_authority ?? {}, "admission_ref"),
      false,
      "ordinary tl-direct authority must not carry an admission_ref",
    );

    // Ordinary / advisory path: findings stay readable without independence.
    const ordinary = helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: sealed.ref });
    assert.equal(ordinary.executor_attribution, "tl-direct");
    assert.equal(
      ordinary.receipt.reviewer_payload.findings.some((entry) => entry.finding_id === findingId),
      true,
      "ordinary/advisory findings must not be discarded when independence is absent",
    );

    // Independence claim without real admission must fail closed with the
    // named closed code (design Open Q2 / D2): ordinary-review-not-independent.
    assert.throws(
      () => helper.verifyReviewRoundReceipt({
        repoRoot,
        receiptRef: sealed.ref,
        requireIndependence: true,
      }),
      (error) => {
        assert.equal(error?.message, "ordinary-review-not-independent");
        return true;
      },
      "requireIndependence without real admission must not succeed as independent",
    );

    // Findings remain on the sealed receipt after the independence fail —
    // the fail-closed gate does not authorize discard.
    const afterFail = helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: sealed.ref });
    assert.equal(
      afterFail.receipt.reviewer_payload.findings.some((entry) => entry.finding_id === findingId),
      true,
      "independence fail closed must not discard ordinary findings from the receipt",
    );
  });
});

// fix-codex-spawn-admission-bypass F-fcsab-r1-02 (index 161): public CLI
// verify-receipt --request must surface the exact closed code for both v3
// ordinary and legacy !v3 when requireIndependence:true (not only in-process).
test("public verify-receipt CLI: requireIndependence on v3 ordinary and legacy !v3 receipts fails with ordinary-review-not-independent (F-fcsab-r1-02)", () => {
  const helper = api();
  const expectedFailure = { ok: false, code: "ordinary-review-not-independent", detail: "Validate the captured reviewer payload and its dispatch tuple." };
  const invokeVerifyReceipt = (tempRoot, requestValue, label) => {
    const requestPath = path.join(tempRoot, `${label}.json`);
    // Exact D30 key order: repoRoot, receiptRef, requireIndependence.
    writeFileSync(requestPath, `${JSON.stringify({
      repoRoot: requestValue.repoRoot,
      receiptRef: requestValue.receiptRef,
      requireIndependence: true,
    })}\n`);
    return spawnSync(process.execPath, [HELPER_PATH, "verify-receipt", "--request", requestPath], {
      encoding: "utf8",
    });
  };

  withRepo(({ tempRoot, repoRoot, mainSha }) => {
    const changeId = "cli-ordinary-v3-not-independent";
    const sealed = sealInitial(helper, { repoRoot, changeId, mainSha });
    assert.equal(sealed.receipt.schema, REVIEW_RECEIPT_SCHEMA);
    assert.equal(sealed.receipt.reviewer_payload.reviewer_identity.executor_kind, "tl-direct");
    const result = invokeVerifyReceipt(tempRoot, { repoRoot, receiptRef: sealed.ref }, "v3-ordinary");
    assert.equal(result.status, 1, `v3 ordinary CLI: ${result.stdout}${result.stderr}`);
    assert.deepEqual(JSON.parse(result.stdout), expectedFailure, "v3 ordinary must emit exact CLI closed code");
  });

  for (const schema of [REVIEW_RECEIPT_SCHEMA_V1, REVIEW_RECEIPT_SCHEMA_V2]) {
    withRepo(({ tempRoot, repoRoot, mainSha }) => {
      const changeId = schema.endsWith("/v1") ? "cli-legacy-v1-not-independent" : "cli-legacy-v2-not-independent";
      const current = authoritativeReceiptPayload(helper, {
        repoRoot,
        changeId,
        baseSha: mainSha,
        headSha: mainSha,
      });
      const reviewerPayload = clone(current);
      delete reviewerPayload.review_authority;
      delete reviewerPayload.output_evidence;
      if (schema === REVIEW_RECEIPT_SCHEMA_V1) {
        delete reviewerPayload.change_id;
        delete reviewerPayload.responsibility_id;
        reviewerPayload.reviewer_identity = { role: "dp-reviewer" };
      } else {
        reviewerPayload.reviewer_identity = { role: "dp-reviewer", executor_kind: "tl-direct" };
      }
      const receipt = {
        schema,
        receipt_digest_sha256: sha256(helper.canonicalJsonV1(reviewerPayload)),
        observation_hashes: receiptObservationHashes(helper, reviewerPayload.findings),
        reviewer_payload: reviewerPayload,
      };
      const targetPath = evidencePath(repoRoot, `review-${changeId}-receipt-r1.json`);
      const ref = writeReceiptEnvelope(helper, targetPath, receipt);
      const result = invokeVerifyReceipt(tempRoot, { repoRoot, receiptRef: ref }, `legacy-${schema.split("/").pop()}`);
      assert.equal(result.status, 1, `legacy ${schema} CLI: ${result.stdout}${result.stderr}`);
      assert.deepEqual(
        JSON.parse(result.stdout),
        expectedFailure,
        `legacy ${schema} must emit the same exact CLI closed code as v3 ordinary`,
      );
    });
  }
});

