test("R6 tip-move→archive→final_ready accepts whitelist descendant parent", () => {
  const helper = api();
  const coreFactory = coreApi().createReviewRemediationEvidenceCore;
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "archive-tip-move-ready";
    const decisionsRelative = path.join("openspec", "changes", changeId, "decisions.md");
    const fixture = prepareArchiveTransitionFixture(helper, {
      repoRoot,
      mainSha,
      changeId,
      mutateReviewed: ({ repoRoot: root }) => {
        write(root, decisionsRelative, [
          "# Decisions",
          "",
          "## Design-Author Identity",
          "",
          "identity: unknown",
          "provenance: unknown",
          "",
          "## Audit Findings Ledger",
          "",
          "- baseline",
          "",
        ].join("\n"));
      },
      beforeArchive: ({ repoRoot: root }) => {
        write(root, decisionsRelative, [
          "# Decisions",
          "",
          "## Design-Author Identity",
          "",
          "identity: unknown",
          "provenance: unknown",
          "",
          "## Audit Findings Ledger",
          "",
          "- baseline",
          "- tip-move bookkeeping only",
          "",
        ].join("\n"));
        commitAll(root, "allowlisted tip-move before archive");
      },
    });
    const tipParent = git(repoRoot, ["rev-parse", `${fixture.postArchiveHeadSha}^`]);
    assert.notEqual(tipParent, fixture.reviewedHeadSha);
    assert.doesNotThrow(() => helper.classifyTipMoveWhitelist({
      repoRoot,
      reviewedSha: fixture.reviewedHeadSha,
      headSha: tipParent,
      changeId,
    }));
    const fake = transitionRunner();
    const sealed = coreFactory({ spawnSyncImpl: fake.runner }).sealFinalEvidenceRecord({
      repoRoot,
      changeId,
      canonicalOwnerId: "owner-1",
    });
    const transition = readTransitionRecord(helper, repoRoot, changeId, fixture.postArchiveHeadSha);
    assert.equal(transition.payload.reviewed_head_sha, fixture.reviewedHeadSha);
    assert.equal(transition.payload.post_archive_parent_sha, tipParent);
    assert.equal(transition.payload.result, "pass");
    assert.deepEqual(helper.classifyFinalReadiness({ repoRoot, changeId }), {
      final_ready: true,
      review_lineage_valid: true,
      review_coverage_valid: true,
      review_coverage_mode: "archive_transition",
      route: "final_ready",
    });
    assert.equal((sealed.record ?? sealed).payload.review_coverage.mode, "archive_transition");
  }, { featureChange: true });
});

