test("legacy full-prose previous receipt routes digest_alg_mismatch full reopen", () => {
  const helper = api();
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "classifier-digest-alg-mismatch";
    writeFullRiskChange(repoRoot, changeId);
    commitAll(repoRoot, "legacy alg baseline");
    const headSha = git(repoRoot, ["rev-parse", "HEAD"]);
    const core = coreApi().createReviewRemediationEvidenceCore();
    const legacyDigest = core.deriveHistoricalRiskShapeDigest({
      repoRoot,
      changeId,
      candidateHead: headSha,
      digestAlg: "full-prose-v0",
    });
    const v1Digest = core.deriveHistoricalRiskShapeDigest({
      repoRoot,
      changeId,
      candidateHead: headSha,
      digestAlg: "behavior-risk-v1",
    });
    assert.notEqual(legacyDigest, v1Digest, "fixture requires alg-distinct digests");
    const reviewerPayload = receiptPayload({
      changeId,
      baseSha: mainSha,
      mergeBaseSha: mainSha,
      headSha,
      findings: [finding("F-001", { state: "closed", disposition: "fix-now" })],
      openFindingIds: [],
      verdict: "finished",
    });
    reviewerPayload.scope.risk_shape_digest_sha256 = legacyDigest;
    delete reviewerPayload.scope.risk_shape_digest_alg;
    reviewerPayload.dispatch_id = resolveLogicalDispatchIdForPayload(helper, changeId, reviewerPayload);
    const previous = writeReceiptFixtureCarrier(helper, { repoRoot, changeId, reviewerPayload });
    const manifests = writeRoundManifestFixtureCarriers(helper, {
      repoRoot,
      changeId,
      roundNumber: 2,
      mainSha,
      surfaceBaseSha: headSha,
      candidateHeadSha: headSha,
    });
    const classified = helper.classifyBoundedRereview({
      repoRoot,
      changeId,
      previousReceiptRef: previous.ref,
      repairDeltaManifestRef: manifests.repair.ref,
      dependencyClosureManifestRef: manifests.closure.ref,
      predecessorMatches: predecessorMatches(previous.receipt),
    });
    assertDispatchableResult(classified, {
      route: "full",
      count: 0,
      round: 2,
      reason: "digest_alg_mismatch",
    });
    assert.equal(classified.risk_shape_digest_sha256, v1Digest);
  });
});

