// Scenario: Untyped error material cannot mint a D30 code
test("CLI preserves only typed D30 codes; untyped prose stays unexpected-io-fault", async (t) => {
  const cliSource = readFileSync(HELPER_PATH, "utf8");
  assert.match(cliSource, /error instanceof CoreFailure && D30_CODES\.has\(error\.code\)/u);
  assert.doesNotMatch(cliSource, /error\.message\.(?:match|split)|error\.code\s*\?\?/u,
    "D30 handler classification cannot parse prose or trust an arbitrary .code property");
  const helper = api();
  withRepo(({ tempRoot, repoRoot, mainSha }) => {
    const changeId = "cli-code-extraction";
    writeFullRiskChange(repoRoot, changeId);
    commitAll(repoRoot, "cli code baseline");
    const headSha = git(repoRoot, ["rev-parse", "HEAD"]);
    const prosePayload = receiptPayload({
      baseSha: mainSha,
      mergeBaseSha: mainSha,
      headSha,
      findings: [finding("F-cli-prose", { state: "open", disposition: "tracked-follow-up" })],
      verdict: "partial",
    });
    const proseRequest = path.join(tempRoot, "seal-receipt-prose.json");
    writeFileSync(proseRequest, JSON.stringify({
      changeId,
      repoRoot,
      reviewerPayload: prosePayload,
    }));
    const prose = spawnSync(process.execPath, [HELPER_PATH, "seal-receipt", "--request", proseRequest], {
      cwd: repoRoot,
      encoding: "utf8",
    });
    assert.notEqual(prose.status, 0);
    assert.deepEqual(
      JSON.parse(prose.stdout),
      { ok: false, code: "unexpected-io-fault", detail: "A repository or filesystem operation failed. Check availability and retry." },
      "prose messages must not invent a leading-token code (e.g. reviewer_… → reviewer)",
    );

    boundChange(repoRoot, "cli-emdash-capture");
    const { payload } = initialPayloadFromDispatch(helper, {
      repoRoot,
      changeId: "cli-emdash-capture",
      mainSha,
      findings: [finding("F-cli-disp", { state: "open", disposition: "tracked-follow-up" })],
    });
    payload.review_authority = null;
    payload.output_evidence = null;
    const payloadPath = path.join(tempRoot, "cli-emdash.bin");
    writeFileSync(payloadPath, Buffer.from(`${helper.canonicalJsonV1(payload)}\n`, "utf8"));
    const captureRequest = path.join(tempRoot, "capture-emdash.json");
    writeFileSync(captureRequest, JSON.stringify({
      repoRoot,
      changeId: "cli-emdash-capture",
      roundNumber: payload.round_number,
      dispatchId: payload.dispatch_id,
      payloadPath,
    }));
    const emdash = spawnSync(process.execPath, [HELPER_PATH, "capture-reviewer-output", "--request", captureRequest], {
      cwd: repoRoot,
      encoding: "utf8",
    });
    assert.notEqual(emdash.status, 0);
    assert.deepEqual(JSON.parse(emdash.stdout), { ok: false, code: "raw-payload-invalid", detail: "Validate the captured reviewer payload and its dispatch tuple." });
  });

  await t.test("safe diagnostic capture gives fixed repairs with unchanged public code and zero publication", async (t) => {
    const helper = api();
    for (const [mutation, detail] of [
      ["full-manifests", "Set both bounded manifest references to null and reproduce the full-review payload before capture."],
      ["missing-alg", "Include scope.risk_shape_digest_alg from the dispatch contract in the reviewer payload before capture."],
    ]) await t.test(mutation, () => withRepo(({ tempRoot, repoRoot, mainSha }) => {
      const changeId = `safe-diagnostic-${mutation}`;
      boundChange(repoRoot, changeId);
      const { payload } = initialPayloadFromDispatch(helper, { repoRoot, changeId, mainSha, findings: [] });
      payload.review_authority = null;
      payload.output_evidence = null;
      if (mutation === "missing-alg") delete payload.scope.risk_shape_digest_alg;
      else payload.scope.repair_delta_manifest_ref = { path: "private-manifest-sentinel.json", digest_sha256: DIGEST_A };
      const payloadPath = path.join(tempRoot, "private-payload-sentinel.bin");
      writeFileSync(payloadPath, `${helper.canonicalJsonV1(payload)}\n`);
      const result = runReviewEvidenceCli(tempRoot, repoRoot, "capture-reviewer-output", JSON.stringify({
        repoRoot, changeId, roundNumber: payload.round_number, dispatchId: payload.dispatch_id, payloadPath,
      }));
      assert.equal(result.status, 1, `${result.stdout}${result.stderr}`);
      assert.deepEqual(JSON.parse(result.stdout), { ok: false, code: "raw-payload-invalid", detail });
      assert.equal(existsSync(evidencePath(repoRoot, `review-${changeId}-raw-r${payload.round_number}-${payload.dispatch_id}.bin`)), false);
      assert.doesNotMatch(`${result.stdout}${result.stderr}`, /private-manifest-sentinel|private-payload-sentinel|full receipt cannot|Error:|\.stack/u);
    }));
  });

  await t.test("safe diagnostic artifact reads classify parent target and race without exposing native fault data", async (t) => {
    for (const kind of ["parent", "target", "race", "native"]) await t.test(kind, () => withRepo(({ tempRoot, repoRoot }) => {
      const safe = path.join(tempRoot, "safe-input");
      mkdirSync(safe);
      const input = path.join(safe, "private-read-sentinel.bin");
      writeFileSync(input, "{}\n");
      let payloadPath = input;
      if (kind === "target") { rmSync(input); mkdirSync(input); }
      if (kind === "parent") {
        const alias = path.join(tempRoot, "private-parent-sentinel");
        symlinkSync(safe, alias);
        payloadPath = path.join(alias, path.basename(input));
      }
      const request = { repoRoot, changeId: "safe-diagnostic-read", roundNumber: 1, dispatchId: DIGEST_A, payloadPath };
      if (kind === "parent" || kind === "target") {
        const result = runReviewEvidenceCli(tempRoot, repoRoot, "capture-reviewer-output", JSON.stringify(request));
        assert.equal(result.status, 1, `${result.stdout}${result.stderr}`);
        assert.deepEqual(JSON.parse(result.stdout), {
          ok: false, code: "evidence-artifact-invalid",
          detail: kind === "parent"
            ? "Use plain evidence directories inside the repository boundary; remove unsafe parent links before retrying."
            : "Use a regular evidence file inside its verified parent; remove unsafe target links or entries before retrying.",
        });
        assert.doesNotMatch(`${result.stdout}${result.stderr}`, /private-read-sentinel|private-parent-sentinel|parent-not-plain-directory|target-not-regular-file/u);
      } else {
        const fault = Object.assign(new Error("private-native-path /private/identity"), { code: "EIO", detailReason: "evidence-read-raced" });
        const core = coreApi().createReviewRemediationEvidenceCore({ fsOps: { readNoFollowFileHooks: { afterLstat() {
          if (kind === "native") throw fault;
          writeFileSync(input, "changed-size\n");
        } } } });
        assert.throws(() => core.captureReviewerOutput(request), (error) => {
          if (kind === "native") { assert.equal(error, fault); assert.equal(CoreFailure.safeDetail(error), null); }
          else {
            assert.equal(error.code, "evidence-artifact-invalid");
            assert.equal(CoreFailure.safeDetail(error), "Evidence changed during a verified read. Retry with stable evidence and rerun the affected command.");
          }
          return true;
        });
      }
    }));
  });

  await t.test("safe diagnostic reason authority rejects forged prose code and mismatched reason ownership", async (t) => {
    assert.equal(CoreFailure.safeDetail(new Error("raw-payload-invalid: private sentinel")), null);
    assert.equal(CoreFailure.safeDetail({ code: "raw-payload-invalid", detailReason: "full-review-manifests-nonnull" }), null);
    assert.equal(CoreFailure.safeDetail(Object.create(CoreFailure.prototype)), null);
    assert.equal(CoreFailure.safeDetail(new CoreFailure("raw-payload-invalid", "private payload sentinel")), null);
    assert.throws(() => new CoreFailure("raw-payload-invalid", "private", "unknown-safe-reason"), TypeError);
    assert.throws(() => new CoreFailure("unexpected-io-fault", "private", "full-review-manifests-nonnull"), TypeError);
    const fault = new DurablePathError("private forged durable code /private/identity");
    assert.equal(CoreFailure.safeDetail(fault), null);

    await t.test("post-hoc root and target boundaries expose only their fixed repair", () => {
      withR11PostHocReceiptCandidate(({ repoRoot, changeId, sealed }) => {
        const tempRoot = path.dirname(repoRoot);
        const postHoc = path.join(repoRoot, "openspec", "changes", changeId, "admission-records", "post-hoc");
        const target = path.join(postHoc, `${sealed.attestation.attestation_id}.json`);
        const outside = path.join(tempRoot, "private-posthoc-target-sentinel.json");
        writeFileSync(outside, readFileSync(target));
        unlinkSync(target);
        symlinkSync(outside, target);
        const request = JSON.stringify({ repoRoot, changeId, attestationId: sealed.attestation.attestation_id });
        const unsafeTarget = runReviewEvidenceCli(tempRoot, repoRoot, "verify-post-hoc-attestation", request);
        assert.equal(unsafeTarget.status, 1);
        assert.deepEqual(JSON.parse(unsafeTarget.stdout), { ok: false, code: "evidence-artifact-invalid",
          detail: "Use a regular evidence file inside its verified parent; remove unsafe target links or entries before retrying." });
        unlinkSync(target);
        const movedRoot = path.join(tempRoot, "private-posthoc-parent-sentinel");
        renameSync(postHoc, movedRoot);
        symlinkSync(movedRoot, postHoc);
        const unsafeRoot = runReviewEvidenceCli(tempRoot, repoRoot, "verify-post-hoc-attestation", request);
        assert.equal(unsafeRoot.status, 1);
        assert.deepEqual(JSON.parse(unsafeRoot.stdout), { ok: false, code: "evidence-artifact-invalid",
          detail: "Use plain evidence directories inside the repository boundary; remove unsafe parent links before retrying." });
        assert.doesNotMatch(`${unsafeTarget.stdout}${unsafeTarget.stderr}${unsafeRoot.stdout}${unsafeRoot.stderr}`, /private-posthoc|parent-not-plain|target-not-regular/u);
      });
    });

    for (const occurrence of [1, 2]) await t.test(`claimed ${occurrence === 1 ? "receipt" : "marker"} readback preserves the safe reason`, () => {
      const helper = api();
      withRepo(({ repoRoot, mainSha }) => {
        const changeId = `safe-diagnostic-seal-${occurrence}`;
        const reviewerPayload = authoritativeReceiptPayload(helper, { repoRoot, changeId, baseSha: mainSha });
        const fake = recordingFsOps();
        const read = fake.ops.readWholeFile;
        let reads = 0;
        fake.ops.readWholeFile = (...args) => {
          if (++reads === occurrence) throw new DurablePathError("same-inode-proof-failed");
          return read(...args);
        };
        const core = coreApi().createReviewRemediationEvidenceCore({ fsOps: fake.ops });
        assert.throws(() => core.sealReviewRoundReceipt({ repoRoot, changeId, reviewerPayload }), (error) => {
          assert.equal(error.code, "evidence-artifact-invalid");
          assert.equal(CoreFailure.safeDetail(error), "Evidence changed during a verified read. Retry with stable evidence and rerun the affected command.");
          return true;
        });
        assert.equal(reads, occurrence, "the claimed receipt/marker boundary must actually be reached");
      });
    });
  });

});

