test("capture still accepts the byte-exact closed historical raw carriers that predate the alg column (R2 exemption lock)", () => {
  const helper = api();
  withRepo(({ repoRoot }) => {
    const changeId = "fix-zero-value-review-rounds";
    const r10Bytes = readFileSync(D30_POST_HOC_R10_OUTPUT_FIXTURE);
    // The historical carrier predates the dispatch contract's alg column — the
    // exact case the closed post-hoc allowlist exists for.
    assert.equal(
      r10Bytes.includes(Buffer.from("risk_shape_digest_alg", "utf8")),
      false,
      "historical fixture must not carry the alg column; otherwise the exemption test proves nothing",
    );
    const ref = helper.captureReviewerOutput({
      repoRoot,
      changeId,
      roundNumber: 4,
      dispatchId: "48aab43c3fccda343b95ae07a6f4d0e64b8defbb3792b25b2b0646d067c99b8a",
      payloadPath: D30_POST_HOC_R10_OUTPUT_FIXTURE,
    });
    assert.equal(ref.digest_sha256, sha256(r10Bytes), "exempted historical bytes stay the published authority");
  });
});

