// Scenario: Stall recovery across a risk shape change keeps independently-verified manifests bounded
test("a stalled chain with a touched validator and a risk shape change stays on recovery when both manifests are independently verified", () => {
  const helper = api();
  withRepo(({ repoRoot }) => {
    // Review r7 F-ehrc-r7-01: the validator yield above is the Else-B arm of
    // the Prefer-A/Else-B gate. When both round manifests carry validated
    // independently-verified evidence, the gate keeps the round bounded and
    // the stall keeps it on convergence_recovery, and the seal accepts it.
    const changeId = "validator-touching-stall-risk-drift-prefer-a";
    const mainSha = advanceMainWithTrustSurface(repoRoot, { oracle: true });
    const { previous, request } = chainThrough(helper, { repoRoot, mainSha, changeId, trajectory: [2, 2, 2] });
    for (const ref of [request.repairDeltaManifestRef, request.dependencyClosureManifestRef]) {
      unlinkSync(path.join(mainNotesRoot(repoRoot), ref.path));
    }
    touchValidatorTrustSurface(repoRoot);
    writeFullRiskChange(repoRoot, changeId, { proposal: { touchRow: "| `src/second-target.mjs` | code | modify | R2 |" } });
    const candidateHeadSha = commitAll(repoRoot, "risk drift in the same round as a validator touch");
    const roundNumber = previous.receipt.reviewer_payload.round_number + 1;
    const sealIndependent = (purpose) => {
      const raw = manifestFixture({
        purpose,
        changeBaseSha: mainSha,
        surfaceBaseSha: previous.receipt.reviewer_payload.lineage.head_sha,
        candidateHeadSha,
      });
      raw.validator.source_path = VALIDATOR_TRUST_SURFACE_CORE;
      raw.validator.provenance = "independently-verified-same-change";
      const materialized = materializeManifest(helper, repoRoot, raw);
      materialized.validator.independent_evidence = evidenceFixture(
        helper,
        repoRoot,
        materialized,
        PRODUCTION_VALIDATOR_ORACLE,
      );
      return sealRawManifest(helper, { repoRoot, changeId, roundNumber, manifest: materialized });
    };
    const repair = sealIndependent("repair-delta");
    const closure = sealIndependent("dependency-closure");
    const recovery = helper.classifyBoundedRereview({
      ...request,
      repairDeltaManifestRef: repair.ref,
      dependencyClosureManifestRef: closure.ref,
    });
    assert.equal(recovery.route, "bounded");
    assert.equal(recovery.full_reopen_reason, "convergence_recovery");
    assert.notEqual(recovery.risk_shape_digest_sha256, previous.receipt.reviewer_payload.scope.risk_shape_digest_sha256,
      "precondition: the recovery round carries a changed risk shape");
    const sealed = sealReceipt(helper, {
      repoRoot,
      changeId,
      reviewerPayload: payloadFromDispatch(recovery, {
        changeId,
        reviewMode: "bounded",
        roundNumber,
        boundedCount: recovery.next_bounded_rereview_count,
        baseSha: mainSha,
        mergeBaseSha: mainSha,
        headSha: candidateHeadSha,
        previousReceiptRef: previous.ref,
        initialFullReceiptDigestSha256: previous.receipt.reviewer_payload.lineage.initial_full_receipt_digest_sha256,
        repairManifestRef: repair.ref,
        closureManifestRef: closure.ref,
        findings: convergeFindings(previous.receipt.reviewer_payload.findings, []),
      }),
    });
    assert.equal(sealed.receipt.reviewer_payload.dispatch_id, recovery.dispatch_id);
  });
});

// Scenario: Unevaluable Full Reopen Is Not Dispatch-Ready Full Authority
// R14 / decisions D16 (design D19, index 218): with a production validator
// oracle available and unchanged at the change base, absent manifest refs on
// a validator-touching round must stay the same unevaluable
// full_reopen_required / manifest_refs_absent that a non-touching round gets
// -- not the dispatchable validator_trust_surface_changed Else-B reopen
// index 215 / L11184 mint when the oracle is unavailable. The same round
// still proves it can be honestly sealed (Prefer-A remains reachable).
test("validator-touching + stable risk with absent manifests and an available production oracle returns unevaluable manifest_refs_absent, not a dispatchable full reopen (R14 D19 index 218 prove-it)", () => {
  const helper = api();
  withRepo(({ repoRoot }) => {
    const changeId = "validator-touching-oracle-available-absent";
    const mainSha = advanceMainWithTrustSurface(repoRoot, { oracle: true });
    writeFullRiskChange(repoRoot, changeId);
    commitAll(repoRoot, "validator-touching oracle-available baseline");
    const initial = sealInitial(helper, { repoRoot, changeId, mainSha });
    const candidateHeadSha = touchValidatorTrustSurface(repoRoot);
    const result = helper.classifyBoundedRereview({
      repoRoot,
      changeId,
      previousReceiptRef: initial.ref,
      repairDeltaManifestRef: null,
      dependencyClosureManifestRef: null,
      predecessorMatches: predecessorMatches(initial.receipt),
    });
    assert.equal(result.route, "full_reopen_required");
    assert.equal(result.full_reopen_debug_reason, "manifest_refs_absent");
    assert.equal(Object.hasOwn(result, "dispatch_id"), false);
    assert.equal(Object.hasOwn(result, "dispatch_ready"), false);
    assert.equal(Object.hasOwn(result, "full_reopen_reason"), false);

    // Same state, sealed against tools/validator.mjs's default pre-existing
    // trust (an unchanged tool, not the touched trust surface): the
    // production oracle's availability does not block Prefer-A.
    const manifests = sealRoundManifests(helper, {
      repoRoot,
      changeId,
      roundNumber: 2,
      mainSha,
      surfaceBaseSha: initial.receipt.reviewer_payload.lineage.head_sha,
      candidateHeadSha,
    });
    const bounded = helper.classifyBoundedRereview({
      repoRoot,
      changeId,
      previousReceiptRef: initial.ref,
      repairDeltaManifestRef: manifests.repair.ref,
      dependencyClosureManifestRef: manifests.closure.ref,
      predecessorMatches: predecessorMatches(initial.receipt),
    });
    assertDispatchableResult(bounded, { route: "bounded", count: 1, round: 2, reason: null });
  });
});

