      assert.equal(pathExists(archiveTransitionTarget(repoRoot, changeId, fixture.postArchiveHeadSha)), false, `${failMode}: no transition record`);
      assert.deepEqual(finalEvidenceFileNames(repoRoot, changeId), [], `${failMode}: no final record`);
