// strengthen-review-receipt-carry-forward-compaction T1 (red tests, design D8 items
// 1, 2, 3(c), 6, 9 plus the two direct items): appended at the very end of the file
// for the same reason as every block above -- appending keeps every prior test's
// group assignment stable. These are the first seven tests the change adds (indices
// 252-258); only runner_d4's upper bound moves 251 -> 258.
//
// They drive production only through the public facade and the request-file CLI. The
// omitting successor is NEVER built through sealReceipt/bindReceiptAuthority: that
// helper captures the raw payload, and once the check exists capture itself refuses
// the omission, so the build and seal legs write the raw carrier directly (the state
// a raw published by a tool older than the check leaves behind -- design D3).
const OMITTED_CARRY_FORWARD_CODE = "predecessor-finding-omitted";
const REVIEWER_PAYLOAD_CHECK_DETAIL = "Validate the captured reviewer payload and its dispatch tuple.";
const OMITTED_CARRY_FORWARD_CLI_FAILURE = Object.freeze({
  ok: false,
  code: OMITTED_CARRY_FORWARD_CODE,
  detail: REVIEWER_PAYLOAD_CHECK_DETAIL,
});

/** A facade call's outcome as data: the D30 code it threw, or "returned". Never a
 * `new CoreFailure(...)` of the not-yet-existing code (that throws TypeError at HEAD). */
function carryForwardFacadeOutcome(run) {
  try {
    run();
    return "returned";
  } catch (error) {
    return error instanceof CoreFailure ? error.code : `${error?.name}: ${error?.message}`;
  }
}

function carryForwardCliOutcome(result) {
  if (result.status === 0) return "exit 0";
  try {
    return JSON.parse(result.stdout);
  } catch {
    return `unparseable CLI output: ${result.stdout}${result.stderr}`;
  }
}

function carryForwardRoundOne(helper, { repoRoot, mainSha, changeId, findings }) {
  writeFullRiskChange(repoRoot, changeId);
  commitAll(repoRoot, `carry-forward baseline for ${changeId}`);
  return sealReceipt(helper, {
    repoRoot,
    changeId,
    reviewerPayload: payloadFromDispatch(initialClassification(helper, { repoRoot, changeId }), {
      changeId,
      baseSha: mainSha,
      mergeBaseSha: mainSha,
      headSha: git(repoRoot, ["rev-parse", "HEAD"]),
      findings,
    }),
  });
}

/** The next plain bounded dispatch after `previous`, with its classifier-issued
 * authority already on the payload. `findings` is the successor's own findings[]. */
function carryForwardBoundedSuccessor(helper, { repoRoot, mainSha, changeId, previous, findings, commitTag }) {
  const previousPayload = previous.receipt.reviewer_payload;
  const roundNumber = previousPayload.round_number + 1;
  const boundedCount = previousPayload.bounded_rereview_count + 1;
  const candidateHead = commitRound(repoRoot, commitTag);
  const manifests = sealRoundManifests(helper, {
    repoRoot,
    changeId,
    roundNumber,
    mainSha,
    surfaceBaseSha: previousPayload.lineage.head_sha,
    candidateHeadSha: candidateHead,
  });
  const dispatch = classifyBounded(helper, {
    repoRoot,
    changeId,
    previousReceipt: previous,
    repairManifest: manifests.repair,
    closureManifest: manifests.closure,
  });
  assertDispatchableResult(dispatch, { route: "bounded", count: boundedCount, round: roundNumber, reason: null });
  const payload = payloadFromDispatch(dispatch, {
    changeId,
    reviewMode: "bounded",
    roundNumber,
    boundedCount,
    baseSha: mainSha,
    mergeBaseSha: mainSha,
    headSha: candidateHead,
    previousReceiptRef: previous.ref,
    initialFullReceiptDigestSha256: previousPayload.lineage.initial_full_receipt_digest_sha256 ?? previous.ref.digest_sha256,
    repairManifestRef: manifests.repair.ref,
    closureManifestRef: manifests.closure.ref,
    findings,
  });
  return { dispatch, manifests, payload };
}

/** Runs one omitting successor through capture (facade and CLI), build-receipt-request
 * (facade and CLI) and seal-receipt (facade and CLI), and reports every observable
 * as data, so a failing run names each entry point instead of stopping at the first. */
function exerciseOmittedCarryForward(helper, scene) {
  const { tempRoot, repoRoot, changeId, payload, authority = { kind: "tl-direct-review" }, admissionRecordId = null, claimPaths = [] } = scene;
  const rawPayload = clone(payload);
  rawPayload.review_authority = null;
  rawPayload.output_evidence = null;
  const rawBytes = Buffer.from(`${helper.canonicalJsonV1(rawPayload)}\n`, "utf8");
  const rawName = `review-${changeId}-raw-r${payload.round_number}-${payload.dispatch_id}.bin`;
  const rawTarget = evidencePath(repoRoot, rawName);
  const payloadPath = path.join(tempRoot, `omitted-${payload.dispatch_id.slice(0, 12)}.bin`);
  writeFileSync(payloadPath, rawBytes);
  const observed = {};

  const captureRequest = {
    repoRoot,
    changeId,
    roundNumber: payload.round_number,
    dispatchId: payload.dispatch_id,
    payloadPath,
  };
  observed.capture = carryForwardFacadeOutcome(() => helper.captureReviewerOutput(captureRequest));
  observed.captureCli = carryForwardCliOutcome(runReviewEvidenceCli(tempRoot, repoRoot, "capture-reviewer-output", `${JSON.stringify(captureRequest)}\n`));
  observed.rawPublishedByCapture = existsSync(rawTarget);

  // Build and seal read a raw carrier that an older capture already published.
  if (!existsSync(rawTarget)) writeFileSync(rawTarget, rawBytes);
  const rawPayloadRef = { path: rawName, digest_sha256: sha256(rawBytes) };
  const buildRequest = { repoRoot, changeId, rawPayloadRef, ...(admissionRecordId === null ? {} : { admissionRecordId }) };
  observed.build = carryForwardFacadeOutcome(() => helper.buildReviewRoundReceiptRequest(buildRequest));
  observed.buildCli = carryForwardCliOutcome(runReviewEvidenceCli(tempRoot, repoRoot, "build-receipt-request", `${JSON.stringify(buildRequest)}\n`));

  const reviewerPayload = clone(payload);
  reviewerPayload.review_authority = authority;
  reviewerPayload.output_evidence = {
    raw_payload_ref: rawPayloadRef,
    raw_payload_sha256: rawPayloadRef.digest_sha256,
    verdict_open_set_sha256: sha256(helper.canonicalJsonV1({
      verdict: reviewerPayload.verdict,
      open_finding_ids: reviewerPayload.scope.open_finding_ids,
    })),
  };
  // The seal-receipt CLI requires its request keys in the exact alphabetical shapes it lists.
  const sealRequest = { ...(admissionRecordId === null ? {} : { admissionRecordId }), changeId, repoRoot, reviewerPayload };
  observed.seal = carryForwardFacadeOutcome(() => helper.sealReviewRoundReceipt(sealRequest));
  observed.sealCli = carryForwardCliOutcome(runReviewEvidenceCli(tempRoot, repoRoot, "seal-receipt", `${JSON.stringify(sealRequest)}\n`));

  const receiptPath = receiptTarget(repoRoot, changeId, payload.round_number, payload.dispatch_id);
  observed.receiptWritten = existsSync(receiptPath);
  observed.markerWritten = existsSync(receiptPath.replace(/\.json$/u, ".commit.json"));
  observed.claimsWritten = claimPaths.map((claimPath) => existsSync(claimPath));
  return observed;
}

function expectedOmittedCarryForward({ claimCount = 0 } = {}) {
  return {
    capture: OMITTED_CARRY_FORWARD_CODE,
    captureCli: OMITTED_CARRY_FORWARD_CLI_FAILURE,
    rawPublishedByCapture: false,
    build: OMITTED_CARRY_FORWARD_CODE,
    buildCli: OMITTED_CARRY_FORWARD_CLI_FAILURE,
    seal: OMITTED_CARRY_FORWARD_CODE,
    sealCli: OMITTED_CARRY_FORWARD_CLI_FAILURE,
    receiptWritten: false,
    markerWritten: false,
    claimsWritten: Array.from({ length: claimCount }, () => false),
  };
}

// Scenario: Omitted Predecessor Open Finding Fails Closed Before Any Claim Or Write (D8 item 1)
test("Omitted Predecessor Open Finding Fails Closed Before Any Claim Or Write: capture, build and seal through the facade and the CLI return predecessor-finding-omitted with nothing published, claimed or written", async (t) => {
  const helper = api();

  await t.test("a bounded successor that drops one predecessor open finding", () => {
    withRepo(({ tempRoot, repoRoot, mainSha }) => {
      const changeId = "carry-forward-open-bounded";
      const previous = carryForwardRoundOne(helper, { repoRoot, mainSha, changeId, findings: openFindings(2) });
      const { payload } = carryForwardBoundedSuccessor(helper, {
        repoRoot, mainSha, changeId, previous, findings: openFindings(1), commitTag: 501,
      });
      assert.deepEqual(previous.receipt.reviewer_payload.scope.open_finding_ids, ["F-001", "F-002"], "precondition: the predecessor lists two open findings");
      assert.deepEqual(payload.scope.open_finding_ids, ["F-001"], "precondition: the successor drops F-002");
      assert.deepEqual(
        exerciseOmittedCarryForward(helper, { tempRoot, repoRoot, changeId, payload }),
        expectedOmittedCarryForward(),
      );
    });
  });

  await t.test("a runtime-agent successor leaves its admission record unclaimed", () => {
    withRepo(({ tempRoot, repoRoot, mainSha }) => {
      const changeId = "carry-forward-open-runtime";
      boundChange(repoRoot, changeId);
      const firstAdmission = preparedRuntimeAdmissionFixture({ repoRoot, changeId });
      const previous = sealPreparedRuntime(helper, {
        repoRoot,
        changeId,
        mainSha,
        admission: firstAdmission,
        payload: runtimeAgentPayload(helper, { repoRoot, changeId, mainSha, findings: openFindings(2) }),
      });
      const previousPayload = previous.receipt.reviewer_payload;
      const candidateHead = commitRound(repoRoot, 502);
      const manifests = sealRoundManifests(helper, {
        repoRoot, changeId, roundNumber: 2, mainSha, surfaceBaseSha: previousPayload.lineage.head_sha, candidateHeadSha: candidateHead,
      });
      const dispatch = classifyBounded(helper, {
        repoRoot, changeId, previousReceipt: previous, repairManifest: manifests.repair, closureManifest: manifests.closure,
      });
      assertDispatchableResult(dispatch, { route: "bounded", count: 1, round: 2, reason: null });
      const admission = preparedRuntimeAdmissionFixture({ repoRoot, changeId });
      const payload = payloadFromDispatch(dispatch, {
        changeId,
        reviewMode: "bounded",
        roundNumber: 2,
        boundedCount: 1,
        baseSha: mainSha,
        mergeBaseSha: mainSha,
        headSha: candidateHead,
        previousReceiptRef: previous.ref,
        initialFullReceiptDigestSha256: previous.ref.digest_sha256,
        repairManifestRef: manifests.repair.ref,
        closureManifestRef: manifests.closure.ref,
        findings: openFindings(1),
      });
      payload.reviewer_identity = { role: "dp-reviewer", executor_kind: "runtime-agent" };
      payload.execution_root_head = candidateHead;
      payload.review_authority = null;
      const claimPath = path.join(repoRoot, "openspec", "changes", changeId, "admission-records", `${admission.record_id}.claim`);
      assert.equal(existsSync(claimPath), false, "precondition: the successor's admission starts unclaimed");
      assert.deepEqual(
        exerciseOmittedCarryForward(helper, {
          tempRoot,
          repoRoot,
          changeId,
          payload,
          authority: {
            kind: "runtime-admission",
            intent_ref: { intent_id: admission.record.intent_id, digest_sha256: admission.record.intent_sha256 },
            admission_ref: { record_id: admission.record_id, digest_sha256: admission.digest },
          },
          admissionRecordId: admission.record_id,
          claimPaths: [claimPath],
        }),
        expectedOmittedCarryForward({ claimCount: 1 }),
      );
    });
  });

  await t.test("a post-hoc attested successor leaves its attestation unclaimed (the open part applies to the closed historical authority)", () => {
    // The default r11 candidate findings carry neither of r3's findings, so the open
    // F-fzvrr-r8-01 that r3 lists is omitted. The frozen allowlisted bytes cannot be
    // rebuilt to omit a different finding; this is the omission they can express.
    withR11PostHocReceiptCandidate(({ repoRoot, changeId, sealed, reviewerPayload }) => {
      assert.equal(reviewerPayload.findings.some((entry) => entry.finding_id === "F-fzvrr-r8-01"), false, "precondition: r3's open finding is omitted");
      const claimPath = path.join(repoRoot, "openspec", "changes", changeId, "admission-records", "post-hoc", `${sealed.attestation.attestation_id}.claim`);
      const cliRoot = mkdtempSync(path.join(os.tmpdir(), "carry-forward-post-hoc-cli-"));
      try {
        const request = { attestationRef: sealed.ref, changeId, repoRoot, reviewerPayload };
        const observed = {
          seal: carryForwardFacadeOutcome(() => helper.sealReviewRoundReceipt(request)),
          sealCli: carryForwardCliOutcome(runReviewEvidenceCli(cliRoot, repoRoot, "seal-receipt", `${JSON.stringify(request)}\n`)),
          attestationClaimed: existsSync(claimPath),
          receiptWritten: existsSync(receiptTarget(repoRoot, changeId, reviewerPayload.round_number, reviewerPayload.dispatch_id)),
        };
        assert.deepEqual(observed, {
          seal: OMITTED_CARRY_FORWARD_CODE,
          sealCli: OMITTED_CARRY_FORWARD_CLI_FAILURE,
          attestationClaimed: false,
          receiptWritten: false,
        });
      } finally {
        rmSync(cliRoot, { recursive: true, force: true });
      }
    });
  });
});

// Scenario: Omitted Predecessor Open Finding Fails Closed Before Any Claim Or Write (D8 item 6, second WHEN/THEN)
test("Omitted Predecessor Open Finding Fails Closed Before Any Claim Or Write: a full successor and every authorization reason are not exempt", async (t) => {
  const helper = api();
  const dropOneOpen = () => openFindings(1);

  await t.test("risk_shape_changed full reopen", () => {
    withRepo(({ tempRoot, repoRoot, mainSha }) => {
      const changeId = "carry-forward-risk-full";
      const initial = carryForwardRoundOne(helper, { repoRoot, mainSha, changeId, findings: openFindings(2) });
      writeFullRiskChange(repoRoot, changeId, { proposal: { touchRow: "| `src/second-target.mjs` | code | modify | R2 |" } });
      const changedHead = commitAll(repoRoot, "selected risk drift");
      const manifests = sealRoundManifests(helper, {
        repoRoot, changeId, roundNumber: 2, mainSha, surfaceBaseSha: initial.receipt.reviewer_payload.lineage.head_sha, candidateHeadSha: changedHead,
      });
      const reopened = classifyBounded(helper, {
        repoRoot, changeId, previousReceipt: initial, repairManifest: manifests.repair, closureManifest: manifests.closure,
      });
      assertDispatchableResult(reopened, { route: "full", count: 0, round: 2, reason: "risk_shape_changed" });
      const payload = payloadFromDispatch(reopened, {
        changeId, reviewMode: "full", roundNumber: 2, boundedCount: 0, baseSha: mainSha, mergeBaseSha: mainSha, headSha: changedHead,
        previousReceiptRef: initial.ref, initialFullReceiptDigestSha256: initial.ref.digest_sha256, findings: dropOneOpen(),
      });
      assert.equal(payload.review_mode, "full");
      assert.deepEqual(exerciseOmittedCarryForward(helper, { tempRoot, repoRoot, changeId, payload }), expectedOmittedCarryForward());
    });
  });

  await t.test("git_lineage_changed full reopen", () => {
    withRepo(({ tempRoot, repoRoot, mainSha }) => {
      const changeId = "carry-forward-lineage-full";
      const initial = carryForwardRoundOne(helper, { repoRoot, mainSha, changeId, findings: openFindings(2) });
      const featureBranch = git(repoRoot, ["branch", "--show-current"]);
      git(repoRoot, ["checkout", "--quiet", "main"]);
      write(repoRoot, "src/main-advance.txt", "main advanced\n");
      const advancedMain = commitAll(repoRoot, "advance main before lineage recovery");
      syncOriginMain(repoRoot, advancedMain);
      git(repoRoot, ["checkout", "--quiet", featureBranch]);
      git(repoRoot, ["rebase", advancedMain]);
      const rebasedHead = git(repoRoot, ["rev-parse", "HEAD"]);
      const reopened = helper.classifyBoundedRereview({
        repoRoot,
        changeId,
        previousReceiptRef: initial.ref,
        repairDeltaManifestRef: null,
        dependencyClosureManifestRef: null,
        predecessorMatches: predecessorMatches(initial.receipt),
      });
      assertDispatchableResult(reopened, { route: "full", count: 0, round: 2, reason: "git_lineage_changed" });
      const payload = payloadFromDispatch(reopened, {
        changeId, reviewMode: "full", roundNumber: 2, boundedCount: 0, baseSha: advancedMain, mergeBaseSha: advancedMain, headSha: rebasedHead,
        previousReceiptRef: initial.ref, initialFullReceiptDigestSha256: initial.ref.digest_sha256, findings: dropOneOpen(),
      });
      assert.deepEqual(exerciseOmittedCarryForward(helper, { tempRoot, repoRoot, changeId, payload }), expectedOmittedCarryForward());
    });
  });

  await t.test("convergence_recovery", () => {
    withRepo(({ tempRoot, repoRoot, mainSha }) => {
      const changeId = "carry-forward-recovery";
      const { previous, request } = chainThrough(helper, { repoRoot, mainSha, changeId, trajectory: [2, 2, 2] });
      const recovery = helper.classifyBoundedRereview(request);
      assert.equal(recovery.route, "bounded");
      assert.equal(recovery.full_reopen_reason, "convergence_recovery");
      const previousPayload = previous.receipt.reviewer_payload;
      const payload = payloadFromDispatch(recovery, {
        changeId, reviewMode: "bounded", roundNumber: recovery.round_number, boundedCount: recovery.next_bounded_rereview_count,
        baseSha: mainSha, mergeBaseSha: mainSha, headSha: git(repoRoot, ["rev-parse", "HEAD"]),
        previousReceiptRef: previous.ref, initialFullReceiptDigestSha256: previousPayload.lineage.initial_full_receipt_digest_sha256,
        repairManifestRef: request.repairDeltaManifestRef, closureManifestRef: request.dependencyClosureManifestRef, findings: dropOneOpen(),
      });
      assert.equal(payload.dispatch_id, recovery.dispatch_id, "the payload carries the classifier-issued recovery authority");
      assert.deepEqual(exerciseOmittedCarryForward(helper, { tempRoot, repoRoot, changeId, payload }), expectedOmittedCarryForward());
    });
  });

  await t.test("handback_authorized_bounded", () => {
    withRepo(({ tempRoot, repoRoot, mainSha }) => {
      const changeId = "carry-forward-handback-bounded";
      const { previous, request } = chainThrough(helper, { repoRoot, mainSha, changeId, trajectory: [2, 2, 2] });
      const resume = issueHalfStateOverride({
        repoRoot, changeId, responsibilityId: "primary-review", reason: "user: authorized one more bounded round after a true stall handback",
      });
      const authorized = helper.classifyBoundedRereview({
        ...request, responsibilityId: "primary-review", handbackCause: "irreversible_high_risk", overrideId: resume.override_id,
      });
      assert.equal(authorized.route, "bounded");
      assert.equal(authorized.full_reopen_reason, "handback_authorized_bounded");
      const previousPayload = previous.receipt.reviewer_payload;
      const payload = payloadFromDispatch(authorized, {
        changeId, reviewMode: "bounded", roundNumber: authorized.round_number, boundedCount: authorized.next_bounded_rereview_count,
        baseSha: mainSha, mergeBaseSha: mainSha, headSha: git(repoRoot, ["rev-parse", "HEAD"]),
        previousReceiptRef: previous.ref, initialFullReceiptDigestSha256: previousPayload.lineage.initial_full_receipt_digest_sha256,
        repairManifestRef: request.repairDeltaManifestRef, closureManifestRef: request.dependencyClosureManifestRef, findings: dropOneOpen(),
      });
      assert.deepEqual(exerciseOmittedCarryForward(helper, { tempRoot, repoRoot, changeId, payload }), expectedOmittedCarryForward());
    });
  });

  await t.test("handback_authorized_full", () => {
    withRepo(({ tempRoot, repoRoot, mainSha }) => {
      const changeId = "carry-forward-handback-full";
      const { previous, request } = chainThrough(helper, { repoRoot, mainSha, changeId, trajectory: [2, 2, 2] });
      writeFullRiskChange(repoRoot, changeId, { proposal: { touchRow: "| `src/second-target.mjs` | code | modify | R2 |" } });
      const authorizedHead = commitAll(repoRoot, "risk drift before the user authorizes one more full round");
      const authorizedRound = previous.receipt.reviewer_payload.round_number + 1;
      for (const ref of [request.repairDeltaManifestRef, request.dependencyClosureManifestRef]) {
        unlinkSync(path.join(mainNotesRoot(repoRoot), ref.path));
      }
      const manifests = sealRoundManifests(helper, {
        repoRoot, changeId, roundNumber: authorizedRound, mainSha,
        surfaceBaseSha: previous.receipt.reviewer_payload.lineage.head_sha, candidateHeadSha: authorizedHead,
      });
      const resume = issueHalfStateOverride({
        repoRoot, changeId, responsibilityId: "primary-review", reason: "user: one more full round, the risk shape moved",
      });
      const authorized = helper.classifyBoundedRereview({
        ...request,
        repairDeltaManifestRef: manifests.repair.ref,
        dependencyClosureManifestRef: manifests.closure.ref,
        responsibilityId: "primary-review",
        overrideId: resume.override_id,
        handbackCause: "reviewer_unrecoverable",
      });
      assert.equal(authorized.full_reopen_reason, "handback_authorized_full");
      const payload = payloadFromDispatch(authorized, {
        changeId, reviewMode: "full", roundNumber: authorizedRound, boundedCount: authorized.next_bounded_rereview_count,
        baseSha: mainSha, mergeBaseSha: mainSha, headSha: authorizedHead,
        previousReceiptRef: previous.ref, initialFullReceiptDigestSha256: previous.receipt.reviewer_payload.lineage.initial_full_receipt_digest_sha256,
        findings: dropOneOpen(),
      });
      assert.equal(payload.review_mode, "full");
      assert.deepEqual(exerciseOmittedCarryForward(helper, { tempRoot, repoRoot, changeId, payload }), expectedOmittedCarryForward());
    });
  });
});

// Scenario: Predecessor Closed Critical Is Carried Unless Closed By A Scope Ruling (D8 item 2)
test("Predecessor Closed Critical Is Carried Unless Closed By A Scope Ruling: a fix-now Critical is required, a scope-ruled one may be omitted, and the closed post-hoc authority is held only to the open part", async (t) => {
  const helper = api();

  // Scenario: Every Receipt Rejects Deferred Critical Dispositions (rewritten AND clause: the predecessor Critical set follows the required carry-forward rule)
  await t.test("Every Receipt Rejects Deferred Critical Dispositions: a successor that omits a predecessor closed fix-now Critical fails closed in capture, build and seal", () => {
    withRepo(({ tempRoot, repoRoot, mainSha }) => {
      const changeId = "carry-forward-critical-omitted";
      const previous = carryForwardRoundOne(helper, {
        repoRoot, mainSha, changeId, findings: [finding("F-001"), t17ClosureFinding("F-CRIT")],
      });
      const { payload } = carryForwardBoundedSuccessor(helper, {
        repoRoot, mainSha, changeId, previous, findings: [finding("F-001")], commitTag: 503,
      });
      assert.deepEqual(previous.receipt.reviewer_payload.scope.open_finding_ids, ["F-001"], "precondition: the Critical is closed, not open");
      assert.equal(payload.findings.some((entry) => entry.finding_id === "F-CRIT"), false, "precondition: the successor omits it");
      assert.deepEqual(exerciseOmittedCarryForward(helper, { tempRoot, repoRoot, changeId, payload }), expectedOmittedCarryForward());
    });
  });

  await t.test("Every Receipt Rejects Deferred Critical Dispositions: a successor that omits a Critical closed under a TL scope ruling seals", () => {
    withRepo(({ repoRoot, mainSha }) => {
      const changeId = "carry-forward-critical-ruled";
      const prepared = prepareRuledChange(helper, { repoRoot, changeId, severity: "Critical" });
      const previous = sealInitial(helper, { repoRoot, mainSha, changeId, findings: [prepared.entry, finding("F-001")] });
      assert.equal(previous.receipt.reviewer_payload.findings[0].observation.requirement_scope, "scope-unresolved", "precondition: closed under a scope ruling");
      assert.equal(previous.receipt.reviewer_payload.findings[0].observation.severity, "Critical");
      const { payload } = carryForwardBoundedSuccessor(helper, {
        repoRoot, mainSha, changeId, previous, findings: [finding("F-001")], commitTag: 504,
      });
      const sealed = sealReceipt(helper, { repoRoot, changeId, reviewerPayload: payload });
      assert.equal(sealed.receipt.reviewer_payload.findings.some((entry) => entry.finding_id === RULED_ID), false);
      assert.doesNotThrow(() => helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: sealed.ref, changeId }));
    });
  });

  await t.test("the closed historical post-hoc r11 tuple, whose frozen raw omits r3's closed Critical, still builds and seals", () => {
    const rawText = readFileSync(D30_POST_HOC_R11_OUTPUT_FIXTURE, "utf8");
    const marker = "## reviewerPayload\n\n```json\n";
    const start = rawText.indexOf(marker) + marker.length;
    const rawPayload = JSON.parse(rawText.slice(start, rawText.indexOf("\n```", start)));
    const predecessor = JSON.parse(readFileSync(
      path.join(D30_POST_HOC_AUTHORITY_FIXTURES, "review-fix-zero-value-review-rounds-receipt-r3.json"),
      "utf8",
    )).reviewer_payload;
    const closedCritical = predecessor.findings.filter((entry) => entry.state === "closed" && entry.observation.severity === "Critical");
    assert.deepEqual(closedCritical.map((entry) => entry.finding_id), ["F-fzvrr-r2-01"], "precondition: r3 holds exactly one closed Critical");
    assert.equal(rawPayload.findings.some((entry) => entry.finding_id === "F-fzvrr-r2-01"), false, "precondition: the frozen r11 raw omits it");
    assert.equal(rawPayload.findings.some((entry) => entry.finding_id === "F-fzvrr-r8-01"), true, "precondition: it still carries r3's open finding");
    withR11PostHocReceiptCandidate(({ repoRoot, changeId, rawPayloadRef, sealed, reviewerPayload }) => {
      const built = helper.buildReviewRoundReceiptRequest({ repoRoot, changeId, rawPayloadRef, attestationRef: sealed.ref });
      assert.deepEqual(built, { repoRoot, changeId, reviewerPayload, attestationRef: sealed.ref });
      const receipt = helper.sealReviewRoundReceipt(built);
      assert.equal(
        helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: receipt.ref, requireIndependence: true }).executor_attribution,
        "post-hoc-tl-attested-runtime-review",
      );
    }, { findings: rawPayload.findings });
  });

  await t.test("the post-hoc exception follows the frozen tuple, not the mere presence of a post-hoc binding", () => {
    const core = coreApi().createReviewRemediationEvidenceCore({});
    assert.equal(
      typeof core.isClosedHistoricalPostHocReceipt,
      "function",
      "the core instance must expose isClosedHistoricalPostHocReceipt(payload)",
    );
    withR11PostHocReceiptCandidate(({ reviewerPayload }) => {
      assert.equal(core.isClosedHistoricalPostHocReceipt(reviewerPayload), true, "the real frozen r11 receipt payload matches its POST_HOC_ALLOWED tuple");
      const mutate = (field, value) => {
        const copy = structuredClone(reviewerPayload);
        if (field === "raw_payload_sha256") copy.output_evidence.raw_payload_sha256 = value;
        else copy[field] = value;
        return copy;
      };
      assert.equal(core.isClosedHistoricalPostHocReceipt(mutate("raw_payload_sha256", DIGEST_A)), false, "another raw digest is not the frozen raw");
      assert.equal(core.isClosedHistoricalPostHocReceipt(mutate("dispatch_id", DIGEST_A)), false, "another dispatch is not the frozen dispatch");
      assert.equal(core.isClosedHistoricalPostHocReceipt(mutate("round_number", reviewerPayload.round_number + 1)), false, "another round is not the frozen round");
      assert.equal(core.isClosedHistoricalPostHocReceipt(mutate("change_id", "another-change")), false, "another change is not the frozen change");
      const withoutOutputEvidence = structuredClone(reviewerPayload);
      delete withoutOutputEvidence.output_evidence;
      assert.equal(core.isClosedHistoricalPostHocReceipt(withoutOutputEvidence), false, "a payload with no raw digest never matches");
    });
  });
});

// Scenario: Earlier Closed Findings May Be Omitted And The Chain Still Seals (D8 item 3(c))
test("Earlier Closed Findings May Be Omitted And The Chain Still Seals: (c) a Critical closed before the predecessor that the predecessor still carries cannot be omitted", () => {
  const helper = api();
  withRepo(({ tempRoot, repoRoot, mainSha }) => {
    const changeId = "carry-forward-critical-earlier";
    // r1 closes the Critical; r2 (the predecessor) carries it again, still closed.
    const roundOne = carryForwardRoundOne(helper, {
      repoRoot, mainSha, changeId, findings: [finding("F-001"), finding("F-002"), t17ClosureFinding("F-CRIT")],
    });
    const roundTwoScene = carryForwardBoundedSuccessor(helper, {
      repoRoot, mainSha, changeId, previous: roundOne, commitTag: 505,
      findings: [finding("F-001"), finding("F-002", { state: "closed", disposition: "fix-now" }), t17ClosureFinding("F-CRIT")],
    });
    const roundTwo = sealReceipt(helper, { repoRoot, changeId, reviewerPayload: roundTwoScene.payload });
    assert.equal(roundTwo.receipt.reviewer_payload.findings.some((entry) => entry.finding_id === "F-CRIT" && entry.state === "closed"), true,
      "precondition: the predecessor still holds the closed Critical");
    assert.equal(roundOne.receipt.reviewer_payload.findings.some((entry) => entry.finding_id === "F-CRIT" && entry.state === "closed"), true,
      "precondition: it closed before the predecessor's round");
    const { payload } = carryForwardBoundedSuccessor(helper, {
      repoRoot, mainSha, changeId, previous: roundTwo, findings: [finding("F-001")], commitTag: 506,
    });
    assert.deepEqual(exerciseOmittedCarryForward(helper, { tempRoot, repoRoot, changeId, payload }), expectedOmittedCarryForward());
  });
});

// Scenario: Raw Reviewer Capture Rejects Invalid Bytes Before Immutable Publication (carve-out: a predecessor ref whose receipt does not exist or fails validation stays raw-payload-invalid)
test("Raw Reviewer Capture Rejects Invalid Bytes Before Immutable Publication: a predecessor ref whose receipt does not exist or fails validation returns raw-payload-invalid and publishes nothing", async (t) => {
  const helper = api();
  const captureWithRef = ({ tempRoot, repoRoot, changeId, payload }) => {
    const rawPayload = clone(payload);
    rawPayload.review_authority = null;
    rawPayload.output_evidence = null;
    const rawBytes = Buffer.from(`${helper.canonicalJsonV1(rawPayload)}\n`, "utf8");
    const payloadPath = path.join(tempRoot, `ref-${payload.dispatch_id.slice(0, 12)}.bin`);
    writeFileSync(payloadPath, rawBytes);
    const request = { repoRoot, changeId, roundNumber: payload.round_number, dispatchId: payload.dispatch_id, payloadPath };
    return {
      facade: carryForwardFacadeOutcome(() => helper.captureReviewerOutput(request)),
      cli: carryForwardCliOutcome(runReviewEvidenceCli(tempRoot, repoRoot, "capture-reviewer-output", `${JSON.stringify(request)}\n`)),
      rawPublished: existsSync(evidencePath(repoRoot, `review-${changeId}-raw-r${payload.round_number}-${payload.dispatch_id}.bin`)),
    };
  };
  const refusal = { facade: "raw-payload-invalid", cli: { ok: false, code: "raw-payload-invalid", detail: REVIEWER_PAYLOAD_CHECK_DETAIL }, rawPublished: false };

  const scene = (run) => withRepo(({ tempRoot, repoRoot, mainSha }) => {
    const changeId = "carry-forward-bad-ref";
    const previous = carryForwardRoundOne(helper, { repoRoot, mainSha, changeId, findings: openFindings(1) });
    const { payload } = carryForwardBoundedSuccessor(helper, {
      repoRoot, mainSha, changeId, previous, findings: openFindings(1), commitTag: 507,
    });
    return run({ tempRoot, repoRoot, changeId, previous, payload });
  });
  // Every variant runs in its own scene (a fresh repo), so the raw target paths never
  // collide and the classifier-issued dispatch id stays untouched: the fixture then
  // fails only on the predecessor ref it names, never on a dispatch id that no
  // classifier issued.
  const withRef = (payload, previousReceiptRef) => {
    const next = clone(payload);
    next.lineage.previous_receipt_ref = previousReceiptRef;
    return next;
  };

  await t.test("control: a successor that carries its required set captures against a real predecessor ref", () => {
    scene(({ tempRoot, repoRoot, changeId, payload }) => {
      const outcome = captureWithRef({ tempRoot, repoRoot, changeId, payload });
      assert.deepEqual({ facade: outcome.facade, rawPublished: outcome.rawPublished }, { facade: "returned", rawPublished: true });
    });
  });

  await t.test("the ref digest does not match the sealed predecessor bytes", () => {
    scene(({ tempRoot, repoRoot, changeId, previous, payload }) => {
      const mutated = withRef(payload, { ...previous.ref, digest_sha256: DIGEST_A });
      assert.deepEqual(captureWithRef({ tempRoot, repoRoot, changeId, payload: mutated }), refusal);
    });
  });

  await t.test("the ref names a receipt-shaped file whose bytes are not a receipt", () => {
    scene(({ tempRoot, repoRoot, changeId, payload }) => {
      const garbagePath = `review-${changeId}-receipt-r1-${"d".repeat(64)}.json`;
      const garbage = Buffer.from("not a receipt\n", "utf8");
      writeFileSync(evidencePath(repoRoot, garbagePath), garbage);
      const unreadable = { path: garbagePath, digest_sha256: sha256(garbage) };
      assert.deepEqual(captureWithRef({ tempRoot, repoRoot, changeId, payload: withRef(payload, unreadable) }), refusal);
    });
  });

  await t.test("the ref names a predecessor receipt that does not exist", () => {
    scene(({ tempRoot, repoRoot, changeId, payload }) => {
      const missing = { path: `review-${changeId}-receipt-r1-${"e".repeat(64)}.json`, digest_sha256: DIGEST_A };
      assert.deepEqual(captureWithRef({ tempRoot, repoRoot, changeId, payload: withRef(payload, missing) }), refusal);
    });
  });

  // The ref path is notes-root relative and flat. A path that names a directory level
  // (the natural mistake is a leading "notes/") points at a receipt that does not exist,
  // so it is the same tuple failure, not an untyped ENOENT on the missing directory.
  await t.test("the ref path carries a notes/ prefix in front of the real predecessor receipt", () => {
    scene(({ tempRoot, repoRoot, changeId, previous, payload }) => {
      const prefixed = { path: `notes/${previous.ref.path}`, digest_sha256: previous.ref.digest_sha256 };
      assert.deepEqual(captureWithRef({ tempRoot, repoRoot, changeId, payload: withRef(payload, prefixed) }), refusal);
    });
  });

  await t.test("the ref path names a sub-directory that does not exist", () => {
    scene(({ tempRoot, repoRoot, changeId, payload }) => {
      const nested = { path: `sub/review-${changeId}-receipt-r1-${"e".repeat(64)}.json`, digest_sha256: DIGEST_A };
      assert.deepEqual(captureWithRef({ tempRoot, repoRoot, changeId, payload: withRef(payload, nested) }), refusal);
    });
  });
});

// Direct unit test of the pure function (design D3, tasks T1 direct item B). It is reached
// through the core instance, as refOwnedByChange is, so the module's three-export contract
// stays exactly as asserted by coreApi().
test("predecessorCarryForwardProblem returns the missing required finding IDs, checks only the open part under post-hoc authority, and never rejects a superset", () => {
  const core = coreApi().createReviewRemediationEvidenceCore({});
  assert.equal(
    typeof core.predecessorCarryForwardProblem,
    "function",
    "the core instance must expose predecessorCarryForwardProblem(successorPayload, predecessorPayload, { postHocAuthority })",
  );
  const missing = (successor, predecessor, options) => {
    const problem = core.predecessorCarryForwardProblem(successor, predecessor, options);
    return problem === null ? null : [...problem].sort();
  };
  const closed = (id, overrides = {}) => finding(id, { state: "closed", disposition: "fix-now", ...overrides });
  const critical = (id, { requirementScope, disposition = "fix-now" } = {}) => closed(id, {
    disposition,
    observation: observation(id, { severity: "Critical", ...(requirementScope === undefined ? {} : { requirement_scope: requirementScope }) }),
  });
  const payloadOf = (findings, openFindingIds) => receiptPayload({
    baseSha: DIGEST_A.slice(0, 40), findings, ...(openFindingIds === undefined ? {} : { openFindingIds }),
  });
  const predecessor = payloadOf([
    finding("O1"),
    finding("O2"),
    critical("C-fix"),
    critical("C-ruled", { requirementScope: "scope-unresolved", disposition: "tracked-follow-up" }),
    closed("I-closed"),
  ]);
  assert.deepEqual(predecessor.scope.open_finding_ids, ["O1", "O2"], "precondition: two open findings");
  const both = { postHocAuthority: false };
  const postHoc = { postHocAuthority: true };

  const required = [finding("O1"), finding("O2"), critical("C-fix")];
  assert.equal(missing(payloadOf(required), predecessor, both), null, "the exact required set is complete");
  assert.equal(missing(payloadOf(required), predecessor, postHoc), null);
  assert.equal(missing(payloadOf([...required, finding("N1")]), predecessor, both), null, "a successor's own new finding is allowed");

  assert.deepEqual(missing(payloadOf([finding("O2"), critical("C-fix")]), predecessor, both), ["O1"], "an omitted open finding is named");
  assert.deepEqual(missing(payloadOf([finding("O2"), critical("C-fix")]), predecessor, postHoc), ["O1"], "the open part applies under post-hoc authority");
  assert.deepEqual(missing(payloadOf([finding("O1"), finding("O2")]), predecessor, both), ["C-fix"], "an omitted closed Critical is named");
  assert.equal(missing(payloadOf([finding("O1"), finding("O2")]), predecessor, postHoc), null, "the closed-Critical part is not checked under post-hoc authority");
  assert.deepEqual(missing(payloadOf([finding("O2")]), predecessor, both), ["C-fix", "O1"], "every missing ID is reported");
  assert.deepEqual(missing(payloadOf([finding("O2")]), predecessor, postHoc), ["O1"], "post-hoc authority reports only the open ID");

  assert.equal(missing(payloadOf(required), predecessor, both), null, "the scope-ruled Critical and the closed Important may be omitted");
  assert.equal(
    missing(payloadOf([...required, closed("I-closed"), critical("C-ruled", { requirementScope: "scope-unresolved", disposition: "tracked-follow-up" })]), predecessor, both),
    null,
    "carrying them again is a superset, never a rejection",
  );
  assert.equal(
    missing(payloadOf([finding("O1", { observation: observation("O1") }), closed("O2"), finding("C-fix"), closed("I-closed")]), predecessor, both),
    null,
    "a required finding carried in any state (closed open-part, reopened Critical) is contained by ID",
  );

  // The real frozen historical pair: r11's raw omits r3's closed Critical and keeps r3's open finding.
  const rawText = readFileSync(D30_POST_HOC_R11_OUTPUT_FIXTURE, "utf8");
  const marker = "## reviewerPayload\n\n```json\n";
  const start = rawText.indexOf(marker) + marker.length;
  const frozenSuccessor = JSON.parse(rawText.slice(start, rawText.indexOf("\n```", start)));
  const frozenPredecessor = JSON.parse(readFileSync(
    path.join(D30_POST_HOC_AUTHORITY_FIXTURES, "review-fix-zero-value-review-rounds-receipt-r3.json"),
    "utf8",
  )).reviewer_payload;
  assert.equal(missing(frozenSuccessor, frozenPredecessor, postHoc), null, "the frozen r11 raw passes under post-hoc authority");
  assert.deepEqual(missing(frozenSuccessor, frozenPredecessor, both), ["F-fzvrr-r2-01"], "without post-hoc authority only its omitted closed Critical is reported");
});

// Scenario: Omitted carry-forward finding returns its explicit code with fixed payload detail (D8 item 9)
test("Omitted carry-forward finding returns its explicit code with fixed payload detail: the runtime catalog, the CLI detail map and the help each name predecessor-finding-omitted", () => {
  const { D30_CODES } = coreApi();
  assert.equal(D30_CODES.has(OMITTED_CARRY_FORWARD_CODE), true, "the runtime D30 code catalog contains the explicit code");
  const helperSource = readFileSync(HELPER_PATH, "utf8");
  const assigned = [...helperSource.matchAll(/assignCodes\("([^"]+)", \x60([^\x60]+)\x60\);/gu)]
    .flatMap(([, detailKey, codes]) => codes.trim().split(/\s+/u).map((code) => [code, detailKey]))
    .filter(([code]) => code === OMITTED_CARRY_FORWARD_CODE);
  assert.deepEqual(assigned, [[OMITTED_CARRY_FORWARD_CODE, "reviewer-payload-check"]], "the CLI detail map holds it exactly once, under reviewer-payload-check");
  const help = execFileSync(process.execPath, [HELPER_PATH, "--help"], { encoding: "utf8" });
  const helpLines = help.split("\n");
  const sectionOf = (command) => {
    const first = helpLines.findIndex((line) => line.startsWith(`${command}:`));
    assert.notEqual(first, -1, `help names ${command}`);
    const lines = [helpLines[first]];
    for (let index = first + 1; index < helpLines.length && helpLines[index].startsWith("  "); index += 1) lines.push(helpLines[index]);
    return lines.join("\n");
  };
  for (const command of ["capture-reviewer-output", "build-receipt-request", "seal-receipt"]) {
    assert.match(sectionOf(command), new RegExp(OMITTED_CARRY_FORWARD_CODE, "u"), `${command} help names the code`);
  }
  assert.doesNotMatch(help, /Added domain codes:[^\n]*predecessor-finding-omitted/u, "the Added domain codes line stays the four generic domain codes");
});

// strengthen-review-receipt-carry-forward-compaction T6 (positive, compatibility and
// long-chain tests, design D8 items 3(a)(b), 4, 5, 7, 8): appended after the T1 block
// for the same reason as every block above. They are the next seven tests the change
// adds (indices 259-265); only runner_d4's upper bound moves 258 -> 265.
//
// Unlike T1 these are not red-to-green: the check already exists, so most of them
// would also pass on a tree without it. Each one therefore pins a way the check could
// go wrong in the other direction (reject a legal superset, apply to the shared read
// side, read a predecessor that is not there, let the receipt outgrow its read cap).
function cfFinding(id, { state = "closed", severity = "Important" } = {}) {
  return state === "closed"
    ? finding(id, { state: "closed", disposition: "fix-now", observation: observation(id, { severity }) })
    : finding(id, { observation: observation(id, { severity }) });
}

function cfSealBounded(helper, scene) {
  const { payload } = carryForwardBoundedSuccessor(helper, scene);
  return sealReceipt(helper, { repoRoot: scene.repoRoot, changeId: scene.changeId, reviewerPayload: payload });
}

/** The classifier verdict for the round after `previous`, reduced to the routing fields. */
function cfNextRoute(helper, { repoRoot, mainSha, changeId, previous, commitTag }) {
  const previousPayload = previous.receipt.reviewer_payload;
  const candidateHead = commitRound(repoRoot, commitTag);
  const manifests = sealRoundManifests(helper, {
    repoRoot,
    changeId,
    roundNumber: previousPayload.round_number + 1,
    mainSha,
    surfaceBaseSha: previousPayload.lineage.head_sha,
    candidateHeadSha: candidateHead,
  });
  const result = classifyBounded(helper, {
    repoRoot,
    changeId,
    previousReceipt: previous,
    repairManifest: manifests.repair,
    closureManifest: manifests.closure,
  });
  return {
    route: result.route,
    dispatch_ready: result.dispatch_ready,
    full_reopen_reason: result.full_reopen_reason,
    round_number: result.round_number,
    next_bounded_rereview_count: result.next_bounded_rereview_count,
  };
}

function cfVerifyEverywhere(helper, { tempRoot, repoRoot, changeId, receiptRef }) {
  const verified = helper.verifyReviewRoundReceipt({ repoRoot, receiptRef, changeId });
  const cli = runReviewEvidenceCli(tempRoot, repoRoot, "verify-receipt", `${JSON.stringify({ repoRoot, receiptRef })}\n`);
  assert.equal(cli.status, 0, `verify-receipt CLI: ${cli.stdout}${cli.stderr}`);
  assert.equal(helper.queryReviewStallState({ repoRoot, changeId }).state, "ok", "the chain walk reads the whole chain");
  return verified;
}

const cfIds = (sealed) => sealed.receipt.reviewer_payload.findings.map((entry) => entry.finding_id);

// Scenario: Earlier Closed Findings May Be Omitted And The Chain Still Seals (D8 item 3(a))
test("Earlier Closed Findings May Be Omitted And The Chain Still Seals: (a) a closed Important and a closed Suggestion the predecessor still carries may be omitted, and verify, the chain walk and classify-bounded behave as when they are carried", () => {
  const helper = api();
  const run = (omit) => withRepo(({ tempRoot, repoRoot, mainSha }) => {
    const changeId = "carry-forward-closed-omitted-a";
    const roundOne = carryForwardRoundOne(helper, {
      repoRoot, mainSha, changeId,
      findings: [cfFinding("F-001", { state: "open" }), cfFinding("F-002", { state: "open" }), cfFinding("F-IMP"), cfFinding("F-SUG", { severity: "Suggestion" })],
    });
    const roundTwo = cfSealBounded(helper, {
      repoRoot, mainSha, changeId, previous: roundOne, commitTag: 601,
      findings: [cfFinding("F-001", { state: "open" }), cfFinding("F-002"), cfFinding("F-IMP"), cfFinding("F-SUG", { severity: "Suggestion" })],
    });
    const carried = [cfFinding("F-IMP"), cfFinding("F-SUG", { severity: "Suggestion" })];
    const roundThree = cfSealBounded(helper, {
      repoRoot, mainSha, changeId, previous: roundTwo, commitTag: 602,
      findings: [cfFinding("F-001", { state: "open" }), cfFinding("F-002"), ...(omit ? [] : carried)],
    });
    const verified = cfVerifyEverywhere(helper, { tempRoot, repoRoot, changeId, receiptRef: roundThree.ref });
    assert.deepEqual(verified.receipt, roundThree.receipt);
    return {
      ids: cfIds(roundThree),
      next: cfNextRoute(helper, { repoRoot, mainSha, changeId, previous: roundThree, commitTag: 603 }),
    };
  });
  const omitted = run(true);
  const carried = run(false);
  assert.deepEqual(omitted.ids, ["F-001", "F-002"], "the omitting successor really left both closed findings out");
  assert.deepEqual(carried.ids, ["F-001", "F-002", "F-IMP", "F-SUG"]);
  assert.equal(omitted.next.route, "bounded");
  assert.deepEqual(omitted.next, carried.next, "classify-bounded returns the same route whether the closed findings are carried or omitted");
});

// Scenario: Earlier Closed Findings May Be Omitted And The Chain Still Seals (D8 item 3(b))
test("Earlier Closed Findings May Be Omitted And The Chain Still Seals: (b) a finding that closed before the predecessor and is absent from the predecessor may stay omitted, whatever its severity", async (t) => {
  const helper = api();
  const rows = [
    {
      name: "a closed Important",
      prepare: ({ repoRoot, changeId }) => {
        writeFullRiskChange(repoRoot, changeId);
        commitAll(repoRoot, `fixture ${changeId}`);
        return cfFinding("F-OLD");
      },
    },
    {
      name: "a Critical closed under a TL scope ruling two rounds earlier",
      prepare: ({ repoRoot, changeId }) => prepareRuledChange(helper, { repoRoot, changeId, severity: "Critical" }).entry,
    },
  ];
  for (const row of rows) {
    await t.test(row.name, () => withRepo(({ tempRoot, repoRoot, mainSha }) => {
      const changeId = `carry-forward-closed-omitted-b-${rows.indexOf(row)}`;
      const earlier = row.prepare({ repoRoot, changeId });
      const roundOne = sealInitial(helper, {
        repoRoot, mainSha, changeId, findings: [earlier, cfFinding("F-001", { state: "open" }), cfFinding("F-002", { state: "open" })],
      });
      const roundTwo = cfSealBounded(helper, {
        repoRoot, mainSha, changeId, previous: roundOne, commitTag: 611,
        findings: [cfFinding("F-001", { state: "open" }), cfFinding("F-002")],
      });
      assert.equal(cfIds(roundTwo).includes(earlier.finding_id), false, "precondition: the predecessor no longer carries the earlier closed finding");
      const roundThree = cfSealBounded(helper, {
        repoRoot, mainSha, changeId, previous: roundTwo, commitTag: 612,
        findings: [cfFinding("F-001", { state: "open" })],
      });
      assert.equal(cfIds(roundThree).includes(earlier.finding_id), false);
      cfVerifyEverywhere(helper, { tempRoot, repoRoot, changeId, receiptRef: roundThree.ref });
    }));
  }
});

// Scenario: Carried Closed Findings Stay Valid And May Reopen (D8 item 4)
test("Carried Closed Findings Stay Valid And May Reopen: a re-carried closed finding seals closed with its Critical revalidated at the new HEAD, and a reopened one seals but is not stall progress", async (t) => {
  const helper = api();

  await t.test("an earlier closed finding carried again keeps its closed state and a carried closed Critical passes the bound-HEAD checks", () => {
    withRepo(({ tempRoot, repoRoot, mainSha }) => {
      const changeId = "carry-forward-closed-recarried";
      const roundOne = carryForwardRoundOne(helper, {
        repoRoot, mainSha, changeId,
        findings: [cfFinding("F-001", { state: "open" }), cfFinding("F-002", { state: "open" }), cfFinding("F-X"), t17ClosureFinding("F-CRIT")],
      });
      const roundTwo = cfSealBounded(helper, {
        repoRoot, mainSha, changeId, previous: roundOne, commitTag: 621,
        findings: [cfFinding("F-001", { state: "open" }), cfFinding("F-002"), t17ClosureFinding("F-CRIT")],
      });
      assert.equal(cfIds(roundTwo).includes("F-X"), false, "precondition: the predecessor omitted F-X");
      const roundThree = cfSealBounded(helper, {
        repoRoot, mainSha, changeId, previous: roundTwo, commitTag: 622,
        findings: [cfFinding("F-001", { state: "open" }), cfFinding("F-002"), cfFinding("F-X"), t17ClosureFinding("F-CRIT")],
      });
      const byId = new Map(roundThree.receipt.reviewer_payload.findings.map((entry) => [entry.finding_id, entry]));
      assert.equal(byId.get("F-X").state, "closed");
      assert.equal(byId.get("F-CRIT").state, "closed");
      assert.notEqual(roundThree.receipt.reviewer_payload.lineage.head_sha, roundOne.receipt.reviewer_payload.lineage.head_sha, "the Critical is judged at a later HEAD");
      cfVerifyEverywhere(helper, { tempRoot, repoRoot, changeId, receiptRef: roundThree.ref });
    });
  });

  await t.test("a carried closed Critical whose anchor is gone at the successor HEAD is refused by the closure check, not by the carry-forward check", () => {
    withRepo(({ repoRoot, mainSha }) => {
      const changeId = "carry-forward-closed-critical-stale";
      const roundOne = carryForwardRoundOne(helper, {
        repoRoot, mainSha, changeId, findings: [cfFinding("F-001", { state: "open" }), t17ClosureFinding("F-CRIT")],
      });
      write(repoRoot, "src/review-target.mjs", "export const renamedTarget = true;\n");
      commitAll(repoRoot, "the anchored carrier moved on");
      const { payload } = carryForwardBoundedSuccessor(helper, {
        repoRoot, mainSha, changeId, previous: roundOne, commitTag: 623,
        findings: [cfFinding("F-001", { state: "open" }), t17ClosureFinding("F-CRIT")],
      });
      const refusal = (() => {
        try { sealReceipt(helper, { repoRoot, changeId, reviewerPayload: payload }); return null; } catch (error) { return error; }
      })();
      assert.ok(refusal instanceof CoreFailure, "the stale anchor is refused");
      assert.equal(refusal.code, "receipt-evidence-invalid", "the closure check owns the refusal, not the carry-forward check");
      assert.match(refusal.message, /Critical closure anchor is stale or absent from its bound-HEAD carrier/u);
    });
  });

  await t.test("a carried closed finding reopened as open seals, and its blocking id is not counted as clearance by the stall projection", () => {
    const stallStreak = (reopen) => withRepo(({ tempRoot, repoRoot, mainSha }) => {
      const changeId = `carry-forward-reopen-${reopen ? "open" : "closed"}`;
      const roundOne = carryForwardRoundOne(helper, {
        repoRoot, mainSha, changeId,
        findings: [cfFinding("F-001", { state: "open" }), cfFinding("F-002", { state: "open" }), t17ClosureFinding("F-CRIT")],
      });
      const critical = reopen
        ? finding("F-CRIT", { observation: t17ClosureFinding("F-CRIT").observation })
        : t17ClosureFinding("F-CRIT");
      const roundTwo = cfSealBounded(helper, {
        repoRoot, mainSha, changeId, previous: roundOne, commitTag: 624,
        findings: [cfFinding("F-001", { state: "open" }), cfFinding("F-002"), critical],
      });
      const sealedCritical = roundTwo.receipt.reviewer_payload.findings.find((entry) => entry.finding_id === "F-CRIT");
      assert.deepEqual([sealedCritical.state, sealedCritical.disposition], reopen ? ["open", null] : ["closed", "fix-now"]);
      cfVerifyEverywhere(helper, { tempRoot, repoRoot, changeId, receiptRef: roundTwo.ref });
      return helper.queryReviewStallState({ repoRoot, changeId }).streak;
    });
    assert.equal(stallStreak(false), 0, "closing F-002 while F-CRIT stays closed is clearance");
    assert.equal(stallStreak(true), 1, "closing F-002 while F-CRIT is reopened is not clearance");
  });
});

// Scenario: Initial And Restarted Chains Skip The Check (D8 item 5)
test("Initial And Restarted Chains Skip The Check: a null previous_receipt_ref seals in capture, build and seal without any predecessor receipt being read", async (t) => {
  const helper = api();
  const recordedCore = () => {
    const opened = [];
    const core = coreApi().createReviewRemediationEvidenceCore({
      fsOps: { openSync(target, ...args) { opened.push(String(target)); return openSync(target, ...args); } },
    });
    return { core, receiptOpens: () => opened.filter((target) => /-receipt-r\d+/u.test(path.basename(target))) };
  };
  const recapture = ({ tempRoot, repoRoot, changeId, sealed, core }) => {
    const payload = sealed.receipt.reviewer_payload;
    const rawPath = path.join(mainNotesRoot(repoRoot), payload.output_evidence.raw_payload_ref.path);
    const payloadPath = path.join(tempRoot, `recapture-${payload.dispatch_id.slice(0, 12)}.bin`);
    writeFileSync(payloadPath, readFileSync(rawPath));
    return core.captureReviewerOutput({
      repoRoot, changeId, roundNumber: payload.round_number, dispatchId: payload.dispatch_id, payloadPath,
    });
  };

  await t.test("round one with a null previous_receipt_ref", () => {
    withRepo(({ tempRoot, repoRoot, mainSha }) => {
      const changeId = "carry-forward-initial-skip";
      const sealed = carryForwardRoundOne(helper, { repoRoot, mainSha, changeId, findings: [finding("F-001")] });
      assert.equal(sealed.receipt.reviewer_payload.lineage.previous_receipt_ref, null);
      const { core, receiptOpens } = recordedCore();
      const ref = recapture({ tempRoot, repoRoot, changeId, sealed, core });
      assert.deepEqual(ref, sealed.receipt.reviewer_payload.output_evidence.raw_payload_ref);
      assert.deepEqual(receiptOpens(), [], "no receipt file is opened to check a round one payload");
    });
  });

  await t.test("a missing_predecessor_seal restart: only a mutable review note exists, and the restarted round one seals without reading it", () => {
    withRepo(({ tempRoot, repoRoot, mainSha }) => {
      const changeId = "carry-forward-restart-skip";
      writeFullRiskChange(repoRoot, changeId);
      commitAll(repoRoot, "restart baseline");
      const mutableNote = path.join(mainNotesRoot(repoRoot), `review-${changeId}-r1.md`);
      writeFileSync(mutableNote, "# earlier review (mutable, never sealed)\n\nopen: F-OLD-001 Important\n");
      const dispatch = initialClassification(helper, { repoRoot, changeId });
      assertDispatchableResult(dispatch, { route: "full", count: 0, round: 1, reason: "initial_review" });
      const sealed = sealReceipt(helper, {
        repoRoot,
        changeId,
        reviewerPayload: payloadFromDispatch(dispatch, {
          changeId,
          baseSha: mainSha,
          mergeBaseSha: mainSha,
          headSha: git(repoRoot, ["rev-parse", "HEAD"]),
          findings: [],
        }),
      });
      assert.equal(sealed.receipt.reviewer_payload.lineage.previous_receipt_ref, null);
      assert.deepEqual(sealed.receipt.reviewer_payload.findings, [], "the restart does not have to mention the mutable note's finding");
      const { core, receiptOpens } = recordedCore();
      recapture({ tempRoot, repoRoot, changeId, sealed, core });
      assert.deepEqual(receiptOpens(), []);
      cfVerifyEverywhere(helper, { tempRoot, repoRoot, changeId, receiptRef: sealed.ref });
    });
  });

  await t.test("control: a round two payload does make the check read its predecessor receipt", () => {
    withRepo(({ tempRoot, repoRoot, mainSha }) => {
      const changeId = "carry-forward-skip-control";
      const roundOne = carryForwardRoundOne(helper, { repoRoot, mainSha, changeId, findings: [finding("F-001")] });
      const roundTwo = cfSealBounded(helper, {
        repoRoot, mainSha, changeId, previous: roundOne, commitTag: 631, findings: [finding("F-001")],
      });
      const { core, receiptOpens } = recordedCore();
      recapture({ tempRoot, repoRoot, changeId, sealed: roundTwo, core });
      assert.ok(receiptOpens().some((target) => target.endsWith(roundOne.ref.path)), "the recorder does see a predecessor read when there is one");
    });
  });
});

// Hand-writes a sealed receipt for a payload exactly as an older tool left it: the raw
// carrier, the envelope and the commit marker, with no capture and no seal call.
function cfWriteLegacyReceipt(helper, { repoRoot, changeId, payload }) {
  const sealedPayload = clone(payload);
  sealedPayload.review_authority = { kind: "tl-direct-review" };
  const rawPayload = clone(payload);
  rawPayload.review_authority = null;
  rawPayload.output_evidence = null;
  const rawBytes = Buffer.from(`${helper.canonicalJsonV1(rawPayload)}\n`, "utf8");
  const rawName = `review-${changeId}-raw-r${payload.round_number}-${payload.dispatch_id}.bin`;
  writeFileSync(evidencePath(repoRoot, rawName), rawBytes);
  sealedPayload.output_evidence = {
    raw_payload_ref: { path: rawName, digest_sha256: sha256(rawBytes) },
    raw_payload_sha256: sha256(rawBytes),
    verdict_open_set_sha256: sha256(helper.canonicalJsonV1({
      verdict: sealedPayload.verdict,
      open_finding_ids: sealedPayload.scope.open_finding_ids,
    })),
  };
  const receipt = resignReceiptEnvelope(helper, {
    schema: REVIEW_RECEIPT_SCHEMA,
    receipt_digest_sha256: null,
    observation_hashes: [],
    reviewer_payload: sealedPayload,
  });
  const targetPath = receiptTarget(repoRoot, changeId, payload.round_number, payload.dispatch_id);
  const ref = writeReceiptEnvelope(helper, targetPath, receipt);
  writeReceiptCommitMarkerFixture(helper, { repoRoot, receipt, receiptRef: ref });
  return { receipt, targetPath, ref };
}

// Scenario: Historical Receipts Keep Their Verification Result (D8 item 7)
test("Historical Receipts Keep Their Verification Result: a sealed successor that omits a predecessor open finding still verifies, walks and classifies, and a compliant successor seals on top of it", () => {
  const helper = api();
  withRepo(({ tempRoot, repoRoot, mainSha }) => {
    const changeId = "carry-forward-historical";
    const roundOne = carryForwardRoundOne(helper, {
      repoRoot, mainSha, changeId, findings: [cfFinding("F-001", { state: "open" }), cfFinding("F-002", { state: "open" })],
    });
    const { payload } = carryForwardBoundedSuccessor(helper, {
      repoRoot, mainSha, changeId, previous: roundOne, commitTag: 641, findings: [cfFinding("F-001", { state: "open" })],
    });
    assert.deepEqual(roundOne.receipt.reviewer_payload.scope.open_finding_ids, ["F-001", "F-002"]);
    assert.equal(payload.findings.some((entry) => entry.finding_id === "F-002"), false, "precondition: the successor omits a predecessor open finding");
    assert.deepEqual(
      [...coreApi().createReviewRemediationEvidenceCore({}).predecessorCarryForwardProblem(
        payload, roundOne.receipt.reviewer_payload, { postHocAuthority: false },
      )],
      ["F-002"],
      "precondition: the current producer would refuse this successor",
    );
    const legacy = cfWriteLegacyReceipt(helper, { repoRoot, changeId, payload });

    const verified = cfVerifyEverywhere(helper, { tempRoot, repoRoot, changeId, receiptRef: legacy.ref });
    assert.deepEqual(verified.receipt, legacy.receipt, "the historical receipt verifies exactly as written");
    assert.deepEqual(helper.queryReviewStallState({ repoRoot, changeId }), { state: "ok", streak: 0 });
    // The scene asserts a dispatchable bounded route before it returns: classify-bounded still
    // accepts the historical receipt as a predecessor.
    const scene = carryForwardBoundedSuccessor(helper, {
      repoRoot, mainSha, changeId, previous: legacy, commitTag: 642, findings: [cfFinding("F-001", { state: "open" })],
    });
    assert.deepEqual([scene.dispatch.route, scene.dispatch.dispatch_ready], ["bounded", true]);
    const compliant = sealReceipt(helper, { repoRoot, changeId, reviewerPayload: scene.payload });
    assert.equal(compliant.receipt.reviewer_payload.lineage.previous_receipt_ref.digest_sha256, legacy.ref.digest_sha256);
    cfVerifyEverywhere(helper, { tempRoot, repoRoot, changeId, receiptRef: compliant.ref });
  });
});

/** The bytes durableSeal writes for a receipt, rebuilt from the public record shape
 * (core's receiptRecordBytes is module-internal and stays so). */
function cfReceiptBytes(helper, payload) {
  return Buffer.from(`${helper.canonicalJsonV1({
    schema: REVIEW_RECEIPT_SCHEMA,
    receipt_digest_sha256: sha256(helper.canonicalJsonV1(payload)),
    observation_hashes: receiptObservationHashes(helper, payload.findings),
    reviewer_payload: payload,
  })}\n`, "utf8");
}

// Sized so that carrying every earlier finding lands at about 259.7 KB at round 26, the
// measurement of the real chain this scenario models (the cap is 262,144 bytes).
const CF_LITE_DETAIL_BYTES = 2746;
const cfLiteFinding = (id, severity) => finding(id, {
  state: "closed",
  disposition: "fix-now",
  observation: observation(id, { severity, detail: `${id} `.padEnd(CF_LITE_DETAIL_BYTES, "x") }),
});

// Scenario: Long Chain Receipt Size Tracks Carried Findings Not Round Count (D8 item 8)
test("Long Chain Receipt Size Tracks Carried Findings Not Round Count: the lite trajectory stays under RECEIPT_SCAN_MAX_BYTES through round 30 while carrying every earlier finding exceeds it before round 30", () => {
  const helper = api();
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "carry-forward-long-chain-size";
    const template = carryForwardRoundOne(helper, { repoRoot, mainSha, changeId, findings: [finding("F-001")] });
    const skeleton = template.receipt.reviewer_payload;
    assert.equal(
      cfReceiptBytes(helper, skeleton).length,
      readFileSync(template.targetPath).length,
      "calibration: the rebuilt serialization is byte-identical to what a real seal writes",
    );
    const scanCap = coreApi().createReviewRemediationEvidenceCore({}).RECEIPT_SCAN_MAX_BYTES;
    assert.equal(scanCap, 256 * 1024, "the cap itself is not what keeps the chain small");

    const critical = [t17ClosureFinding("F-CRIT-1"), t17ClosureFinding("F-CRIT-2")];
    const ownFindings = (round) => (round === 1
      ? Array.from({ length: 8 }, (_, index) => cfLiteFinding(`S-1-${index}`, "Suggestion"))
      : Array.from({ length: 3 }, (_, index) => cfLiteFinding(`S-${round}-${index}`, "Suggestion")));
    const sizeOf = (round, findings) => {
      const payload = clone(skeleton);
      payload.round_number = round;
      payload.findings = findings;
      payload.scope.open_finding_ids = [];
      return cfReceiptBytes(helper, payload).length;
    };
    const everyEarlier = [...critical];
    const sizes = { lite: [], carryAll: [] };
    for (let round = 1; round <= 30; round += 1) {
      const own = ownFindings(round);
      everyEarlier.push(...own);
      sizes.carryAll.push(sizeOf(round, clone(everyEarlier)));
      sizes.lite.push(sizeOf(round, [...clone(critical), ...own]));
    }
    const cap = scanCap;
    assert.ok(Math.max(...sizes.lite) < cap, `the lite chain stays below the cap (max ${Math.max(...sizes.lite)})`);
    assert.ok(sizes.lite[29] <= sizes.lite[1] + 1024, "a round 30 receipt is no larger than a round 2 receipt: size follows the carried set, not the round count");
    const firstOver = sizes.carryAll.findIndex((size) => size > cap) + 1;
    assert.ok(sizes.carryAll[25] > 255 * 1000 && sizes.carryAll[25] < cap, `the model reproduces the measured 26-round size (${sizes.carryAll[25]})`);
    assert.ok(firstOver >= 26 && firstOver < 30, `carrying every earlier finding crosses the cap around round 27, as the 26-round chain nearly did (first over at round ${firstOver})`);
    assert.ok(sizes.carryAll[29] > cap);
  });
});

test("Long Chain Receipt Size Tracks Carried Findings Not Round Count: a four-round chain that carries only the required set seals end to end and every receipt names exactly the required set plus its own findings", () => {
  const helper = api();
  withRepo(({ tempRoot, repoRoot, mainSha }) => {
    const changeId = "carry-forward-short-chain";
    const critical = () => [t17ClosureFinding("F-CRIT-1"), t17ClosureFinding("F-CRIT-2")];
    const suggestion = (id) => cfFinding(id, { severity: "Suggestion" });
    const roundOne = carryForwardRoundOne(helper, {
      repoRoot, mainSha, changeId,
      findings: [cfFinding("F-001", { state: "open" }), cfFinding("F-002", { state: "open" }), cfFinding("F-003", { state: "open" }), ...critical(), suggestion("S-1")],
    });
    const roundTwo = cfSealBounded(helper, {
      repoRoot, mainSha, changeId, previous: roundOne, commitTag: 651,
      findings: [cfFinding("F-001", { state: "open" }), cfFinding("F-002", { state: "open" }), cfFinding("F-003"), ...critical(), suggestion("S-2")],
    });
    const roundThree = cfSealBounded(helper, {
      repoRoot, mainSha, changeId, previous: roundTwo, commitTag: 652,
      findings: [cfFinding("F-001", { state: "open" }), cfFinding("F-002"), ...critical(), suggestion("S-3")],
    });
    const roundFour = cfSealBounded(helper, {
      repoRoot, mainSha, changeId, previous: roundThree, commitTag: 653,
      findings: [cfFinding("F-001"), ...critical(), suggestion("S-4")],
    });
    assert.deepEqual(cfIds(roundTwo), ["F-001", "F-002", "F-003", "F-CRIT-1", "F-CRIT-2", "S-2"]);
    assert.deepEqual(cfIds(roundThree), ["F-001", "F-002", "F-CRIT-1", "F-CRIT-2", "S-3"]);
    assert.deepEqual(cfIds(roundFour), ["F-001", "F-CRIT-1", "F-CRIT-2", "S-4"]);
    assert.deepEqual(roundFour.receipt.reviewer_payload.scope.open_finding_ids, []);
    // The newest receipt's verification walks the whole chain back to round one.
    cfVerifyEverywhere(helper, { tempRoot, repoRoot, changeId, receiptRef: roundFour.ref });
    assert.ok(
      readFileSync(roundFour.targetPath).length <= readFileSync(roundOne.targetPath).length,
      "the receipt does not grow with the round number once earlier closed findings are left out",
    );
  });
});

// F-rrcf-r1-04: only the predecessor receipt file's own absence is a dispatch-tuple
// failure. An ENOENT raised anywhere else while the predecessor is being read or
// validated (admission record, attestation, git object, notes root) is a native
// I/O fault and stays untyped, like every other native fault.
test("Raw Reviewer Capture Rejects Invalid Bytes Before Immutable Publication: only the absence of the predecessor receipt file itself maps to raw-payload-invalid, an ENOENT elsewhere stays untyped", () => {
  const helper = api();
  withRepo(({ tempRoot, repoRoot, mainSha }) => {
    const changeId = "carry-forward-enoent-scope";
    const roundOne = carryForwardRoundOne(helper, { repoRoot, mainSha, changeId, findings: [cfFinding("F-001", { state: "open" })] });
    const { payload } = carryForwardBoundedSuccessor(helper, {
      repoRoot, mainSha, changeId, previous: roundOne, commitTag: 661, findings: [cfFinding("F-001", { state: "open" })],
    });
    const rawPayload = clone(payload);
    rawPayload.review_authority = null;
    rawPayload.output_evidence = null;
    const payloadPath = path.join(tempRoot, "enoent-scope.bin");
    writeFileSync(payloadPath, Buffer.from(`${helper.canonicalJsonV1(rawPayload)}\n`, "utf8"));
    const request = { repoRoot, changeId, roundNumber: payload.round_number, dispatchId: payload.dispatch_id, payloadPath };
    const rawTarget = evidencePath(repoRoot, `review-${changeId}-raw-r${payload.round_number}-${payload.dispatch_id}.bin`);
    const coreThatFailsPredecessorRead = (fault) => coreApi().createReviewRemediationEvidenceCore({
      fsOps: { openSync(target, ...args) { if (path.basename(String(target)) === roundOne.ref.path) throw fault; return openSync(target, ...args); } },
    });

    const elsewhere = Object.assign(new Error("ENOENT: no such file or directory, open 'admission-record.json'"), {
      code: "ENOENT", path: path.join(repoRoot, "openspec", "changes", changeId, "admission-records", "absent.json"),
    });
    assert.throws(
      () => coreThatFailsPredecessorRead(elsewhere).captureReviewerOutput(request),
      (error) => error === elsewhere,
      "an ENOENT whose path is not the predecessor receipt file stays the untyped native fault",
    );
    assert.equal(existsSync(rawTarget), false, "nothing is published on that fault");

    const own = Object.assign(new Error("ENOENT: no such file or directory, lstat predecessor"), { code: "ENOENT", path: roundOne.targetPath });
    assert.equal(
      carryForwardFacadeOutcome(() => coreThatFailsPredecessorRead(own).captureReviewerOutput(request)),
      "raw-payload-invalid",
      "control: the predecessor receipt file's own absence is raw-payload-invalid",
    );
    assert.equal(existsSync(rawTarget), false);

    assert.deepEqual(
      helper.captureReviewerOutput(request).path,
      path.basename(rawTarget),
      "control: with no fault the same request publishes",
    );
  });
});

// ---------------------------------------------------------------------------
// strengthen-continuation-receipt-chain-verification (T1-T3, appended at the very
// end of the file; only runner_d4's upper bound moves). A `SendMessage` /
// `followup_task` continuation writes a `cooperative-only` v1 admission record
// (`instance_mode: continue`, `parent_record_id` -> the record it continues).
// The receipt gate must accept it only through a verified chain back to a
// host-verified generic fresh root; every other authority path keeps its result.
// ---------------------------------------------------------------------------

const CONTINUATION_CHAIN_BASE_MS = Date.parse("2026-10-01T00:00:00.000Z");
const CONTINUATION_CHAIN_STEP_MS = 60_000;
const CONTINUATION_CHAIN_FIELDS = Object.freeze({
  objective: "independent-judgment",
  responsibility_id: "primary-review",
  instance_mode: "fresh",
  evidence_scope: "local diff",
  return_and_stop: "return findings and stop",
  role: "dp-reviewer",
});

// The named hop bound is read from the production constant so a future change of
// the bound moves P3 (exactly the bound) and F8 (bound + 1) together instead of
// leaving them testing a stale number.
function continuationChainMaxHops() {
  const match = /const ADMISSION_CHAIN_MAX_HOPS = (\d+);/u.exec(readFileSync(CORE_PATH, "utf8"));
  assert.notEqual(match, null, "the core module must keep a named ADMISSION_CHAIN_MAX_HOPS constant");
  return Number(match[1]);
}

// Builds a continuation chain with the production `writeAdmissionRecord` writer
// from ONE linked worktree (root first, then `hops` continuation records, each
// naming the previous record as `parent_record_id`; `now` is injected and
// strictly increasing unless `atMs` says otherwise), mirrors the records into the
// main checkout the receipt tests seal from, and returns every record as
// `{ record_id, digest, record }` read back through `readAdmissionRecord`.
// `existingRoot` starts the chain from a record that is already mirrored into
// `repoRoot` (for example the v2 record `preparedRuntimeAdmissionFixture` makes).
function genericV1ContinuationChainFixture({ repoRoot, changeId }, {
  hops = 1,
  rootRoleBinding = "host-verified",
  rootFields = {},
  hopFields = () => ({}),
  atMs = (index) => CONTINUATION_CHAIN_BASE_MS + index * CONTINUATION_CHAIN_STEP_MS,
  existingRoot = null,
} = {}) {
  const cwd = path.join(path.dirname(repoRoot), ".worktree", changeId);
  mkdirSync(path.dirname(cwd), { recursive: true });
  git(repoRoot, ["worktree", "add", "--quiet", "--detach", cwd, "HEAD"]);
  const recordIds = [];
  try {
    const write = (fields, roleBinding, index) => {
      const written = writeAdmissionRecord({
        cwd,
        host: "claude-code",
        prompt: "generic v1 continuation chain fixture prompt",
        fields: { ...CONTINUATION_CHAIN_FIELDS, ...fields },
        roleBinding,
        now: () => new Date(atMs(index)),
      });
      assert.equal(written.ok, true, written.code);
      recordIds.push(written.record_id);
      return written;
    };
    if (existingRoot === null) {
      write(rootFields, rootRoleBinding, 0);
    } else {
      recordIds.push(existingRoot.record_id);
    }
    for (let hop = 1; hop <= hops; hop += 1) {
      write(
        { instance_mode: "continue", parent_record_id: recordIds.at(-1), ...hopFields(hop) },
        "cooperative-only",
        hop,
      );
    }
    cpSync(
      path.join(cwd, "openspec", "changes", changeId, "admission-records"),
      path.join(repoRoot, "openspec", "changes", changeId, "admission-records"),
      { recursive: true },
    );
  } finally {
    git(repoRoot, ["worktree", "remove", "--force", cwd]);
  }
  const chain = recordIds.map((recordId) => {
    const read = readAdmissionRecord({ repoRoot, changeId, recordId });
    assert.equal(read.ok, true, read.code);
    return { record_id: recordId, digest: read.digest, record: read.record };
  });
  return { chain, root: chain[0], leaf: chain.at(-1) };
}

function continuationRecordsDir(repoRoot, changeId) {
  return path.join(repoRoot, "openspec", "changes", changeId, "admission-records");
}

// A raw writer for record shapes `writeAdmissionRecord` refuses to produce (the
// cycle in F7), serialized exactly the way the production writer does.
function writeContinuationRawRecord(repoRoot, changeId, record) {
  writeFileSync(
    path.join(continuationRecordsDir(repoRoot, changeId), `${record.record_id}.json`),
    `${JSON.stringify(record, null, 2)}\n`,
    { mode: 0o600 },
  );
}

// Returns the thrown error (or null) so a case can assert on the three public
// entry points without one aborting the others.
function continuationThrownBy(action) {
  try {
    action();
  } catch (error) {
    return error;
  }
  return null;
}

// Runs one step of a legitimate chain and turns an unexpected failure into a
// named positive-premise failure (so a negative case can never pass vacuously
// against an implementation that rejects every continuation).
function continuationMustSucceed(label, action) {
  try {
    return action();
  } catch (error) {
    assert.fail(`${label}: a legitimate continuation chain must succeed, got ${error?.code ?? error?.name}: ${error?.message}`);
  }
}

function continuationClaimDir(repoRoot, changeId, recordId) {
  return path.join(continuationRecordsDir(repoRoot, changeId), `${recordId}.claim`);
}

// Positive premise P1/P2 shared by every case: build -> seal -> verify with
// `requireIndependence`, the runtime-agent attribution, and a claim on the leaf
// only (never on an ancestor).
function sealAndVerifyContinuationChain(helper, { repoRoot, changeId, mainSha, chain }) {
  const { leaf } = chain;
  const payload = runtimeAgentPayload(helper, { repoRoot, changeId, mainSha, findings: [] });
  const rawPayloadRef = writeGenericV1RawPayload(helper, { repoRoot, payload });
  const built = continuationMustSucceed("build-receipt-request", () => helper.buildReviewRoundReceiptRequest({
    repoRoot,
    changeId,
    rawPayloadRef,
    admissionRecordId: leaf.record_id,
  }));
  assert.deepEqual(built.reviewerPayload.review_authority, genericV1OnePieceAuthority(leaf));
  assert.equal(existsSync(continuationClaimDir(repoRoot, changeId, leaf.record_id)), false, "building never claims the continuation record");
  const sealed = continuationMustSucceed("seal-receipt", () => helper.sealReviewRoundReceipt(built));
  assert.equal(sealed.receipt.schema, REVIEW_RECEIPT_SCHEMA);
  assert.deepEqual(sealed.receipt.reviewer_payload.reviewer_identity, { role: "dp-reviewer", executor_kind: "runtime-agent" });
  assert.equal(existsSync(continuationClaimDir(repoRoot, changeId, leaf.record_id)), true, "sealing claims the continuation record");
  for (const ancestor of chain.chain.slice(0, -1)) {
    assert.equal(existsSync(continuationClaimDir(repoRoot, changeId, ancestor.record_id)), false, "an ancestor record is never claimed");
  }
  const verified = continuationMustSucceed("verify-receipt", () => helper.verifyReviewRoundReceipt({
    repoRoot,
    receiptRef: sealed.ref,
    requireIndependence: true,
  }));
  assert.equal(verified.executor_attribution, "runtime-agent");
  return { payload, built, sealed, verified };
}

// T1 (I5 characterization). A historical v2 receipt binds `executor_evidence`
// straight to the admission record. v2 sealing no longer exists, so the receipt is
// composed by bytes (the `continueChain` / `sealRuntimeAgent` shapes of the v2
// tests deleted in afc8aaeb3, rebuilt over the production writers); the claim is
// written by the production `claimAdmissionRecord`. The chain is two hops deep and
// roots in a `cooperative-only` fresh record (the D13 shape): the v2 walker
// accepts it today and must keep accepting it, while `requireIndependence` keeps
// returning `ordinary-review-not-independent` for every v2 receipt.
//
// The same scenario covers these existing regression tests, which this change
// does not edit and which must stay green:
//   I1 `generic v1 …` groups (host-verified fresh v1 record, e.g. "generic v1 runtime
//      receipt: builder derives a one-piece authority …"),
//   I2 "generic v1 role binding: …" (cooperative-only fresh/fork leaf stays rejected),
//   I3 `Unresolved Binding Leaves Review And Verify Unsealable`
//      (main-cwd-receipt-round-trip.test.mjs),
//   I4 "v3 normal runtime receipt binds prepared intent, admission v2, raw output, …"
//      (Codex prepared-intent two-piece path),
//   I6 "historical walkReceiptAuthorityChain and cross-tip continuation after tip SSOT
//      switch …" (lineage traversal),
//   I7 `continue records do not inflate work_lane_fresh_total …`
//      (session-usage-lineage.test.mjs).
test("Continuation Acceptance Leaves Other Authority Paths Unchanged: a historical v2 executor_evidence receipt bound to a two-hop cooperative-only-rooted chain still verifies and still fails requireIndependence (I5 characterization)", () => {
  const helper = api();
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "cont-chain-v2-executor-evidence";
    boundChange(repoRoot, changeId);
    const chain = genericV1ContinuationChainFixture({ repoRoot, changeId }, { hops: 2, rootRoleBinding: "cooperative-only" });
    assert.equal(chain.chain.length, 3, "root plus two continuation hops");
    assert.equal(chain.root.record.role_binding, "cooperative-only");
    assert.equal(chain.leaf.record.instance_mode, "continue");
    assert.equal(chain.leaf.record.parent_record_id, chain.chain[1].record_id);

    const reviewerPayload = runtimeAgentPayload(helper, { repoRoot, changeId, mainSha, findings: [] });
    bindReceiptAuthority(helper, { repoRoot, changeId, reviewerPayload });
    delete reviewerPayload.review_authority;
    delete reviewerPayload.output_evidence;
    delete reviewerPayload.execution_root_head;
    reviewerPayload.reviewer_identity = {
      role: "dp-reviewer",
      executor_kind: "runtime-agent",
      executor_evidence: {
        admission_record_id: chain.leaf.record_id,
        admission_record_sha256: chain.leaf.digest,
        dispatch_id_sha256: reviewerPayload.dispatch_id,
      },
    };
    const claimed = claimAdmissionRecord({
      repoRoot,
      changeId,
      recordId: chain.leaf.record_id,
      claim: {
        round_number: reviewerPayload.round_number,
        head_sha: reviewerPayload.lineage.head_sha,
        responsibility_id: reviewerPayload.responsibility_id,
        dispatch_id: reviewerPayload.dispatch_id,
      },
    });
    assert.equal(claimed.ok, true, claimed.code);
    const receipt = {
      schema: REVIEW_RECEIPT_SCHEMA_V2,
      receipt_digest_sha256: sha256(helper.canonicalJsonV1(reviewerPayload)),
      observation_hashes: receiptObservationHashes(helper, reviewerPayload.findings),
      reviewer_payload: reviewerPayload,
    };
    const ref = writeReceiptEnvelope(helper, evidencePath(repoRoot, `review-${changeId}-receipt-r1.json`), receipt);

    const verified = helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: ref });
    assert.equal(verified.receipt.schema, REVIEW_RECEIPT_SCHEMA_V2);
    assert.equal(verified.executor_attribution, "runtime-agent");
    assert.throws(
      () => helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: ref, requireIndependence: true }),
      coreFailureIs("ordinary-review-not-independent"),
      "a v2 receipt never satisfies requireIndependence, whatever its chain",
    );

    // Positive premise for the walker: changing a deep ancestor's responsibility_id
    // turns the same receipt into a failure, so the fixture really runs through
    // the chain walk and the passes above are not vacuous.
    rewriteGenericV1Record(repoRoot, changeId, chain.root.record_id, (record) => {
      record.responsibility_id = "other-deliverable";
    });
    assert.throws(
      () => helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: ref }),
      (error) => coreFailureIs("receipt-evidence-invalid")(error) && /admission chain parent responsibility_id mismatch/u.test(error.message),
      "the v2 chain walk still reports a broken ancestor through the v2 receipt-evidence-invalid wrapper",
    );
  });

  // I2 for a fork leaf: a cooperative-only record that is not a declared `continue`
  // keeps the original closed code on every public entry point (the existing I2
  // test covers the fresh and wrong-role leaves on the build side only). No positive
  // premise here: it would seal a continuation chain, which only the new core can do,
  // and this test must stay green on the base core (F13's control and P1 carry it).
  runContinuationFaultCase(helper, "i2-fork-leaf", { entries: ["build", "seal", "verify"], premise: false });
});

// T2 red matrix. Every case below arranges ONE fault in an otherwise legitimate
// chain, drives the public entry points (build-receipt-request, seal-receipt,
// verify-receipt) and asserts the design D12 expected code, the closed reason and
// the absence of any seal artifact; then it runs the same fixture shape without the
// fault as the positive premise, so a negative can never pass because every
// continuation is rejected. Chain faults (walker rejection or root check) all
// report `receipt-authority-invalid`; the leaf content-to-ID failure of F11 keeps
// `receipt-identity-authority-mismatch`.
const CONTINUATION_CHAIN_FAULT_CODE = "receipt-authority-invalid";

function continuationFaultCases() {
  const maxHops = continuationChainMaxHops();
  const baseMs = CONTINUATION_CHAIN_BASE_MS;
  const step = CONTINUATION_CHAIN_STEP_MS;
  const forkFields = { instance_mode: "fork", fork_reason: "short side task" };
  return {
    f1: {
      label: "F1 the named parent record does not exist",
      legit: { hops: 1 },
      prose: /admission chain parent unavailable/u,
      arrange({ repoRoot, changeId }) {
        const built = genericV1ContinuationChainFixture({ repoRoot, changeId }, { hops: 1 });
        rmSync(genericV1RecordPath(repoRoot, changeId, built.root.record_id));
        return built;
      },
    },
    f2: {
      label: "F2 the continuation record carries no parent_record_id (rewritten at file level before build)",
      legit: { hops: 1 },
      prose: /admission chain parent unavailable/u,
      arrange({ repoRoot, changeId }) {
        const built = genericV1ContinuationChainFixture({ repoRoot, changeId }, { hops: 1 });
        built.leaf.digest = rewriteGenericV1Record(repoRoot, changeId, built.leaf.record_id, (record) => {
          delete record.parent_record_id;
        });
        return built;
      },
    },
    f3: {
      label: "F3 the parent belongs to a different change_id",
      legit: { hops: 1 },
      prose: /admission chain parent change_id mismatch/u,
      arrange({ repoRoot, changeId }) {
        const built = genericV1ContinuationChainFixture({ repoRoot, changeId }, { hops: 1 });
        rewriteGenericV1Record(repoRoot, changeId, built.root.record_id, (record) => {
          record.change_id = "cont-chain-other-change";
        });
        return built;
      },
    },
    f4: {
      label: "F4 the parent names a different role",
      legit: { hops: 1 },
      prose: /admission chain parent role mismatch/u,
      arrange: ({ repoRoot, changeId }) => genericV1ContinuationChainFixture({ repoRoot, changeId }, {
        hops: 1,
        rootFields: { role: "dp-programmer" },
      }),
    },
    f5: {
      label: "F5 the parent belongs to another responsibility_id thread",
      legit: { hops: 1 },
      prose: /admission chain parent responsibility_id mismatch/u,
      arrange: ({ repoRoot, changeId }) => genericV1ContinuationChainFixture({ repoRoot, changeId }, {
        hops: 1,
        rootFields: { responsibility_id: "other-deliverable" },
      }),
    },
    "f6-later": {
      label: "F6 the parent was admitted after the continuation",
      legit: { hops: 1 },
      prose: /admission chain parent admitted_at must precede the continuation/u,
      arrange: ({ repoRoot, changeId }) => genericV1ContinuationChainFixture({ repoRoot, changeId }, {
        hops: 1,
        atMs: (index) => (index === 0 ? baseMs + 2 * step : baseMs + step),
      }),
    },
    "f6-equal": {
      label: "F6 the parent admitted_at equals the continuation's (not strictly earlier)",
      legit: { hops: 1 },
      prose: /admission chain parent admitted_at must precede the continuation/u,
      arrange: ({ repoRoot, changeId }) => genericV1ContinuationChainFixture({ repoRoot, changeId }, {
        hops: 1,
        atMs: () => baseMs,
      }),
    },
    f7: {
      label: "F7 the chain contains a cycle (A -> B -> A)",
      legit: { hops: 1 },
      prose: /admission chain contains a cycle/u,
      arrange({ repoRoot, changeId }) {
        const built = genericV1ContinuationChainFixture({ repoRoot, changeId }, { hops: 1 });
        const cycleRecord = (recordId, parentId, atMs) => ({
          ...built.leaf.record,
          record_id: recordId,
          parent_record_id: parentId,
          admitted_at: new Date(atMs).toISOString(),
        });
        writeContinuationRawRecord(repoRoot, changeId, cycleRecord(CYCLE_RECORD_A, CYCLE_RECORD_B, baseMs + 40_000));
        writeContinuationRawRecord(repoRoot, changeId, cycleRecord(CYCLE_RECORD_B, CYCLE_RECORD_A, baseMs + 20_000));
        built.leaf.digest = rewriteGenericV1Record(repoRoot, changeId, built.leaf.record_id, (record) => {
          record.parent_record_id = CYCLE_RECORD_A;
        });
        return built;
      },
    },
    f8: {
      label: "F8 the chain is one hop longer than ADMISSION_CHAIN_MAX_HOPS (P3 is the exactly-at-bound positive pair)",
      legit: { hops: maxHops },
      prose: new RegExp(`admission chain exceeds ${maxHops} hops to a fresh root`, "u"),
      arrange: ({ repoRoot, changeId }) => genericV1ContinuationChainFixture({ repoRoot, changeId }, { hops: maxHops + 1 }),
    },
    "f9-fork-parent": {
      label: "F9 the parent is a fork record",
      legit: { hops: 1 },
      prose: /fork admission record cannot evidence an independent runtime-agent reviewer/u,
      arrange: ({ repoRoot, changeId }) => genericV1ContinuationChainFixture({ repoRoot, changeId }, {
        hops: 1,
        rootFields: forkFields,
        rootRoleBinding: "cooperative-only",
      }),
    },
    "f9-fork-above-parent": {
      label: "F9 a fork record sits above the parent",
      legit: { hops: 3 },
      prose: /fork admission record cannot evidence an independent runtime-agent reviewer/u,
      arrange: ({ repoRoot, changeId }) => genericV1ContinuationChainFixture({ repoRoot, changeId }, {
        // hop 1 is the fork, hop 2 a continue whose parent is the fork, hop 3 the leaf:
        // the fork is two records above the leaf, not its direct parent.
        hops: 3,
        hopFields: (hop) => (hop === 1 ? { ...forkFields, parent_record_id: undefined } : {}),
      }),
    },
    "i2-fork-leaf": {
      label: "I2 the leaf itself is a cooperative-only fork record (not a declared continue)",
      legit: { hops: 1 },
      code: "receipt-identity-authority-mismatch",
      prose: null,
      arrange: ({ repoRoot, changeId }) => genericV1ContinuationChainFixture({ repoRoot, changeId }, {
        hops: 1,
        hopFields: () => ({ ...forkFields, parent_record_id: undefined }),
      }),
    },
    f10: {
      label: "F10 the fresh root is cooperative-only",
      legit: { hops: 1 },
      prose: /admission chain root is not host-verified/u,
      arrange: ({ repoRoot, changeId }) => genericV1ContinuationChainFixture({ repoRoot, changeId }, {
        hops: 1,
        rootRoleBinding: "cooperative-only",
      }),
    },
    d8: {
      label: "D8 the fresh root is a v2 prepared-intent record, not a v1 generic record",
      legit: { hops: 1 },
      prose: /admission chain root is not a generic admission record/u,
      arrange({ repoRoot, changeId }) {
        const v2 = preparedRuntimeAdmissionFixture({ repoRoot, changeId });
        const v2AdmittedMs = Date.parse(v2.record.admitted_at);
        assert.ok(Number.isFinite(v2AdmittedMs), "the v2 root record carries an admitted_at the continuation can follow");
        return genericV1ContinuationChainFixture({ repoRoot, changeId }, {
          hops: 1,
          existingRoot: v2,
          atMs: (index) => v2AdmittedMs + index * CONTINUATION_CHAIN_STEP_MS,
        });
      },
    },
    f11: {
      label: "F11 the continuation record was written at a head other than the reviewed head",
      legit: { hops: 1 },
      code: "receipt-identity-authority-mismatch",
      prose: null,
      arrange({ repoRoot, changeId }) {
        const built = genericV1ContinuationChainFixture({ repoRoot, changeId }, { hops: 1 });
        built.leaf.digest = rewriteGenericV1Record(repoRoot, changeId, built.leaf.record_id, (record) => {
          record.head_sha = "0".repeat(40);
        });
        return built;
      },
    },
  };
}

// Drives one faulty chain through the requested public entry points and checks the
// closed code, the reason, path-freeness and cross-entry equality (F13), plus the
// seal-side artifact assertions (F14) shared by every seal-side negative.
function assertContinuationChainFault(helper, { helperRepo, changeId, chain, spec, entries, label }) {
  const { repoRoot, tempRoot, mainSha } = helperRepo;
  const { leaf } = chain;
  const expectedCode = spec.code ?? CONTINUATION_CHAIN_FAULT_CODE;
  const payload = runtimeAgentPayload(helper, { repoRoot, changeId, mainSha, findings: [] });
  bindReceiptAuthority(helper, { repoRoot, changeId, reviewerPayload: payload });
  payload.review_authority = genericV1OnePieceAuthority(leaf);
  const rawPayloadRef = writeGenericV1RawPayload(helper, { repoRoot, payload });
  const problems = [];
  const outcomes = {};
  if (entries.includes("build")) {
    outcomes.build = continuationThrownBy(() => helper.buildReviewRoundReceiptRequest({
      repoRoot,
      changeId,
      rawPayloadRef,
      admissionRecordId: leaf.record_id,
    }));
  }
  if (entries.includes("seal")) {
    outcomes.seal = continuationThrownBy(() => helper.sealReviewRoundReceipt({
      repoRoot,
      changeId,
      reviewerPayload: clone(payload),
      admissionRecordId: leaf.record_id,
    }));
    // F14: the failure precedes every claim and every receipt write.
    const sealArtifacts = readdirSync(mainNotesRoot(repoRoot)).filter((name) => name.startsWith(`review-${changeId}-receipt-`));
    if (sealArtifacts.length !== 0) problems.push(`${label}/seal: no receipt file or .commit.json may exist, found ${sealArtifacts.join(", ")}`);
    if (existsSync(continuationClaimDir(repoRoot, changeId, leaf.record_id))) {
      problems.push(`${label}/seal: the continuation record must stay unclaimed`);
    }
  }
  if (entries.includes("verify")) {
    const receipt = {
      schema: REVIEW_RECEIPT_SCHEMA,
      receipt_digest_sha256: sha256(helper.canonicalJsonV1(payload)),
      observation_hashes: receiptObservationHashes(helper, payload.findings),
      reviewer_payload: payload,
    };
    const ref = writeReceiptEnvelope(
      helper,
      evidencePath(repoRoot, `review-${changeId}-receipt-r${payload.round_number}-${payload.dispatch_id}.json`),
      receipt,
    );
    outcomes.verify = continuationThrownBy(() => helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: ref, requireIndependence: true }));
  }
  for (const [entry, error] of Object.entries(outcomes)) {
    if (error === null) {
      problems.push(`${label}/${entry}: must fail closed but succeeded`);
      continue;
    }
    if (!(error instanceof CoreFailure)) {
      problems.push(`${label}/${entry}: expected a closed CoreFailure, got ${error?.name}: ${error?.message}`);
      continue;
    }
    if (error.code !== expectedCode) problems.push(`${label}/${entry}: expected code ${expectedCode}, got ${error.code}`);
    if (spec.prose !== null && !spec.prose.test(error.message)) {
      problems.push(`${label}/${entry}: reason ${JSON.stringify(error.message)} must name the chain fault ${spec.prose}`);
    }
    if (spec.prose === null && /admission chain/u.test(error.message)) {
      problems.push(`${label}/${entry}: a leaf content-to-ID failure must not be reported as a chain fault`);
    }
    if (/[\\/]/u.test(error.message) || error.message.includes(repoRoot) || error.message.includes(tempRoot)) {
      problems.push(`${label}/${entry}: reason ${JSON.stringify(error.message)} must expose no filesystem path`);
    }
  }
  const failures = Object.values(outcomes).filter((error) => error instanceof CoreFailure);
  if (failures.length === Object.keys(outcomes).length && new Set(failures.map((error) => error.message)).size > 1) {
    problems.push(`${label}: every entry must report the same code and reason, got ${JSON.stringify(failures.map((error) => error.message))}`);
  }
  assert.deepEqual(problems, [], `${label}: continuation chain fault outcome`);
}

function runContinuationFaultCase(helper, key, { entries, premise = true }) {
  const spec = continuationFaultCases()[key];
  assert.notEqual(spec, undefined, `unknown continuation fault case ${key}`);
  withRepo((helperRepo) => {
    const { repoRoot, mainSha } = helperRepo;
    const changeId = `cont-chain-${key}`;
    boundChange(repoRoot, changeId);
    const chain = spec.arrange({ repoRoot, changeId });
    assertContinuationChainFault(helper, { helperRepo, changeId, chain, spec, entries, label: spec.label });
    if (premise) {
      const okChangeId = `${changeId}-ok`;
      boundChange(repoRoot, okChangeId);
      const legit = genericV1ContinuationChainFixture({ repoRoot, changeId: okChangeId }, spec.legit);
      sealAndVerifyContinuationChain(helper, { repoRoot, changeId: okChangeId, mainSha, chain: legit });
    }
  });
}

// Scenario: Continued Thread Seals A Bounded Rereview Receipt (P1, P2).
test("Continued Thread Seals A Bounded Rereview Receipt: a one-hop continuation of a host-verified generic fresh root builds, seals runtime-agent and verifies under requireIndependence (P1 P2)", () => {
  const helper = api();
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "cont-chain-p1-p2";
    boundChange(repoRoot, changeId);
    const chain = genericV1ContinuationChainFixture({ repoRoot, changeId }, { hops: 1 });
    assert.equal(chain.root.record.role_binding, "host-verified");
    assert.equal(chain.leaf.record.role_binding, "cooperative-only", "the continuation record is never promoted to host-verified");
    assert.equal(chain.leaf.record.instance_mode, "continue");
    assert.equal(chain.leaf.record.parent_record_id, chain.root.record_id);
    sealAndVerifyContinuationChain(helper, { repoRoot, changeId, mainSha, chain });
  });
});

