// Scenario: Broken Or Unbounded Chains Fail Closed (F1, F3-F9 at seal and verify; F12 verify only).
test("Broken Or Unbounded Chains Fail Closed: a missing, mismatched, not-earlier, cyclic, fork or over-long parent chain fails seal and verify with receipt-authority-invalid and writes no receipt (F1 F3-F9 F12)", async (t) => {
  const helper = api();
  for (const key of ["f1", "f3", "f4", "f5", "f6-later", "f6-equal", "f7", "f8", "f9-fork-parent", "f9-fork-above-parent"]) {
    await t.test(continuationFaultCases()[key].label, () => {
      runContinuationFaultCase(helper, key, { entries: ["seal", "verify"] });
    });
  }
  // F12: an ancestor is changed after a legitimate seal. The ancestor is not part of
  // the leaf digest, so only the verify-side chain walk can catch it.
  const tampers = [
    ["role", (record) => { record.role = "dp-programmer"; }, /admission chain parent role mismatch/u],
    ["responsibility_id", (record) => { record.responsibility_id = "other-deliverable"; }, /admission chain parent responsibility_id mismatch/u],
    ["admitted_at", (record) => { record.admitted_at = new Date(CONTINUATION_CHAIN_BASE_MS + 10 * CONTINUATION_CHAIN_STEP_MS).toISOString(); }, /admission chain parent admitted_at must precede the continuation/u],
  ];
  for (const [field, mutate, prose] of tampers) {
    await t.test(`F12 a sealed receipt fails verify after its ancestor ${field} is changed`, () => {
      withRepo(({ repoRoot, mainSha, tempRoot }) => {
        const changeId = `cont-chain-f12-${field.replace(/_/gu, "-")}`;
        boundChange(repoRoot, changeId);
        const chain = genericV1ContinuationChainFixture({ repoRoot, changeId }, { hops: 2 });
        const { sealed } = sealAndVerifyContinuationChain(helper, { repoRoot, changeId, mainSha, chain });
        rewriteGenericV1Record(repoRoot, changeId, chain.root.record_id, mutate);
        const error = continuationThrownBy(() => helper.verifyReviewRoundReceipt({
          repoRoot,
          receiptRef: sealed.ref,
          requireIndependence: true,
        }));
        const problems = [];
        if (!(error instanceof CoreFailure)) {
          problems.push(`expected a closed CoreFailure, got ${error === null ? "success" : `${error.name}: ${error.message}`}`);
        } else {
          if (error.code !== CONTINUATION_CHAIN_FAULT_CODE) problems.push(`expected code ${CONTINUATION_CHAIN_FAULT_CODE}, got ${error.code}`);
          if (!prose.test(error.message)) problems.push(`reason ${JSON.stringify(error.message)} must name ${prose}`);
          if (/[\\/]/u.test(error.message) || error.message.includes(repoRoot) || error.message.includes(tempRoot)) {
            problems.push(`reason ${JSON.stringify(error.message)} must expose no filesystem path`);
          }
        }
        assert.deepEqual(problems, [], `F12 ancestor ${field}`);
      });
    });
  }
});

