// T3 (G1): one walker, mechanically locked. FR2 forbids a second `parent_record_id`
// walker, so the shared `assertAdmissionChainRootsToFresh` must stay the only function
// that follows the chain: defined exactly once, called exactly twice (the v2
// `executor_evidence` binding and the generic runtime-admission helper), and exactly one
// non-test script call reads an admission record keyed by a `parent_record_id`.
// Whole-line comment removal only. `stripJsCommentSpans` is not used here: it
// mis-reads a token in the core module and blanks everything after line ~3470, which
// would silently hide the very call sites this lock counts.
function continuationCodeLines(source) {
  return source
    .split("\n")
    .filter((line) => !/^\s*(?:\/\/|\/\*|\*)/u.test(line))
    .join("\n");
}

function continuationBalancedCallSpans(source, callee) {
  const spans = [];
  let from = 0;
  for (;;) {
    const start = source.indexOf(`${callee}(`, from);
    if (start === -1) return spans;
    let depth = 0;
    let end = start + callee.length;
    for (; end < source.length; end += 1) {
      if (source[end] === "(") depth += 1;
      else if (source[end] === ")") {
        depth -= 1;
        if (depth === 0) break;
      }
    }
    spans.push(source.slice(start, end + 1));
    from = end + 1;
  }
}

test("Chain Walk Has One Implementation: assertAdmissionChainRootsToFresh is defined once and called by the v2 executor_evidence binding and the generic helper, and exactly one non-test script call reads a record by parent_record_id (G1)", () => {
  const coreSource = continuationCodeLines(readFileSync(CORE_PATH, "utf8"));
  const walker = "assertAdmissionChainRootsToFresh";
  const definitions = coreSource.match(new RegExp(`\\bfunction\\s+${walker}\\s*\\(`, "gu")) ?? [];
  assert.equal(definitions.length, 1, `${walker} must be defined exactly once in the core module`);
  const callSites = (source) => (source.match(new RegExp(`\\b${walker}\\s*\\(`, "gu")) ?? []).length - (new RegExp(`\\bfunction\\s+${walker}\\s*\\(`, "u").test(source) ? 1 : 0);
  assert.equal(callSites(coreSource), 2, `${walker} must be called exactly twice in the core module`);
  assert.equal(
    callSites(sourceFunctionSlice(coreSource, "validateAdmissionBinding", "admissionClaimTuple")),
    1,
    "the v2 executor_evidence binding keeps calling the shared walker",
  );
  assert.equal(
    callSites(sourceFunctionSlice(coreSource, "assertGenericAdmissionContentToId", "validateV3NormalAuthority")),
    1,
    "the generic runtime-admission helper must call the same shared walker",
  );

  const scriptsRoot = repoPath(".devpro/scripts");
  const readers = [];
  for (const file of listMjsFiles(scriptsRoot)) {
    const relative = path.relative(scriptsRoot, file).split(path.sep).join("/");
    if (relative.startsWith("tests/") || relative.endsWith(".test.mjs")) continue;
    const source = continuationCodeLines(readFileSync(file, "utf8"));
    for (const span of continuationBalancedCallSpans(source, "readAdmissionRecord")) {
      if (/\bparent_record_id\b/u.test(span)) readers.push(`${relative}: ${span.replace(/\s+/gu, " ").slice(0, 120)}`);
    }
  }
  assert.equal(readers.length, 1, `exactly one non-test script call may read an admission record keyed by parent_record_id, found ${JSON.stringify(readers)}`);
  assert.match(readers[0], /^lib\/review-remediation-evidence-core\.mjs: /u, "that single reader is the shared chain walker in the core module");
});

test("large Git blob manifest inputs seal without the child-process 1 MiB ceiling", async (t) => {
  const helper = api();
  for (const size of [0, 1024 * 1024 - 1, 1024 * 1024, 1024 * 1024 + 1, 3_880_000]) {
    await t.test(`${size} binary bytes`, () => withRepo(({ repoRoot, mainSha }) => {
      const carrierPath = "src/large-review-input.bin";
      const bytes = Buffer.alloc(size);
      for (let index = 0; index < bytes.length; index += 1) bytes[index] = index % 256;
      writeFileSync(path.join(repoRoot, carrierPath), bytes);
      const candidateHeadSha = commitAll(repoRoot, "large binary manifest input");
      for (const purpose of ["repair-delta", "dependency-closure"]) {
        const sealed = sealManifest(helper, {
          repoRoot, changeId: "large-manifest-input", roundNumber: 1,
          manifest: manifestFixture({
            purpose, changeBaseSha: mainSha, candidateHeadSha,
            entries: [{ id: "large-input", path: carrierPath, digest_sha256: DIGEST_A }],
          }),
        });
        assert.equal(sealed.manifest.inputs.entries[0].digest_sha256, sha256(bytes));
        assert.equal(helper.verifyReviewManifest({
          repoRoot, manifestRef: sealed.ref, verificationMode: "current",
        }).manifest.manifest_digest_sha256, sealed.manifest.manifest_digest_sha256);
      }
    }));
  }
});

