test("classify-final names an unconverged latest receipt before archive instead of a bare reopen", () => {
  const helper = api();
  withRepo(({ repoRoot, mainSha }) => {
    // A finished verdict that still carries an open Suggestion: nothing blocks at Critical/Important,
    // yet seal-final refuses it. The pre-archive classifier has to say so, with the ids to close.
    const changeId = "final-open-suggestion";
    prepareFinalReceipt(helper, {
      repoRoot,
      mainSha,
      changeId,
      findings: [
        finding("F-closed", { state: "closed", disposition: "fix-now" }),
        scopedOpenFinding("F-suggestion-a", { severity: "Suggestion" }),
        scopedOpenFinding("F-suggestion-b", { severity: "Suggestion" }),
      ],
    });
    assert.deepEqual(helper.classifyFinalReadiness({ repoRoot, changeId }), {
      final_ready: false,
      review_lineage_valid: true,
      review_coverage_valid: false,
      review_coverage_mode: null,
      route: "full_reopen_required",
      full_reopen_debug_reason: "latest_receipt_not_converged",
      open_finding_ids: ["F-suggestion-a", "F-suggestion-b"],
    });
    assert.throws(
      () => sealFinal(helper, { repoRoot, changeId }),
      /latest finished receipt still contains open findings open_finding_ids=F-suggestion-a,F-suggestion-b$/u,
      "the seal error lists every open id, not only the blocking ones",
    );
  }, { featureChange: true });

  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "final-partial-verdict";
    prepareFinalReceipt(helper, {
      repoRoot,
      mainSha,
      changeId,
      verdict: "partial",
      findings: [scopedOpenFinding("F-open", { severity: "Important" })],
    });
    const readiness = helper.classifyFinalReadiness({ repoRoot, changeId });
    assert.equal(readiness.full_reopen_debug_reason, "latest_receipt_not_converged");
    assert.deepEqual(readiness.open_finding_ids, ["F-open"]);
  }, { featureChange: true });

  withRepo(({ repoRoot, mainSha }) => {
    // A converged receipt keeps the existing pre-seal shape: no diagnosis field at all.
    const changeId = "final-converged-pre-seal";
    prepareFinalReceipt(helper, { repoRoot, mainSha, changeId });
    const readiness = helper.classifyFinalReadiness({ repoRoot, changeId });
    assert.equal(Object.hasOwn(readiness, "full_reopen_debug_reason"), false);
    assert.equal(Object.hasOwn(readiness, "open_finding_ids"), false);
    assert.equal(readiness.review_coverage_valid, true);
  }, { featureChange: true });
});


// #2975 index 279: bookkeeping-only coverage uses existing bounded authority,
// with no new reviewer admission; runner_d4 alone extends to this appended case.
test("coverage-only bookkeeping successor binds its new HEAD through bounded TL-direct authority", () => {
  const helper = api();
  withRepo(({ repoRoot, mainSha }) => {
    const changeId = "coverage-only-bookkeeping-successor";
    const tasksPath = `openspec/changes/${changeId}/tasks.md`;
    writeMiniRiskChange(repoRoot, changeId, {
      riskClasses: "none\nrationale: bookkeeping checkbox only; no behavioral or trust-boundary change",
    });
    write(repoRoot, tasksPath, "- [ ] Record the completed verification evidence.\n");
    commitAll(repoRoot, "coverage baseline");
    const { dispatch, payload } = initialPayloadFromDispatch(helper, { repoRoot, changeId, mainSha, findings: [] });
    const initial = sealReceipt(helper, { repoRoot, changeId, reviewerPayload: payload });
    const initialBytes = readFileSync(initial.targetPath);

    write(repoRoot, tasksPath, "- [x] Record the completed verification evidence.\n");
    const newHead = commitAll(repoRoot, "bookkeeping checkbox only");
    const changedPaths = git(repoRoot, ["diff", "--name-only", payload.lineage.head_sha, newHead]).split("\n");
    assert.deepEqual(changedPaths, [tasksPath]);
    assert.equal(isAllowedPostRegressionHeadDeltaPath(tasksPath), true);

    const manifests = ["repair-delta", "dependency-closure"].map((purpose) => sealManifest(helper, {
      repoRoot,
      changeId,
      roundNumber: 2,
      manifest: manifestFixture({
        purpose,
        changeBaseSha: mainSha,
        surfaceBaseSha: payload.lineage.head_sha,
        candidateHeadSha: newHead,
        entries: [{ id: "bookkeeping-task", path: tasksPath, digest_sha256: DIGEST_A }],
      }),
    }));
    const [repair, closure] = manifests;
    for (const { manifest } of manifests) {
      assert.equal(manifest.inputs.entries[0].digest_sha256, sha256(readFileSync(path.join(repoRoot, tasksPath))));
      assert.notEqual(manifest.inputs.entries[0].digest_sha256, DIGEST_A, "materializeManifest replaces the placeholder before sealing");
      assert.equal(manifest.lineage.candidate_head_sha, newHead);
    }
    const bounded = classifyBounded(helper, {
      repoRoot, changeId, previousReceipt: initial, repairManifest: repair, closureManifest: closure,
    });
    assertDispatchableResult(bounded, { route: "bounded", count: 1, round: 2, reason: null });
    assert.equal(bounded.risk_shape_digest_sha256, dispatch.risk_shape_digest_sha256);
    const successor = sealReceipt(helper, {
      repoRoot,
      changeId,
      reviewerPayload: payloadFromDispatch(bounded, {
        changeId,
        baseSha: mainSha,
        mergeBaseSha: mainSha,
        headSha: newHead,
        previousReceiptRef: initial.ref,
        initialFullReceiptDigestSha256: initial.ref.digest_sha256,
        repairManifestRef: repair.ref,
        closureManifestRef: closure.ref,
        findings: [],
      }),
    });
    const verified = helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: successor.ref });
    assert.equal(verified.executor_attribution, "tl-direct");
    assert.equal(verified.receipt.reviewer_payload.lineage.head_sha, newHead);
    assert.equal(verified.receipt.reviewer_payload.bounded_rereview_count, 1);
    assert.deepEqual(readFileSync(initial.targetPath), initialBytes);
    assert.throws(
      () => helper.verifyReviewRoundReceipt({ repoRoot, receiptRef: successor.ref, requireIndependence: true }),
      { message: "ordinary-review-not-independent" },
    );
  });
});

// #3288: a CLI-normalized internal blank run must still be diagnosed by title.
test("archive ADDED, MODIFIED and REMOVED diagnostics name the exact requirement and canonical path", () => {
  const helper = api();
  const coreFactory = coreApi().createReviewRemediationEvidenceCore;
  for (const mode of ["ADDED", "MODIFIED", "REMOVED"]) withRepo(({ repoRoot, mainSha }) => {
    const changeId = "transition-body-diagnostic-" + mode.toLowerCase();
    prepareArchiveTransitionFixture(helper, {
      repoRoot, mainSha, changeId,
      mutateReviewed: ({ activeRoot }) => {
        if (mode !== "MODIFIED") return;
        const deltaPath = path.join(activeRoot, "specs/archive-fixture/spec.md");
        const original = readFileSync(deltaPath, "utf8");
        const changed = original.replace("The modified requirement SHALL use the reviewed wording.\n\n", "The modified requirement SHALL use the reviewed wording.\n\n\n");
        assert.notEqual(changed, original);
        writeFileSync(deltaPath, changed);
      },
      mutateArchive: () => {
        const target = path.join(repoRoot, "openspec/specs/archive-fixture/spec.md");
        const original = readFileSync(target, "utf8");
        if (mode === "ADDED") {
          const changed = original.replace("The added requirement SHALL be present", "The added requirement MUST be present");
          assert.notEqual(changed, original); writeFileSync(target, changed);
        } else if (mode === "REMOVED") {
          const retained = archiveCanonicalBeforeSpec().split("### Requirement: Existing Removed")[1];
          assert.ok(retained); writeFileSync(target, original + "\n### Requirement: Existing Removed" + retained);
        }
      },
    });
    const diagnostics = {
      ADDED: "ADDED promotion title/body mismatch or absence (Added Requirement; openspec/specs/archive-fixture/spec.md)",
      MODIFIED: "MODIFIED promotion title/body mismatch (Existing Modified; openspec/specs/archive-fixture/spec.md)",
      REMOVED: "REMOVED promotion retained or title/body mismatch (Existing Removed; openspec/specs/archive-fixture/spec.md)",
    };
    const fake = transitionRunner();
    assert.throws(() => coreFactory({ spawnSyncImpl: fake.runner }).sealFinalEvidenceRecord({ repoRoot, changeId, canonicalOwnerId: "owner-1" }), error => {
      assert.ok(error.message.includes(diagnostics[mode]), error.message); return true;
    });
    assert.equal(pathExists(archiveTransitionTarget(repoRoot, changeId)), false);
  });
});

// #3288: repair is before commit; final authority still seals the exact delta.
test("archive repaired MODIFIED blank run closes through the unchanged final seal", () => {
  const helper = api();
  const coreFactory = coreApi().createReviewRemediationEvidenceCore;
  for (const leadingBOM of [false, true]) withRepo(({ repoRoot, mainSha }) => {
    const changeId = "transition-modified-blank-repair";
    const fixture = prepareArchiveTransitionFixture(helper, {
      repoRoot, mainSha, changeId,
      mutateReviewed: ({ activeRoot }) => {
        const deltaPath = path.join(activeRoot, "specs/archive-fixture/spec.md");
        writeFileSync(deltaPath, (leadingBOM ? "\uFEFF" : "") + readFileSync(deltaPath, "utf8").replace(
          "The modified requirement SHALL use the reviewed wording.\n\n",
          "The modified requirement SHALL use the reviewed wording.\n\n\n",
        ));
      },
      mutateArchive: ({ reviewedHeadSha, archiveRelativeRoot }) => {
        const canonical = path.join(repoRoot, "openspec/specs/archive-fixture/spec.md");
        if (leadingBOM) writeFileSync(canonical, "\uFEFF" + readFileSync(canonical, "utf8"));
        const result = repairArchiveDeltaBodies({
          repoRoot, changeId, reviewedHeadSha,
          archiveRoot: archiveRelativeRoot.split(path.sep).join("/"), apply: true,
        });
        assert.deepEqual(result.repairs, [{ path: "openspec/specs/archive-fixture/spec.md", title: "Existing Modified", mode: "MODIFIED" }]);
      },
    });
    const fake = transitionRunner();
    const core = coreFactory({ spawnSyncImpl: fake.runner });
    core.sealFinalEvidenceRecord({ repoRoot, changeId, canonicalOwnerId: "owner-1" });
    assert.equal(core.verifyFinalEvidenceRecord({ repoRoot, changeId }).record.payload.head_sha, fixture.postArchiveHeadSha);
    assert.equal(core.classifyFinalReadiness({ repoRoot, changeId }).final_ready, true);
    const transition = readTransitionRecord(helper, repoRoot, changeId);
    const promoted = transition.payload.canonical_promotion_mapping.entries.find(item => item.requirement_title === "Existing Modified");
    assert.equal(promoted.delta_body_digest, promoted.post_body_digest);
    const archived = path.join(repoRoot, fixture.archiveRelativeRoot, "specs/archive-fixture/spec.md");
    const canonical = path.join(repoRoot, "openspec/specs/archive-fixture/spec.md");
    assert.equal(readFileSync(archived, "utf8").startsWith("\uFEFF"), leadingBOM);
    assert.equal(readFileSync(canonical, "utf8").startsWith("\uFEFF"), leadingBOM);
    assert.equal(git(repoRoot, ["rev-parse", "HEAD^"]), fixture.reviewedHeadSha);
  });
});

if (reviewRemediationEvidenceTestIndex !== REVIEW_REMEDIATION_EVIDENCE_TEST_GROUP_RANGE_END) {
  throw new Error(
    `review-remediation-evidence grouped ${reviewRemediationEvidenceTestIndex} tests, expected ${REVIEW_REMEDIATION_EVIDENCE_TEST_GROUP_RANGE_END}`,
  );
}
